export const REFERENCE_SHA256 = "051f2622830d0d32ccad209f97979fd8236b63a3e1eae1abf1865544b51c379d";
export const REFERENCE_SECTIONS = {
  "array-foundations": {
    "id": "array-foundations",
    "title": "An array is one fixed-size row of same-type values",
    "body": "\r\n        <span class=\"section-no\">Foundations / Arrays</span>\r\n        <h2>An array is one fixed-size row of same-type values</h2>\r\n        <p class=\"lede\">An array stores a numbered sequence. Its length is fixed when it is created, its first index is 0, and its final valid index is always <code>length - 1</code>.</p>\r\n        <div class=\"array-wrap\" aria-label=\"Five-element marks array with indexes zero through four\"><div class=\"array\"><span class=\"cell\" data-label=\"index 0\">63</span><span class=\"cell\" data-label=\"index 1\">29</span><span class=\"cell\" data-label=\"index 2\">72</span><span class=\"cell\" data-label=\"index 3\">85</span><span class=\"cell\" data-label=\"index 4\">18</span></div></div>\r\n        <div class=\"properties\"><div class=\"property\"><small>Type</small><b>int[]</b></div><div class=\"property\"><small>Length</small><b>5</b></div><div class=\"property\"><small>First index</small><b>0</b></div><div class=\"property\"><small>Last index</small><b>4</b></div></div>\r\n        <h3>Declare, create, initialise, use</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Array basics (code fragment)</span></div><pre><code><span class=\"cm\">// 1. Declare a variable that can refer to an int array.</span>\r\n<span class=\"ty\">int</span>[] marks;\r\n\r\n<span class=\"cm\">// 2. Create five int cells. Every cell starts at 0.</span>\r\nmarks = <span class=\"kw\">new</span> <span class=\"ty\">int</span>[5];\r\n\r\n<span class=\"cm\">// 3. Store values by index.</span>\r\nmarks[0] = 63;\r\nmarks[marks.length - 1] = 18; <span class=\"cm\">// last valid cell</span>\r\n\r\n<span class=\"cm\">// A literal declares, creates, and fills in one statement.</span>\r\n<span class=\"ty\">int</span>[] ready = {63, 29, 72, 85, 18};\r\n\r\n<span class=\"cm\">// Reading index 5 would throw ArrayIndexOutOfBoundsException.</span>\r\nSystem.out.println(ready[2]); <span class=\"cm\">// prints 72</span></code></pre></div>\r\n        <div class=\"callout\"><strong>Fixed size does not mean fixed values.</strong> You may replace values in existing cells, but you cannot make the same array gain a sixth cell. Create a new array or use an <code>ArrayList</code> when size must grow.</div>\r\n        <details><summary>Quick check: why is <code>marks[marks.length]</code> invalid?</summary><div class=\"answer\">For length 5, valid indexes are 0 through 4. <code>marks.length</code> is 5, one position beyond the array.</div></details>\r\n        <h3>Array helpers you will meet</h3><p>These come from <code>java.util.Arrays</code> (add <code>import java.util.Arrays;</code>). The file and merge-sort examples later in this guide use them.</p><div class=\"table-scroll\"><table><thead><tr><th>Call</th><th>What it does</th><th>Result for the example</th></tr></thead><tbody><tr><td><code>Arrays.toString(a)</code></td><td>Readable text for the contents. Printing an array directly shows an unreadable reference such as <code>[I@6d06d69c</code>.</td><td><code>[63, 29, 72, 85, 18]</code></td></tr><tr><td><code>Arrays.copyOf(a, n)</code></td><td>New array of length <code>n</code>. Copies the first <code>n</code> values; extra cells get default values.</td><td><code>int[] a = {63, 29, 72};</code> then <code>Arrays.copyOf(a, 5)</code> → <code>[63, 29, 72, 0, 0]</code></td></tr><tr><td><code>Arrays.copyOfRange(a, from, to)</code></td><td>New array from index <code>from</code> up to, but <strong>not including</strong>, <code>to</code>.</td><td><code>int[] a = {63, 29, 72, 85};</code> then <code>Arrays.copyOfRange(a, 1, 3)</code> → <code>[29, 72]</code></td></tr><tr><td><code>Arrays.fill(a, v)</code></td><td>Stores <code>v</code> in every cell.</td><td><code>int[] a = new int[4]; Arrays.fill(a, 7);</code> → <code>a</code> is <code>[7, 7, 7, 7]</code></td></tr><tr><td><code>Arrays.equals(a, b)</code></td><td>Compares contents cell by cell. Both <code>a == b</code> and <code>a.equals(b)</code> only ask whether the two variables reach the <em>same</em> array.</td><td>Two separate <code>{1,2,3}</code> arrays: <code>==</code> false, <code>.equals</code> false, <code>Arrays.equals</code> true</td></tr></tbody></table></div><div class=\"callout\"><strong>Length syntax differs.</strong> An array uses <code>marks.length</code> (no parentheses). A String uses <code>name.length()</code>.</div><details><summary>Quick check: what does <code>Arrays.copyOfRange(a, 1, 3)</code> return for <code>a = {63, 29, 72, 85}</code>?</summary><div class=\"answer\"><code>[29, 72]</code>. It copies indexes 1 and 2. The end index 3 is excluded, which is why merge sort writes <code>m + 1</code> for the left half.</div></details>\r\n      "
  },
  "array-loops": {
    "id": "array-loops",
    "title": "A for loop connects an index to every array cell",
    "body": "\r\n        <span class=\"section-no\">Foundations / Arrays &amp; loops</span>\r\n        <h2>A for loop connects an index to every array cell</h2>\r\n        <p class=\"lede\">Use an indexed loop when you need the position or want to change array cells. Use an enhanced for loop when you only need to read each value.</p>\r\n        <h3>Indexed loop · read and update</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Visit every valid index</span></div><pre><code><span class=\"ty\">int</span>[] marks = {63, 29, 72, 85, 18};\r\n\r\n<span class=\"cm\">// i takes the values 0, 1, 2, 3, and 4.</span>\r\n<span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; marks.length; i++) {\r\n    <span class=\"cm\">// Update the actual array cell at index i.</span>\r\n    marks[i] = marks[i] + 1;\r\n    System.out.println(<span class=\"st\">\"index \"</span> + i + <span class=\"st\">\" = \"</span> + marks[i]);\r\n}</code></pre></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Iteration</th><th>i</th><th>Old marks[i]</th><th>Statement</th><th>New marks[i]</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>63</td><td><code>marks[0] = 63 + 1</code></td><td>64</td></tr><tr><td>2</td><td>1</td><td>29</td><td><code>marks[1] = 29 + 1</code></td><td>30</td></tr><tr><td>3</td><td>2</td><td>72</td><td><code>marks[2] = 72 + 1</code></td><td>73</td></tr><tr><td>4</td><td>3</td><td>85</td><td><code>marks[3] = 85 + 1</code></td><td>86</td></tr><tr><td>5</td><td>4</td><td>18</td><td><code>marks[4] = 18 + 1</code></td><td>19</td></tr></tbody></table></div>\r\n        <h3>Enhanced loop · read only</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Sum values without indexes</span></div><pre><code><span class=\"ty\">int</span> total = 0;\r\n<span class=\"kw\">for</span> (<span class=\"ty\">int</span> mark : marks) {\r\n    total += mark; <span class=\"cm\">// mark is a copy of the current int value</span>\r\n}\r\n\r\n<span class=\"cm\">// mark = 0 here would NOT replace an array cell.</span></code></pre></div>\r\n        <p>With an array of <em>objects</em> the loop variable is a copy of the <strong>reference</strong>, not of the object. Assigning to it never changes the array, but calling a method such as <code>dog.setName(\"Rex\")</code> (<code>Dog</code> is a small class, described in the next section) changes the one shared object, and the array sees that change.</p>\r\n        <div class=\"debug-list\"><strong>Loop checklist</strong><ul><li>Start at <code>0</code>.</li><li>Continue while <code>i &lt; array.length</code>.</li><li>Use <code>i++</code> to reach the next cell.</li><li>Never hard-code the final index when <code>length</code> is available.</li></ul></div>\r\n        <details><summary>Debug question: what is wrong with <code>i &lt;= marks.length</code>?</summary><div class=\"answer\">The final iteration uses index 5 for a five-cell array. That index does not exist, so the program throws <code>ArrayIndexOutOfBoundsException</code>.</div></details>\r\n      "
  },
  "array-types": {
    "id": "array-types",
    "title": "Primitive arrays hold values; reference arrays hold routes to objects",
    "body": "\r\n        <span class=\"section-no\">Foundations / Types</span>\r\n        <h2>Primitive arrays hold values; reference arrays hold routes to objects</h2>\r\n        <p class=\"lede\">The array object itself is always a reference type. The important difference is what each cell stores: a primitive value such as an <code>int</code>, or a reference that may point to an object.</p>\r\n        <p class=\"fine-print\">The <code>Dog</code> used in these examples is a small class: <code>new Dog(\"Coco\", \"brown\", 2.0)</code> sets a name, a colour and an age, and it has <code>getName()</code>, <code>setName(String)</code> and <code>getAge()</code>. Its body is not needed to follow the diagrams.</p>\r\n        <div class=\"direction-grid\">\r\n          <div class=\"paper-card\"><h3>Primitive elements</h3><div class=\"array-wrap\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">0</span><span class=\"cell\" data-label=\"1\">0</span><span class=\"cell\" data-label=\"2\">0</span></div></div><p><code>new int[3]</code> creates three actual integer values. Their default is <code>0</code>.</p></div>\r\n          <div class=\"paper-card\"><h3>Reference elements</h3><div class=\"array-wrap\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">null</span><span class=\"cell\" data-label=\"1\">null</span><span class=\"cell\" data-label=\"2\">null</span></div></div><p><code>new Dog[3]</code> creates three reference cells. It creates no Dog objects; every default is <code>null</code>.</p></div>\r\n        </div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Declaration</th><th>What a cell stores</th><th>Default</th><th>Typical danger</th></tr></thead><tbody><tr><td><code>int[]</code></td><td>An integer value</td><td><code>0</code></td><td>Wrong index</td></tr><tr><td><code>double[]</code></td><td>A decimal value</td><td><code>0.0</code></td><td>Wrong index</td></tr><tr><td><code>boolean[]</code></td><td>A true/false value</td><td><code>false</code></td><td>Wrong assumption about default</td></tr><tr><td><code>String[]</code></td><td>A String reference</td><td><code>null</code></td><td>Calling a method through null</td></tr><tr><td><code>Dog[]</code></td><td>A Dog reference</td><td><code>null</code></td><td>Believing the Dogs already exist</td></tr></tbody></table></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Reference cells and aliasing</span></div><pre><code><span class=\"ty\">Dog</span>[] dogs = <span class=\"kw\">new</span> <span class=\"ty\">Dog</span>[2]; <span class=\"cm\">// [null, null]</span>\r\n<span class=\"ty\">Dog</span> pet = <span class=\"kw\">new</span> <span class=\"ty\">Dog</span>(<span class=\"st\">\"Coco\"</span>, <span class=\"st\">\"brown\"</span>, 2.0);\r\ndogs[0] = pet; <span class=\"cm\">// copy the reference, not the whole object</span>\r\npet.setName(<span class=\"st\">\"Milo\"</span>);\r\n\r\n<span class=\"cm\">// dogs[0].getName() is now also \"Milo\".</span>\r\n<span class=\"cm\">// pet and dogs[0] reach the same Dog object.</span></code></pre></div>\r\n        <details><summary>Quick check: does <code>new Dog[5]</code> call the Dog constructor five times?</summary><div class=\"answer\">No. It creates one array containing five <code>null</code> references. A Dog constructor runs only when you explicitly write <code>new Dog(...)</code>.</div></details>\r\n      "
  },
  "array-copy": {
    "id": "array-copy",
    "title": "An array variable holds a reference, so assignment shares the array",
    "body": "\r\n        <span class=\"section-no\">Foundations / Copying &amp; passing</span>\r\n        <h2>An array variable holds a reference, so assignment shares the array</h2>\r\n        <p class=\"lede\">Writing <code>b = a</code> for arrays copies the route to the array, not the array. Two variables then reach one set of cells. To get a second, independent array you must create one.</p>\r\n        <div class=\"direction-grid\">\r\n          <div class=\"paper-card\"><h3>Assignment · <code>alias = a</code></h3>\r\n            <div class=\"ref-row\"><div class=\"ref-stack\"><span class=\"stack-frame\">a</span><span class=\"stack-frame\">alias</span></div><span class=\"stack-arrow\">→</span><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"One array containing 99, 2, 3 reached by both a and alias\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">99</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">3</span></div></div></div>\r\n            <p>One array. A change through either name is visible through both.</p></div>\r\n          <div class=\"paper-card\"><h3>Copy · <code>Arrays.copyOf</code></h3>\r\n            <div class=\"ref-row\"><div class=\"ref-stack\"><span class=\"stack-frame\">copy</span></div><span class=\"stack-arrow\">→</span><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"A separate array containing 1, 2, 3 reached by copy\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">3</span></div></div></div>\r\n            <p>A second array. It kept the old values because it was copied before <code>alias[0] = 99</code> ran.</p></div>\r\n        </div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Alias versus copy</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy Alias versus copy\">Copy code</button></div><pre><code><span class=\"ty\">int</span>[] a = {1, 2, 3};\r\n<span class=\"ty\">int</span>[] alias = a;                          <span class=\"cm\">// copies the reference only</span>\r\n<span class=\"ty\">int</span>[] copy = <span class=\"ty\">Arrays</span>.copyOf(a, a.length);  <span class=\"cm\">// builds a second array</span>\r\n\r\nalias[0] = 99;\r\n\r\n<span class=\"ty\">System</span>.out.println(<span class=\"ty\">Arrays</span>.toString(a));     <span class=\"cm\">// [99, 2, 3]</span>\r\n<span class=\"ty\">System</span>.out.println(<span class=\"ty\">Arrays</span>.toString(alias)); <span class=\"cm\">// [99, 2, 3]</span>\r\n<span class=\"ty\">System</span>.out.println(<span class=\"ty\">Arrays</span>.toString(copy));  <span class=\"cm\">// [1, 2, 3]</span></code></pre></div>\r\n        <h3>Passing an array to a method</h3>\r\n        <p>Java passes a <em>copy of the reference</em>. The method can change the cells the caller sees, which is why <code>insertionSort(int[] a)</code> can be <code>void</code> and still sort the caller's array. Reassigning the parameter itself changes nothing outside the method.</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Parameter behaviour</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy Parameter behaviour\">Copy code</button></div><pre><code><span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> addBonus(<span class=\"ty\">int</span>[] marks) {\r\n    <span class=\"cm\">// marks is a copy of the caller's REFERENCE, so these writes reach the caller's array.</span>\r\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; marks.length; i++) marks[i] += 5;\r\n}\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> replace(<span class=\"ty\">int</span>[] marks) {\r\n    <span class=\"cm\">// This only repoints the local variable. The caller's variable is unchanged.</span>\r\n    marks = <span class=\"kw\">new</span> <span class=\"ty\">int</span>[]{0, 0, 0};\r\n}\r\n\r\n<span class=\"ty\">int</span>[] m = {60, 70};\r\naddBonus(m);   <span class=\"cm\">// m is now [65, 75]</span>\r\nreplace(m);    <span class=\"cm\">// m is still [65, 75]</span></code></pre></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Statement</th><th>Caller's <code>m</code> afterwards</th><th>Why</th></tr></thead><tbody><tr><td><code>addBonus(m)</code></td><td><code>[65, 75]</code></td><td>The loop wrote into the shared array.</td></tr><tr><td><code>replace(m)</code></td><td><code>[65, 75]</code></td><td>Only the parameter was repointed to a new array.</td></tr></tbody></table></div>\r\n        <h3>Copying an array of objects is shallow</h3>\r\n        <p><code>Arrays.copyOf(dogs, dogs.length)</code> copies the <em>references</em>. The new array and the old one then reach the same Dog objects, so <code>copy[0].setName(\"Milo\")</code> also changes <code>dogs[0]</code>. Primitive arrays have no such sharing because each cell holds the value itself.</p>\r\n        <details><summary>Quick check: after <code>int[] b = a; b[0] = 99;</code>, what is <code>a[0]</code>?</summary><div class=\"answer\"><code>99</code>. There is only one array. <code>b</code> and <code>a</code> are two names for it.</div></details>\r\n        <details><summary>Quick check: why can a sort method be <code>void</code>?</summary><div class=\"answer\">The array itself is rearranged in place through the reference the method received, so nothing needs to be returned.</div></details>\r\n      "
  },
  "memory": {
    "id": "memory",
    "title": "Memory diagrams for object arrays",
    "body": "\r\n        <span class=\"section-no\">Foundations / Memory diagrams</span>\r\n        <h2>Memory diagrams for object arrays</h2>\r\n        <p class=\"lede\">Draw variables, the array, and the object as separate boxes. Use arrows to show which reference reaches which object.</p>\r\n        <div class=\"code-panel\">\r\n          <div class=\"code-head\"><span>Reference example</span></div>\r\n          <pre><code><span class=\"ty\">Staff</span>[] emps = <span class=\"kw\">new</span> <span class=\"ty\">Staff</span>[5];\r\n<span class=\"ty\">Staff</span> one = <span class=\"kw\">new</span> <span class=\"ty\">Staff</span>(<span class=\"st\">\"Mike Jones\"</span>, 10017, <span class=\"st\">\"Mat\"</span>);\r\nemps[emps.length - 1] = one;\r\nemps[emps.length - 1].setDepartment(<span class=\"st\">\"Bio\"</span>);\r\nemps[emps.length - 1].setId(10011);</code></pre>\r\n        </div>\r\n        <h3 id=\"memory-illustration\">Final state—with the changes left visible</h3>\r\n        <p>The red cancellations show the original constructor values. The red rewrites show what the setter calls changed. Labels such as <code>A1</code> and <code>S1</code> are simple diagram identifiers, not real machine addresses.</p>\r\n        <div class=\"memory-board\" role=\"img\" aria-label=\"Hand-corrected memory diagram. emps refers to array A1. Array positions zero to three are null and position four refers to Staff object S1. Variable one also refers to S1. The Staff object refers to Mike Jones, has old ID 10017 crossed out and new ID 10011, and has old department Mat crossed out and new department Bio.\">\r\n          <div class=\"memory-sketch\">\r\n            <div class=\"sketch-heading\">1. Variable <strong>emps</strong> points to the array</div>\r\n            <div class=\"sketch-variable-row\">\r\n              <div class=\"sketch-ref\"><strong>emps</strong><small>A1</small></div>\r\n              <span class=\"sketch-arrow\">↘</span>\r\n              <div class=\"sketch-array-wrap\">\r\n                <span class=\"sketch-address\">A1</span>\r\n                <div class=\"sketch-array\">\r\n                  <div class=\"sketch-slot\" data-index=\"0\">null</div>\r\n                  <div class=\"sketch-slot\" data-index=\"1\">null</div>\r\n                  <div class=\"sketch-slot\" data-index=\"2\">null</div>\r\n                  <div class=\"sketch-slot\" data-index=\"3\">null</div>\r\n                  <div class=\"sketch-slot changed\" data-index=\"4\"><span class=\"old-value\">null</span><br><span class=\"new-value\">S1</span></div>\r\n                </div>\r\n                <div class=\"sketch-note\">length = 5 · last index = length − 1 = 4</div>\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"sketch-heading\">2. <strong>one</strong> and <strong>emps[4]</strong> point to the same Staff object</div>\r\n            <div class=\"sketch-object-row\">\r\n              <div>\r\n                <div class=\"sketch-ref\"><strong>one</strong><small>S1</small></div>\r\n                <div class=\"sketch-ref\" style=\"margin-top:.7rem\"><strong>emps[4]</strong><small>S1</small></div>\r\n              </div>\r\n              <span class=\"sketch-arrow\">→</span>\r\n              <div class=\"staff-sketch\">\r\n                <div class=\"staff-sketch-title\">Staff object · S1</div>\r\n                <div class=\"sketch-field\"><span class=\"sketch-field-name\">name</span><span>T1 <span class=\"red-arrow\">→</span></span></div>\r\n                <div class=\"sketch-field\"><span class=\"sketch-field-name\">staffId</span><span class=\"rewrite\"><span class=\"old-value\">10017</span><span class=\"red-arrow\">→</span><span class=\"new-value\">10011</span></span></div>\r\n                <div class=\"sketch-field\"><span class=\"sketch-field-name\">department</span><span class=\"rewrite\"><span class=\"old-value\">T2</span><span class=\"red-arrow\">→</span><span class=\"new-value\">T3</span></span></div>\r\n              </div>\r\n              <span class=\"sketch-arrow\">→</span>\r\n              <div class=\"string-bank\">\r\n                <div class=\"string-box\">T1 · \"Mike Jones\"</div>\r\n                <div class=\"string-box abandoned\">T2 · \"Mat\"</div>\r\n                <div class=\"string-box replacement\">T3 · \"Bio\"</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"correction-note\">setDepartment(\"Bio\") redirects department from T2 to T3; setId(10011) replaces the primitive value directly.</div>\r\n            <div class=\"memory-legend\"><span><i class=\"legend-line\"></i> crossed out = old value</span><span class=\"new-value\">red writing = new value</span></div>\r\n          </div>\r\n        </div>\r\n        <div class=\"flow-steps\">\r\n          <div class=\"flow-step\"><b>1</b><div><strong>Create the array.</strong> It has five positions numbered 0 to 4. Every position begins as <code>null</code>.</div></div>\r\n          <div class=\"flow-step\"><b>2</b><div><strong>Create the Staff object.</strong> Variable <code>one</code> refers to it.</div></div>\r\n          <div class=\"flow-step\"><b>3</b><div><strong>Copy the reference.</strong> <code>emps[4] = one</code> makes both places refer to the same object; it does not copy the object.</div></div>\r\n          <div class=\"flow-step\"><b>4</b><div><strong>Mutate through the array.</strong> The two setter calls change that shared object to ID <code>10011</code> and department <code>Bio</code>.</div></div>\r\n        </div>\r\n        <h3 id=\"object-array-example\">Safe object-array access</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Dog array pattern</span></div><pre><code><span class=\"ty\">Dog</span>[] dogs = <span class=\"kw\">new</span> <span class=\"ty\">Dog</span>[5];\r\n<span class=\"ty\">Dog</span> d1 = <span class=\"kw\">new</span> <span class=\"ty\">Dog</span>(<span class=\"st\">\"Snowy\"</span>, <span class=\"st\">\"white\"</span>, 1.5);\r\ndogs[1] = d1;\r\n\r\n<span class=\"kw\">if</span> (dogs[0] != <span class=\"kw\">null</span>) dogs[0].setName(<span class=\"st\">\"Coco\"</span>);\r\n<span class=\"kw\">if</span> (dogs[dogs.length - 1] != <span class=\"kw\">null</span>\r\n        &amp;&amp; dogs[dogs.length - 1].getAge() &lt; 1) {\r\n    System.out.println(<span class=\"st\">\"Last dog is a puppy\"</span>);\r\n}</code></pre></div>\r\n        <p>The <code>null</code> check matters: an array position exists even when it does not yet refer to a <code>Dog</code> object.</p>\r\n        <h3>Check your diagram reading</h3>\r\n        <details><summary>How many Staff objects exist after all five statements?</summary><div class=\"answer\">One. The variable <code>one</code> and array position <code>emps[4]</code> hold two references to the same object.</div></details>\r\n        <details><summary>What would happen if <code>dogs[0].setName(\"Coco\")</code> ran without the null check?</summary><div class=\"answer\">It would throw a <code>NullPointerException</code> because <code>dogs[0]</code> does not refer to a Dog object yet.</div></details>\r\n      "
  },
  "scanner-array": {
    "id": "scanner-array",
    "title": "Yes, Java can create an array of Scanners",
    "body": "\r\n        <span class=\"section-no\">Foundations / Unusual reference arrays</span>\r\n        <h2>Yes, Java can create an array of Scanners</h2>\r\n        <p class=\"lede\">A <code>Scanner</code> is an object, so <code>Scanner[]</code> is legal. Each cell stores a Scanner reference. It is usually impractical because every open Scanner owns a resource that must be closed correctly.</p>\r\n        <div class=\"array-wrap\"><div class=\"array\"><span class=\"cell key\" data-label=\"readers[0]\">Scanner A</span><span class=\"cell key\" data-label=\"readers[1]\">Scanner B</span></div></div>\r\n        <p class=\"fine-print\">The figure shows the array <em>after</em> both assignments. Right after <code>new Scanner[2]</code> it is <code>[null, null]</code>.</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Legal, but rarely the best design (a method fragment)</span></div><pre><code><span class=\"kw\">import</span> java.io.File;\r\n<span class=\"kw\">import</span> java.io.FileNotFoundException;\r\n<span class=\"kw\">import</span> java.util.Scanner;\r\n\r\n<span class=\"kw\">public static void</span> scannerArrayDemo() <span class=\"kw\">throws</span> FileNotFoundException {\r\n    <span class=\"cm\">// The array begins as [null, null].</span>\r\n    <span class=\"ty\">Scanner</span>[] readers = <span class=\"kw\">new</span> <span class=\"ty\">Scanner</span>[2];\r\n    readers[0] = <span class=\"kw\">new</span> <span class=\"ty\">Scanner</span>(<span class=\"kw\">new</span> <span class=\"ty\">File</span>(<span class=\"st\">\"marks-a.txt\"</span>));\r\n    readers[1] = <span class=\"kw\">new</span> <span class=\"ty\">Scanner</span>(<span class=\"kw\">new</span> <span class=\"ty\">File</span>(<span class=\"st\">\"marks-b.txt\"</span>));\r\n\r\n    <span class=\"cm\">// Close every non-null Scanner. If opening readers[1] failed, readers[0] would stay open: one reason this design is fragile.</span>\r\n    <span class=\"kw\">for</span> (<span class=\"ty\">Scanner</span> reader : readers) {\r\n        <span class=\"kw\">if</span> (reader != <span class=\"kw\">null</span>) reader.close();\r\n    }\r\n}</code></pre></div>\r\n        <div class=\"callout\"><strong>Prefer one Scanner in a try-with-resources block</strong> for one file. It closes automatically, is easier to reason about, and avoids keeping several files open at once.</div>\r\n        <details><summary>Possible test question: what are the two defaults in <code>new Scanner[2]</code>?</summary><div class=\"answer\"><code>null</code> and <code>null</code>. The statement creates the array only; it does not create Scanner objects.</div></details>\r\n      "
  },
  "searching": {
    "id": "searching",
    "title": "What searching means",
    "body": "\r\n        <span class=\"section-no\">Searching</span>\r\n        <h2>What searching means</h2>\r\n        <p class=\"lede\">Searching is the process of looking for a particular element in a collection. A successful method returns its index; an unsuccessful search returns <code>-1</code>.</p>\r\n        <div class=\"term-grid\">\r\n          <div class=\"term\"><strong>Search key</strong>The value being looked for.</div>\r\n          <div class=\"term\"><strong>Comparison</strong>Checking the key against an array value.</div>\r\n          <div class=\"term\"><strong>Ordered collection</strong>Values already arranged by a rule.</div>\r\n          <div class=\"term\"><strong>Unordered collection</strong>Values may appear in any order.</div>\r\n        </div>\r\n        <p>Use a search to check membership, display or update an item, or find the position needed for another operation.</p>\r\n        <h3>Reading Big-O: why we count steps</h3><p>Big-O describes how the number of steps grows as the number of values <code>n</code> grows. It ignores small constant details and keeps the dominant growth. <em>Best</em>, <em>average</em> and <em>worst</em> case describe three situations for the same size <code>n</code>: the most favourable input, a typical input, and the least favourable input. In this guide one <em>comparison</em> means one probe: one look at an array value (for binary search, <code>arr[mid]</code>), even though Java may spell it as two tests such as <code>==</code> then <code>&lt;</code>.</p><div class=\"table-scroll\"><table><thead><tr><th>n values</th><th>Binary search<br><code>O(log n)</code><br>worst comparisons</th><th>Linear search<br><code>O(n)</code></th><th>Merge sort<br><code>O(n log n)</code></th><th>Simple sorts<br><code>O(n²)</code> worst</th></tr></thead><tbody><tr><td>10</td><td>4</td><td>10</td><td>≈ 33</td><td>100</td></tr><tr><td>100</td><td>7</td><td>100</td><td>≈ 664</td><td>10,000</td></tr><tr><td>1,000</td><td>10</td><td>1,000</td><td>≈ 9,966</td><td>1,000,000</td></tr><tr><td>1,000,000</td><td>20</td><td>1,000,000</td><td>≈ 20 million</td><td>1,000,000,000,000</td></tr></tbody></table></div><p class=\"fine-print\">Binary search column: ⌊log₂ n⌋ + 1 comparisons. Merge column: n × log₂ n. These are step counts, not seconds.</p><div class=\"term-grid\"><div class=\"term\"><strong><code>O(1)</code> · constant</strong>The work does not depend on n, such as reading <code>marks[0]</code>.</div><div class=\"term\"><strong><code>O(log n)</code> · logarithmic</strong>Each step discards a fraction of the data. Doubling n adds one step.</div><div class=\"term\"><strong><code>O(n)</code> · linear</strong>Each value is touched about once. Doubling n doubles the work.</div><div class=\"term\"><strong><code>O(n²)</code> · quadratic</strong>Each value may meet every other value. Doubling n quadruples the work.</div></div>\r\n      "
  },
  "linear-array": {
    "id": "linear-array",
    "title": "The array we will search",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · The array we will search</span>\r\n        <h2>The array we will search</h2>\r\n        <p class=\"lede\">Ten values in no particular order: <code>[63, 29, 85, 72, 18, 42, 23, 54, 8, 32]</code>.</p>\r\n        \r\n        <div class=\"paper-card\">\r\n          <div class=\"kicker\">An unsorted array of ten values</div>\r\n          <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array 63, 29, 85, 72, 18, 42, 23, 54, 8, 32\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">63</span><span class=\"cell\" data-label=\"1\">29</span><span class=\"cell\" data-label=\"2\">85</span><span class=\"cell\" data-label=\"3\">72</span><span class=\"cell\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div>\r\n          <figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"The same values as bars: no pattern at all\"><div class=\"bar\" style=\"--p:0.741\"><i></i><b>63</b><small>0</small></div><div class=\"bar\" style=\"--p:0.341\"><i></i><b>29</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>85</b><small>2</small></div><div class=\"bar\" style=\"--p:0.847\"><i></i><b>72</b><small>3</small></div><div class=\"bar\" style=\"--p:0.212\"><i></i><b>18</b><small>4</small></div><div class=\"bar\" style=\"--p:0.494\"><i></i><b>42</b><small>5</small></div><div class=\"bar\" style=\"--p:0.271\"><i></i><b>23</b><small>6</small></div><div class=\"bar\" style=\"--p:0.635\"><i></i><b>54</b><small>7</small></div><div class=\"bar\" style=\"--p:0.094\"><i></i><b>8</b><small>8</small></div><div class=\"bar\" style=\"--p:0.376\"><i></i><b>32</b><small>9</small></div></div></figure>\r\n        </div>\r\n        <p>Look at the bars: there is no order to exploit. The values jump up and down, so nothing about one cell tells you anything about the next. That is the situation linear search is built for.</p>\r\n        <p>We will use two searches throughout this chapter: for <code>18</code>, which <strong>is</strong> in the array (at index 4), and for <code>31</code>, which is <strong>not</strong>.</p>\r\n    \r\n      "
  },
  "linear-definition": {
    "id": "linear-definition",
    "title": "The textbook definition",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · The textbook definition</span>\r\n        <h2>The textbook definition</h2>\r\n        \r\n        <div class=\"paper-card definition\">\r\n          <p><strong>Linear search</strong> (also called <em>sequential search</em>) finds a value in a collection by examining the elements one at a time, in order, starting from the first. It stops as soon as an element equals the target and returns that element's index. If it reaches the end without a match it reports failure, by convention by returning <code>-1</code>. It works on any array, sorted or not.</p>\r\n        </div>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Key</strong>The value we are looking for. Also called the target or search value.</div><div class=\"term\"><strong>Index</strong>The position of a value in the array, starting at 0.</div><div class=\"term\"><strong>Probe / comparison</strong>One equality test, <code>arr[i] == key</code>. The cost of a search is measured in these.</div><div class=\"term\"><strong>Match</strong>A cell whose value equals the key.</div><div class=\"term\"><strong>Found</strong>The search returns the <em>index</em> of the match.</div><div class=\"term\"><strong>Not found</strong>The search returns <code>-1</code>, a value that can never be a valid index.</div><div class=\"term\"><strong>Early exit</strong>Stopping at the first match instead of examining the rest.</div></div>\r\n        <p>“Linear” describes the cost: in the worst case you look at every one of the <code>n</code> elements, so the work grows in a straight line with the size of the array.</p>\r\n    \r\n      "
  },
  "linear-simple": {
    "id": "linear-simple",
    "title": "In plain language",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · In plain language</span>\r\n        <h2>In plain language</h2>\r\n        <p class=\"lede\">Open the drawers one by one until you find what you are looking for, or run out of drawers.</p>\r\n        \r\n        <div class=\"paper-card\">\r\n          <p>Imagine a row of ten closed drawers and you are looking for the one containing your keys. You have no idea which it is, so you open the first drawer, then the second, then the third, until you find them. If you open the last drawer and still have not found them, they are not in the row.</p>\r\n          <p>That is the entire algorithm. There is no clever shortcut because nothing tells you where to look. The only way to be sure a value is <em>not</em> there is to have looked everywhere.</p>\r\n        </div>\r\n        <p>Here is the search for <code>18</code>, one step at a time. Crossed-out cells are ruled out. The labelled cell, marked <code>i</code>, is the one being examined.</p>\r\n        <div class=\"worked-visual\" aria-label=\"Linear search for 18\"><div class=\"worked-step\"><h4>Step 1: look at index 0: is 63 == 18? No</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Looking at index 0\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 i\">63</span><span class=\"cell\" data-label=\"1\">29</span><span class=\"cell\" data-label=\"2\">85</span><span class=\"cell\" data-label=\"3\">72</span><span class=\"cell\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div></div><div class=\"worked-step\"><h4>Step 2: look at index 1: is 29 == 18? No</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Looking at index 1\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">63</span><span class=\"cell bound\" data-label=\"1 i\">29</span><span class=\"cell\" data-label=\"2\">85</span><span class=\"cell\" data-label=\"3\">72</span><span class=\"cell\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div></div><div class=\"worked-step\"><h4>Step 3: look at index 2: is 85 == 18? No</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Looking at index 2\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">63</span><span class=\"cell discarded\" data-label=\"1\">29</span><span class=\"cell bound\" data-label=\"2 i\">85</span><span class=\"cell\" data-label=\"3\">72</span><span class=\"cell\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div></div><div class=\"worked-step\"><h4>Step 4: look at index 3: is 72 == 18? No</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Looking at index 3\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">63</span><span class=\"cell discarded\" data-label=\"1\">29</span><span class=\"cell discarded\" data-label=\"2\">85</span><span class=\"cell bound\" data-label=\"3 i\">72</span><span class=\"cell\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div></div><div class=\"worked-step\"><h4>Step 5: look at index 4: is 18 == 18? Yes, found</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Looking at index 4\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">63</span><span class=\"cell discarded\" data-label=\"1\">29</span><span class=\"cell discarded\" data-label=\"2\">85</span><span class=\"cell discarded\" data-label=\"3\">72</span><span class=\"cell key\" data-label=\"4 i\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div></div></div>\r\n        <p>It took <strong>5 comparisons</strong>: four misses and one hit, and the search stopped immediately at the hit. The five cells to the right of it were never looked at.</p>\r\n    \r\n      "
  },
  "linear-idea": {
    "id": "linear-idea",
    "title": "The main idea",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · The main idea</span>\r\n        <h2>The main idea</h2>\r\n        \r\n        <p>Linear search is built on one statement that stays true all the way through, called a <strong>loop invariant</strong>:</p>\r\n        <div class=\"callout\"><strong>Invariant:</strong> when the loop is about to examine index <code>i</code>, the key is <em>not</em> in cells <code>0 … i − 1</code>.</div>\r\n        <div class=\"worked-visual\" aria-label=\"The ruled-out region grows\"><div class=\"worked-step\"><h4>The loop is about to examine index 0: nothing is ruled out yet</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"before index 0\"><div class=\"array\"><span class=\"cell\" data-label=\"0 i\">63</span><span class=\"cell\" data-label=\"1\">29</span><span class=\"cell\" data-label=\"2\">85</span><span class=\"cell\" data-label=\"3\">72</span><span class=\"cell\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div></div><div class=\"worked-step\"><h4>The loop is about to examine index 3: indexes 0..2 are ruled out</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"before index 3\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">63</span><span class=\"cell discarded\" data-label=\"1\">29</span><span class=\"cell discarded\" data-label=\"2\">85</span><span class=\"cell\" data-label=\"3 i\">72</span><span class=\"cell\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div></div><div class=\"worked-step\"><h4>The loop is about to examine index 7: indexes 0..6 are ruled out</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"before index 7\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">63</span><span class=\"cell discarded\" data-label=\"1\">29</span><span class=\"cell discarded\" data-label=\"2\">85</span><span class=\"cell discarded\" data-label=\"3\">72</span><span class=\"cell discarded\" data-label=\"4\">18</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7 i\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div></div></div>\r\n        <p>Each failed comparison enlarges the ruled-out region by one cell. That has two consequences:</p>\r\n        <ul>\r\n          <li>If a comparison succeeds at index <code>i</code>, the key is there, and returning <code>i</code> is correct.</li>\r\n          <li>If the loop ends, <em>every</em> cell has been ruled out, so returning <code>-1</code> is correct. The <code>return -1</code> belongs <strong>after</strong> the loop, never inside it.</li>\r\n        </ul>\r\n        <div class=\"flow-steps\"><div class=\"flow-step\"><b>1</b><div>Start at index 0.</div></div><div class=\"flow-step\"><b>2</b><div>Compare <code>arr[i]</code> with the key.</div></div><div class=\"flow-step\"><b>3</b><div>Equal? Return <code>i</code>. Not equal? Move to <code>i + 1</code>.</div></div><div class=\"flow-step\"><b>4</b><div>Past the last index? Return <code>-1</code>.</div></div></div>\r\n    \r\n      "
  },
  "linear-movements": {
    "id": "linear-movements",
    "title": "Comparison, match, return",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · Comparison, match, return</span>\r\n        <h2>Comparison, match, return</h2>\r\n        \r\n        <p class=\"lede\">A linear search only ever does two things: compare and return. Being precise about both is what makes a trace correct.</p>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Comparison</strong><code>arr[i] == key</code>. Only equality is tested, never <code>&lt;</code> or <code>&gt;</code>, which is why the order of the array does not matter.</div><div class=\"term\"><strong>Match</strong>The comparison is true. The search ends here.</div><div class=\"term\"><strong>Return value</strong>The index on success, <code>-1</code> on failure. Some programs return <code>true</code> / <code>false</code> instead; that changes the answer's type, not the work done.</div><div class=\"term\"><strong>Miss</strong>A false comparison. The search moves on.</div></div>\r\n        <h3>Why <code>-1</code>?</h3>\r\n        <p>The return value has to tell the caller two things with one number: <em>where</em>, or <em>not found</em>. Every real index is <code>0</code> or more, so <code>-1</code> can never be confused with one. Returning <code>0</code> for “not found” would be a bug, because index 0 is a real position.</p>\r\n        <h3>The same array, four searches</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Key</th><th>Returned</th><th>Comparisons</th><th>Why</th></tr></thead><tbody><tr><td>63</td><td>0</td><td>1</td><td>first cell: the best case</td></tr><tr><td>18</td><td>4</td><td>5</td><td>found in the middle</td></tr><tr><td>32</td><td>9</td><td>10</td><td>last cell: the worst case that succeeds</td></tr><tr><td>31</td><td>-1</td><td>10</td><td>not present: the worst case</td></tr></tbody></table></div>\r\n        <p>Notice that the answer is not decided by how big the array is but by <strong>where</strong> the key happens to sit.</p>\r\n    \r\n      "
  },
  "linear": {
    "id": "linear",
    "title": "Check one position at a time",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search</span>\r\n        <h2 id=\"linear-concept\">Check one position at a time</h2>\r\n        <p class=\"lede\">Linear search—also called sequential search—starts at index 0 and compares the key with each value until it finds a match or reaches the end.</p>\r\n\r\n        <h3 id=\"linear-illustration\">Illustration</h3>\r\n        <p>Search for <code>18</code> from left to right in the unsorted lecture array. The highlighted cell is where the search stops.</p>\r\n        <div class=\"array-wrap\"><div class=\"array\"><span class=\"cell\">63</span><span class=\"cell\">29</span><span class=\"cell\">85</span><span class=\"cell\">72</span><span class=\"cell key\" data-label=\"found\">18</span><span class=\"cell\">42</span><span class=\"cell\">23</span><span class=\"cell\">54</span><span class=\"cell\">8</span><span class=\"cell\">32</span></div></div>\r\n\r\n        <h3 id=\"linear-trace\">Trace table</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Comparison</th><th>Index</th><th>Question</th><th>Decision</th></tr></thead><tbody>\r\n          <tr><td>1</td><td>0</td><td><code>63 == 18</code></td><td>No · continue</td></tr>\r\n          <tr><td>2</td><td>1</td><td><code>29 == 18</code></td><td>No · continue</td></tr>\r\n          <tr><td>3</td><td>2</td><td><code>85 == 18</code></td><td>No · continue</td></tr>\r\n          <tr><td>4</td><td>3</td><td><code>72 == 18</code></td><td>No · continue</td></tr>\r\n          <tr><td>5</td><td>4</td><td><code>18 == 18</code></td><td>Yes · return 4</td></tr>\r\n        </tbody></table></div>\r\n\r\n        <h3 id=\"linear-implementation\">Implementation</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Iterative linear search</span></div><pre><code><span class=\"kw\">public static</span> <span class=\"ty\">int</span> linearSearch(<span class=\"ty\">int</span>[] arr, <span class=\"ty\">int</span> key) {\r\n    <span class=\"cm\">// Visit every valid index from left to right.</span>\r\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; arr.length; i++) {\r\n        <span class=\"cm\">// Stop immediately when the current value matches.</span>\r\n        <span class=\"kw\">if</span> (arr[i] == key) <span class=\"kw\">return</span> i;\r\n    }\r\n    <span class=\"cm\">// Reaching this line means that no position matched.</span>\r\n    <span class=\"kw\">return</span> -1;\r\n}</code></pre></div>\r\n        <details><summary>Recursive implementation</summary><div class=\"answer\"><pre><code><span class=\"kw\">public static</span> <span class=\"ty\">int</span> linearSearchRec(<span class=\"ty\">int</span>[] arr, <span class=\"ty\">int</span> key, <span class=\"ty\">int</span> index) {\r\n    <span class=\"cm\">// Base case: index moved beyond the final position.</span>\r\n    <span class=\"kw\">if</span> (index == arr.length) <span class=\"kw\">return</span> -1;\r\n    <span class=\"cm\">// Success case: the current position contains the key.</span>\r\n    <span class=\"kw\">if</span> (arr[index] == key) <span class=\"kw\">return</span> index;\r\n    <span class=\"cm\">// Smaller problem: search from the next index.</span>\r\n    <span class=\"kw\">return</span> linearSearchRec(arr, key, index + 1);\r\n}</code></pre></div></details>\r\n\r\n        <div class=\"audit-grid\">\r\n          <div class=\"from-scratch\"><strong>Write it from scratch</strong><ol><li>Accept the array and key.</li><li>Loop from index 0 to <code>length - 1</code>.</li><li>Return the matching index.</li><li>After the loop, return <code>-1</code>.</li></ol></div>\r\n          <div class=\"direction-card\"><strong>Ascending or descending?</strong><p>Linear search uses equality only, so the same code works for ascending, descending, or unsorted arrays.</p></div>\r\n          <div class=\"debug-list\"><strong>Debug checklist</strong><ul><li>Use <code>i &lt; arr.length</code>, not <code>&lt;=</code>.</li><li>Put <code>return -1</code> after the loop.</li><li>Start recursion with index <code>0</code>.</li></ul></div>\r\n        </div>\r\n\r\n        <h3 id=\"linear-example\">Worked example · key absent</h3>\r\n        <p>Search for <code>31</code> in the same unsorted array. Every cell is crossed out because each one failed its equality test. The label under a cell shows its index and the order in which it was checked.</p>\r\n        <div class=\"worked-visual\"><div class=\"worked-step\"><h4>Complete scan</h4><div class=\"array-wrap\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0 · 1st\">63</span><span class=\"cell discarded\" data-label=\"1 · 2nd\">29</span><span class=\"cell discarded\" data-label=\"2 · 3rd\">85</span><span class=\"cell discarded\" data-label=\"3 · 4th\">72</span><span class=\"cell discarded\" data-label=\"4 · 5th\">18</span><span class=\"cell discarded\" data-label=\"5 · 6th\">42</span><span class=\"cell discarded\" data-label=\"6 · 7th\">23</span><span class=\"cell discarded\" data-label=\"7 · 8th\">54</span><span class=\"cell discarded\" data-label=\"8 · 9th\">8</span><span class=\"cell discarded\" data-label=\"9 · 10th\">32</span></div></div><div class=\"result-line\">No value equals 31 → return <code>-1</code> after 10 comparisons.</div></div></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Indexes tested</th><th>Values tested</th><th>Match?</th><th>Return</th></tr></thead><tbody><tr><td>0 → 9</td><td>63, 29, 85, 72, 18, 42, 23, 54, 8, 32</td><td>No</td><td><code>-1</code></td></tr></tbody></table></div>\r\n        <div class=\"properties\"><div class=\"property\"><small>Best</small><b>O(1)</b></div><div class=\"property\"><small>Average</small><b>O(n)</b></div><div class=\"property\"><small>Worst</small><b>O(n)</b></div><div class=\"property\"><small>Sorted?</small><b>Not needed</b></div><div class=\"property\"><small>Iterative space</small><b>O(1)</b></div><div class=\"property\"><small>Recursive space</small><b>O(n)</b></div><div class=\"property\"><small>Duplicates</small><b>First match</b></div><div class=\"property\"><small>Input changed?</small><b>No</b></div></div>\r\n\r\n        <h3 id=\"linear-strings\">Duplicates, Strings, and objects</h3><p><strong>Duplicates.</strong> The loop returns at the <em>first</em> match. In <code>[7, 3, 7, 1]</code> searching for <code>7</code> returns <code>0</code>; index 2 is never examined.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Searching for 7 stops at index 0; index 2 is never visited\"><div class=\"array\"><span class=\"cell key\" data-label=\"0\">7</span><span class=\"cell\" data-label=\"1\">3</span><span class=\"cell discarded\" data-label=\"2\">7</span><span class=\"cell\" data-label=\"3\">1</span></div></div><p><strong>Strings and objects.</strong> For primitive cells <code>==</code> compares values. For reference cells it compares references, so text must be compared with <code>.equals</code>.</p><div class=\"code-panel\"><div class=\"code-head\"><span>Search a String array</span></div><pre><code><span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"ty\">int</span> linearSearchStrings(<span class=\"ty\">String</span>[] names, <span class=\"ty\">String</span> key) {\r\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; names.length; i++) {\r\n        <span class=\"cm\">// Unfilled cells are null; calling equals on null would throw.</span>\r\n        <span class=\"cm\">// equals compares the text. == would only compare references.</span>\r\n        <span class=\"kw\">if</span> (names[i] != <span class=\"kw\">null</span> &amp;&amp; names[i].equals(key)) <span class=\"kw\">return</span> i;\r\n    }\r\n    <span class=\"kw\">return</span> -1;\r\n}</code></pre></div><div class=\"table-scroll\"><table><thead><tr><th>Call</th><th>Array</th><th>Result</th><th>Reason</th></tr></thead><tbody><tr><td><code>linearSearchStrings(names, &quot;Raj&quot;)</code></td><td><code>{&quot;Ana&quot;, null, &quot;Raj&quot;}</code></td><td><code>2</code></td><td>Index 1 is skipped safely because it is null.</td></tr><tr><td><code>linearSearchStrings(names, &quot;Zed&quot;)</code></td><td>same</td><td><code>-1</code></td><td>All three positions were checked.</td></tr></tbody></table></div><details><summary>Quick check: why test <code>names[i] != null</code> first?</summary><div class=\"answer\">A cell that was never assigned holds <code>null</code>. Calling <code>.equals</code> through it throws <code>NullPointerException</code>. The <code>&amp;&amp;</code> stops before that call.</div></details><details><summary>Quick check: can <code>new String(&quot;Raj&quot;) == &quot;Raj&quot;</code> be true?</summary><div class=\"answer\">No. <code>new String(...)</code> creates a different object, so the references differ even though the text matches. <code>.equals</code> returns true.</div></details>\r\n\r\n        <h3 id=\"linear-questions\">Questions</h3>\r\n        <details><summary>When is linear search a sensible choice?</summary><div class=\"answer\">When the collection is small, unsorted, or searched only once. Sorting first would add unnecessary work.</div></details>\r\n        <details><summary>What are the best and worst cases?</summary><div class=\"answer\">Best: the key is at index 0, so one comparison gives <code>O(1)</code>. Worst: the key is last or absent, so all <code>n</code> values are checked: <code>O(n)</code>.</div></details>\r\n        <div class=\"method-summary\"><strong>Linear search in one sentence</strong><p>Check each value in order; return its index on a match, otherwise return <code>-1</code> after the final position.</p></div>\r\n      "
  },
  "linear-variants": {
    "id": "linear-variants",
    "title": "Variations: first, last, all, count",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · Variations: first, last, all, count</span>\r\n        <h2>Variations: first, last, all, count</h2>\r\n        \r\n        <p>When the key appears more than once, “find it” is ambiguous. Linear search handles every version with a small change, and they are all the same walk along the array. Take <code>[7, 3, 7, 1, 7]</code> and the key <code>7</code>:</p>\r\n        <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"7 appears at indexes 0, 2 and 4\"><div class=\"array\"><span class=\"cell key\" data-label=\"0\">7</span><span class=\"cell\" data-label=\"1\">3</span><span class=\"cell key\" data-label=\"2\">7</span><span class=\"cell\" data-label=\"3\">1</span><span class=\"cell key\" data-label=\"4\">7</span></div></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Question</th><th>How</th><th>Answer</th><th>Comparisons</th></tr></thead><tbody><tr><td>First match</td><td>Return as soon as you find it (the standard version).</td><td>index <strong>0</strong></td><td>1</td></tr><tr><td>Last match</td><td>Do not stop: remember the latest index, or search from the right.</td><td>index <strong>4</strong></td><td>5</td></tr><tr><td>Every match</td><td>Do not stop: collect each matching index.</td><td>indexes <strong>[0, 2, 4]</strong></td><td>5</td></tr><tr><td>How many</td><td>Do not stop: add 1 to a counter for each match.</td><td><strong>3</strong> times</td><td>5</td></tr></tbody></table></div>\r\n        <div class=\"two-col\">\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>First match (stops early)</span></div><pre><code><span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; arr.length; i++) {\r\n    <span class=\"kw\">if</span> (arr[i] == key) <span class=\"kw\">return</span> i;\r\n}\r\n<span class=\"kw\">return</span> -1;</code></pre></div>\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>Last match (never stops early)</span></div><pre><code><span class=\"ty\">int</span> found = -1;\r\n<span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; arr.length; i++) {\r\n    <span class=\"kw\">if</span> (arr[i] == key) found = i;\r\n}\r\n<span class=\"kw\">return</span> found;</code></pre></div>\r\n        </div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Count every occurrence</span></div><pre><code><span class=\"ty\">int</span> count = 0;\r\n<span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; arr.length; i++) {\r\n    <span class=\"kw\">if</span> (arr[i] == key) count++;\r\n}\r\n<span class=\"kw\">return</span> count;</code></pre></div>\r\n        <p>The first-match version is the only one that can finish early. Any question that needs <em>all</em> the matches, or the last, forces a full scan every time: <code>n</code> comparisons whether or not the key is present.</p>\r\n    \r\n      "
  },
  "linear-examples": {
    "id": "linear-examples",
    "title": "Worked examples",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · Worked examples</span>\r\n        <h2>Worked examples</h2>\r\n        <p class=\"lede\">Six searches: best case, typical case, worst case that succeeds, failure, Strings, and the unsorted array from Test 1.</p>\r\n        <article class=\"example-card\"><h3>Key in the first cell · search <code>63</code></h3><p>The luckiest possible search.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [63, 29, 85, 72, 18, 42, 23, 54, 8, 32]\"><div class=\"array\"><span class=\"cell key\" data-label=\"0\">63</span><span class=\"cell\" data-label=\"1\">29</span><span class=\"cell\" data-label=\"2\">85</span><span class=\"cell\" data-label=\"3\">72</span><span class=\"cell\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div><div class=\"table-scroll\"><table><thead><tr><th>Comparison</th><th>Index</th><th>Question</th><th>Decision</th></tr></thead><tbody><tr><td>1</td><td>0</td><td><code>63 == 63</code></td><td>Yes: return 0</td></tr></tbody></table></div><div class=\"result-line\"><code>1</code> comparison, returns <code>0</code>. This is the <strong>best case</strong>: <code>O(1)</code>, no matter how long the array is.</div></article><article class=\"example-card\"><h3>Key in the middle · search <code>18</code></h3><p>The ordinary case.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [63, 29, 85, 72, 18, 42, 23, 54, 8, 32]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">63</span><span class=\"cell\" data-label=\"1\">29</span><span class=\"cell\" data-label=\"2\">85</span><span class=\"cell\" data-label=\"3\">72</span><span class=\"cell key\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div><div class=\"table-scroll\"><table><thead><tr><th>Comparison</th><th>Index</th><th>Question</th><th>Decision</th></tr></thead><tbody><tr><td>1</td><td>0</td><td><code>63 == 18</code></td><td>No: continue</td></tr><tr><td>2</td><td>1</td><td><code>29 == 18</code></td><td>No: continue</td></tr><tr><td>3</td><td>2</td><td><code>85 == 18</code></td><td>No: continue</td></tr><tr><td>4</td><td>3</td><td><code>72 == 18</code></td><td>No: continue</td></tr><tr><td>5</td><td>4</td><td><code>18 == 18</code></td><td>Yes: return 4</td></tr></tbody></table></div><div class=\"result-line\"><code>5</code> comparisons, returns <code>4</code>. The cost is the key's position plus one.</div></article><article class=\"example-card\"><h3>Key in the last cell · search <code>32</code></h3><p>The unluckiest search that still succeeds.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [63, 29, 85, 72, 18, 42, 23, 54, 8, 32]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">63</span><span class=\"cell\" data-label=\"1\">29</span><span class=\"cell\" data-label=\"2\">85</span><span class=\"cell\" data-label=\"3\">72</span><span class=\"cell\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell key\" data-label=\"9\">32</span></div></div><div class=\"table-scroll\"><table><thead><tr><th>Comparison</th><th>Index</th><th>Question</th><th>Decision</th></tr></thead><tbody><tr><td>1</td><td>0</td><td><code>63 == 32</code></td><td>No: continue</td></tr><tr><td>2</td><td>1</td><td><code>29 == 32</code></td><td>No: continue</td></tr><tr><td>3</td><td>2</td><td><code>85 == 32</code></td><td>No: continue</td></tr><tr><td>4</td><td>3</td><td><code>72 == 32</code></td><td>No: continue</td></tr><tr><td>5</td><td>4</td><td><code>18 == 32</code></td><td>No: continue</td></tr><tr><td>6</td><td>5</td><td><code>42 == 32</code></td><td>No: continue</td></tr><tr><td>7</td><td>6</td><td><code>23 == 32</code></td><td>No: continue</td></tr><tr><td>8</td><td>7</td><td><code>54 == 32</code></td><td>No: continue</td></tr><tr><td>9</td><td>8</td><td><code>8 == 32</code></td><td>No: continue</td></tr><tr><td>10</td><td>9</td><td><code>32 == 32</code></td><td>Yes: return 9</td></tr></tbody></table></div><div class=\"result-line\"><code>10</code> comparisons: all <code>n = 10</code> of them. A <strong>worst case</strong>: <code>O(n)</code>.</div></article><article class=\"example-card\"><h3>Key not present · search <code>31</code></h3><p>Failure is the most expensive outcome, because only a full scan can prove absence.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [63, 29, 85, 72, 18, 42, 23, 54, 8, 32]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">63</span><span class=\"cell\" data-label=\"1\">29</span><span class=\"cell\" data-label=\"2\">85</span><span class=\"cell\" data-label=\"3\">72</span><span class=\"cell\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">23</span><span class=\"cell\" data-label=\"7\">54</span><span class=\"cell\" data-label=\"8\">8</span><span class=\"cell\" data-label=\"9\">32</span></div></div><div class=\"table-scroll\"><table><thead><tr><th>Comparison</th><th>Index</th><th>Question</th><th>Decision</th></tr></thead><tbody><tr><td>1</td><td>0</td><td><code>63 == 31</code></td><td>No: continue</td></tr><tr><td>2</td><td>1</td><td><code>29 == 31</code></td><td>No: continue</td></tr><tr><td>3</td><td>2</td><td><code>85 == 31</code></td><td>No: continue</td></tr><tr><td>4</td><td>3</td><td><code>72 == 31</code></td><td>No: continue</td></tr><tr><td>5</td><td>4</td><td><code>18 == 31</code></td><td>No: continue</td></tr><tr><td>6</td><td>5</td><td><code>42 == 31</code></td><td>No: continue</td></tr><tr><td>7</td><td>6</td><td><code>23 == 31</code></td><td>No: continue</td></tr><tr><td>8</td><td>7</td><td><code>54 == 31</code></td><td>No: continue</td></tr><tr><td>9</td><td>8</td><td><code>8 == 31</code></td><td>No: continue</td></tr><tr><td>10</td><td>9</td><td><code>32 == 31</code></td><td>No: continue</td></tr><tr><td></td><td></td><td>end of the array</td><td><strong>return -1</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>10</code> comparisons and returns <code>-1</code>. Also the <strong>worst case</strong>: <code>O(n)</code>.</div></article><article class=\"example-card\"><h3>Searching Strings · find <code>\"Lee\"</code> in <code>[Raj, Ana, Lee, Mike, Zed]</code></h3><p>Same algorithm, but the comparison must be <code>.equals</code>, not <code>==</code>.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [Raj, Ana, Lee, Mike, Zed]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">Raj</span><span class=\"cell\" data-label=\"1\">Ana</span><span class=\"cell key\" data-label=\"2\">Lee</span><span class=\"cell\" data-label=\"3\">Mike</span><span class=\"cell\" data-label=\"4\">Zed</span></div></div><div class=\"table-scroll\"><table><thead><tr><th>Comparison</th><th>Index</th><th>Question</th><th>Decision</th></tr></thead><tbody><tr><td>1</td><td>0</td><td><code>Raj == Lee</code></td><td>No: continue</td></tr><tr><td>2</td><td>1</td><td><code>Ana == Lee</code></td><td>No: continue</td></tr><tr><td>3</td><td>2</td><td><code>Lee == Lee</code></td><td>Yes: return 2</td></tr></tbody></table></div><div class=\"result-line\"><code>3</code> comparisons, returns <code>2</code>. For Strings write <code>arr[i].equals(key)</code>: <code>==</code> compares references, not letters.</div></article><article class=\"example-card\"><h3>The nine values from Test 1 · search <code>88</code></h3><p>Unsorted, and 88 is not in it. Binary search cannot be used here, because the array is not sorted.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [50, 83, 76, 6, 32, 90, 12, 2, 59]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">50</span><span class=\"cell\" data-label=\"1\">83</span><span class=\"cell\" data-label=\"2\">76</span><span class=\"cell\" data-label=\"3\">6</span><span class=\"cell\" data-label=\"4\">32</span><span class=\"cell\" data-label=\"5\">90</span><span class=\"cell\" data-label=\"6\">12</span><span class=\"cell\" data-label=\"7\">2</span><span class=\"cell\" data-label=\"8\">59</span></div></div><div class=\"table-scroll\"><table><thead><tr><th>Comparison</th><th>Index</th><th>Question</th><th>Decision</th></tr></thead><tbody><tr><td>1</td><td>0</td><td><code>50 == 88</code></td><td>No: continue</td></tr><tr><td>2</td><td>1</td><td><code>83 == 88</code></td><td>No: continue</td></tr><tr><td>3</td><td>2</td><td><code>76 == 88</code></td><td>No: continue</td></tr><tr><td>4</td><td>3</td><td><code>6 == 88</code></td><td>No: continue</td></tr><tr><td>5</td><td>4</td><td><code>32 == 88</code></td><td>No: continue</td></tr><tr><td>6</td><td>5</td><td><code>90 == 88</code></td><td>No: continue</td></tr><tr><td>7</td><td>6</td><td><code>12 == 88</code></td><td>No: continue</td></tr><tr><td>8</td><td>7</td><td><code>2 == 88</code></td><td>No: continue</td></tr><tr><td>9</td><td>8</td><td><code>59 == 88</code></td><td>No: continue</td></tr><tr><td></td><td></td><td>end of the array</td><td><strong>return -1</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>9</code> comparisons and <code>-1</code>: every cell had to be checked. If the array were sorted, binary search would settle the same question in 4 steps (see the binary-search chapter).</div></article>\r\n      "
  },
  "linear-properties": {
    "id": "linear-properties",
    "title": "Properties",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · Properties</span>\r\n        <h2>Properties</h2>\r\n        \r\n        <div class=\"properties\"><div class=\"property\"><small>Best time</small><b>O(1)</b></div><div class=\"property\"><small>Average time</small><b>O(n)</b></div><div class=\"property\"><small>Worst time</small><b>O(n)</b></div><div class=\"property\"><small>Extra space</small><b>O(1)</b></div><div class=\"property\"><small>Needs sorted data</small><b>No</b></div><div class=\"property\"><small>Works on</small><b>Any array or list</b></div><div class=\"property\"><small>Compares with</small><b>== / equals</b></div><div class=\"property\"><small>Finds</small><b>First match</b></div></div>\r\n        <h3>No precondition</h3>\r\n        <p>It needs the data in no particular order, and it does not care whether the array is ascending, descending or random. This is its great strength: it always works.</p>\r\n        <h3>Simple and safe</h3>\r\n        <p>There is no arithmetic on indexes, nothing to overflow, and no way to skip over the answer. It is hard to get wrong.</p>\r\n        <h3>Any structure you can walk</h3>\r\n        <p>It needs only “give me the next element”, so it works on a linked list, a file read line by line, or any stream, where jumping to the middle (as binary search does) is impossible.</p>\r\n        <h3>The price is time</h3>\r\n        <p>The cost grows in a straight line with the number of values. Search a million values and a miss costs a million comparisons.</p>\r\n    \r\n      "
  },
  "linear-complexity": {
    "id": "linear-complexity",
    "title": "Why those complexities occur",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · Why those complexities occur</span>\r\n        <h2>Why those complexities occur</h2>\r\n        \r\n        <div class=\"complexity-grid\"><div class=\"complexity-item\"><strong>Best case · O(1)</strong>The key is in the first cell: one comparison, whatever the size.</div><div class=\"complexity-item\"><strong>Worst case · O(n)</strong>The key is in the last cell or missing: all <code>n</code> comparisons.</div></div>\r\n        <h3>The cost depends on where the key is</h3>\r\n        <p>For our ten values, the number of comparisons needed to find a key is its index plus one. Here is that cost for a key in each position:</p>\r\n        <figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Comparisons needed when the key is at each index: 1 to 10\"><div class=\"bar\" style=\"--p:0.100\"><i></i><b>1</b><small>idx 0</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>2</b><small>idx 1</small></div><div class=\"bar\" style=\"--p:0.300\"><i></i><b>3</b><small>idx 2</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>4</b><small>idx 3</small></div><div class=\"bar\" style=\"--p:0.500\"><i></i><b>5</b><small>idx 4</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>6</b><small>idx 5</small></div><div class=\"bar\" style=\"--p:0.700\"><i></i><b>7</b><small>idx 6</small></div><div class=\"bar\" style=\"--p:0.800\"><i></i><b>8</b><small>idx 7</small></div><div class=\"bar\" style=\"--p:0.900\"><i></i><b>9</b><small>idx 8</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>10</b><small>idx 9</small></div></div></figure>\r\n        <p class=\"fig-cap\">A taller bar means more comparisons. A key that is absent costs the full height of the last bar, 10.</p>\r\n        <h3>The average case</h3>\r\n        <p>If the key is equally likely to be in any cell, the average cost is the middle of 1 and 10:</p>\r\n        <div class=\"formula\">(1 + 2 + … + n) / n = (n + 1) / 2 → O(n)</div>\r\n        <p>For ten values that is 5.5 comparisons. Halving the cost still leaves a cost proportional to <code>n</code>, so the order of growth is linear.</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>n (values)</th><th>Worst case</th><th>Average (key present)</th><th>Absent key</th></tr></thead><tbody><tr><td>10</td><td>10</td><td>5.5</td><td>10</td></tr><tr><td>100</td><td>100</td><td>50.5</td><td>100</td></tr><tr><td>1,000</td><td>1,000</td><td>500.5</td><td>1,000</td></tr><tr><td>1,000,000</td><td>1,000,000</td><td>500,000.5</td><td>1,000,000</td></tr></tbody></table></div>\r\n        <p>The pattern to remember: <strong>ten times as many values means ten times as many comparisons</strong>. Compare that with the next chapter, where ten times as many values adds only about 3 more comparisons.</p>\r\n        <h3>Space</h3>\r\n        <p>An index and the key: <code>O(1)</code> extra space (the recursive version uses <code>O(n)</code> stack space).</p>\r\n    \r\n      "
  },
  "linear-when": {
    "id": "linear-when",
    "title": "When to use it",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · When to use it</span>\r\n        <h2>When to use it</h2>\r\n        \r\n        <div class=\"use-grid\"><div class=\"use good\"><strong>A good choice</strong>The data is <strong>not sorted</strong> and is searched only once or twice; small collections (a handful of values); a quick check inside a bigger program; data in a structure with no random access (linked list, file); when you need the first match, or all matches.</div><div class=\"use poor\"><strong>A poor choice</strong>A large array searched many times (sort it once, then use binary search); when the data is already sorted (binary search is far faster); when speed matters and you can organise the data in advance.</div></div>\r\n        <p>The honest comparison: sorting an array first costs about <code>n log n</code>. If you will only search once, scanning (<code>n</code>) is cheaper than sorting and then binary searching. If you will search many times, the one-off sort pays for itself, as the binary-search chapter shows with numbers.</p>\r\n    \r\n      "
  },
  "linear-mistakes": {
    "id": "linear-mistakes",
    "title": "Common mistakes",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · Common mistakes</span>\r\n        <h2>Common mistakes</h2>\r\n        <div class=\"mistake\"><span class=\"mistake-no\">1</span><div><strong>Returning <code>-1</code> inside the loop.</strong><br><code>for (...) { if (arr[i] == key) return i; else return -1; }</code> gives up after the <em>first</em> cell. The failure return belongs after the loop.</div></div><div class=\"mistake\"><span class=\"mistake-no\">2</span><div><strong>Looping to <code>i &lt;= arr.length</code>.</strong><br>Index <code>arr.length</code> does not exist and throws <code>ArrayIndexOutOfBoundsException</code>. Use <code>&lt;</code>.</div></div><div class=\"mistake\"><span class=\"mistake-no\">3</span><div><strong>Returning <code>0</code> for “not found”.</strong><br>0 is a valid index. Use <code>-1</code>.</div></div><div class=\"mistake\"><span class=\"mistake-no\">4</span><div><strong>Comparing Strings with <code>==</code>.</strong><br>That compares references. Use <code>arr[i].equals(key)</code>; and test for <code>null</code> cells first if the array may have empty slots.</div></div><div class=\"mistake\"><span class=\"mistake-no\">5</span><div><strong>Assuming the array must be sorted.</strong><br>Linear search does not need sorting. Sorting first just to linear search wastes time.</div></div><div class=\"mistake\"><span class=\"mistake-no\">6</span><div><strong>Counting a comparison after the match.</strong><br>The search stops at the match, so the comparison that succeeds is the last one counted.</div></div><div class=\"mistake\"><span class=\"mistake-no\">7</span><div><strong>Returning the value instead of the index.</strong><br>The caller already knows the value (it is the key). The useful information is the position.</div></div><div class=\"mistake\"><span class=\"mistake-no\">8</span><div><strong>Believing it is “slow”.</strong><br>It is only slow on large data searched repeatedly. For ten values it is as fast as anything.</div></div>\r\n      "
  },
  "linear-summary": {
    "id": "linear-summary",
    "title": "A test-ready summary",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · A test-ready summary</span>\r\n        <h2>A test-ready summary</h2>\r\n        \r\n        <div class=\"test-summary\">\r\n          <p>Linear search examines the elements of an array one at a time from the first, comparing each with the key, and returns the index of the first match or -1 if the end is reached without one. It needs no sorted data and works on any collection. Its best case is O(1) (key in the first cell), and its average and worst cases are O(n) (about n / 2 and n comparisons), with O(1) extra space. It is the right choice for small or unsorted data searched rarely, and the wrong choice for large collections searched repeatedly, where sorting once and using binary search is faster.</p>\r\n        </div>\r\n    \r\n      "
  },
  "linear-practice": {
    "id": "linear-practice",
    "title": "Practice",
    "body": "\r\n        <span class=\"section-no\">Searching / Linear search · Practice</span>\r\n        <h2>Practice</h2>\r\n        \r\n        <h3>Guided question</h3>\r\n        <p>Use linear search to find <code>7</code> in <code>[4, 9, 7, 2, 7]</code>. Write each comparison, say what is returned, and count the comparisons.</p>\r\n        <details><summary>Reveal the guided answer</summary><div class=\"answer\"><p><strong>Comparison 1:</strong> <code>4 == 7</code> → no</p><p><strong>Comparison 2:</strong> <code>9 == 7</code> → no</p><p><strong>Comparison 3:</strong> <code>7 == 7</code> → yes, return 2</p><p><strong>Result:</strong> returns 2 after 3 comparisons. The second 7 (index 4) is never examined, because the search stops at the first match.</p></div></details>\r\n        <h3>Independent question</h3>\r\n        <p>Search for <code>12</code> in <code>[8, 3, 9, 5, 12, 1]</code>, then for <code>4</code>. Give the index returned and the number of comparisons for each.</p>\r\n        <ul class=\"checklist\">\r\n          <li>Write the comparison for each index.</li>\r\n          <li>Stop at the first match.</li>\r\n          <li>If there is no match, say why the answer is <code>-1</code>.</li>\r\n        </ul>\r\n        <details><summary>Reveal the independent answer</summary><div class=\"answer\"><p>Key <code>12</code>: returns <strong>4</strong> after <strong>5</strong> comparisons.</p><p>Key <code>4</code>: returns <strong>-1</strong> after <strong>6</strong> comparisons, because every cell had to be checked to prove 4 is absent.</p></div></details>\r\n        <h3>Test-style question</h3>\r\n        <p>How many comparisons does linear search need to decide that <code>88</code> is not in <code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code>? What is the worst-case time complexity in big-O notation?</p>\r\n        <details><summary>Reveal the test-style answer</summary><div class=\"answer\"><p><strong>9 comparisons</strong> (one for every value), returning -1. Worst case: <strong>O(n)</strong>.</p></div></details>\r\n    \r\n      "
  },
  "binary-array": {
    "id": "binary-array",
    "title": "The array we will search",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · The array we will search</span>\r\n        <h2>The array we will search</h2>\r\n        <p class=\"lede\">Ten values, already sorted from smallest to largest: <code>[8, 18, 23, 29, 34, 42, 54, 63, 72, 85]</code>.</p>\r\n        \r\n        <div class=\"paper-card\">\r\n          <div class=\"kicker\">A sorted array of ten values</div>\r\n          <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Sorted array 8, 18, 23, 29, 34, 42, 54, 63, 72, 85\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell\" data-label=\"4\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9\">85</span></div></div>\r\n          <figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"The same values as bars: a perfect staircase\"><div class=\"bar\" style=\"--p:0.094\"><i></i><b>8</b><small>0</small></div><div class=\"bar\" style=\"--p:0.212\"><i></i><b>18</b><small>1</small></div><div class=\"bar\" style=\"--p:0.271\"><i></i><b>23</b><small>2</small></div><div class=\"bar\" style=\"--p:0.341\"><i></i><b>29</b><small>3</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>34</b><small>4</small></div><div class=\"bar\" style=\"--p:0.494\"><i></i><b>42</b><small>5</small></div><div class=\"bar\" style=\"--p:0.635\"><i></i><b>54</b><small>6</small></div><div class=\"bar\" style=\"--p:0.741\"><i></i><b>63</b><small>7</small></div><div class=\"bar\" style=\"--p:0.847\"><i></i><b>72</b><small>8</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>85</b><small>9</small></div></div></figure>\r\n        </div>\r\n        <p>Compare these bars with the random bars in the linear-search chapter. Here the values form a staircase that only goes up. That orderliness is the whole point: <strong>if you look at one cell, the order tells you which side of it the key must be on.</strong> Binary search turns that knowledge into speed.</p>\r\n        <p>We will search for <code>18</code> (present, at index 1) and for <code>31</code> (absent: it falls between 29 and 34).</p>\r\n    \r\n      "
  },
  "binary-definition": {
    "id": "binary-definition",
    "title": "The textbook definition",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · The textbook definition</span>\r\n        <h2>The textbook definition</h2>\r\n        \r\n        <div class=\"paper-card definition\">\r\n          <p><strong>Binary search</strong> finds a value in a <em>sorted</em> array by repeatedly comparing the key with the middle element of the part of the array that could still contain it. If the middle element equals the key the search ends. Otherwise the half that cannot contain the key is discarded, and the search continues in the other half. It returns the index of the key, or <code>-1</code> when no candidates remain.</p>\r\n        </div>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Precondition: sorted</strong>The array must already be in order (ascending, or descending with the comparison flipped). On unsorted data the answer is simply wrong.</div><div class=\"term\"><strong><code>low</code> and <code>high</code></strong>The first and last indexes that could still hold the key. Together they are the <em>search window</em>.</div><div class=\"term\"><strong><code>mid</code></strong>The probe position, the middle of the window: <code>low + (high − low) / 2</code>.</div><div class=\"term\"><strong>Probe</strong>One comparison of the key with <code>arr[mid]</code>.</div><div class=\"term\"><strong>Discard</strong>Throwing away the half that cannot contain the key, by moving <code>low</code> up (<code>mid + 1</code>) or <code>high</code> down (<code>mid − 1</code>).</div><div class=\"term\"><strong>Not found</strong>The window becomes empty: <code>low &gt; high</code>.</div><div class=\"term\"><strong>Invariant</strong>If the key is in the array at all, it is somewhere in <code>low … high</code>.</div></div>\r\n        <p>The name means “two parts”: every probe splits the remaining candidates into two parts and throws one away.</p>\r\n    \r\n      "
  },
  "binary-simple": {
    "id": "binary-simple",
    "title": "In plain language",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · In plain language</span>\r\n        <h2>In plain language</h2>\r\n        <p class=\"lede\">Guess the number I am thinking of by always guessing the middle: each answer throws away half of the possibilities.</p>\r\n        \r\n        <div class=\"paper-card\">\r\n          <p>You have played this game. I think of a number from 1 to 100, and you guess. After each guess I say “higher” or “lower”. A clever player never guesses randomly: she guesses <strong>50</strong>, the middle. Whatever the answer, half of all the numbers are gone at once. Then she guesses the middle of what is left.</p>\r\n          <p>A phone book works the same way. Looking for “Mokoena”, you do not start at page 1: you open the book in the middle, see that you are at “K”, know that M comes later, and ignore everything before that page.</p>\r\n        </div>\r\n        <p>Here is the game for a secret number of <strong>37</strong>:</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Guess no.</th><th>Guess</th><th>Answer</th><th>Numbers still possible</th></tr></thead><tbody><tr><td>1</td><td>50</td><td>too high → guess lower</td><td>100</td></tr><tr><td>2</td><td>25</td><td>too low → guess higher</td><td>49</td></tr><tr><td>3</td><td>37</td><td>equal: found!</td><td>24</td></tr></tbody></table></div>\r\n        <p>Only <strong>3 guesses</strong> were needed out of 100 possibilities. The very worst case for 1 to 100 is 7 guesses, because 100 → 50 → 25 → 12 → 6 → 3 → 1 uses at most seven halvings. A player who guesses 1, 2, 3, … needs up to 100.</p>\r\n        <p>Binary search is exactly this game, played on an array: <code>mid</code> is the guess, “higher / lower” is the comparison with <code>arr[mid]</code>, and the sorted order is what lets a single comparison eliminate half of the array.</p>\r\n    \r\n      "
  },
  "binary-idea": {
    "id": "binary-idea",
    "title": "The main idea",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · The main idea</span>\r\n        <h2>The main idea</h2>\r\n        \r\n        <p>Binary search keeps a <em>window</em> of cells where the key could still be, and each probe shrinks it. The window starts as the whole array and obeys one rule that never breaks:</p>\r\n        <div class=\"callout\"><strong>Invariant:</strong> if the key is in the array, it is inside the window <code>low … high</code>.</div>\r\n        <p>Here is the search for <code>18</code>. Crossed-out cells have been discarded; <code>low</code>, <code>mid</code> and <code>high</code> are labelled. After the first probe, <code>34</code> is larger than the key, so everything from 34 rightwards is discarded. The second probe lands on <code>18</code>.</p>\r\n        <div class=\"worked-visual\" aria-label=\"Binary search for 18\"><div class=\"worked-step\"><h4>Probe 1: low = 0, high = 9, mid = 4; arr[mid] = 34 (34 > 18) → search the left half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 1: window 0 to 9\"><div class=\"array\"><span class=\"cell\" data-label=\"0 low\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell bound\" data-label=\"4 mid\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9 high\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 2: low = 0, high = 3, mid = 1; arr[mid] = 18 (equal) → found it!</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 2: window 0 to 3\"><div class=\"array\"><span class=\"cell\" data-label=\"0 low\">8</span><span class=\"cell key\" data-label=\"1 mid\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3 high\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell discarded\" data-label=\"8\">72</span><span class=\"cell discarded\" data-label=\"9\">85</span></div></div></div></div>\r\n        <h3>Why the middle?</h3>\r\n        <p>Probing the middle guarantees that, whatever the comparison says, <strong>at least half</strong> the window disappears. Probing anywhere else risks removing less. The window for ten values shrinks roughly 10 → 5 → 2 → 1, halving each time, so the number of probes is the number of times you can halve <code>n</code>, about <code>log₂ n</code>.</p>\r\n        <div class=\"halving\" role=\"img\" aria-label=\"Size after each halving: 10, 5, 2, 1\"><div class=\"halve-row\"><span>probe 1</span><div class=\"halve-bar\"><i style=\"width:100.00%\"></i></div><span class=\"halve-n\">10 left</span></div><div class=\"halve-row\"><span>probe 2</span><div class=\"halve-bar\"><i style=\"width:50.00%\"></i></div><span class=\"halve-n\">5 left</span></div><div class=\"halve-row\"><span>probe 3</span><div class=\"halve-bar\"><i style=\"width:20.00%\"></i></div><span class=\"halve-n\">2 left</span></div><div class=\"halve-row\"><span>probe 4</span><div class=\"halve-bar\"><i style=\"width:10.00%\"></i></div><span class=\"halve-n\">1 left</span></div></div>\r\n        <h3>Why the array must be sorted</h3>\r\n        <p>The discarding step is only legal because of order. “<code>34 &gt; 18</code>, so 18 cannot be to the right of 34” is true <em>only</em> if everything to the right of 34 is at least 34. In an unsorted array that statement is false, and binary search would throw away the very cell it was looking for. The mistakes section shows this with a real example.</p>\r\n        <div class=\"flow-steps\"><div class=\"flow-step\"><b>1</b><div>Set <code>low = 0</code>, <code>high = n − 1</code>.</div></div><div class=\"flow-step\"><b>2</b><div>While <code>low ≤ high</code>: compute <code>mid</code>.</div></div><div class=\"flow-step\"><b>3</b><div>Equal to the key? Return <code>mid</code>.</div></div><div class=\"flow-step\"><b>4</b><div>Key larger? <code>low = mid + 1</code>. Key smaller? <code>high = mid − 1</code>.</div></div><div class=\"flow-step\"><b>5</b><div>Window empty? Return <code>-1</code>.</div></div></div>\r\n    \r\n      "
  },
  "binary-movements": {
    "id": "binary-movements",
    "title": "Probe, compare, discard",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · Probe, compare, discard</span>\r\n        <h2>Probe, compare, discard</h2>\r\n        \r\n        <p class=\"lede\">Each loop turn of binary search is three small steps. Keeping them separate makes the trace table easy to write.</p>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Probe</strong>Compute <code>mid</code> and read <code>arr[mid]</code>.</div><div class=\"term\"><strong>Compare</strong>Three possible answers: <code>arr[mid] == key</code> (found), <code>arr[mid] &lt; key</code> (key is to the right), <code>arr[mid] &gt; key</code> (key is to the left).</div><div class=\"term\"><strong>Discard</strong>Move one end of the window past <code>mid</code>: <code>low = mid + 1</code> or <code>high = mid − 1</code>.</div><div class=\"term\"><strong>Iteration</strong>One probe, one comparison outcome and one discard. “After how many iterations?” counts these.</div></div>\r\n        <h3>Why <code>mid + 1</code> and <code>mid − 1</code>, not just <code>mid</code>?</h3>\r\n        <p>The probe at <code>mid</code> has already been compared and failed, so <code>mid</code> itself is ruled out. If you wrote <code>low = mid</code> the window could stay the same size forever, for example with <code>low = 2</code>, <code>high = 3</code>, where <code>mid</code> is 2. Stepping past <code>mid</code> guarantees the window shrinks every time, so the loop must end.</p>\r\n        <h3>Why <code>low + (high − low) / 2</code> and not <code>(low + high) / 2</code>?</h3>\r\n        <p>For small arrays they give the same answer. But <code>low + high</code> can be too big for an <code>int</code>. An <code>int</code> in Java holds numbers up to 2,147,483,647 (about 2.1 billion). With <code>low = 2,000,000,000</code> and <code>high = 2,100,000,000</code>:</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Formula</th><th>Calculation</th><th>Result</th></tr></thead><tbody><tr><td><code>(low + high) / 2</code></td><td><code>2,000,000,000 + 2,100,000,000 = 4,100,000,000</code>: more than the largest <code>int</code>, so Java <em>wraps round</em> to a negative number</td><td><code>-194,967,296</code> → <code>-97,483,648</code> (a negative index: crash)</td></tr><tr><td><code>low + (high − low) / 2</code></td><td><code>2,100,000,000 − 2,000,000,000 = 100,000,000</code>, halved is <code>50,000,000</code>, plus <code>low</code></td><td><strong><code>2,050,000,000</code></strong> (correct)</td></tr></tbody></table></div>\r\n        <p>The second form only ever adds half of the <em>distance</em> between the ends to <code>low</code>, so it can never leave the range of valid indexes. The extra effort costs nothing, so it is the form to always use.</p>\r\n        <h3>Reading a trace</h3>\r\n        <p>In a trace table, the <em>Candidates</em> column is the number of cells in the window, <code>high − low + 1</code>. It roughly halves down each row until it reaches 0 (not found) or the key is hit.</p>\r\n    \r\n      "
  },
  "binary": {
    "id": "binary",
    "title": "Discard half each time",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search</span>\r\n        <h2 id=\"binary-concept\">Discard half each time</h2>\r\n        <p class=\"lede\">Binary search works only on a sorted array. Compare with the middle: go left when the key is smaller, right when it is larger, or stop when equal.</p>\r\n        <div class=\"callout\"><strong>Non-negotiable rule:</strong> if the array is not sorted by the same key, binary search can discard the part that actually contains the answer.</div>\r\n\r\n        <h3 id=\"binary-illustration\">Illustration</h3>\r\n        <div class=\"array-wrap\"><div class=\"array\"><span class=\"cell\" data-label=\"low\">8</span><span class=\"cell key\" data-label=\"2nd mid\">18</span><span class=\"cell\">23</span><span class=\"cell\">29</span><span class=\"cell\" data-label=\"1st mid\">34</span><span class=\"cell\">42</span><span class=\"cell\">54</span><span class=\"cell\">63</span><span class=\"cell\">72</span><span class=\"cell\" data-label=\"high\">85</span></div></div>\r\n        <p>Searching for the highlighted 18. First compare with 34 at index 4 (the 1st midpoint). Because 18 is smaller, indexes 4 to 9 are discarded. The 2nd midpoint is index 1, where 18 is found.</p>\r\n\r\n        <h3 id=\"binary-trace\">Trace table</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Step</th><th>low</th><th>high</th><th>mid</th><th>Value</th><th>Action</th></tr></thead><tbody>\r\n          <tr><td>1</td><td>0</td><td>9</td><td>4</td><td>34</td><td><code>18 &lt; 34</code> → high = 3</td></tr>\r\n          <tr><td>2</td><td>0</td><td>3</td><td>1</td><td>18</td><td>Match → return 1</td></tr>\r\n        </tbody></table></div>\r\n\r\n        <h3 id=\"binary-implementation\">Implementation</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Iterative binary search</span></div><pre><code><span class=\"kw\">public static</span> <span class=\"ty\">int</span> binarySearch(<span class=\"ty\">int</span>[] arr, <span class=\"ty\">int</span> key) {\r\n    <span class=\"cm\">// The active search range includes both endpoints.</span>\r\n    <span class=\"ty\">int</span> low = 0, high = arr.length - 1;\r\n    <span class=\"kw\">while</span> (low &lt;= high) {\r\n        <span class=\"cm\">// This form avoids overflow from (low + high) / 2.</span>\r\n        <span class=\"ty\">int</span> mid = low + (high - low) / 2;\r\n        <span class=\"kw\">if</span> (arr[mid] == key) <span class=\"kw\">return</span> mid;\r\n        <span class=\"cm\">// Ascending order: larger keys can only be on the right.</span>\r\n        <span class=\"kw\">if</span> (arr[mid] &lt; key) low = mid + 1;\r\n        <span class=\"kw\">else</span> high = mid - 1;\r\n    }\r\n    <span class=\"cm\">// The range is empty when low passes high.</span>\r\n    <span class=\"kw\">return</span> -1;\r\n}</code></pre></div>\r\n        <details><summary>Recursive implementation</summary><div class=\"answer\"><pre><code><span class=\"kw\">public static</span> <span class=\"ty\">int</span> binarySearchRec(<span class=\"ty\">int</span>[] arr, <span class=\"ty\">int</span> key,\r\n                                  <span class=\"ty\">int</span> low, <span class=\"ty\">int</span> high) {\r\n    <span class=\"cm\">// Base case: no indexes remain.</span>\r\n    <span class=\"kw\">if</span> (low &gt; high) <span class=\"kw\">return</span> -1;\r\n    <span class=\"ty\">int</span> mid = low + (high - low) / 2;\r\n    <span class=\"kw\">if</span> (arr[mid] == key) <span class=\"kw\">return</span> mid;\r\n    <span class=\"cm\">// Recur into exactly one smaller half.</span>\r\n    <span class=\"kw\">if</span> (key &lt; arr[mid])\r\n        <span class=\"kw\">return</span> binarySearchRec(arr, key, low, mid - 1);\r\n    <span class=\"kw\">return</span> binarySearchRec(arr, key, mid + 1, high);\r\n}</code></pre></div></details>\r\n\r\n        <div class=\"audit-grid\">\r\n          <div class=\"from-scratch\"><strong>Write it from scratch</strong><ol><li>Set <code>low</code> and <code>high</code>.</li><li>Repeat while <code>low &lt;= high</code>.</li><li>Calculate <code>mid</code>.</li><li>Return, move <code>low</code>, or move <code>high</code>.</li><li>Return <code>-1</code>.</li></ol></div>\r\n          <div class=\"direction-card\"><strong>Descending-order change</strong><p>Equality stays the same, but the direction reverses: when <code>key &gt; arr[mid]</code>, set <code>high = mid - 1</code>; otherwise set <code>low = mid + 1</code>.</p><p><strong>Same comparison, opposite decision.</strong> In a descending array the larger values are on the left, so the branches swap. Search for <code>18</code> in <code>[85, 72, 63, 54, 42, 34, 29, 23, 18, 8]</code>:</p><div class=\"table-scroll\"><table><thead><tr><th>Step</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Decision (descending)</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>9</td><td>4</td><td>42</td><td><code>18 &lt; 42</code> → smaller keys are to the right → <code>low = 5</code></td></tr><tr><td>2</td><td>5</td><td>9</td><td>7</td><td>23</td><td><code>18 &lt; 23</code> → <code>low = 8</code></td></tr><tr><td>3</td><td>8</td><td>9</td><td>8</td><td>18</td><td>Match → return <code>8</code></td></tr></tbody></table></div></div>\r\n          <div class=\"debug-list\"><strong>Debug checklist</strong><ul><li>Confirm the array’s ordering first.</li><li>Use <code>mid ± 1</code> so the range shrinks.</li><li>Keep <code>low &lt;= high</code> so a one-cell range is checked.</li></ul></div>\r\n        </div>\r\n\r\n        <h3 id=\"binary-example\">Worked example · key absent</h3>\r\n        <p>Search for <code>31</code> in the sorted array below. Every row shows the complete array; crossed-out cells are outside the active range.</p>\r\n        <div class=\"worked-visual\" aria-label=\"Four-step binary search for 31 in a sorted ten-value array, ending with not found\">\r\n          <div class=\"worked-step\"><h4>Step 1 · low = 0, high = 9, mid = 4</h4><p><code>arr[4] = 34</code>. Because <code>31 &lt; 34</code>, discard index 4 and everything to its right: <code>high = 3</code>.</p><div class=\"array-wrap\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 low\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell key\" data-label=\"4 mid\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell bound\" data-label=\"9 high\">85</span></div></div></div>\r\n          <div class=\"worked-step\"><h4>Step 2 · low = 0, high = 3, mid = 1</h4><p><code>arr[1] = 18</code>. Because <code>31 &gt; 18</code>, discard indexes 0 and 1: <code>low = 2</code>.</p><div class=\"array-wrap\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 low\">8</span><span class=\"cell key\" data-label=\"1 mid\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell bound\" data-label=\"3 high\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell discarded\" data-label=\"8\">72</span><span class=\"cell discarded\" data-label=\"9\">85</span></div></div></div>\r\n          <div class=\"worked-step\"><h4>Step 3 · low = 2, high = 3, mid = 2</h4><p><code>arr[2] = 23</code>. Because <code>31 &gt; 23</code>, set <code>low = 3</code>.</p><div class=\"array-wrap\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">8</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell key bound\" data-label=\"2 low/mid\">23</span><span class=\"cell bound\" data-label=\"3 high\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell discarded\" data-label=\"8\">72</span><span class=\"cell discarded\" data-label=\"9\">85</span></div></div></div>\r\n          <div class=\"worked-step\"><h4>Step 4 · low = high = mid = 3</h4><p><code>arr[3] = 29</code>. Because <code>31 &gt; 29</code>, set <code>low = 4</code>. Now <code>low &gt; high</code>, so no candidate remains.</p><div class=\"array-wrap\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">8</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell discarded\" data-label=\"2\">23</span><span class=\"cell key bound\" data-label=\"3 all\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell discarded\" data-label=\"8\">72</span><span class=\"cell discarded\" data-label=\"9\">85</span></div></div></div>\r\n          <div class=\"result-line\">Result: 31 is absent → return <code>-1</code> after 4 comparisons.</div>\r\n        </div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Step</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Update</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>9</td><td>4</td><td>34</td><td><code>high = 3</code></td></tr><tr><td>2</td><td>0</td><td>3</td><td>1</td><td>18</td><td><code>low = 2</code></td></tr><tr><td>3</td><td>2</td><td>3</td><td>2</td><td>23</td><td><code>low = 3</code></td></tr><tr><td>4</td><td>3</td><td>3</td><td>3</td><td>29</td><td><code>low = 4</code></td></tr></tbody></table></div>\r\n        <h3 id=\"binary-duplicates\">Duplicates · which match is returned?</h3><p>Binary search returns <em>whichever equal value the midpoint lands on first</em>. It is not guaranteed to be the first or the last copy. Search for <code>20</code> in <code>[10, 20, 20, 20, 30]</code>:</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Duplicates example: low 0, high 4, mid 2 holds 20, so index 2 is returned\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 low\">10</span><span class=\"cell\" data-label=\"1\">20</span><span class=\"cell key\" data-label=\"2 mid\">20</span><span class=\"cell\" data-label=\"3\">20</span><span class=\"cell bound\" data-label=\"4 high\">30</span></div></div><div class=\"result-line\"><code>mid = 0 + (4 − 0) / 2 = 2</code> and <code>arr[2] == 20</code> → return <code>2</code> after 1 comparison. Index 1 also holds 20, but it is never reached.</div><p>If a lab needs the <em>first</em> occurrence, keep searching left after a match instead of returning immediately.</p>\r\n        <div class=\"properties\"><div class=\"property\"><small>Best</small><b>O(1)</b></div><div class=\"property\"><small>Average</small><b>O(log n)</b></div><div class=\"property\"><small>Worst</small><b>O(log n)</b></div><div class=\"property\"><small>Sorted?</small><b>Required</b></div><div class=\"property\"><small>Iterative space</small><b>O(1)</b></div><div class=\"property\"><small>Recursive space</small><b>O(log n)</b></div><div class=\"property\"><small>Duplicates</small><b>Any match</b></div><div class=\"property\"><small>Input changed?</small><b>No</b></div></div>\r\n\r\n        <h3 id=\"binary-questions\">Questions</h3>\r\n        <details><summary>Why is binary search faster on large arrays?</summary><div class=\"answer\">Each comparison discards about half of the remaining values, so the number of steps grows logarithmically rather than linearly.</div></details>\r\n        <details><summary>What is the recursive base case for “not found”?</summary><div class=\"answer\"><code>low &gt; high</code>. It means no indexes remain in the current search range.</div></details>\r\n        <div class=\"method-summary\"><strong>Binary search in one sentence</strong><p>On a correctly sorted array, compare with the middle and discard the impossible half until a match is found or the range is empty.</p></div>\r\n      "
  },
  "binary-descending": {
    "id": "binary-descending",
    "title": "Descending order",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · Descending order</span>\r\n        <h2>Descending order</h2>\r\n        \r\n        <p>If the array is sorted from <em>largest</em> to <em>smallest</em>, the logic is the same but the directions swap: a probe that is <em>larger</em> than the key means the key is to the <strong>right</strong>, where the smaller values are.</p>\r\n        <div class=\"two-col\">\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>Ascending array</span></div><pre><code><span class=\"kw\">if</span> (arr[mid] == key) <span class=\"kw\">return</span> mid;\r\n<span class=\"kw\">if</span> (arr[mid] &lt; key) low = mid + 1;\r\n<span class=\"kw\">else</span>                high = mid - 1;</code></pre></div>\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>Descending array</span></div><pre><code><span class=\"kw\">if</span> (arr[mid] == key) <span class=\"kw\">return</span> mid;\r\n<span class=\"kw\">if</span> (arr[mid] &gt; key) low = mid + 1;\r\n<span class=\"kw\">else</span>                high = mid - 1;</code></pre></div>\r\n        </div>\r\n        <p>Only the single comparison changes. Searching for <code>18</code> in the descending array <code>[85, 72, 63, 54, 42, 34, 29, 23, 18, 8]</code>:</p>\r\n        <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"descending array\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">85</span><span class=\"cell\" data-label=\"1\">72</span><span class=\"cell\" data-label=\"2\">63</span><span class=\"cell\" data-label=\"3\">54</span><span class=\"cell\" data-label=\"4\">42</span><span class=\"cell\" data-label=\"5\">34</span><span class=\"cell\" data-label=\"6\">29</span><span class=\"cell\" data-label=\"7\">23</span><span class=\"cell\" data-label=\"8\">18</span><span class=\"cell\" data-label=\"9\">8</span></div></div>\r\n        <div class=\"worked-visual\" aria-label=\"Binary search for 18\"><div class=\"worked-step\"><h4>Probe 1: low = 0, high = 9, mid = 4; arr[mid] = 42 (42 > 18) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 1: window 0 to 9\"><div class=\"array\"><span class=\"cell\" data-label=\"0 low\">85</span><span class=\"cell\" data-label=\"1\">72</span><span class=\"cell\" data-label=\"2\">63</span><span class=\"cell\" data-label=\"3\">54</span><span class=\"cell bound\" data-label=\"4 mid\">42</span><span class=\"cell\" data-label=\"5\">34</span><span class=\"cell\" data-label=\"6\">29</span><span class=\"cell\" data-label=\"7\">23</span><span class=\"cell\" data-label=\"8\">18</span><span class=\"cell\" data-label=\"9 high\">8</span></div></div></div><div class=\"worked-step\"><h4>Probe 2: low = 5, high = 9, mid = 7; arr[mid] = 23 (23 > 18) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 2: window 5 to 9\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">85</span><span class=\"cell discarded\" data-label=\"1\">72</span><span class=\"cell discarded\" data-label=\"2\">63</span><span class=\"cell discarded\" data-label=\"3\">54</span><span class=\"cell discarded\" data-label=\"4\">42</span><span class=\"cell\" data-label=\"5 low\">34</span><span class=\"cell\" data-label=\"6\">29</span><span class=\"cell bound\" data-label=\"7 mid\">23</span><span class=\"cell\" data-label=\"8\">18</span><span class=\"cell\" data-label=\"9 high\">8</span></div></div></div><div class=\"worked-step\"><h4>Probe 3: low = 8, high = 9, mid = 8; arr[mid] = 18 (equal) → found it!</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 3: window 8 to 9\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">85</span><span class=\"cell discarded\" data-label=\"1\">72</span><span class=\"cell discarded\" data-label=\"2\">63</span><span class=\"cell discarded\" data-label=\"3\">54</span><span class=\"cell discarded\" data-label=\"4\">42</span><span class=\"cell discarded\" data-label=\"5\">34</span><span class=\"cell discarded\" data-label=\"6\">29</span><span class=\"cell discarded\" data-label=\"7\">23</span><span class=\"cell key\" data-label=\"8 low/mid\">18</span><span class=\"cell\" data-label=\"9 high\">8</span></div></div></div></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Probe</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Question</th><th>Decision</th><th>Candidates</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>9</td><td><code>0 + (9 − 0) / 2 = 4</code></td><td>42</td><td><code>42 > 18</code></td><td>search the right half</td><td>10</td></tr><tr><td>2</td><td>5</td><td>9</td><td><code>5 + (9 − 5) / 2 = 7</code></td><td>23</td><td><code>23 > 18</code></td><td>search the right half</td><td>5</td></tr><tr><td>3</td><td>8</td><td>9</td><td><code>8 + (9 − 8) / 2 = 8</code></td><td>18</td><td><code>18 == 18</code></td><td>found</td><td>2</td></tr></tbody></table></div>\r\n        <p>Found at index <code>8</code> after <code>3</code> probes. The count is the same kind of count as the ascending search: the order of the data changes the <em>direction</em> of each decision, never the number of halvings.</p>\r\n        <div class=\"callout\"><strong>Test habit:</strong> before tracing, look at the array and decide which way it is sorted, then write down what “larger than the key” means for that array.</div>\r\n    \r\n      "
  },
  "binary-examples": {
    "id": "binary-examples",
    "title": "Worked examples",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · Worked examples</span>\r\n        <h2>Worked examples</h2>\r\n        <p class=\"lede\">Six searches: the best case, a key at the far end, keys outside the range, a key between two values, and question 3(c) from Test 1.</p>\r\n        <article class=\"example-card\"><h3>Found at the first probe · search <code>34</code></h3><p>The middle cell happens to be the key.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [8, 18, 23, 29, 34, 42, 54, 63, 72, 85]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell\" data-label=\"4\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9\">85</span></div></div><div class=\"worked-visual\" aria-label=\"Binary search for 34\"><div class=\"worked-step\"><h4>Probe 1: low = 0, high = 9, mid = 4; arr[mid] = 34 (equal) → found it!</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 1: window 0 to 9\"><div class=\"array\"><span class=\"cell\" data-label=\"0 low\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell key\" data-label=\"4 mid\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9 high\">85</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Probe</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Question</th><th>Decision</th><th>Candidates</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>9</td><td><code>0 + (9 − 0) / 2 = 4</code></td><td>34</td><td><code>34 == 34</code></td><td>found</td><td>10</td></tr></tbody></table></div><div class=\"result-line\"><code>1</code> probe, returns <code>4</code>. This is the <strong>best case</strong>: <code>O(1)</code>.</div></article><article class=\"example-card\"><h3>Found at the very end · search <code>85</code></h3><p>The key is the last cell, so the window must shrink all the way to it.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [8, 18, 23, 29, 34, 42, 54, 63, 72, 85]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell\" data-label=\"4\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9\">85</span></div></div><div class=\"worked-visual\" aria-label=\"Binary search for 85\"><div class=\"worked-step\"><h4>Probe 1: low = 0, high = 9, mid = 4; arr[mid] = 34 (34 < 85) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 1: window 0 to 9\"><div class=\"array\"><span class=\"cell\" data-label=\"0 low\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell bound\" data-label=\"4 mid\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9 high\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 2: low = 5, high = 9, mid = 7; arr[mid] = 63 (63 < 85) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 2: window 5 to 9\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">8</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell discarded\" data-label=\"2\">23</span><span class=\"cell discarded\" data-label=\"3\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell\" data-label=\"5 low\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell bound\" data-label=\"7 mid\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9 high\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 3: low = 8, high = 9, mid = 8; arr[mid] = 72 (72 < 85) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 3: window 8 to 9\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">8</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell discarded\" data-label=\"2\">23</span><span class=\"cell discarded\" data-label=\"3\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell bound\" data-label=\"8 low/mid\">72</span><span class=\"cell\" data-label=\"9 high\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 4: low = 9, high = 9, mid = 9; arr[mid] = 85 (equal) → found it!</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 4: window 9 to 9\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">8</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell discarded\" data-label=\"2\">23</span><span class=\"cell discarded\" data-label=\"3\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell discarded\" data-label=\"8\">72</span><span class=\"cell key\" data-label=\"9 low/mid/high\">85</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Probe</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Question</th><th>Decision</th><th>Candidates</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>9</td><td><code>0 + (9 − 0) / 2 = 4</code></td><td>34</td><td><code>34 < 85</code></td><td>search the right half</td><td>10</td></tr><tr><td>2</td><td>5</td><td>9</td><td><code>5 + (9 − 5) / 2 = 7</code></td><td>63</td><td><code>63 < 85</code></td><td>search the right half</td><td>5</td></tr><tr><td>3</td><td>8</td><td>9</td><td><code>8 + (9 − 8) / 2 = 8</code></td><td>72</td><td><code>72 < 85</code></td><td>search the right half</td><td>2</td></tr><tr><td>4</td><td>9</td><td>9</td><td><code>9 + (9 − 9) / 2 = 9</code></td><td>85</td><td><code>85 == 85</code></td><td>found</td><td>1</td></tr></tbody></table></div><div class=\"result-line\"><code>4</code> probes, returns <code>9</code>. A key at either end is a near-worst case, but still only 4 probes for 10 values.</div></article><article class=\"example-card\"><h3>Smaller than everything · search <code>5</code></h3><p>The key is below the smallest value, so every probe says “go left”.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [8, 18, 23, 29, 34, 42, 54, 63, 72, 85]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell\" data-label=\"4\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9\">85</span></div></div><div class=\"worked-visual\" aria-label=\"Binary search for 5\"><div class=\"worked-step\"><h4>Probe 1: low = 0, high = 9, mid = 4; arr[mid] = 34 (34 > 5) → search the left half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 1: window 0 to 9\"><div class=\"array\"><span class=\"cell\" data-label=\"0 low\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell bound\" data-label=\"4 mid\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9 high\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 2: low = 0, high = 3, mid = 1; arr[mid] = 18 (18 > 5) → search the left half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 2: window 0 to 3\"><div class=\"array\"><span class=\"cell\" data-label=\"0 low\">8</span><span class=\"cell bound\" data-label=\"1 mid\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3 high\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell discarded\" data-label=\"8\">72</span><span class=\"cell discarded\" data-label=\"9\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 3: low = 0, high = 0, mid = 0; arr[mid] = 8 (8 > 5) → search the left half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 3: window 0 to 0\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 low/mid/high\">8</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell discarded\" data-label=\"2\">23</span><span class=\"cell discarded\" data-label=\"3\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell discarded\" data-label=\"8\">72</span><span class=\"cell discarded\" data-label=\"9\">85</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Probe</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Question</th><th>Decision</th><th>Candidates</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>9</td><td><code>0 + (9 − 0) / 2 = 4</code></td><td>34</td><td><code>34 > 5</code></td><td>search the left half</td><td>10</td></tr><tr><td>2</td><td>0</td><td>3</td><td><code>0 + (3 − 0) / 2 = 1</code></td><td>18</td><td><code>18 > 5</code></td><td>search the left half</td><td>4</td></tr><tr><td>3</td><td>0</td><td>0</td><td><code>0 + (0 − 0) / 2 = 0</code></td><td>8</td><td><code>8 > 5</code></td><td>search the left half</td><td>1</td></tr><tr><td></td><td>0</td><td>-1</td><td></td><td></td><td><code>low &gt; high</code></td><td><strong>stop: return -1</strong></td><td>0</td></tr></tbody></table></div><div class=\"result-line\"><code>3</code> probes and <code>-1</code>. The window empties from the right: <code>high</code> falls to <code>-1</code>, which is below <code>low</code>.</div></article><article class=\"example-card\"><h3>Larger than everything · search <code>100</code></h3><p>Every probe says “go right”.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [8, 18, 23, 29, 34, 42, 54, 63, 72, 85]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell\" data-label=\"4\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9\">85</span></div></div><div class=\"worked-visual\" aria-label=\"Binary search for 100\"><div class=\"worked-step\"><h4>Probe 1: low = 0, high = 9, mid = 4; arr[mid] = 34 (34 < 100) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 1: window 0 to 9\"><div class=\"array\"><span class=\"cell\" data-label=\"0 low\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell bound\" data-label=\"4 mid\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9 high\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 2: low = 5, high = 9, mid = 7; arr[mid] = 63 (63 < 100) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 2: window 5 to 9\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">8</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell discarded\" data-label=\"2\">23</span><span class=\"cell discarded\" data-label=\"3\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell\" data-label=\"5 low\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell bound\" data-label=\"7 mid\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9 high\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 3: low = 8, high = 9, mid = 8; arr[mid] = 72 (72 < 100) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 3: window 8 to 9\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">8</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell discarded\" data-label=\"2\">23</span><span class=\"cell discarded\" data-label=\"3\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell bound\" data-label=\"8 low/mid\">72</span><span class=\"cell\" data-label=\"9 high\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 4: low = 9, high = 9, mid = 9; arr[mid] = 85 (85 < 100) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 4: window 9 to 9\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">8</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell discarded\" data-label=\"2\">23</span><span class=\"cell discarded\" data-label=\"3\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell discarded\" data-label=\"8\">72</span><span class=\"cell bound\" data-label=\"9 low/mid/high\">85</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Probe</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Question</th><th>Decision</th><th>Candidates</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>9</td><td><code>0 + (9 − 0) / 2 = 4</code></td><td>34</td><td><code>34 < 100</code></td><td>search the right half</td><td>10</td></tr><tr><td>2</td><td>5</td><td>9</td><td><code>5 + (9 − 5) / 2 = 7</code></td><td>63</td><td><code>63 < 100</code></td><td>search the right half</td><td>5</td></tr><tr><td>3</td><td>8</td><td>9</td><td><code>8 + (9 − 8) / 2 = 8</code></td><td>72</td><td><code>72 < 100</code></td><td>search the right half</td><td>2</td></tr><tr><td>4</td><td>9</td><td>9</td><td><code>9 + (9 − 9) / 2 = 9</code></td><td>85</td><td><code>85 < 100</code></td><td>search the right half</td><td>1</td></tr><tr><td></td><td>10</td><td>9</td><td></td><td></td><td><code>low &gt; high</code></td><td><strong>stop: return -1</strong></td><td>0</td></tr></tbody></table></div><div class=\"result-line\"><code>4</code> probes and <code>-1</code>. This time <code>low</code> climbs to <code>10</code>, past <code>high</code>.</div></article><article class=\"example-card\"><h3>Between two values · search <code>31</code></h3><p>31 is not stored, but it would sit between 29 and 34. The same example the earlier section traced.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [8, 18, 23, 29, 34, 42, 54, 63, 72, 85]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell\" data-label=\"4\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9\">85</span></div></div><div class=\"worked-visual\" aria-label=\"Binary search for 31\"><div class=\"worked-step\"><h4>Probe 1: low = 0, high = 9, mid = 4; arr[mid] = 34 (34 > 31) → search the left half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 1: window 0 to 9\"><div class=\"array\"><span class=\"cell\" data-label=\"0 low\">8</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3\">29</span><span class=\"cell bound\" data-label=\"4 mid\">34</span><span class=\"cell\" data-label=\"5\">42</span><span class=\"cell\" data-label=\"6\">54</span><span class=\"cell\" data-label=\"7\">63</span><span class=\"cell\" data-label=\"8\">72</span><span class=\"cell\" data-label=\"9 high\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 2: low = 0, high = 3, mid = 1; arr[mid] = 18 (18 < 31) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 2: window 0 to 3\"><div class=\"array\"><span class=\"cell\" data-label=\"0 low\">8</span><span class=\"cell bound\" data-label=\"1 mid\">18</span><span class=\"cell\" data-label=\"2\">23</span><span class=\"cell\" data-label=\"3 high\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell discarded\" data-label=\"8\">72</span><span class=\"cell discarded\" data-label=\"9\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 3: low = 2, high = 3, mid = 2; arr[mid] = 23 (23 < 31) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 3: window 2 to 3\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">8</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell bound\" data-label=\"2 low/mid\">23</span><span class=\"cell\" data-label=\"3 high\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell discarded\" data-label=\"8\">72</span><span class=\"cell discarded\" data-label=\"9\">85</span></div></div></div><div class=\"worked-step\"><h4>Probe 4: low = 3, high = 3, mid = 3; arr[mid] = 29 (29 < 31) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 4: window 3 to 3\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">8</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell discarded\" data-label=\"2\">23</span><span class=\"cell bound\" data-label=\"3 low/mid/high\">29</span><span class=\"cell discarded\" data-label=\"4\">34</span><span class=\"cell discarded\" data-label=\"5\">42</span><span class=\"cell discarded\" data-label=\"6\">54</span><span class=\"cell discarded\" data-label=\"7\">63</span><span class=\"cell discarded\" data-label=\"8\">72</span><span class=\"cell discarded\" data-label=\"9\">85</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Probe</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Question</th><th>Decision</th><th>Candidates</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>9</td><td><code>0 + (9 − 0) / 2 = 4</code></td><td>34</td><td><code>34 > 31</code></td><td>search the left half</td><td>10</td></tr><tr><td>2</td><td>0</td><td>3</td><td><code>0 + (3 − 0) / 2 = 1</code></td><td>18</td><td><code>18 < 31</code></td><td>search the right half</td><td>4</td></tr><tr><td>3</td><td>2</td><td>3</td><td><code>2 + (3 − 2) / 2 = 2</code></td><td>23</td><td><code>23 < 31</code></td><td>search the right half</td><td>2</td></tr><tr><td>4</td><td>3</td><td>3</td><td><code>3 + (3 − 3) / 2 = 3</code></td><td>29</td><td><code>29 < 31</code></td><td>search the right half</td><td>1</td></tr><tr><td></td><td>4</td><td>3</td><td></td><td></td><td><code>low &gt; high</code></td><td><strong>stop: return -1</strong></td><td>0</td></tr></tbody></table></div><div class=\"result-line\"><code>4</code> probes and <code>-1</code>. Not found is decided the moment the window is empty: no need to look at any more cells.</div></article><article class=\"example-card\"><h3>Test 1 question 3(c) · search <code>88</code> in <code>{2, 6, 12, 32, 50, 59, 76, 83, 90}</code></h3><p>“Searching for the number 88 will be determined after how many iterations?” 88 is not in the array, but it would fit between 83 and 90.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array [2, 6, 12, 32, 50, 59, 76, 83, 90]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">6</span><span class=\"cell\" data-label=\"2\">12</span><span class=\"cell\" data-label=\"3\">32</span><span class=\"cell\" data-label=\"4\">50</span><span class=\"cell\" data-label=\"5\">59</span><span class=\"cell\" data-label=\"6\">76</span><span class=\"cell\" data-label=\"7\">83</span><span class=\"cell\" data-label=\"8\">90</span></div></div><div class=\"worked-visual\" aria-label=\"Binary search for 88\"><div class=\"worked-step\"><h4>Probe 1: low = 0, high = 8, mid = 4; arr[mid] = 50 (50 < 88) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 1: window 0 to 8\"><div class=\"array\"><span class=\"cell\" data-label=\"0 low\">2</span><span class=\"cell\" data-label=\"1\">6</span><span class=\"cell\" data-label=\"2\">12</span><span class=\"cell\" data-label=\"3\">32</span><span class=\"cell bound\" data-label=\"4 mid\">50</span><span class=\"cell\" data-label=\"5\">59</span><span class=\"cell\" data-label=\"6\">76</span><span class=\"cell\" data-label=\"7\">83</span><span class=\"cell\" data-label=\"8 high\">90</span></div></div></div><div class=\"worked-step\"><h4>Probe 2: low = 5, high = 8, mid = 6; arr[mid] = 76 (76 < 88) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 2: window 5 to 8\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">2</span><span class=\"cell discarded\" data-label=\"1\">6</span><span class=\"cell discarded\" data-label=\"2\">12</span><span class=\"cell discarded\" data-label=\"3\">32</span><span class=\"cell discarded\" data-label=\"4\">50</span><span class=\"cell\" data-label=\"5 low\">59</span><span class=\"cell bound\" data-label=\"6 mid\">76</span><span class=\"cell\" data-label=\"7\">83</span><span class=\"cell\" data-label=\"8 high\">90</span></div></div></div><div class=\"worked-step\"><h4>Probe 3: low = 7, high = 8, mid = 7; arr[mid] = 83 (83 < 88) → search the right half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 3: window 7 to 8\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">2</span><span class=\"cell discarded\" data-label=\"1\">6</span><span class=\"cell discarded\" data-label=\"2\">12</span><span class=\"cell discarded\" data-label=\"3\">32</span><span class=\"cell discarded\" data-label=\"4\">50</span><span class=\"cell discarded\" data-label=\"5\">59</span><span class=\"cell discarded\" data-label=\"6\">76</span><span class=\"cell bound\" data-label=\"7 low/mid\">83</span><span class=\"cell\" data-label=\"8 high\">90</span></div></div></div><div class=\"worked-step\"><h4>Probe 4: low = 8, high = 8, mid = 8; arr[mid] = 90 (90 > 88) → search the left half</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Probe 4: window 8 to 8\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">2</span><span class=\"cell discarded\" data-label=\"1\">6</span><span class=\"cell discarded\" data-label=\"2\">12</span><span class=\"cell discarded\" data-label=\"3\">32</span><span class=\"cell discarded\" data-label=\"4\">50</span><span class=\"cell discarded\" data-label=\"5\">59</span><span class=\"cell discarded\" data-label=\"6\">76</span><span class=\"cell discarded\" data-label=\"7\">83</span><span class=\"cell bound\" data-label=\"8 low/mid/high\">90</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Probe</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Question</th><th>Decision</th><th>Candidates</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>8</td><td><code>0 + (8 − 0) / 2 = 4</code></td><td>50</td><td><code>50 < 88</code></td><td>search the right half</td><td>9</td></tr><tr><td>2</td><td>5</td><td>8</td><td><code>5 + (8 − 5) / 2 = 6</code></td><td>76</td><td><code>76 < 88</code></td><td>search the right half</td><td>4</td></tr><tr><td>3</td><td>7</td><td>8</td><td><code>7 + (8 − 7) / 2 = 7</code></td><td>83</td><td><code>83 < 88</code></td><td>search the right half</td><td>2</td></tr><tr><td>4</td><td>8</td><td>8</td><td><code>8 + (8 − 8) / 2 = 8</code></td><td>90</td><td><code>90 > 88</code></td><td>search the left half</td><td>1</td></tr><tr><td></td><td>8</td><td>7</td><td></td><td></td><td><code>low &gt; high</code></td><td><strong>stop: return -1</strong></td><td>0</td></tr></tbody></table></div><div class=\"result-line\"><strong>4 iterations</strong>, then the window is empty (<code>low = 8 &gt; high = 7</code>) and the search returns <code>-1</code>. Each probe moves <code>low</code> up: the key is larger than <code>50</code>, <code>76</code> and <code>83</code>, but smaller than <code>90</code>.</div></article>\r\n      "
  },
  "binary-properties": {
    "id": "binary-properties",
    "title": "Properties",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · Properties</span>\r\n        <h2>Properties</h2>\r\n        \r\n        <div class=\"properties\"><div class=\"property\"><small>Best time</small><b>O(1)</b></div><div class=\"property\"><small>Average time</small><b>O(log n)</b></div><div class=\"property\"><small>Worst time</small><b>O(log n)</b></div><div class=\"property\"><small>Extra space</small><b>O(1)*</b></div><div class=\"property\"><small>Needs sorted data</small><b>Yes</b></div><div class=\"property\"><small>Needs random access</small><b>Yes</b></div><div class=\"property\"><small>Compares with</small><b>< , > , ==</b></div><div class=\"property\"><small>Finds</small><b>Any one match</b></div></div>\r\n        <p class=\"fine-print\">* iterative version. The recursive version uses <code>O(log n)</code> stack space.</p>\r\n        <h3>Sorted data only</h3>\r\n        <p>This is the one big requirement. If the data is not sorted, either sort it first (<code>O(n log n)</code>) or use linear search.</p>\r\n        <h3>Random access</h3>\r\n        <p>It jumps straight to <code>arr[mid]</code>. That is instant in an array but slow in a linked list, where reaching the middle means walking there. On a linked list, binary search loses its advantage.</p>\r\n        <h3>Duplicates</h3>\r\n        <p>If the key appears several times, binary search returns <em>one</em> of them, not necessarily the first. With <code>[10, 20, 20, 20, 30]</code> and key 20 it returns index 2, the middle one. Finding the first or last occurrence needs a small variation.</p>\r\n        <h3>Logarithmic cost</h3>\r\n        <p>Doubling the array size adds only <strong>one</strong> extra probe.</p>\r\n    \r\n      "
  },
  "binary-complexity": {
    "id": "binary-complexity",
    "title": "Why those complexities occur",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · Why those complexities occur</span>\r\n        <h2>Why those complexities occur</h2>\r\n        \r\n        <div class=\"complexity-grid\"><div class=\"complexity-item\"><strong>Best case · O(1)</strong>The key is the middle cell on the first probe.</div><div class=\"complexity-item\"><strong>Worst case · O(log n)</strong>The window halves each probe, so at most <code>⌊log₂ n⌋ + 1</code> probes.</div></div>\r\n        <h3>Halving a million</h3>\r\n        <p>For a million values, here is how many candidates remain after each probe:</p>\r\n        <div class=\"halving\" role=\"img\" aria-label=\"Size after each halving: 1000000, 500000, 250000, 125000, 62500, 31250, 15625, 7812, 3906, 1953, 976, 488, 244, 122, 61, 30, 15, 7, 3, 1\"><div class=\"halve-row\"><span>probe 1</span><div class=\"halve-bar\"><i style=\"width:100.00%\"></i></div><span class=\"halve-n\">1,000,000 left</span></div><div class=\"halve-row\"><span>probe 2</span><div class=\"halve-bar\"><i style=\"width:50.00%\"></i></div><span class=\"halve-n\">500,000 left</span></div><div class=\"halve-row\"><span>probe 3</span><div class=\"halve-bar\"><i style=\"width:25.00%\"></i></div><span class=\"halve-n\">250,000 left</span></div><div class=\"halve-row\"><span>probe 4</span><div class=\"halve-bar\"><i style=\"width:12.50%\"></i></div><span class=\"halve-n\">125,000 left</span></div><div class=\"halve-row\"><span>probe 5</span><div class=\"halve-bar\"><i style=\"width:6.25%\"></i></div><span class=\"halve-n\">62,500 left</span></div><div class=\"halve-row\"><span>probe 6</span><div class=\"halve-bar\"><i style=\"width:3.12%\"></i></div><span class=\"halve-n\">31,250 left</span></div><div class=\"halve-row\"><span>probe 7</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">15,625 left</span></div><div class=\"halve-row\"><span>probe 8</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">7,812 left</span></div><div class=\"halve-row\"><span>probe 9</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">3,906 left</span></div><div class=\"halve-row\"><span>probe 10</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">1,953 left</span></div><div class=\"halve-row\"><span>probe 11</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">976 left</span></div><div class=\"halve-row\"><span>probe 12</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">488 left</span></div><div class=\"halve-row\"><span>probe 13</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">244 left</span></div><div class=\"halve-row\"><span>probe 14</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">122 left</span></div><div class=\"halve-row\"><span>probe 15</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">61 left</span></div><div class=\"halve-row\"><span>probe 16</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">30 left</span></div><div class=\"halve-row\"><span>probe 17</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">15 left</span></div><div class=\"halve-row\"><span>probe 18</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">7 left</span></div><div class=\"halve-row\"><span>probe 19</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">3 left</span></div><div class=\"halve-row\"><span>probe 20</span><div class=\"halve-bar\"><i style=\"width:2.00%\"></i></div><span class=\"halve-n\">1 left</span></div></div>\r\n        <p>Twenty probes take you from a million candidates to one. That is the whole story of <code>O(log n)</code>: <strong>how many times can you halve n before you reach 1?</strong></p>\r\n        <div class=\"formula\">maximum probes = ⌊log₂ n⌋ + 1</div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>n (values)</th><th>Binary search: at most</th><th>Linear search: at most</th><th>Binary is about this many times fewer</th></tr></thead><tbody><tr><td>10</td><td>4</td><td>10</td><td>≈ 2×</td></tr><tr><td>100</td><td>7</td><td>100</td><td>≈ 14×</td></tr><tr><td>1,000</td><td>10</td><td>1,000</td><td>≈ 100×</td></tr><tr><td>1,000,000</td><td>20</td><td>1,000,000</td><td>≈ 50,000×</td></tr><tr><td>1,000,000,000</td><td>30</td><td>1,000,000,000</td><td>≈ 33,333,333×</td></tr></tbody></table></div>\r\n        <p>Ten times more data adds about 3 probes, not 10 times the work. Even for a <em>billion</em> values binary search needs at most 30 probes.</p>\r\n        <h3>Average and best case</h3>\r\n        <p>The average is still about <code>log₂ n</code>: most keys sit deep in the tree of halving, not near the first probe. The best case is a single probe.</p>\r\n        <h3>Is it worth sorting first?</h3>\r\n        <p>Binary search is fast, but it needs sorted data, and sorting costs about <code>n log₂ n</code>. For <code>n = 1,000,000</code> that is roughly <strong>20,000,000</strong> steps, once. Each later linear search costs up to 1,000,000 steps but each binary search only 20, saving almost a million steps per search. So the sort pays for itself after about <strong>21 searches</strong>. For one search, just scan; for many, sort once.</p>\r\n        <h3>Space</h3>\r\n        <p>The iterative version needs just <code>low</code>, <code>high</code> and <code>mid</code>: <code>O(1)</code>.</p>\r\n    \r\n      "
  },
  "binary-when": {
    "id": "binary-when",
    "title": "When to use it",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · When to use it</span>\r\n        <h2>When to use it</h2>\r\n        \r\n        <div class=\"use-grid\"><div class=\"use good\"><strong>A good choice</strong>Large collections that are <strong>sorted</strong> (or that you can sort once) and searched many times; dictionaries, phone books, product catalogues, leaderboards; any array with random access.</div><div class=\"use poor\"><strong>A poor choice</strong>Unsorted data searched once; very small arrays (linear search is just as fast and simpler); linked lists (no fast access to the middle); data that changes constantly, since keeping it sorted costs time.</div></div>\r\n        <p>The decision rule: <em>sorted + random access + searched more than a few times → binary search</em>. Otherwise linear search. This is exactly the choice behind Test 1's last question: of the four algorithms listed, binary search is the most efficient for searching, <code>O(log n)</code>.</p>\r\n    \r\n      "
  },
  "binary-mistakes": {
    "id": "binary-mistakes",
    "title": "Common mistakes",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · Common mistakes</span>\r\n        <h2>Common mistakes</h2>\r\n        \r\n        <div class=\"mistake\"><span class=\"mistake-no\">1</span><div><strong>Searching an unsorted array.</strong><br>Binary search on <code>[5, 1, 9, 3, 7]</code> for <code>3</code> (which <em>is</em> there, at index 3) returns <strong>-1</strong>: the first probe reads <code>9</code>, concludes “3 must be to the left”, and discards the cell holding 3. Always check the precondition.</div></div><div class=\"mistake\"><span class=\"mistake-no\">2</span><div><strong>Computing <code>mid</code> as <code>(low + high) / 2</code>.</strong><br>Works for small arrays but can overflow for very large ones (see the earlier section). Write <code>low + (high − low) / 2</code>.</div></div><div class=\"mistake\"><span class=\"mistake-no\">3</span><div><strong>Looping with <code>low &lt; high</code> instead of <code>low &lt;= high</code>.</strong><br>When one candidate remains, <code>low == high</code>, and the loop quits without checking it. On <code>[1, 3, 5, 7, 9]</code>, searching for <code>9</code> (index 4) returns <strong>-1</strong> with the wrong condition.</div></div><div class=\"mistake\"><span class=\"mistake-no\">4</span><div><strong>Setting <code>low = mid</code> or <code>high = mid</code>.</strong><br>The window may stop shrinking and the loop never ends. Use <code>mid + 1</code> and <code>mid − 1</code>.</div></div><div class=\"mistake\"><span class=\"mistake-no\">5</span><div><strong>Getting the direction wrong for descending data.</strong><br>Larger-than-key means <em>go right</em> in a descending array. Decide this before you trace.</div></div><div class=\"mistake\"><span class=\"mistake-no\">6</span><div><strong>Comparing Strings with <code>&lt;</code> or <code>==</code>.</strong><br>Use <code>compareTo</code> for order and <code>.equals</code> for equality.</div></div><div class=\"mistake\"><span class=\"mistake-no\">7</span><div><strong>Returning <code>mid</code> when the key is absent.</strong><br>Return <code>-1</code> only after the loop ends.</div></div><div class=\"mistake\"><span class=\"mistake-no\">8</span><div><strong>Miscounting iterations.</strong><br>One iteration is one probe. The final check that finds <code>low &gt; high</code> is not a probe.</div></div>\r\n    \r\n      "
  },
  "binary-summary": {
    "id": "binary-summary",
    "title": "A test-ready summary",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · A test-ready summary</span>\r\n        <h2>A test-ready summary</h2>\r\n        \r\n        <div class=\"test-summary\">\r\n          <p>Binary search finds a key in a sorted array. It keeps a window low…high, probes the middle at mid = low + (high − low) / 2, and either returns mid if arr[mid] equals the key or discards the half that cannot contain the key (low = mid + 1 or high = mid − 1). When the window is empty (low &gt; high) it returns -1. Each probe halves the candidates, so the worst case is O(log n), at most ⌊log₂ n⌋ + 1 probes, with O(1) extra space. It requires sorted data and random access, and is far faster than linear search, O(n), on large sorted arrays.</p>\r\n        </div>\r\n    \r\n      "
  },
  "binary-practice": {
    "id": "binary-practice",
    "title": "Practice",
    "body": "\r\n        <span class=\"section-no\">Searching / Binary search · Practice</span>\r\n        <h2>Practice</h2>\r\n        \r\n        <h3>Guided question</h3>\r\n        <p>Use binary search to find <code>29</code> in <code>[8, 18, 23, 29, 34, 42, 54, 63, 72, 85]</code>. Write low, high, mid and <code>arr[mid]</code> for each probe.</p>\r\n        <details><summary>Reveal the guided answer</summary><div class=\"answer\"><p><strong>Probe 1:</strong> low = 0, high = 9, mid = 4; <code>arr[mid] = 34</code> → search the left half</p><p><strong>Probe 2:</strong> low = 0, high = 3, mid = 1; <code>arr[mid] = 18</code> → search the right half</p><p><strong>Probe 3:</strong> low = 2, high = 3, mid = 2; <code>arr[mid] = 23</code> → search the right half</p><p><strong>Probe 4:</strong> low = 3, high = 3, mid = 3; <code>arr[mid] = 29</code> → found</p><p><strong>Result:</strong> found at index 3 after 4 probes.</p></div></details>\r\n        <h3>Independent question</h3>\r\n        <p>Search for <code>50</code> in <code>[3, 9, 14, 21, 35, 47, 60, 71]</code>. How many iterations are needed, and what is returned?</p>\r\n        <ul class=\"checklist\">\r\n          <li>Start with <code>low = 0</code> and <code>high = 7</code>.</li>\r\n          <li>Compute <code>mid</code> each time with <code>low + (high − low) / 2</code>.</li>\r\n          <li>Decide left or right, and update <code>low</code> or <code>high</code>.</li>\r\n          <li>Stop when the key is found or <code>low &gt; high</code>.</li>\r\n        </ul>\r\n        <details><summary>Reveal the independent answer</summary><div class=\"answer\"><div class=\"table-scroll\"><table><thead><tr><th>Probe</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Question</th><th>Decision</th><th>Candidates</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>7</td><td><code>0 + (7 − 0) / 2 = 3</code></td><td>21</td><td><code>21 < 50</code></td><td>search the right half</td><td>8</td></tr><tr><td>2</td><td>4</td><td>7</td><td><code>4 + (7 − 4) / 2 = 5</code></td><td>47</td><td><code>47 < 50</code></td><td>search the right half</td><td>4</td></tr><tr><td>3</td><td>6</td><td>7</td><td><code>6 + (7 − 6) / 2 = 6</code></td><td>60</td><td><code>60 > 50</code></td><td>search the left half</td><td>2</td></tr><tr><td></td><td>6</td><td>5</td><td></td><td></td><td><code>low &gt; high</code></td><td><strong>stop: return -1</strong></td><td>0</td></tr></tbody></table></div><p><strong>3 iterations</strong>, returns <code>-1</code>: 50 is not in the array.</p></div></details>\r\n        <h3>Test-style question</h3>\r\n        <p>For the sorted array <code>[2, 6, 12, 32, 50, 59, 76, 83, 90]</code> of Test 1, after how many iterations will the search for <code>5</code> be decided, and what is returned? Then state the worst-case time complexity of binary search.</p>\r\n        <details><summary>Reveal the test-style answer</summary><div class=\"answer\"><div class=\"table-scroll\"><table><thead><tr><th>Probe</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Question</th><th>Decision</th><th>Candidates</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>8</td><td><code>0 + (8 − 0) / 2 = 4</code></td><td>50</td><td><code>50 > 5</code></td><td>search the left half</td><td>9</td></tr><tr><td>2</td><td>0</td><td>3</td><td><code>0 + (3 − 0) / 2 = 1</code></td><td>6</td><td><code>6 > 5</code></td><td>search the left half</td><td>4</td></tr><tr><td>3</td><td>0</td><td>0</td><td><code>0 + (0 − 0) / 2 = 0</code></td><td>2</td><td><code>2 < 5</code></td><td>search the right half</td><td>1</td></tr><tr><td></td><td>1</td><td>0</td><td></td><td></td><td><code>low &gt; high</code></td><td><strong>stop: return -1</strong></td><td>0</td></tr></tbody></table></div><p><strong>3 iterations</strong>, returns <code>-1</code>. The worst case is <strong>O(log n)</strong>.</p></div></details>\r\n    \r\n      "
  },
  "search-summary": {
    "id": "search-summary",
    "title": "Choose the search from the data you have",
    "body": "\r\n        <span class=\"section-no\">Searching / Chapter summary</span>\r\n        <h2>Choose the search from the data you have</h2>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Question</th><th>Linear search</th><th>Binary search</th></tr></thead><tbody><tr><td>Must data be sorted?</td><td>No</td><td>Yes</td></tr><tr><td>Worst time</td><td><code>O(n)</code></td><td><code>O(log n)</code></td></tr><tr><td>Core movement</td><td>Advance one index</td><td>Discard half</td></tr><tr><td>Not-found condition</td><td>End of array</td><td><code>low &gt; high</code></td></tr></tbody></table></div>\r\n        <details><summary>Quick check: which search for one lookup in a small unsorted array?</summary><div class=\"answer\">Linear search. Sorting first would add work and could change the original order.</div></details>\r\n      "
  },
  "why-sort": {
    "id": "why-sort",
    "title": "Why sort data at all?",
    "body": "\r\n        <span class=\"section-no\">Sorting · Why sort data at all?</span>\r\n        <h2>Why sort data at all?</h2>\r\n        <p class=\"lede\">Before the algorithms: what does sorted data give you that unsorted data does not, and what does it cost?</p>\r\n        \r\n        <p>Everything in this chapter is about putting values in order. Before learning <em>how</em>, it is worth being clear about <strong>why</strong>, because it is a favourite exam question and because it explains why searching and sorting are taught together.</p>\r\n        <div class=\"callout\"><strong>Short answer for a test:</strong> sorting data makes it easier and faster to find information in it. A sorted array can be searched with binary search, in <code>O(log n)</code> instead of <code>O(n)</code>.</div>\r\n        <h3>What becomes easy once data is sorted</h3>\r\n        <p>Take the nine values from Test 1. Unsorted they tell you nothing at a glance; sorted, a lot of questions answer themselves.</p>\r\n        <div class=\"paper-card\">\r\n          <div class=\"kicker\">Unsorted</div>\r\n          <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Unsorted array\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">50</span><span class=\"cell\" data-label=\"1\">83</span><span class=\"cell\" data-label=\"2\">76</span><span class=\"cell\" data-label=\"3\">6</span><span class=\"cell\" data-label=\"4\">32</span><span class=\"cell\" data-label=\"5\">90</span><span class=\"cell\" data-label=\"6\">12</span><span class=\"cell\" data-label=\"7\">2</span><span class=\"cell\" data-label=\"8\">59</span></div></div>\r\n          <figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Unsorted values as bars\"><div class=\"bar\" style=\"--p:0.556\"><i></i><b>50</b><small>0</small></div><div class=\"bar\" style=\"--p:0.922\"><i></i><b>83</b><small>1</small></div><div class=\"bar\" style=\"--p:0.844\"><i></i><b>76</b><small>2</small></div><div class=\"bar\" style=\"--p:0.067\"><i></i><b>6</b><small>3</small></div><div class=\"bar\" style=\"--p:0.356\"><i></i><b>32</b><small>4</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>90</b><small>5</small></div><div class=\"bar\" style=\"--p:0.133\"><i></i><b>12</b><small>6</small></div><div class=\"bar\" style=\"--p:0.022\"><i></i><b>2</b><small>7</small></div><div class=\"bar\" style=\"--p:0.656\"><i></i><b>59</b><small>8</small></div></div></figure>\r\n          <div class=\"kicker\">The same values, sorted ascending</div>\r\n          <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Sorted array with minimum, median and maximum marked\"><div class=\"array\"><span class=\"cell key\" data-label=\"0 min\">2</span><span class=\"cell\">6</span><span class=\"cell\">12</span><span class=\"cell\">32</span><span class=\"cell bound\" data-label=\"4 median\">50</span><span class=\"cell\">59</span><span class=\"cell\">76</span><span class=\"cell\">83</span><span class=\"cell key\" data-label=\"8 max\">90</span></div></div>\r\n          <figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Sorted values as a staircase\"><div class=\"bar done min\" style=\"--p:0.022\"><i></i><b>2</b><small>0</small></div><div class=\"bar done\" style=\"--p:0.067\"><i></i><b>6</b><small>1</small></div><div class=\"bar done\" style=\"--p:0.133\"><i></i><b>12</b><small>2</small></div><div class=\"bar done\" style=\"--p:0.356\"><i></i><b>32</b><small>3</small></div><div class=\"bar done\" style=\"--p:0.556\"><i></i><b>50</b><small>4</small></div><div class=\"bar done\" style=\"--p:0.656\"><i></i><b>59</b><small>5</small></div><div class=\"bar done\" style=\"--p:0.844\"><i></i><b>76</b><small>6</small></div><div class=\"bar done\" style=\"--p:0.922\"><i></i><b>83</b><small>7</small></div><div class=\"bar done swap\" style=\"--p:1.000\"><i></i><b>90</b><small>8</small></div></div></figure>\r\n        </div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Question</th><th>Unsorted array</th><th>Sorted array</th></tr></thead><tbody><tr><td>Smallest and largest value?</td><td>Look at all 9 cells</td><td>The first and last cell: <code>2</code> and <code>90</code></td></tr><tr><td>Median (middle) value?</td><td>Needs a lot of work</td><td>The middle cell: <code>50</code></td></tr><tr><td>Is a value present?</td><td>Linear search: up to 9 comparisons</td><td>Binary search: at most 4 probes</td></tr><tr><td>Where are the duplicates?</td><td>Anywhere</td><td>Next to each other (see below)</td></tr><tr><td>Merge two lists?</td><td>No shortcut</td><td>Merge them by zipping (that is merge sort's merge step)</td></tr><tr><td>Show a list to a person?</td><td>Hard to read</td><td>Alphabetical or numerical order, easy to scan</td></tr></tbody></table></div>\r\n        <h3>Duplicates end up side by side</h3>\r\n        <p>Finding repeated values in <code>[3, 1, 3, 2, 3]</code> means comparing every pair. After sorting, <code>[1, 2, 3, 3, 3]</code>, equal values are neighbours, so one pass comparing each cell with the next finds them all.</p>\r\n        <h3>Sorting is not free: is it worth it?</h3>\r\n        <p>Sorting costs about <code>n log₂ n</code> steps, and it only pays off if you search more than a few times. Suppose you have <strong>1,000,000</strong> values and will search for <strong>1,000</strong> different keys:</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Strategy</th><th>Work</th><th>Total</th></tr></thead><tbody><tr><td>Never sort: linear search every time</td><td>1,000 searches × up to 1,000,000 comparisons</td><td><strong>1,000,000,000</strong></td></tr><tr><td>Sort once, then binary search every time</td><td>sort ≈ 20,000,000 steps, then 1,000 searches × 20 probes</td><td><strong>20,020,000</strong></td></tr></tbody></table></div>\r\n        <p>That is about <strong>49× less work</strong> after sorting. With a single search the answer flips: scanning once costs 1,000,000 and sorting first costs 20,000,000. The rule: <em>search once, scan; search often, sort first.</em></p>\r\n        <details><summary>Quick check: Test 1 question 3(a), “What is the purpose of sorting data?”</summary><div class=\"answer\">To arrange data in a defined order (ascending or descending) so that information is easier and faster to find, for example by using binary search instead of scanning every element. Other valid points: duplicates become adjacent, minimum and maximum are at the ends, and sorted data is easier to read and merge.</div></details>\r\n    \r\n      "
  },
  "sort-map": {
    "id": "sort-map",
    "title": "The sorting map",
    "body": "\r\n        <span class=\"section-no\">Sorting</span>\r\n        <h2>The sorting map</h2>\r\n        <p class=\"lede\">Every algorithm orders values, but each uses a different repeated action. The four are taught in this order: Bubble, Selection, Insertion, Merge.</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Algorithm</th><th>Repeated action</th><th>Typical time</th><th>Best fit</th></tr></thead><tbody>\r\n          <tr><td><strong>Bubble</strong></td><td>Compare neighbours; swap wrong pairs</td><td><code>O(n²)</code></td><td>Learning and tiny inputs</td></tr>\r\n          <tr><td><strong>Selection</strong></td><td>Find the smallest remaining value; place it next</td><td><code>O(n²)</code></td><td>When few swaps matter</td></tr>\r\n          <tr><td><strong>Insertion</strong></td><td>Shift larger sorted values; insert a key</td><td><code>O(n²)</code></td><td>Small or nearly sorted data</td></tr>\r\n          <tr><td><strong>Merge</strong></td><td>Divide into halves; merge sorted halves</td><td><code>O(n log n)</code></td><td>Large data and predictable speed</td></tr>\r\n        </tbody></table></div>\r\n\r\n        <h3 id=\"sort-terms\">Vocabulary behind every property tile</h3>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Comparison-based</strong>Order is decided only by asking questions such as <code>a &lt; b</code>.</div><div class=\"term\"><strong>Best / average / worst</strong>The same algorithm on three arrangements of the same <code>n</code> values: already ordered, typical, and the most awkward.</div><div class=\"term\"><strong>In-place</strong>Values are rearranged inside the original array using only a few extra variables: <code>O(1)</code> auxiliary space.</div><div class=\"term\"><strong>Auxiliary space</strong>Extra memory beyond the input array, such as the temporary copies merge sort makes.</div><div class=\"term\"><strong>Adaptive</strong>Does less work when the input is already or nearly sorted.</div><div class=\"term\"><strong>Stable</strong>Equal values keep their original relative order.</div></div>\r\n        <h4>Why stability matters</h4>\r\n        <p>Sort these students by mark. Ana and Ben both scored 70, and Ana was listed first.</p>\r\n        <div class=\"direction-grid\">\r\n          <div><strong>Start</strong><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start: Ana 70, Ben 70, Cy 65\"><div class=\"array\"><span class=\"cell\" data-label=\"Ana\">70</span><span class=\"cell\" data-label=\"Ben\">70</span><span class=\"cell\" data-label=\"Cy\">65</span></div></div></div>\r\n          <div><strong>Stable sort result</strong><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Stable result: Cy 65, Ana 70, Ben 70. Ana is still before Ben\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"Cy\">65</span><span class=\"cell sorted\" data-label=\"Ana\">70</span><span class=\"cell sorted\" data-label=\"Ben\">70</span></div></div></div>\r\n        </div>\r\n        <div class=\"direction-grid\">\r\n          <div><strong>An unstable sort may give</strong><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Possible unstable result: Cy 65, Ben 70, Ana 70. Ben has moved before Ana\"><div class=\"array\"><span class=\"cell\" data-label=\"Cy\">65</span><span class=\"cell shift\" data-label=\"Ben\">70</span><span class=\"cell shift\" data-label=\"Ana\">70</span></div></div></div>\r\n          <div><p>Both outputs are sorted by mark. Only the stable one keeps Ana before Ben, which matters when you sort by one field and want an earlier ordering by another field preserved.</p></div>\r\n        </div>\r\n\r\n        <h3 id=\"sort-inversions\">Count the disorder: inversions</h3>\r\n        <p>An <strong>inversion</strong> is a pair of positions whose values are in the wrong order: a larger value sits to the left of a smaller one. <code>[4, 2, 5, 1, 3]</code> has six: (4,2), (4,1), (4,3), (2,1), (5,1), (5,3).</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Algorithm</th><th>What is counted</th><th>On <code>[4, 2, 5, 1, 3]</code></th><th>Link to inversions</th></tr></thead><tbody><tr><td>Bubble</td><td>adjacent swaps</td><td>6</td><td>Each swap of neighbours removes exactly one inversion.</td></tr><tr><td>Insertion</td><td>shifts</td><td>6</td><td>Each shift removes exactly one inversion.</td></tr><tr><td>Selection</td><td>swaps</td><td>2</td><td>At most <code>n − 1</code> swaps; one swap can remove several inversions at once.</td></tr></tbody></table></div>\r\n        <p>A fully reversed array of <code>n</code> values has <code>n(n − 1) / 2</code> inversions. For <code>[5, 4, 3, 2, 1]</code> that is 10, which equals the 10 shifts in the reverse-order insertion example. This is the reason bubble and insertion sort are <code>O(n²)</code> in the worst case.</p>\r\n      "
  },
  "bubble-array": {
    "id": "bubble-array",
    "title": "The array we will sort",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · The array we will sort</span>\r\n        <h2>The array we will sort</h2>\r\n        <p class=\"lede\">We will sort <code>[4, 2, 5, 1, 3]</code> from smallest to largest, and watch exactly what happens to every value.</p>\r\n        \r\n        <div class=\"paper-card\">\r\n          <div class=\"kicker\">Starting array: the same five values every sorting algorithm in this guide uses</div>\r\n          <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Starting array 4, 2, 5, 1, 3\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">4</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">5</span><span class=\"cell\" data-label=\"3\">1</span><span class=\"cell\" data-label=\"4\">3</span></div></div>\r\n          <figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"The same array drawn as bars: taller means larger\"><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>0</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>2</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>3</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure>\r\n          <div class=\"kicker\">The result we want</div>\r\n          <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Sorted array 1, 2, 3, 4, 5\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div>\r\n        </div>\r\n        <p>Using one array for every algorithm lets you compare them fairly, step against step. The bar picture above shows the same numbers as heights, which is often the quickest way to <em>see</em> what a sorting algorithm is doing: sorting is just turning an uneven skyline into a staircase.</p>\r\n        <p>Two details of this array will matter. The <code>5</code> is larger than both values after it, so bubble sort will pick it up and carry it to the right end. The <code>1</code> is small and sits near the right end: bubble sort can only move it <strong>one place left per pass</strong>, so it takes three passes to reach the front. Keep an eye on both as you read the trace.</p>\r\n    \r\n      "
  },
  "bubble-definition": {
    "id": "bubble-definition",
    "title": "The textbook definition",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · The textbook definition</span>\r\n        <h2>The textbook definition</h2>\r\n        \r\n        <div class=\"paper-card definition\">\r\n          <p><strong>Bubble sort</strong> is a comparison-based sorting algorithm that makes repeated passes over an array. In each pass it compares every pair of neighbouring values and swaps the pair if it is in the wrong order. After each pass the largest value in the part still being sorted has moved to its final place at the right end. The algorithm stops when a pass makes no swaps, or when only one value is left.</p>\r\n        </div>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Pass</strong>One complete walk from the left of the active range to its right end. A pass is not one comparison: it is many.</div><div class=\"term\"><strong>Adjacent pair</strong>Two neighbouring cells, <code>array[j]</code> and <code>array[j + 1]</code>. Bubble sort only ever compares neighbours.</div><div class=\"term\"><strong>Swap</strong>Exchange the two values of a pair so the smaller is on the left (for ascending order).</div><div class=\"term\"><strong>Active range</strong>The cells a pass still has to look at. It shrinks by one cell after every pass.</div><div class=\"term\"><strong>Locked tail</strong>The right-hand cells that already hold their final values, so later passes skip them.</div><div class=\"term\"><strong><code>swapped</code> flag</strong>A boolean that becomes true when a pass swaps anything. If it stays false, the array is sorted and we can stop early.</div><div class=\"term\"><strong>Inversion</strong>A pair of values that is in the wrong order. Every swap of neighbours fixes exactly one inversion.</div></div>\r\n        <p>The name comes from the picture: big values slowly “bubble up” to the end of the array the way air bubbles rise through water, while small values sink towards the front, only one place at a time.</p>\r\n    \r\n      "
  },
  "bubble-simple": {
    "id": "bubble-simple",
    "title": "In plain language",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · In plain language</span>\r\n        <h2>In plain language</h2>\r\n        <p class=\"lede\">Think of walking along a line of people and swapping any neighbours who are standing in the wrong order.</p>\r\n        \r\n        <div class=\"paper-card\">\r\n          <p>Picture a row of students you want ordered from shortest to tallest. You stand at the left end and look at the first two students. If the left one is taller, they swap places. Then you take one step right and look at the next pair, and so on to the end of the row.</p>\r\n          <p>When you reach the end, something useful has happened without any planning: <strong>the tallest student has been swapped all the way to the right end</strong>, because whenever you met a taller student you carried them one step further. Walk along again (stopping one place earlier, since the end is finished) and the second tallest lands next to them.</p>\r\n        </div>\r\n        <p>Here is the smallest possible example, three values <code>[3, 1, 2]</code>, drawn as bars. The two bars that are being compared are outlined; the bars that just changed places are filled darker.</p>\r\n        <div class=\"strip\" role=\"group\" aria-label=\"Bubble sort on 3, 1, 2\"><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"3, 1, 2\"><div class=\"bar cmp\" style=\"--p:1.000\"><i></i><b>3</b><small>0</small></div><div class=\"bar cmp\" style=\"--p:0.333\"><i></i><b>1</b><small>1</small></div><div class=\"bar\" style=\"--p:0.667\"><i></i><b>2</b><small>2</small></div></div></figure><p class=\"fig-cap\">Start</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"After first swap [1, 3, 2]\"><div class=\"bar swap\" style=\"--p:0.333\"><i></i><b>1</b><small>0</small></div><div class=\"bar swap\" style=\"--p:1.000\"><i></i><b>3</b><small>1</small></div><div class=\"bar\" style=\"--p:0.667\"><i></i><b>2</b><small>2</small></div></div></figure><p class=\"fig-cap\">Compare 3 and 1: wrong order, swap</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"After second swap [1, 2, 3]\"><div class=\"bar\" style=\"--p:0.333\"><i></i><b>1</b><small>0</small></div><div class=\"bar swap\" style=\"--p:0.667\"><i></i><b>2</b><small>1</small></div><div class=\"bar done swap\" style=\"--p:1.000\"><i></i><b>3</b><small>2</small></div></div></figure><p class=\"fig-cap\">Compare 3 and 2: wrong order, swap</p></div></div>\r\n        <div class=\"legend\"><span><i class=\"swatch cmp\"></i>being compared</span><span><i class=\"swatch swap\"></i>just swapped</span><span><i class=\"swatch sorted\"></i>final position</span></div>\r\n        <div class=\"compare-list\"><div class=\"compare\"><span class=\"compare-num\">1</span><code>3 &gt; 1</code><span class=\"verdict move\">true · swap</span></div><div class=\"compare\"><span class=\"compare-num\">2</span><code>3 &gt; 2</code><span class=\"verdict move\">true · swap</span></div></div>\r\n        <p>That was pass 1: two comparisons, two swaps, and the <code>3</code> is home. Pass 2 compares only <code>1</code> and <code>2</code>; they are already in order, nothing is swapped, and the algorithm knows it is finished.</p>\r\n    \r\n      "
  },
  "bubble-idea": {
    "id": "bubble-idea",
    "title": "The main idea",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · The main idea</span>\r\n        <h2>The main idea</h2>\r\n        \r\n        <p>Bubble sort never looks at the whole array at once. It follows one tiny rule, <em>“if the left neighbour is bigger, swap”</em>, and repeats it along the array. Everything else follows from that rule.</p>\r\n        <h3>One pass carries the biggest value to the end</h3>\r\n        <p>Watch pass 1 on <code>[4, 2, 5, 1, 3]</code>. The <code>4</code> is carried one step (it beats <code>2</code>), then meets <code>5</code> and is left behind. From then on it is the <code>5</code> that gets carried, past <code>1</code> and past <code>3</code>, all the way to the end. A larger value is only stopped by an even larger one, so the maximum can never be stopped.</p>\r\n        <div class=\"strip\" role=\"group\" aria-label=\"Pass 1 of bubble sort on 4, 2, 5, 1, 3, one comparison at a time\"><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"start\"><div class=\"bar cmp\" style=\"--p:0.800\"><i></i><b>4</b><small>0</small></div><div class=\"bar cmp\" style=\"--p:0.400\"><i></i><b>2</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>2</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>3</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure><p class=\"fig-cap\">Start</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"After comparing 4 and 2: [2, 4, 5, 1, 3]\"><div class=\"bar swap\" style=\"--p:0.400\"><i></i><b>2</b><small>0</small></div><div class=\"bar swap\" style=\"--p:0.800\"><i></i><b>4</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>2</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>3</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure><p class=\"fig-cap\">4 vs 2: swap</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"After comparing 4 and 5: [2, 4, 5, 1, 3]\"><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>0</small></div><div class=\"bar cmp\" style=\"--p:0.800\"><i></i><b>4</b><small>1</small></div><div class=\"bar cmp\" style=\"--p:1.000\"><i></i><b>5</b><small>2</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>3</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure><p class=\"fig-cap\">4 vs 5: keep</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"After comparing 5 and 1: [2, 4, 1, 5, 3]\"><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>0</small></div><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>1</small></div><div class=\"bar swap\" style=\"--p:0.200\"><i></i><b>1</b><small>2</small></div><div class=\"bar swap\" style=\"--p:1.000\"><i></i><b>5</b><small>3</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure><p class=\"fig-cap\">5 vs 1: swap</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"After comparing 5 and 3: [2, 4, 1, 3, 5]\"><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>0</small></div><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>1</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>2</small></div><div class=\"bar swap\" style=\"--p:0.600\"><i></i><b>3</b><small>3</small></div><div class=\"bar done swap\" style=\"--p:1.000\"><i></i><b>5</b><small>4</small></div></div></figure><p class=\"fig-cap\">5 vs 3: swap</p></div></div>\r\n        <div class=\"legend\"><span><i class=\"swatch cmp\"></i>being compared</span><span><i class=\"swatch swap\"></i>just swapped</span><span><i class=\"swatch sorted\"></i>final position</span></div>\r\n        <h3>After pass <em>k</em>, the last <em>k</em> cells are final</h3>\r\n        <p>The maximum reaches the last cell, the next pass brings the second largest to the cell before it, and so on. Cells in the <strong>locked tail</strong> never need to be compared again, which is why each pass can stop one cell earlier than the one before.</p>\r\n        <div class=\"worked-visual\" aria-label=\"End of every pass\"><div class=\"worked-step\"><h4>After pass 1</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 1: [2, 4, 1, 3, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">4</span><span class=\"cell\" data-label=\"2\">1</span><span class=\"cell\" data-label=\"3\">3</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After pass 2</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 2: [2, 1, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">1</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After pass 3</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 3: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After pass 4</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 4: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div></div>\r\n        <h3>Small values move slowly</h3>\r\n        <p>Notice the <code>1</code>: it starts at index 3 and moves left <strong>one place per pass</strong> (index 2, then 1, then 0). A big value can travel the whole array in one pass; a small value can only creep. That asymmetry is the reason bubble sort is slow on some inputs, and we will measure it in the examples.</p>\r\n        <div class=\"callout\"><strong>The repeating recipe:</strong> compare a pair → swap if the left one is larger → step right → at the end of the range lock the last cell → start the next pass, one cell shorter → stop when a pass makes no swaps.</div>\r\n    \r\n      "
  },
  "bubble-movements": {
    "id": "bubble-movements",
    "title": "Comparison, swap, pass",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · Comparison, swap, pass</span>\r\n        <h2>Comparison, swap, pass</h2>\r\n        \r\n        <p class=\"lede\">These words describe different things. Counting them separately is what makes a trace table correct, and exam questions often ask for exactly one of them.</p>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Comparison</strong>One question, such as <code>4 &gt; 2</code>. Bubble sort asks one for every pair in every pass, whether or not anything moves.</div><div class=\"term\"><strong>Swap</strong>Exchanging two neighbours. It happens only when the answer to the comparison was <em>yes, they are out of order</em>.</div><div class=\"term\"><strong>Pass</strong>A whole run of comparisons along the active range. “Show the array after each pass” means one snapshot per pass, not per swap.</div><div class=\"term\"><strong>Early exit</strong>Stopping because a pass made no swaps. Without the flag, bubble sort keeps making every pass even on sorted data.</div></div>\r\n        <h3>How one swap actually works</h3>\r\n        <p>Java cannot exchange two cells in a single step. If you wrote <code>a[j] = a[j + 1]; a[j + 1] = a[j];</code> both cells would end up equal, because the first line destroys the original <code>a[j]</code>. A third variable, <code>temp</code>, keeps it safe. Follow the swap of <code>a[j] = 4</code> and <code>a[j + 1] = 2</code>:</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Step</th><th>Code</th><th>temp</th><th>a[j]</th><th>a[j + 1]</th><th>What happened</th></tr></thead><tbody><tr><td>0</td><td>(before)</td><td>—</td><td>4</td><td>2</td><td>Out of order, so we swap</td></tr><tr><td>1</td><td><code>int temp = a[j];</code></td><td><strong>4</strong></td><td>4</td><td>2</td><td>The 4 is saved</td></tr><tr><td>2</td><td><code>a[j] = a[j + 1];</code></td><td>4</td><td><strong>2</strong></td><td>2</td><td>Both cells hold 2; the 4 survives only in <code>temp</code></td></tr><tr><td>3</td><td><code>a[j + 1] = temp;</code></td><td>4</td><td>2</td><td><strong>4</strong></td><td>The 4 is restored on the right: swapped</td></tr></tbody></table></div>\r\n        <h3>Swap versus shift</h3>\r\n        <p>Insertion sort <em>shifts</em>: it copies a larger value one place right while the key waits in a variable, then drops the key in once. Bubble sort <em>swaps</em>: it exchanges two neighbours using three assignments. They fix the same kind of problem (an out-of-order pair) but a swap does more writing, which is one reason insertion sort is usually the faster of the two in practice.</p>\r\n        <h3>Every swap fixes exactly one inversion</h3>\r\n        <p>An <strong>inversion</strong> is a pair of values in the wrong order. In <code>[4, 2, 5, 1, 3]</code> the inversions are (4,2), (4,1), (4,3), (2,1), (5,1), (5,3): <strong>6</strong> of them. A swap of neighbours repairs exactly one pair and breaks none, so bubble sort needs exactly <strong>6 swaps</strong> for this array, and that is what the trace shows. Counting inversions is a quick way to predict the number of swaps before you trace anything.</p>\r\n    \r\n      "
  },
  "bubble": {
    "id": "bubble",
    "title": "Compare neighbouring values",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort</span>\r\n        <h2 id=\"bubble-concept\">Compare neighbouring values</h2>\r\n        <p class=\"lede\">Bubble sort repeatedly compares adjacent values. When the left value is larger, the pair swaps. After one complete pass, the largest unsorted value has moved to the end.</p>\r\n\r\n        <h3 id=\"bubble-illustration\">Illustration · first pass</h3>\r\n        <p>Start with the lecture array <code>[63, 29, 72, 85, 18]</code>.</p>\r\n        <div class=\"compare-list\">\r\n          <div class=\"compare\"><span class=\"compare-num\">1</span><code>63 &gt; 29</code><span class=\"verdict move\">swap → [29,63,72,85,18]</span></div>\r\n          <div class=\"compare\"><span class=\"compare-num\">2</span><code>63 &gt; 72</code><span class=\"verdict\">no swap</span></div>\r\n          <div class=\"compare\"><span class=\"compare-num\">3</span><code>72 &gt; 85</code><span class=\"verdict\">no swap</span></div>\r\n          <div class=\"compare\"><span class=\"compare-num\">4</span><code>85 &gt; 18</code><span class=\"verdict move\">swap → [29,63,72,18,85]</span></div>\r\n        </div>\r\n        <div class=\"array-wrap\"><div class=\"array\"><span class=\"cell\">29</span><span class=\"cell\">63</span><span class=\"cell\">72</span><span class=\"cell\">18</span><span class=\"divider\"></span><span class=\"cell sorted\" data-label=\"locked\">85</span></div></div>\r\n\r\n        <h3 id=\"bubble-trace\">Trace table</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Array after pass</th><th>Comparisons</th><th>Swaps</th><th>Guaranteed result</th></tr></thead><tbody>\r\n          <tr><td>1</td><td><code>[29,63,72,18,85]</code></td><td>4</td><td>2</td><td>85 is fixed</td></tr>\r\n          <tr><td>2</td><td><code>[29,63,18,72,85]</code></td><td>3</td><td>1</td><td>72 is fixed</td></tr>\r\n          <tr><td>3</td><td><code>[29,18,63,72,85]</code></td><td>2</td><td>1</td><td>63 is fixed</td></tr>\r\n          <tr><td>4</td><td><code>[18,29,63,72,85]</code></td><td>1</td><td>1</td><td>Array sorted</td></tr>\r\n        </tbody></table></div>\r\n\r\n        <h3 id=\"bubble-implementation\">Implementation</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Optimised bubble sort</span></div><pre><code><span class=\"kw\">public static void</span> bubbleSort(<span class=\"ty\">int</span>[] arr) {\r\n    <span class=\"cm\">// Each pass locks one more large value at the right.</span>\r\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> pass = 0; pass &lt; arr.length - 1; pass++) {\r\n        <span class=\"ty\">boolean</span> swapped = <span class=\"kw\">false</span>;\r\n        <span class=\"cm\">// Ignore the positions already locked by earlier passes.</span>\r\n        <span class=\"kw\">for</span> (<span class=\"ty\">int</span> j = 0; j &lt; arr.length - 1 - pass; j++) {\r\n            <span class=\"cm\">// Ascending order: swap an inverted neighbouring pair.</span>\r\n            <span class=\"kw\">if</span> (arr[j] &gt; arr[j + 1]) {\r\n                <span class=\"ty\">int</span> temp = arr[j];\r\n                arr[j] = arr[j + 1];\r\n                arr[j + 1] = temp;\r\n                swapped = <span class=\"kw\">true</span>;\r\n            }\r\n        }\r\n        <span class=\"cm\">// No swaps means the whole array is already sorted.</span>\r\n        <span class=\"kw\">if</span> (!swapped) <span class=\"kw\">break</span>;\r\n    }\r\n}</code></pre></div>\r\n        <details><summary>Recursive bubble sort</summary><div class=\"answer\"><p>First call: <code>bubbleSortRec(arr, arr.length)</code>.</p><pre><code><span class=\"kw\">public static void</span> bubbleSortRec(<span class=\"ty\">int</span>[] arr, <span class=\"ty\">int</span> n) {\r\n    <span class=\"cm\">// Base case: zero or one active value is sorted.</span>\r\n    <span class=\"kw\">if</span> (n &lt;= 1) <span class=\"kw\">return</span>;\r\n\r\n    <span class=\"ty\">boolean</span> swapped = <span class=\"kw\">false</span>;\r\n    <span class=\"cm\">// One pass moves the largest active value to index n - 1.</span>\r\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> j = 0; j &lt; n - 1; j++) {\r\n        <span class=\"kw\">if</span> (arr[j] &gt; arr[j + 1]) {\r\n            <span class=\"ty\">int</span> temp = arr[j];\r\n            arr[j] = arr[j + 1];\r\n            arr[j + 1] = temp;\r\n            swapped = <span class=\"kw\">true</span>;\r\n        }\r\n    }\r\n    <span class=\"cm\">// Sort the remaining prefix only if the pass changed it.</span>\r\n    <span class=\"kw\">if</span> (swapped) bubbleSortRec(arr, n - 1);\r\n}</code></pre></div></details>\r\n\r\n        <div class=\"audit-grid\">\r\n          <div class=\"from-scratch\"><strong>Write it from scratch</strong><ol><li>Repeat passes.</li><li>Compare indexes <code>j</code> and <code>j + 1</code>.</li><li>Swap an inverted pair.</li><li>Shorten the next pass.</li><li>Stop early after a no-swap pass.</li></ol></div>\r\n          <div class=\"direction-card\"><strong>Ascending ↔ descending</strong><p>Ascending swaps when <code>arr[j] &gt; arr[j+1]</code>. Descending swaps when <code>arr[j] &lt; arr[j+1]</code>.</p><p><strong>Same pair, opposite decision:</strong> for neighbours <code>63, 29</code>, ascending swaps (<code>63 &gt; 29</code>) while descending keeps them (<code>63 &lt; 29</code> is false). In every descending pass the <em>smallest</em> active value is carried to the right edge.</p></div>\r\n          <div class=\"debug-list\"><strong>Debug checklist</strong><ul><li>Stop at <code>n - 1 - pass</code>.</li><li>Reset <code>swapped</code> for every pass.</li><li>Use a temporary variable for the swap.</li></ul></div>\r\n        </div>\r\n\r\n                <h3 id=\"bubble-example\">Worked example · full run on <code>[4, 2, 5, 1, 3]</code></h3><p>This is the same array the insertion-sort chapter uses, so the work can be compared. The orange line marks the boundary of the values already locked at the right.</p><div class=\"worked-visual\" aria-label=\"Four-pass bubble sort trace of 4, 2, 5, 1, 3\"><div class=\"worked-step\"><h4>Pass 1 · compare neighbours with j = 0..3 (pairs within cells 0–4) · 4 comparisons, 3 swaps</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array before pass 1: [4, 2, 5, 1, 3]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">4</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">5</span><span class=\"cell\" data-label=\"3\">1</span><span class=\"cell\" data-label=\"4\">3</span></div></div><div class=\"compare-list\"><div class=\"compare\"><span class=\"compare-num\">1</span><code>4 &gt; 2</code><span class=\"verdict move\">swap → [2, 4, 5, 1, 3]</span></div><div class=\"compare\"><span class=\"compare-num\">2</span><code>4 &gt; 5</code><span class=\"verdict\">no swap</span></div><div class=\"compare\"><span class=\"compare-num\">3</span><code>5 &gt; 1</code><span class=\"verdict move\">swap → [2, 4, 1, 5, 3]</span></div><div class=\"compare\"><span class=\"compare-num\">4</span><code>5 &gt; 3</code><span class=\"verdict move\">swap → [2, 4, 1, 3, 5]</span></div></div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array after pass 1: [2, 4, 1, 3, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">4</span><span class=\"cell\" data-label=\"2\">1</span><span class=\"cell\" data-label=\"3\">3</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell sorted\" data-label=\"4 locked\">5</span></div></div><p>After pass 1, <code>5</code> is fixed at index 4.</p></div><div class=\"worked-step\"><h4>Pass 2 · compare neighbours with j = 0..2 (pairs within cells 0–3) · 3 comparisons, 2 swaps</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array before pass 2: [2, 4, 1, 3, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">4</span><span class=\"cell\" data-label=\"2\">1</span><span class=\"cell\" data-label=\"3\">3</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div><div class=\"compare-list\"><div class=\"compare\"><span class=\"compare-num\">1</span><code>2 &gt; 4</code><span class=\"verdict\">no swap</span></div><div class=\"compare\"><span class=\"compare-num\">2</span><code>4 &gt; 1</code><span class=\"verdict move\">swap → [2, 1, 4, 3, 5]</span></div><div class=\"compare\"><span class=\"compare-num\">3</span><code>4 &gt; 3</code><span class=\"verdict move\">swap → [2, 1, 3, 4, 5]</span></div></div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array after pass 2: [2, 1, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">1</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell sorted\" data-label=\"3 locked\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div><p>After pass 2, <code>4</code> is fixed at index 3.</p></div><div class=\"worked-step\"><h4>Pass 3 · compare neighbours with j = 0..1 (pairs within cells 0–2) · 2 comparisons, 1 swap</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array before pass 3: [2, 1, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">1</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div><div class=\"compare-list\"><div class=\"compare\"><span class=\"compare-num\">1</span><code>2 &gt; 1</code><span class=\"verdict move\">swap → [1, 2, 3, 4, 5]</span></div><div class=\"compare\"><span class=\"compare-num\">2</span><code>2 &gt; 3</code><span class=\"verdict\">no swap</span></div></div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array after pass 3: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell sorted\" data-label=\"2 locked\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div><p>After pass 3, <code>3</code> is fixed at index 2.</p></div><div class=\"worked-step\"><h4>Pass 4 · compare neighbours with j = 0 only (cells 0–1) · 1 comparison, 0 swaps</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array before pass 4: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div><div class=\"compare-list\"><div class=\"compare\"><span class=\"compare-num\">1</span><code>1 &gt; 2</code><span class=\"verdict\">no swap</span></div></div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array after pass 4: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell sorted\" data-label=\"1 locked\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div><p>After pass 4, <code>2</code> is fixed at index 1.</p></div></div><div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Array after pass</th><th>Comparisons</th><th>Swaps</th><th>Guaranteed</th></tr></thead><tbody><tr><td>1</td><td><code>[2, 4, 1, 3, 5]</code></td><td>4</td><td>3</td><td>5 fixed</td></tr><tr><td>2</td><td><code>[2, 1, 3, 4, 5]</code></td><td>3</td><td>2</td><td>4 fixed</td></tr><tr><td>3</td><td><code>[1, 2, 3, 4, 5]</code></td><td>2</td><td>1</td><td>3 fixed</td></tr><tr><td>4</td><td><code>[1, 2, 3, 4, 5]</code></td><td>1</td><td>0</td><td>Array sorted</td></tr><tr><td><strong>Total</strong></td><td>—</td><td><strong>10</strong></td><td><strong>6</strong></td><td>Sorted</td></tr></tbody></table></div><div class=\"result-line\">Sorted after 4 passes: <code>10</code> comparisons and <code>6</code> swaps. The 6 swaps equal the 6 inversions in the starting array.</div>\r\n        <h3>Best case · already sorted</h3>\r\n        <p>For <code>[1,2,3,4]</code>, show every neighbour comparison in the first pass.</p>\r\n        <div class=\"worked-visual\"><div class=\"worked-step\"><h4>Pass 1 · active range 0..3</h4><div class=\"array-wrap\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span></div></div><div class=\"compare-list\"><div class=\"compare\"><span class=\"compare-num\">1</span><code>1 &gt; 2</code><span class=\"verdict\">false · no swap</span></div><div class=\"compare\"><span class=\"compare-num\">2</span><code>2 &gt; 3</code><span class=\"verdict\">false · no swap</span></div><div class=\"compare\"><span class=\"compare-num\">3</span><code>3 &gt; 4</code><span class=\"verdict\">false · no swap</span></div></div><div class=\"result-line\"><code>swapped == false</code> → stop after one pass. Best time: <code>O(n)</code>.</div></div></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Before</th><th>Comparisons</th><th>Swaps</th><th>After</th><th>Decision</th></tr></thead><tbody><tr><td>1</td><td><code>[1,2,3,4]</code></td><td>3</td><td>0</td><td><code>[1,2,3,4]</code></td><td>Stop early</td></tr></tbody></table></div>\r\n        <div class=\"properties\"><div class=\"property\"><small>Best</small><b>O(n)*</b></div><div class=\"property\"><small>Average</small><b>O(n²)</b></div><div class=\"property\"><small>Worst</small><b>O(n²)</b></div><div class=\"property\"><small>Stable</small><b>Yes</b></div><div class=\"property\"><small>In-place</small><b>Yes</b></div><div class=\"property\"><small>Adaptive</small><b>Yes*</b></div><div class=\"property\"><small>Iterative space</small><b>O(1)</b></div><div class=\"property\"><small>Recursive space</small><b>O(n)</b></div></div>\r\n\r\n        <p class=\"fine-print\">* Best case <code>O(n)</code> and “adaptive” apply to the optimised version shown here, which stops after a pass with no swaps. Without the <code>swapped</code> flag, bubble sort always makes <code>n(n − 1) / 2</code> comparisons.</p>\r\n\r\n        <h3 id=\"bubble-questions\">Questions</h3>\r\n        <details><summary>What does one full pass guarantee?</summary><div class=\"answer\">The largest value in the unsorted section reaches its final position at the right.</div></details>\r\n        <details><summary>Why does the inner loop become shorter?</summary><div class=\"answer\">Values at the right have already been locked into their final positions, so comparing them again would be wasted work.</div></details>\r\n        <div class=\"method-summary\"><strong>Bubble sort in one sentence</strong><p>Swap inverted neighbours over repeated passes so the largest active value bubbles into its final position on the right.</p></div>\r\n      "
  },
  "bubble-descending": {
    "id": "bubble-descending",
    "title": "Descending order",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · Descending order</span>\r\n        <h2>Descending order</h2>\r\n        \r\n        <p>To sort from largest to smallest, change <strong>one symbol</strong>: swap when the left value is <em>smaller</em> than its right neighbour.</p>\r\n        <div class=\"two-col\">\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>Ascending</span></div><pre><code><span class=\"kw\">if</span> (arr[j] &gt; arr[j + 1]) {\r\n    swap(arr, j, j + 1);\r\n}</code></pre></div>\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>Descending</span></div><pre><code><span class=\"kw\">if</span> (arr[j] &lt; arr[j + 1]) {\r\n    swap(arr, j, j + 1);\r\n}</code></pre></div>\r\n        </div>\r\n        <p>Nothing else moves: the loops, the shrinking range and the <code>swapped</code> flag stay identical. The only difference is which value gets carried. In descending order the <em>smallest</em> value of the active range is carried to the right end each pass, and the largest values drift left.</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th></th><th>Ascending</th><th>Descending</th></tr></thead><tbody><tr><td>Start</td><td><code>[4, 2, 5, 1, 3]</code></td><td><code>[4, 2, 5, 1, 3]</code></td></tr><tr><td>After pass 1</td><td><code>[2, 4, 1, 3, 5]</code> · 3 swaps</td><td><code>[4, 5, 2, 3, 1]</code> · 2 swaps</td></tr><tr><td>After pass 2</td><td><code>[2, 1, 3, 4, 5]</code> · 2 swaps</td><td><code>[5, 4, 3, 2, 1]</code> · 2 swaps</td></tr><tr><td>After pass 3</td><td><code>[1, 2, 3, 4, 5]</code> · 1 swaps</td><td><code>[5, 4, 3, 2, 1]</code> · 0 swaps</td></tr><tr><td>After pass 4</td><td><code>[1, 2, 3, 4, 5]</code> · 0 swaps</td><td>—</td></tr></tbody></table></div>\r\n        <p>Both runs start from the same array. Ascending needs <strong>6 swaps</strong> (the 6 inversions). Descending needs <strong>4 swaps</strong>: out of the 10 possible pairs, 6 are out of order for ascending, so the other 10 − 6 = 4 pairs are out of order for descending. Comparisons: 10 for ascending and 9 for descending, because the early-exit pass happens at a different moment.</p>\r\n        <div class=\"callout\"><strong>Test habit:</strong> when a question says <em>descending</em>, write the direction at the top of your working and check the first comparison before you start. Most lost marks on this question type come from silently sorting in the wrong direction.</div>\r\n    \r\n      "
  },
  "bubble-examples": {
    "id": "bubble-examples",
    "title": "Worked examples",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · Worked examples</span>\r\n        <h2>Worked examples</h2>\r\n        <p class=\"lede\">Six arrays, each chosen to teach one thing: the best case, the worst case, fast values, slow values, stability, and a longer realistic run.</p>\r\n        <article class=\"example-card\"><h3>Already sorted · <code>[1, 2, 3, 4, 5]</code></h3><p>Every neighbouring pair is already in order, so the first pass swaps nothing.</p><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Start [1, 2, 3, 4, 5]\"><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>1</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>2</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>3</small></div><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>4</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>5</small></div></div></figure><div class=\"worked-visual\" aria-label=\"Bubble sort snapshots for [1, 2, 3, 4, 5]\"><div class=\"worked-step\"><h4>Start</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After pass 1 · no swaps, so the array is sorted</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 1: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Pairs compared</th><th>Array after the pass</th><th>Comparisons</th><th>Swaps</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td><code>[1, 2, 3, 4, 5]</code></td><td>—</td><td>—</td></tr><tr><td>1</td><td>j = 0..3</td><td><code>[1, 2, 3, 4, 5]</code> <em>(no swaps: stop)</em></td><td>4</td><td>0</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>sorted</strong></td><td><strong>4</strong></td><td><strong>0</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>4</code> comparisons and <code>0</code> swaps: one pass is enough. This early exit is what makes bubble sort <code>O(n)</code> in the best case, <em>but only because of the swapped flag</em>.</div></article><article class=\"example-card\"><h3>Reverse order · <code>[5, 4, 3, 2, 1]</code></h3><p>Every pair is out of order, so every comparison swaps.</p><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Start [5, 4, 3, 2, 1]\"><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>5</small></div><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>4</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>3</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>2</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>1</small></div></div></figure><div class=\"worked-visual\" aria-label=\"Bubble sort snapshots for [5, 4, 3, 2, 1]\"><div class=\"worked-step\"><h4>Start</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [5, 4, 3, 2, 1]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">5</span><span class=\"cell\" data-label=\"1\">4</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">2</span><span class=\"cell\" data-label=\"4\">1</span></div></div></div><div class=\"worked-step\"><h4>After pass 1 · the last 1 cell is final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 1: [4, 3, 2, 1, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">4</span><span class=\"cell\" data-label=\"1\">3</span><span class=\"cell\" data-label=\"2\">2</span><span class=\"cell\" data-label=\"3\">1</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After pass 2 · the last 2 cells are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 2: [3, 2, 1, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">3</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">1</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After pass 3 · the last 3 cells are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 3: [2, 1, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">1</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After pass 4 · the last 4 cells are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 4: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Pairs compared</th><th>Array after the pass</th><th>Comparisons</th><th>Swaps</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td><code>[5, 4, 3, 2, 1]</code></td><td>—</td><td>—</td></tr><tr><td>1</td><td>j = 0..3</td><td><code>[4, 3, 2, 1, 5]</code></td><td>4</td><td>4</td></tr><tr><td>2</td><td>j = 0..2</td><td><code>[3, 2, 1, 4, 5]</code></td><td>3</td><td>3</td></tr><tr><td>3</td><td>j = 0..1</td><td><code>[2, 1, 3, 4, 5]</code></td><td>2</td><td>2</td></tr><tr><td>4</td><td>j = 0 only</td><td><code>[1, 2, 3, 4, 5]</code></td><td>1</td><td>1</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>sorted</strong></td><td><strong>10</strong></td><td><strong>10</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>10</code> comparisons and <code>10</code> swaps: <code>1 + 2 + 3 + 4 = n(n − 1) / 2</code>. Comparisons and swaps are equal here, the worst case.</div></article><article class=\"example-card\"><h3>A large value near the front · <code>[5, 1, 2, 3, 4]</code></h3><p>The one out-of-place value is large, so a single pass carries it all the way to the right.</p><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Start [5, 1, 2, 3, 4]\"><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>5</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>1</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>2</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>3</small></div><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>4</small></div></div></figure><div class=\"worked-visual\" aria-label=\"Bubble sort snapshots for [5, 1, 2, 3, 4]\"><div class=\"worked-step\"><h4>Start</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [5, 1, 2, 3, 4]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">5</span><span class=\"cell\" data-label=\"1\">1</span><span class=\"cell\" data-label=\"2\">2</span><span class=\"cell\" data-label=\"3\">3</span><span class=\"cell\" data-label=\"4\">4</span></div></div></div><div class=\"worked-step\"><h4>After pass 1 · the last 1 cell is final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 1: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After pass 2 · no swaps, so the array is sorted</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 2: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Pairs compared</th><th>Array after the pass</th><th>Comparisons</th><th>Swaps</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td><code>[5, 1, 2, 3, 4]</code></td><td>—</td><td>—</td></tr><tr><td>1</td><td>j = 0..3</td><td><code>[1, 2, 3, 4, 5]</code></td><td>4</td><td>4</td></tr><tr><td>2</td><td>j = 0..2</td><td><code>[1, 2, 3, 4, 5]</code> <em>(no swaps: stop)</em></td><td>3</td><td>0</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>sorted</strong></td><td><strong>7</strong></td><td><strong>4</strong></td></tr></tbody></table></div><div class=\"result-line\">Only <code>2</code> passes (the second one just confirms the order), <code>4</code> swaps. Large values travel fast: bubble sort calls these <em>rabbits</em>.</div></article><article class=\"example-card\"><h3>A small value near the back · <code>[2, 3, 4, 5, 1]</code></h3><p>The same five values, but now the out-of-place value is the small one at the end.</p><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Start [2, 3, 4, 5, 1]\"><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>2</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>3</small></div><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>4</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>5</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>1</small></div></div></figure><div class=\"worked-visual\" aria-label=\"Bubble sort snapshots for [2, 3, 4, 5, 1]\"><div class=\"worked-step\"><h4>Start</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [2, 3, 4, 5, 1]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">3</span><span class=\"cell\" data-label=\"2\">4</span><span class=\"cell\" data-label=\"3\">5</span><span class=\"cell\" data-label=\"4\">1</span></div></div></div><div class=\"worked-step\"><h4>After pass 1 · the last 1 cell is final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 1: [2, 3, 4, 1, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">3</span><span class=\"cell\" data-label=\"2\">4</span><span class=\"cell\" data-label=\"3\">1</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After pass 2 · the last 2 cells are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 2: [2, 3, 1, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">3</span><span class=\"cell\" data-label=\"2\">1</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After pass 3 · the last 3 cells are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 3: [2, 1, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">1</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After pass 4 · the last 4 cells are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 4: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Pairs compared</th><th>Array after the pass</th><th>Comparisons</th><th>Swaps</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td><code>[2, 3, 4, 5, 1]</code></td><td>—</td><td>—</td></tr><tr><td>1</td><td>j = 0..3</td><td><code>[2, 3, 4, 1, 5]</code></td><td>4</td><td>1</td></tr><tr><td>2</td><td>j = 0..2</td><td><code>[2, 3, 1, 4, 5]</code></td><td>3</td><td>1</td></tr><tr><td>3</td><td>j = 0..1</td><td><code>[2, 1, 3, 4, 5]</code></td><td>2</td><td>1</td></tr><tr><td>4</td><td>j = 0 only</td><td><code>[1, 2, 3, 4, 5]</code></td><td>1</td><td>1</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>sorted</strong></td><td><strong>10</strong></td><td><strong>4</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>4</code> passes, <code>4</code> swaps. The <code>1</code> moves one place left per pass, so it needs four passes. Small values near the end are <em>turtles</em>, and they are what makes bubble sort slow.</div></article><article class=\"example-card\"><h3>Duplicates · <code>[3ᵃ, 1, 3ᵇ, 2]</code></h3><p>Two equal values, labelled so we can tell them apart. The rule is to swap only when the left value is <em>strictly</em> larger.</p><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Start [3ᵃ, 1, 3ᵇ, 2]\"><div class=\"bar\" style=\"--p:1.000\"><i></i><b>3</b><small>3ᵃ</small></div><div class=\"bar\" style=\"--p:0.333\"><i></i><b>1</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>3</b><small>3ᵇ</small></div><div class=\"bar\" style=\"--p:0.667\"><i></i><b>2</b><small>2</small></div></div></figure><div class=\"worked-visual\" aria-label=\"Bubble sort snapshots for [3ᵃ, 1, 3ᵇ, 2]\"><div class=\"worked-step\"><h4>Start</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [3ᵃ, 1, 3ᵇ, 2]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">3ᵃ</span><span class=\"cell\" data-label=\"1\">1</span><span class=\"cell\" data-label=\"2\">3ᵇ</span><span class=\"cell\" data-label=\"3\">2</span></div></div></div><div class=\"worked-step\"><h4>After pass 1 · the last 1 cell is final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 1: [1, 3ᵃ, 2, 3ᵇ]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell\" data-label=\"1\">3ᵃ</span><span class=\"cell\" data-label=\"2\">2</span><span class=\"cell sorted\" data-label=\"3\">3ᵇ</span></div></div></div><div class=\"worked-step\"><h4>After pass 2 · the last 2 cells are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 2: [1, 2, 3ᵃ, 3ᵇ]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3ᵃ</span><span class=\"cell sorted\" data-label=\"3\">3ᵇ</span></div></div></div><div class=\"worked-step\"><h4>After pass 3 · no swaps, so the array is sorted</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 3: [1, 2, 3ᵃ, 3ᵇ]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3ᵃ</span><span class=\"cell sorted\" data-label=\"3\">3ᵇ</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Pairs compared</th><th>Array after the pass</th><th>Comparisons</th><th>Swaps</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td><code>[3ᵃ, 1, 3ᵇ, 2]</code></td><td>—</td><td>—</td></tr><tr><td>1</td><td>j = 0..2</td><td><code>[1, 3ᵃ, 2, 3ᵇ]</code></td><td>3</td><td>2</td></tr><tr><td>2</td><td>j = 0..1</td><td><code>[1, 2, 3ᵃ, 3ᵇ]</code></td><td>2</td><td>1</td></tr><tr><td>3</td><td>j = 0 only</td><td><code>[1, 2, 3ᵃ, 3ᵇ]</code> <em>(no swaps: stop)</em></td><td>1</td><td>0</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>sorted</strong></td><td><strong>6</strong></td><td><strong>3</strong></td></tr></tbody></table></div><div class=\"result-line\">The result is <code>[1, 2, 3ᵃ, 3ᵇ]</code>: <code>3ᵃ</code> is still before <code>3ᵇ</code>. Equal neighbours are never swapped, so bubble sort is <strong>stable</strong>. Writing <code>&gt;=</code> instead of <code>&gt;</code> would swap them and lose that.</div></article><article class=\"example-card\"><h3>A longer array · <code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code> (nine values)</h3><p>This is the array from Test 1, question 3. With nine values the snapshots are long, so only the table after each pass is shown. Try predicting each row before you read it.</p><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Start [50, 83, 76, 6, 32, 90, 12, 2, 59]\"><div class=\"bar\" style=\"--p:0.556\"><i></i><b>50</b><small>50</small></div><div class=\"bar\" style=\"--p:0.922\"><i></i><b>83</b><small>83</small></div><div class=\"bar\" style=\"--p:0.844\"><i></i><b>76</b><small>76</small></div><div class=\"bar\" style=\"--p:0.067\"><i></i><b>6</b><small>6</small></div><div class=\"bar\" style=\"--p:0.356\"><i></i><b>32</b><small>32</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>90</b><small>90</small></div><div class=\"bar\" style=\"--p:0.133\"><i></i><b>12</b><small>12</small></div><div class=\"bar\" style=\"--p:0.022\"><i></i><b>2</b><small>2</small></div><div class=\"bar\" style=\"--p:0.656\"><i></i><b>59</b><small>59</small></div></div></figure><div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Pairs compared</th><th>Array after the pass</th><th>Comparisons</th><th>Swaps</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td><code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code></td><td>—</td><td>—</td></tr><tr><td>1</td><td>j = 0..7</td><td><code>[50, 76, 6, 32, 83, 12, 2, 59, 90]</code></td><td>8</td><td>6</td></tr><tr><td>2</td><td>j = 0..6</td><td><code>[50, 6, 32, 76, 12, 2, 59, 83, 90]</code></td><td>7</td><td>5</td></tr><tr><td>3</td><td>j = 0..5</td><td><code>[6, 32, 50, 12, 2, 59, 76, 83, 90]</code></td><td>6</td><td>5</td></tr><tr><td>4</td><td>j = 0..4</td><td><code>[6, 32, 12, 2, 50, 59, 76, 83, 90]</code></td><td>5</td><td>2</td></tr><tr><td>5</td><td>j = 0..3</td><td><code>[6, 12, 2, 32, 50, 59, 76, 83, 90]</code></td><td>4</td><td>2</td></tr><tr><td>6</td><td>j = 0..2</td><td><code>[6, 2, 12, 32, 50, 59, 76, 83, 90]</code></td><td>3</td><td>1</td></tr><tr><td>7</td><td>j = 0..1</td><td><code>[2, 6, 12, 32, 50, 59, 76, 83, 90]</code></td><td>2</td><td>1</td></tr><tr><td>8</td><td>j = 0 only</td><td><code>[2, 6, 12, 32, 50, 59, 76, 83, 90]</code> <em>(no swaps: stop)</em></td><td>1</td><td>0</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>sorted</strong></td><td><strong>36</strong></td><td><strong>22</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>36</code> comparisons and <code>22</code> swaps (= the <code>22</code> inversions). Count how many passes it needed: the <code>2</code> sits at index 7 and must walk to index 0, one place per pass.</div></article>\r\n      "
  },
  "bubble-properties": {
    "id": "bubble-properties",
    "title": "Properties",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · Properties</span>\r\n        <h2>Properties</h2>\r\n        \r\n        <div class=\"properties\"><div class=\"property\"><small>Best time</small><b>O(n)*</b></div><div class=\"property\"><small>Average time</small><b>O(n²)</b></div><div class=\"property\"><small>Worst time</small><b>O(n²)</b></div><div class=\"property\"><small>Extra space</small><b>O(1)</b></div><div class=\"property\"><small>Stable</small><b>Yes</b></div><div class=\"property\"><small>In-place</small><b>Yes</b></div><div class=\"property\"><small>Adaptive</small><b>Yes*</b></div><div class=\"property\"><small>Type</small><b>Comparison</b></div></div>\r\n        <p class=\"fine-print\">* only with the <code>swapped</code> early-exit flag. Without it, bubble sort always makes <code>n(n − 1) / 2</code> comparisons.</p>\r\n        <h3>Stable</h3>\r\n        <p>Equal values keep their original left-to-right order, because a pair is swapped only when the left value is <em>strictly greater</em>. Equal neighbours are left alone, so they can never cross each other.</p>\r\n        <h3>In-place</h3>\r\n        <p>Everything happens inside the original array. The only extra storage is a few variables (<code>j</code>, <code>pass</code>, <code>temp</code>, <code>swapped</code>), so the extra space is constant, <code>O(1)</code>.</p>\r\n        <h3>Adaptive (with the flag)</h3>\r\n        <p>On sorted or nearly sorted data the flag lets the algorithm stop after very few passes. But note <em>nearly sorted</em> must mean “no small value is far to the right”: one turtle forces many passes (see <code>[2, 3, 4, 5, 1]</code>).</p>\r\n        <h3>Comparison-based</h3>\r\n        <p>All decisions come from asking whether one value is greater than another; it never uses the value's digits or range. This is why no comparison-based sort can beat <code>O(n log n)</code> in general.</p>\r\n        <h3>Swaps equal inversions</h3>\r\n        <p>The number of swaps is exactly the number of inversions in the input, from 0 (sorted) to <code>n(n − 1) / 2</code> (reversed).</p>\r\n    \r\n      "
  },
  "bubble-complexity": {
    "id": "bubble-complexity",
    "title": "Why those complexities occur",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · Why those complexities occur</span>\r\n        <h2>Why those complexities occur</h2>\r\n        \r\n        <div class=\"complexity-grid\"><div class=\"complexity-item\"><strong>Best case · O(n)</strong>An already sorted array: pass 1 makes <code>n − 1</code> comparisons, finds no swap and stops.</div><div class=\"complexity-item\"><strong>Worst case · O(n²)</strong>A reversed array: every pair is out of order in every pass, so all <code>n(n − 1) / 2</code> comparisons also swap.</div></div>\r\n        <h3>Counting the comparisons</h3>\r\n        <p>Pass 1 compares <code>n − 1</code> pairs. Pass 2 compares one fewer, because the last cell is locked. Pass 3 one fewer again, down to a final pass of one comparison. For five values:</p>\r\n        <div class=\"stairs\" role=\"img\" aria-label=\"4 + 3 + 2 + 1 = 10 comparisons\"><div class=\"stair-row\"><span>pass 1</span><div class=\"stair-sq\"><i></i><i></i><i></i><i></i></div><span class=\"stair-n\">4</span></div><div class=\"stair-row\"><span>pass 2</span><div class=\"stair-sq\"><i></i><i></i><i></i></div><span class=\"stair-n\">3</span></div><div class=\"stair-row\"><span>pass 3</span><div class=\"stair-sq\"><i></i><i></i></div><span class=\"stair-n\">2</span></div><div class=\"stair-row\"><span>pass 4</span><div class=\"stair-sq\"><i></i></div><span class=\"stair-n\">1</span></div><div class=\"stair-total\">total = 4 + 3 + 2 + 1 = <b>10</b></div></div>\r\n        <p>Each row is one pass and each square one comparison. The shape is a staircase, and the area of a staircase of height <code>n − 1</code> is half of a square:</p>\r\n        <div class=\"formula\">(n − 1) + (n − 2) + … + 2 + 1 = n(n − 1) / 2 → O(n²)</div>\r\n        <p>For <code>n = 8</code> the staircase has 28 squares (7 + 6 + 5 + 4 + 3 + 2 + 1). Here is how fast that grows:</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>n (values)</th><th>Comparisons n(n − 1) / 2</th></tr></thead><tbody><tr><td>5</td><td>10</td></tr><tr><td>10</td><td>45</td></tr><tr><td>100</td><td>4,950</td></tr><tr><td>1,000</td><td>499,500</td></tr><tr><td>2,000</td><td>1,999,000</td></tr></tbody></table></div>\r\n        <p>Double the array from 1,000 to 2,000 values and the work does not double, it roughly <strong>quadruples</strong> (499,500 → 1,999,000). That is what “quadratic” means in practice, and it is why bubble sort is only comfortable for small arrays.</p>\r\n        <h3>Best case with the flag</h3>\r\n        <p>For <code>[1, 2, 3, 4, 5]</code> the first pass makes 4 comparisons, sets nothing, and the loop ends: <code>n − 1</code> steps, so <code>O(n)</code>. Without the <code>swapped</code> flag the staircase would still be walked in full.</p>\r\n        <h3>Average case</h3>\r\n        <p>For random data about half of all pairs are inverted, so about <code>n(n − 1) / 4</code> swaps happen. The constant halves, but the growth is still proportional to <code>n²</code>.</p>\r\n        <h3>Space</h3>\r\n        <p>Nothing is copied. A few variables are enough, so the space is <code>O(1)</code>.</p>\r\n    \r\n      "
  },
  "bubble-when": {
    "id": "bubble-when",
    "title": "When to use it",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · When to use it</span>\r\n        <h2>When to use it</h2>\r\n        \r\n        <div class=\"use-grid\"><div class=\"use good\"><strong>A good choice</strong>Teaching the idea of sorting; tiny arrays (a handful of values); checking whether data is already sorted (one pass with no swaps proves it); data where the only disorder is a few <em>large</em> values near the front.</div><div class=\"use poor\"><strong>A poor choice</strong>Anything large or random: <code>O(n²)</code> comparisons grow too fast; data with a small value far to the right (turtles); any situation where you need guaranteed <code>O(n log n)</code> time; and almost every real program, where insertion sort or merge sort does better.</div></div>\r\n        <p>In practice bubble sort is a learning tool, not a working tool. It earns its place because it is the clearest example of <em>repeated local fixing</em>: a rule about two neighbours, applied repeatedly, produces a globally sorted array. When you are asked in an exam to choose between algorithms for a large array, bubble sort is almost never the answer.</p>\r\n        <p>Compared with its two quadratic cousins: <strong>insertion sort</strong> does less writing and is better on nearly sorted data; <strong>selection sort</strong> makes the fewest swaps. Bubble sort is the one that can notice “already sorted” in a single pass, but only if you remember the flag.</p>\r\n    \r\n      "
  },
  "bubble-mistakes": {
    "id": "bubble-mistakes",
    "title": "Common mistakes",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · Common mistakes</span>\r\n        <h2>Common mistakes</h2>\r\n        <div class=\"mistake\"><span class=\"mistake-no\">1</span><div><strong>Letting the inner loop run to the end every time.</strong><br>With <code>j &lt; arr.length - 1</code> the program still works but re-checks the locked tail. Use <code>j &lt; arr.length - 1 - pass</code> so each pass is shorter.</div></div><div class=\"mistake\"><span class=\"mistake-no\">2</span><div><strong>Reading past the end.</strong><br>The comparison uses <code>arr[j + 1]</code>, so <code>j</code> must stop at <code>length - 2</code>. A loop condition of <code>j &lt; arr.length</code> throws <code>ArrayIndexOutOfBoundsException</code>.</div></div><div class=\"mistake\"><span class=\"mistake-no\">3</span><div><strong>Swapping without a temporary variable.</strong><br><code>a[j] = a[j + 1]; a[j + 1] = a[j];</code> leaves two equal values and loses one. Always save one value in <code>temp</code> first.</div></div><div class=\"mistake\"><span class=\"mistake-no\">4</span><div><strong>Using <code>&gt;=</code> instead of <code>&gt;</code>.</strong><br>Equal values then swap with each other. That wastes swaps and destroys stability.</div></div><div class=\"mistake\"><span class=\"mistake-no\">5</span><div><strong>Forgetting to reset <code>swapped</code> at the start of each pass.</strong><br>If it stays true from an earlier pass, the early exit never triggers and the sort loses its best-case speed.</div></div><div class=\"mistake\"><span class=\"mistake-no\">6</span><div><strong>Writing the array after every swap when asked for “after each pass”.</strong><br>A pass is the whole walk. Record one array per pass, and count swaps and comparisons separately.</div></div><div class=\"mistake\"><span class=\"mistake-no\">7</span><div><strong>Reversing the loops for descending order.</strong><br>Only the comparison changes (<code>&lt;</code> instead of <code>&gt;</code>). The loops, the range and the flag stay the same.</div></div><div class=\"mistake\"><span class=\"mistake-no\">8</span><div><strong>Stopping early for the wrong reason.</strong><br>Stop when a <em>whole pass</em> makes no swaps, not when one pair happens to be in order.</div></div>\r\n      "
  },
  "bubble-summary": {
    "id": "bubble-summary",
    "title": "A test-ready summary",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · A test-ready summary</span>\r\n        <h2>A test-ready summary</h2>\r\n        \r\n        <div class=\"test-summary\">\r\n          <p>Bubble sort is a stable, in-place, comparison-based sorting algorithm. It repeatedly walks through the array, compares each pair of neighbouring values and swaps them when they are in the wrong order, so after each pass the largest remaining value has moved to its final place at the right. Each pass is one cell shorter than the one before, and with a <code>swapped</code> flag it stops as soon as a pass makes no swaps. The number of swaps equals the number of inversions. Its best-case time is O(n) for sorted input, and its average and worst cases are O(n²) with O(1) extra space. It is suitable for teaching and tiny arrays, but not for large or random data.</p>\r\n        </div>\r\n    \r\n      "
  },
  "bubble-practice": {
    "id": "bubble-practice",
    "title": "Practice",
    "body": "\r\n        <span class=\"section-no\">Sorting / Bubble sort · Practice</span>\r\n        <h2>Practice</h2>\r\n        \r\n        <h3>Guided question</h3>\r\n        <p>Use bubble sort (ascending, with the early-exit flag) on <code>[6, 3, 8, 4]</code>. For each pass write every comparison, then the array at the end of the pass.</p>\r\n        <details><summary>Reveal the guided answer</summary><div class=\"answer\"><p><strong>Pass 1:</strong> <code>6 &gt; 3</code> swap; <code>6 &gt; 8</code> keep; <code>8 &gt; 4</code> swap → <code>[3, 6, 4, 8]</code></p><p><strong>Pass 2:</strong> <code>3 &gt; 6</code> keep; <code>6 &gt; 4</code> swap → <code>[3, 4, 6, 8]</code></p><p><strong>Pass 3:</strong> <code>3 &gt; 4</code> keep → <code>[3, 4, 6, 8]</code></p><p><strong>Totals:</strong> 6 comparisons and 3 swaps, in 3 passes. The last pass made no swaps, so the algorithm stopped.</p></div></details>\r\n        <h3>Independent question</h3>\r\n        <p>Trace bubble sort on <code>[9, 4, 7, 3, 5]</code>.</p>\r\n        <ul class=\"checklist\">\r\n          <li>Predict the number of swaps first, using the inversions.</li>\r\n          <li>Write the array after every pass.</li>\r\n          <li>Record the comparisons and swaps in each pass.</li>\r\n          <li>Say why the algorithm stopped.</li>\r\n        </ul>\r\n        <details><summary>Reveal the independent answer</summary><div class=\"answer\"><p>Inversions: <code>7</code>, so exactly 7 swaps are needed.</p><div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Pairs compared</th><th>Array after the pass</th><th>Comparisons</th><th>Swaps</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td><code>[9, 4, 7, 3, 5]</code></td><td>—</td><td>—</td></tr><tr><td>1</td><td>j = 0..3</td><td><code>[4, 7, 3, 5, 9]</code></td><td>4</td><td>4</td></tr><tr><td>2</td><td>j = 0..2</td><td><code>[4, 3, 5, 7, 9]</code></td><td>3</td><td>2</td></tr><tr><td>3</td><td>j = 0..1</td><td><code>[3, 4, 5, 7, 9]</code></td><td>2</td><td>1</td></tr><tr><td>4</td><td>j = 0 only</td><td><code>[3, 4, 5, 7, 9]</code> <em>(no swaps: stop)</em></td><td>1</td><td>0</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>sorted</strong></td><td><strong>10</strong></td><td><strong>7</strong></td></tr></tbody></table></div></div></details>\r\n        <h3>Test-style question</h3>\r\n        <p>Show the contents of the array <code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code> at the end of each pass when sorting <strong>descending</strong> with bubble sort. (This is Test 1, question 3(b), with bubble sort instead of insertion sort.)</p>\r\n        <details><summary>Reveal the test-style answer</summary><div class=\"answer\"><div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Pairs compared</th><th>Array after the pass</th><th>Comparisons</th><th>Swaps</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td><code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code></td><td>—</td><td>—</td></tr><tr><td>1</td><td>j = 0..7</td><td><code>[83, 76, 50, 32, 90, 12, 6, 59, 2]</code></td><td>8</td><td>6</td></tr><tr><td>2</td><td>j = 0..6</td><td><code>[83, 76, 50, 90, 32, 12, 59, 6, 2]</code></td><td>7</td><td>2</td></tr><tr><td>3</td><td>j = 0..5</td><td><code>[83, 76, 90, 50, 32, 59, 12, 6, 2]</code></td><td>6</td><td>2</td></tr><tr><td>4</td><td>j = 0..4</td><td><code>[83, 90, 76, 50, 59, 32, 12, 6, 2]</code></td><td>5</td><td>2</td></tr><tr><td>5</td><td>j = 0..3</td><td><code>[90, 83, 76, 59, 50, 32, 12, 6, 2]</code></td><td>4</td><td>2</td></tr><tr><td>6</td><td>j = 0..2</td><td><code>[90, 83, 76, 59, 50, 32, 12, 6, 2]</code> <em>(no swaps: stop)</em></td><td>3</td><td>0</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>sorted</strong></td><td><strong>33</strong></td><td><strong>14</strong></td></tr></tbody></table></div><p>Remember: descending means the <em>smallest</em> value of the active range is carried to the right end on each pass.</p></div></details>\r\n    \r\n      "
  },
  "selection-array": {
    "id": "selection-array",
    "title": "The array we will sort",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · The array we will sort</span>\r\n        <h2>The array we will sort</h2>\r\n        <p class=\"lede\">The same five values again: <code>[4, 2, 5, 1, 3]</code>, sorted from smallest to largest.</p>\r\n        \r\n        <div class=\"paper-card\">\r\n          <div class=\"kicker\">Starting array</div>\r\n          <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Starting array 4, 2, 5, 1, 3\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">4</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">5</span><span class=\"cell\" data-label=\"3\">1</span><span class=\"cell\" data-label=\"4\">3</span></div></div>\r\n          <figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"The same array as bars\"><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>0</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>2</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>3</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure>\r\n          <div class=\"kicker\">The result we want</div>\r\n          <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Sorted array\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div>\r\n        </div>\r\n        <p>It is the same array that bubble sort and insertion sort use, so you can compare the three methods on identical data. One value deserves attention: the <code>1</code> is the smallest and sits at index 3. Bubble sort moves it one place per pass. Selection sort will find it and move it to the front <strong>in a single swap</strong>.</p>\r\n    \r\n      "
  },
  "selection-definition": {
    "id": "selection-definition",
    "title": "The textbook definition",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · The textbook definition</span>\r\n        <h2>The textbook definition</h2>\r\n        \r\n        <div class=\"paper-card definition\">\r\n          <p><strong>Selection sort</strong> is a comparison-based sorting algorithm that divides the array into a sorted prefix on the left and an unsorted suffix on the right. In each iteration it <em>scans the whole unsorted suffix</em> to find the smallest value, then swaps that value into the first position of the suffix. The sorted prefix therefore grows by one cell per iteration, and every cell in it is already in its final place.</p>\r\n        </div>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Sorted prefix</strong>The cells <code>0 .. i − 1</code>. They hold the smallest values, in order, and never change again.</div><div class=\"term\"><strong>Unsorted suffix</strong>The cells <code>i .. n − 1</code>. The next minimum is somewhere in here.</div><div class=\"term\"><strong>Boundary <code>i</code></strong>The first cell of the unsorted suffix, which is the cell about to be filled.</div><div class=\"term\"><strong>Scan</strong>Looking at every cell of the suffix once, comparing it with the best candidate so far.</div><div class=\"term\"><strong><code>minIndex</code></strong>The <em>position</em> of the smallest value found so far. We remember where it is, not just what it is.</div><div class=\"term\"><strong>Swap</strong>Exchanging <code>array[i]</code> with <code>array[minIndex]</code>. There is at most one per iteration.</div></div>\r\n        <p>The name says what it does: each iteration <strong>selects</strong> the right value for the next position, rather than shuffling values into place as bubble and insertion sort do.</p>\r\n    \r\n      "
  },
  "selection-simple": {
    "id": "selection-simple",
    "title": "In plain language",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · In plain language</span>\r\n        <h2>In plain language</h2>\r\n        <p class=\"lede\">Keep choosing the smallest card from the pile that is left, and lay it down next in the row.</p>\r\n        \r\n        <div class=\"paper-card\">\r\n          <p>Imagine a pile of numbered cards on a table. Look through <strong>all</strong> of them and pull out the smallest; put it at the left end of your row. Now look through the cards that are left, pull out the smallest of those, and put it next in the row. Keep going until the pile is empty. Your row is sorted.</p>\r\n          <p>In an array there is no separate table: the “pile” is the part of the array to the right of the boundary, and “putting it in the row” means swapping the chosen value into the boundary cell. Whatever was sitting in that cell goes to the place the chosen value came from.</p>\r\n        </div>\r\n        <div class=\"strip\" role=\"group\" aria-label=\"Selection sort on 3, 1, 2\"><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"3, 1, 2\"><div class=\"bar\" style=\"--p:1.000\"><i></i><b>3</b><small>0</small></div><div class=\"bar\" style=\"--p:0.333\"><i></i><b>1</b><small>1</small></div><div class=\"bar\" style=\"--p:0.667\"><i></i><b>2</b><small>2</small></div></div></figure><p class=\"fig-cap\">Start</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"smallest is 1\"><div class=\"bar\" style=\"--p:1.000\"><i></i><b>3</b><small>0</small></div><div class=\"bar min\" style=\"--p:0.333\"><i></i><b>1</b><small>1</small></div><div class=\"bar\" style=\"--p:0.667\"><i></i><b>2</b><small>2</small></div></div></figure><p class=\"fig-cap\">i = 0: scan all three, smallest is 1</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"after swap [1, 3, 2]\"><div class=\"bar done\" style=\"--p:0.333\"><i></i><b>1</b><small>0</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>3</b><small>1</small></div><div class=\"bar\" style=\"--p:0.667\"><i></i><b>2</b><small>2</small></div></div></figure><p class=\"fig-cap\">swap it into index 0</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"after second swap\"><div class=\"bar done\" style=\"--p:0.333\"><i></i><b>1</b><small>0</small></div><div class=\"bar done\" style=\"--p:0.667\"><i></i><b>2</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>3</b><small>2</small></div></div></figure><p class=\"fig-cap\">i = 1: smallest of the rest is 2, swap</p></div></div>\r\n        <div class=\"legend\"><span><i class=\"swatch min\"></i>smallest found so far</span><span><i class=\"swatch sorted\"></i>final position</span></div>\r\n        <p>Two iterations were enough for three values: the last cell is automatically correct when all the others are, so the loop only runs <code>n − 1</code> times.</p>\r\n    \r\n      "
  },
  "selection-idea": {
    "id": "selection-idea",
    "title": "The main idea",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · The main idea</span>\r\n        <h2>The main idea</h2>\r\n        \r\n        <p>Selection sort splits the array in two with a movable boundary. Everything left of the boundary is <strong>finished</strong>; everything right of it is untouched. The whole algorithm is: <em>find the smallest value on the right, put it at the boundary, move the boundary one cell right</em>.</p>\r\n        <h3>One scan for the minimum</h3>\r\n        <p>Here is the scan for <code>i = 0</code>. We start by assuming index 0 holds the minimum, then look at every other cell. Whenever we meet something smaller we move our “minimum so far” marker to it. Only when the scan ends do we know the true minimum and swap once.</p>\r\n        <div class=\"strip\" role=\"group\" aria-label=\"Scan for the minimum at i = 0\"><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"assume index 0 is the minimum\"><div class=\"bar min\" style=\"--p:0.800\"><i></i><b>4</b><small>0</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>2</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>3</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure><p class=\"fig-cap\">Start of the scan: assume index 0 holds the minimum</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"after looking at index 1; minimum so far at index 1\"><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>0</small></div><div class=\"bar min\" style=\"--p:0.400\"><i></i><b>2</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>2</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>3</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure><p class=\"fig-cap\">index 1: is 2 &lt; 4? yes, new minimum</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"after looking at index 2; minimum so far at index 1\"><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>0</small></div><div class=\"bar min\" style=\"--p:0.400\"><i></i><b>2</b><small>1</small></div><div class=\"bar cmp\" style=\"--p:1.000\"><i></i><b>5</b><small>2</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>3</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure><p class=\"fig-cap\">index 2: is 5 &lt; 2? no</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"after looking at index 3; minimum so far at index 3\"><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>0</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>2</small></div><div class=\"bar min\" style=\"--p:0.200\"><i></i><b>1</b><small>3</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure><p class=\"fig-cap\">index 3: is 1 &lt; 2? yes, new minimum</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"after looking at index 4; minimum so far at index 3\"><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>0</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>2</small></div><div class=\"bar min\" style=\"--p:0.200\"><i></i><b>1</b><small>3</small></div><div class=\"bar cmp\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure><p class=\"fig-cap\">index 4: is 3 &lt; 1? no</p></div><div class=\"strip-cell\"><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"after the swap [1, 2, 5, 4, 3]\"><div class=\"bar done swap\" style=\"--p:0.200\"><i></i><b>1</b><small>0</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>1</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>2</small></div><div class=\"bar swap\" style=\"--p:0.800\"><i></i><b>4</b><small>3</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>4</small></div></div></figure><p class=\"fig-cap\">scan finished: swap it with index 0</p></div></div>\r\n        <div class=\"legend\"><span><i class=\"swatch min\"></i>smallest found so far</span><span><i class=\"swatch cmp\"></i>being compared</span><span><i class=\"swatch swap\"></i>just swapped</span></div>\r\n        <h3>The prefix is final, not just sorted</h3>\r\n        <p>This is the biggest difference from insertion sort. In insertion sort the left part is sorted <em>among itself</em> but later values may still be inserted in the middle. In selection sort the left part holds the globally smallest values, so a finished cell is <strong>never touched again</strong>.</p>\r\n        <div class=\"worked-visual\" aria-label=\"End of every iteration\"><div class=\"worked-step\"><h4>After i = 0 · swapped index 0 with index 3</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 0: [1, 2, 5, 4, 3]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">5</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">3</span></div></div></div><div class=\"worked-step\"><h4>After i = 1 · the minimum was already in place, so nothing moved</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 1: [1, 2, 5, 4, 3]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"2\">5</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">3</span></div></div></div><div class=\"worked-step\"><h4>After i = 2 · swapped index 2 with index 4</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 2: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After i = 3 · the minimum was already in place, so nothing moved</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 3: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"4\">5</span></div></div></div></div>\r\n        <h3>The cost of choosing</h3>\r\n        <p>Finding the minimum means looking at every cell of the suffix, every time, even if the array was sorted to begin with. The algorithm has no way to know the minimum is already in place until it has checked. That is what you pay for the very small number of swaps.</p>\r\n        <div class=\"callout\"><strong>The repeating recipe:</strong> set <code>minIndex = i</code> → scan <code>i + 1 .. n − 1</code>, updating <code>minIndex</code> whenever a smaller value appears → swap <code>array[i]</code> with <code>array[minIndex]</code> → move <code>i</code> right.</div>\r\n    \r\n      "
  },
  "selection-movements": {
    "id": "selection-movements",
    "title": "Scan, select, swap",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · Scan, select, swap</span>\r\n        <h2>Scan, select, swap</h2>\r\n        \r\n        <p class=\"lede\">Selection sort separates <em>finding</em> from <em>moving</em>. Seeing them as two phases makes the code and the trace easy to follow.</p>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Comparison</strong>A question inside the scan: <code>array[j] &lt; array[minIndex]</code>. Every iteration makes <code>n − 1 − i</code> of them, regardless of the data.</div><div class=\"term\"><strong>Selection</strong>Deciding which cell holds the minimum. Nothing in the array moves during this phase.</div><div class=\"term\"><strong>Swap</strong>The only movement: one exchange per iteration at most, and none if the minimum is already at <code>i</code>.</div><div class=\"term\"><strong>Iteration</strong>One value of <code>i</code>: a full scan plus (maybe) one swap.</div></div>\r\n        <h3>Why remember the index, not the value?</h3>\r\n        <p>Knowing that the smallest value is <code>1</code> is not enough: to swap we must know <em>where</em> the <code>1</code> is. That is why the code keeps <code>minIndex</code>. A common slip is to store <code>min = array[j]</code> and then be unable to find its position.</p>\r\n        <h3>One swap can move a value a long way</h3>\r\n        <p>Bubble sort moves values one neighbour at a time. Selection sort's swap jumps: in iteration 0 the <code>4</code> and the <code>1</code> trade places across three cells. That long jump is what keeps the swap count tiny, but it also has a price, which you will meet in the section on stability: jumping over equal values can reorder them.</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Step</th><th>Code</th><th>Effect on [4, 2, 5, 1, 3]</th></tr></thead><tbody><tr><td>scan</td><td><code>for (j = i + 1; j &lt; n; j++) if (a[j] &lt; a[minIndex]) minIndex = j;</code></td><td><code>minIndex</code> ends at 3 (the value 1). Nothing has moved yet.</td></tr><tr><td>swap</td><td><code>temp = a[i]; a[i] = a[minIndex]; a[minIndex] = temp;</code></td><td><code>[1, 2, 5, 4, 3]</code>: the 4 and the 1 trade places.</td></tr></tbody></table></div>\r\n        <p>Counting rule: <strong>comparisons</strong> for this array total 10 no matter what; <strong>swaps</strong> total 2. Compare that with bubble sort's 6 swaps on the same array.</p>\r\n    \r\n      "
  },
  "selection": {
    "id": "selection",
    "title": "Select the smallest remaining value",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort</span>\r\n        <h2 id=\"selection-concept\">Select the smallest remaining value</h2>\r\n        <p class=\"lede\">Selection sort scans the unsorted section for its smallest value, then swaps that value into the next open position. The sorted section grows from left to right.</p>\r\n\r\n        <h3 id=\"selection-illustration\">Illustration · choose the first minimum</h3>\r\n        <p>In <code>[63,29,72,85,18]</code>, begin with 63 as the assumed minimum. Comparing the remaining values eventually finds 18 at index 4.</p>\r\n        <div class=\"array-wrap\"><div class=\"array\"><span class=\"cell key\" data-label=\"swap out\">63</span><span class=\"cell\">29</span><span class=\"cell\">72</span><span class=\"cell\">85</span><span class=\"cell key\" data-label=\"minimum\">18</span></div></div>\r\n        <p>Swap 63 and 18:</p>\r\n        <div class=\"array-wrap\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"fixed\">18</span><span class=\"divider\"></span><span class=\"cell\">29</span><span class=\"cell\">72</span><span class=\"cell\">85</span><span class=\"cell\">63</span></div></div>\r\n\r\n        <h3 id=\"selection-trace\">Trace table</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Position</th><th>Minimum found</th><th>Action</th><th>Array after placement</th><th>Comparisons</th></tr></thead><tbody>\r\n          <tr><td>0</td><td>18 at index 4</td><td>Swap 63 ↔ 18</td><td><code>[18,29,72,85,63]</code></td><td>4</td></tr>\r\n          <tr><td>1</td><td>29 at index 1</td><td>No swap needed</td><td><code>[18,29,72,85,63]</code></td><td>3</td></tr>\r\n          <tr><td>2</td><td>63 at index 4</td><td>Swap 72 ↔ 63</td><td><code>[18,29,63,85,72]</code></td><td>2</td></tr>\r\n          <tr><td>3</td><td>72 at index 4</td><td>Swap 85 ↔ 72</td><td><code>[18,29,63,72,85]</code></td><td>1</td></tr>\r\n        </tbody></table></div>\r\n\r\n        <h3 id=\"selection-implementation\">Implementation</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Selection sort</span></div><pre><code><span class=\"kw\">public static void</span> selectionSort(<span class=\"ty\">int</span>[] arr) {\r\n    <span class=\"cm\">// i is the next position to fill in the sorted prefix.</span>\r\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; arr.length - 1; i++) {\r\n        <span class=\"ty\">int</span> minIndex = i;\r\n        <span class=\"cm\">// Search the unsorted suffix for its smallest value.</span>\r\n        <span class=\"kw\">for</span> (<span class=\"ty\">int</span> j = i + 1; j &lt; arr.length; j++) {\r\n            <span class=\"kw\">if</span> (arr[j] &lt; arr[minIndex]) minIndex = j;\r\n        }\r\n        <span class=\"cm\">// Place the selected minimum at i; avoid a self-swap.</span>\r\n        <span class=\"kw\">if</span> (minIndex != i) {\r\n            <span class=\"ty\">int</span> temp = arr[i];\r\n            arr[i] = arr[minIndex];\r\n            arr[minIndex] = temp;\r\n        }\r\n    }\r\n}</code></pre></div>\r\n        <details><summary>Recursive selection sort</summary><div class=\"answer\"><p>First call: <code>selectionSortRec(arr, 0)</code>.</p><pre><code><span class=\"kw\">public static void</span> selectionSortRec(<span class=\"ty\">int</span>[] arr, <span class=\"ty\">int</span> start) {\r\n    <span class=\"cm\">// Base case: fewer than two values remain.</span>\r\n    <span class=\"kw\">if</span> (start &gt;= arr.length - 1) <span class=\"kw\">return</span>;\r\n\r\n    <span class=\"ty\">int</span> minIndex = start;\r\n    <span class=\"cm\">// Find the minimum in start..last.</span>\r\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> j = start + 1; j &lt; arr.length; j++) {\r\n        <span class=\"kw\">if</span> (arr[j] &lt; arr[minIndex]) minIndex = j;\r\n    }\r\n    <span class=\"kw\">if</span> (minIndex != start) {\r\n        <span class=\"ty\">int</span> temp = arr[start];\r\n        arr[start] = arr[minIndex];\r\n        arr[minIndex] = temp;\r\n    }\r\n    <span class=\"cm\">// The prefix gained one fixed value; solve the suffix.</span>\r\n    selectionSortRec(arr, start + 1);\r\n}</code></pre></div></details>\r\n\r\n        <div class=\"audit-grid\">\r\n          <div class=\"from-scratch\"><strong>Write it from scratch</strong><ol><li>Choose the next position <code>i</code>.</li><li>Assume <code>i</code> holds the minimum.</li><li>Scan the suffix and update <code>minIndex</code>.</li><li>Swap the minimum into <code>i</code>.</li></ol></div>\r\n          <div class=\"direction-card\"><strong>Ascending ↔ descending</strong><p>For ascending, select the minimum with <code>&lt;</code>. For descending, select the maximum with <code>&gt;</code>.</p><p><strong>Same array, opposite choice:</strong> on <code>[63, 29, 72, 85, 18]</code> with <code>i = 0</code>, ascending selects <code>18</code> (index 4) and descending selects <code>85</code> (index 3).</p></div>\r\n          <div class=\"debug-list\"><strong>Debug checklist</strong><ul><li>Store an index, not only the minimum value.</li><li>Start the inner loop at <code>i + 1</code>.</li><li>Swap only after the scan finishes.</li></ul></div>\r\n        </div>\r\n\r\n                <h3 id=\"selection-example\">Worked example · full run on <code>[4, 2, 5, 1, 3]</code></h3><p>The orange divider marks the end of the sorted prefix. Dashed-outline cells mark the position <code>i</code> being filled; the raised cell is the minimum found.</p><div class=\"worked-visual\" aria-label=\"Four-step selection sort trace of 4, 2, 5, 1, 3\"><div class=\"worked-step\"><h4>i = 0 · fill index 0 with the smallest of the remaining values</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array before choosing position 0: [4, 2, 5, 1, 3]\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 i\">4</span><span class=\"cell\">2</span><span class=\"cell\">5</span><span class=\"cell key\" data-label=\"3 min\">1</span><span class=\"cell\">3</span></div></div><p>Scan indexes 1–4 (4 comparisons). The smallest remaining value is <code>1</code> at index 3. Swap index 0 (<code>4</code>) with index 3 (<code>1</code>).</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array after position 0: [1, 2, 5, 4, 3]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">5</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">3</span></div></div></div><div class=\"worked-step\"><h4>i = 1 · fill index 1 with the smallest of the remaining values</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array before choosing position 1: [1, 2, 5, 4, 3]\"><div class=\"array\"><span class=\"cell sorted\">1</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell key bound\" data-label=\"1 i = min\">2</span><span class=\"cell\">5</span><span class=\"cell\">4</span><span class=\"cell\">3</span></div></div><p>Scan indexes 2–4 (3 comparisons). The smallest remaining value is <code>2</code> at index 1. Index 1 already holds the minimum, so no swap is needed.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array after position 1: [1, 2, 5, 4, 3]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"2\">5</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">3</span></div></div></div><div class=\"worked-step\"><h4>i = 2 · fill index 2 with the smallest of the remaining values</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array before choosing position 2: [1, 2, 5, 4, 3]\"><div class=\"array\"><span class=\"cell sorted\">1</span><span class=\"cell sorted\">2</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell bound\" data-label=\"2 i\">5</span><span class=\"cell\">4</span><span class=\"cell key\" data-label=\"4 min\">3</span></div></div><p>Scan indexes 3–4 (2 comparisons). The smallest remaining value is <code>3</code> at index 4. Swap index 2 (<code>5</code>) with index 4 (<code>3</code>).</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array after position 2: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>i = 3 · fill index 3 with the smallest of the remaining values</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array before choosing position 3: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\">1</span><span class=\"cell sorted\">2</span><span class=\"cell sorted\">3</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell key bound\" data-label=\"3 i = min\">4</span><span class=\"cell\">5</span></div></div><p>Scan index 4 (1 comparison). The smallest remaining value is <code>4</code> at index 3. Index 3 already holds the minimum, so no swap is needed.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Array after position 3: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"4\">5</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>i</th><th>Minimum found</th><th>Action</th><th>Array after</th><th>Comparisons</th></tr></thead><tbody><tr><td>0</td><td>1 at index 3</td><td>Swap</td><td><code>[1, 2, 5, 4, 3]</code></td><td>4</td></tr><tr><td>1</td><td>2 at index 1</td><td>No swap</td><td><code>[1, 2, 5, 4, 3]</code></td><td>3</td></tr><tr><td>2</td><td>3 at index 4</td><td>Swap</td><td><code>[1, 2, 3, 4, 5]</code></td><td>2</td></tr><tr><td>3</td><td>4 at index 3</td><td>No swap</td><td><code>[1, 2, 3, 4, 5]</code></td><td>1</td></tr><tr><td><strong>Total</strong></td><td>—</td><td><strong>2 swaps</strong></td><td>Sorted</td><td><strong>10</strong></td></tr></tbody></table></div><div class=\"result-line\">Sorted: <code>10</code> comparisons but only <code>2</code> swaps, compared with 6 swaps for bubble sort on the same array.</div><h3 id=\"selection-stability\">Why selection sort is not stable</h3><p>The swap moves a value across everything between the two positions, which can jump it over an equal value. Label two equal 2s as <code>2ᵃ</code> and <code>2ᵇ</code> and sort <code>[2ᵃ, 2ᵇ, 1]</code>: the minimum 1 is swapped with <code>2ᵃ</code>.</p><div class=\"direction-grid\"><div><strong>Before</strong><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start: 2a, 2b, 1\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2ᵃ</span><span class=\"cell\" data-label=\"1\">2ᵇ</span><span class=\"cell\" data-label=\"2\">1</span></div></div></div><div><strong>After the swap at i = 0</strong><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After one selection swap: 1, 2b, 2a\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell shift\" data-label=\"1\">2ᵇ</span><span class=\"cell shift\" data-label=\"2\">2ᵃ</span></div></div></div></div><p><code>2ᵇ</code> now sits before <code>2ᵃ</code>, so the equal values changed relative order. Insertion sort avoids this because it never moves a value past an equal one. Merge sort avoids it because, on a tie, the merge takes the left value first (<code>&lt;=</code>).</p>\r\n        <h3>Best case · already sorted</h3>\r\n        <p>For <code>[1,2,3,4]</code>, each scan confirms that the first unsorted value is already the minimum.</p>\r\n        <div class=\"worked-visual\"><div class=\"worked-step\"><h4>The sorted boundary grows, but the scans do not disappear</h4><div class=\"array-wrap\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"i=0 · 3 checks\">1</span><span class=\"cell sorted\" data-label=\"i=1 · 2 checks\">2</span><span class=\"cell sorted\" data-label=\"i=2 · 1 check\">3</span><span class=\"cell sorted\" data-label=\"final\">4</span></div></div><div class=\"result-line\">Comparisons: <code>3 + 2 + 1 = 6</code> · swaps: <code>0</code> · still <code>O(n²)</code>.</div></div></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>i</th><th>Suffix scanned</th><th>minIndex</th><th>Comparisons</th><th>Swap?</th></tr></thead><tbody><tr><td>0</td><td><code>[1,2,3,4]</code></td><td>0</td><td>3</td><td>No</td></tr><tr><td>1</td><td><code>[2,3,4]</code></td><td>1</td><td>2</td><td>No</td></tr><tr><td>2</td><td><code>[3,4]</code></td><td>2</td><td>1</td><td>No</td></tr></tbody></table></div>\r\n        <div class=\"properties\"><div class=\"property\"><small>Best</small><b>O(n²)</b></div><div class=\"property\"><small>Average</small><b>O(n²)</b></div><div class=\"property\"><small>Worst</small><b>O(n²)</b></div><div class=\"property\"><small>Stable</small><b>No</b></div><div class=\"property\"><small>In-place</small><b>Yes</b></div><div class=\"property\"><small>Adaptive</small><b>No</b></div><div class=\"property\"><small>Iterative space</small><b>O(1)</b></div><div class=\"property\"><small>Recursive space</small><b>O(n)</b></div></div>\r\n\r\n        <h3 id=\"selection-questions\">Questions</h3>\r\n        <details><summary>Why might selection sort be chosen over bubble sort?</summary><div class=\"answer\">Selection sort makes at most one swap per outer iteration, so it can be useful when writes or swaps are expensive.</div></details>\r\n        <details><summary>Why is it not adaptive?</summary><div class=\"answer\">It scans the entire remaining unsorted section to find the minimum even when the array is already sorted.</div></details>\r\n        <div class=\"method-summary\"><strong>Selection sort in one sentence</strong><p>Find the smallest value in the unsorted suffix and swap it into the next position of the sorted prefix.</p></div>\r\n      "
  },
  "selection-descending": {
    "id": "selection-descending",
    "title": "Descending order",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · Descending order</span>\r\n        <h2>Descending order</h2>\r\n        \r\n        <p>To sort largest to smallest, select the <strong>largest</strong> value of the suffix instead of the smallest. Only the comparison changes, and the variable is best renamed so the code still reads honestly.</p>\r\n        <div class=\"two-col\">\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>Ascending: pick the minimum</span></div><pre><code><span class=\"kw\">if</span> (arr[j] &lt; arr[minIndex]) {\r\n    minIndex = j;\r\n}</code></pre></div>\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>Descending: pick the maximum</span></div><pre><code><span class=\"kw\">if</span> (arr[j] &gt; arr[maxIndex]) {\r\n    maxIndex = j;\r\n}</code></pre></div>\r\n        </div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Iteration</th><th>Ascending (chooses the smallest)</th><th>Descending (chooses the largest)</th></tr></thead><tbody><tr><td>i = 0</td><td><code>[1, 2, 5, 4, 3]</code> · swap</td><td><code>[5, 2, 4, 1, 3]</code> · swap</td></tr><tr><td>i = 1</td><td><code>[1, 2, 5, 4, 3]</code> · no swap</td><td><code>[5, 4, 2, 1, 3]</code> · swap</td></tr><tr><td>i = 2</td><td><code>[1, 2, 3, 4, 5]</code> · swap</td><td><code>[5, 4, 3, 1, 2]</code> · swap</td></tr><tr><td>i = 3</td><td><code>[1, 2, 3, 4, 5]</code> · no swap</td><td><code>[5, 4, 3, 2, 1]</code> · swap</td></tr></tbody></table></div>\r\n        <p>Ascending made <strong>2 swaps</strong>, descending <strong>4</strong>, and both made the same <strong>10 comparisons</strong>. The comparison count never depends on direction or on the data, only the number of swaps does.</p>\r\n    \r\n      "
  },
  "selection-examples": {
    "id": "selection-examples",
    "title": "Worked examples",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · Worked examples</span>\r\n        <h2>Worked examples</h2>\r\n        <p class=\"lede\">Five arrays: no disorder, a reversed array, the most swaps, duplicates and a longer run.</p>\r\n        <article class=\"example-card\"><h3>Already sorted · <code>[1, 2, 3, 4, 5]</code></h3><p>Every minimum is already sitting at the boundary.</p><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Start [1, 2, 3, 4, 5]\"><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>1</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>2</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>3</small></div><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>4</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>5</small></div></div></figure><div class=\"worked-visual\" aria-label=\"Selection sort snapshots for [1, 2, 3, 4, 5]\"><div class=\"worked-step\"><h4>Start: nothing is sorted</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After i = 0 · cells 0..0 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 0: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted key\" data-label=\"0\">1</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After i = 1 · cells 0..1 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 1: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted key\" data-label=\"1\">2</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After i = 2 · cells 0..2 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 2: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted key\" data-label=\"2\">3</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After i = 3 · cells 0..3 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 3: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted key\" data-label=\"3\">4</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"4\">5</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>i</th><th>Choice</th><th>Action</th><th>Array after the iteration</th><th>Comparisons</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td>—</td><td><code>[1, 2, 3, 4, 5]</code></td><td>—</td></tr><tr><td>0</td><td>smallest of the unsorted part is <code>1</code> at index 0</td><td>already in place: no swap</td><td><code>[1, 2, 3, 4, 5]</code></td><td>4</td></tr><tr><td>1</td><td>smallest of the unsorted part is <code>2</code> at index 1</td><td>already in place: no swap</td><td><code>[1, 2, 3, 4, 5]</code></td><td>3</td></tr><tr><td>2</td><td>smallest of the unsorted part is <code>3</code> at index 2</td><td>already in place: no swap</td><td><code>[1, 2, 3, 4, 5]</code></td><td>2</td></tr><tr><td>3</td><td>smallest of the unsorted part is <code>4</code> at index 3</td><td>already in place: no swap</td><td><code>[1, 2, 3, 4, 5]</code></td><td>1</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>0 swaps</strong></td><td><strong>sorted</strong></td><td><strong>10</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>10</code> comparisons and <code>0</code> swaps. The data is perfectly sorted and selection sort still makes <strong>all 10 comparisons</strong>: it cannot know the answer without looking. That is why it is not adaptive.</div></article><article class=\"example-card\"><h3>Reverse order · <code>[5, 4, 3, 2, 1]</code></h3><p>A surprise: the worst-looking input is not the worst case for swaps.</p><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Start [5, 4, 3, 2, 1]\"><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>5</small></div><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>4</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>3</small></div><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>2</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>1</small></div></div></figure><div class=\"worked-visual\" aria-label=\"Selection sort snapshots for [5, 4, 3, 2, 1]\"><div class=\"worked-step\"><h4>Start: nothing is sorted</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [5, 4, 3, 2, 1]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">5</span><span class=\"cell\" data-label=\"1\">4</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">2</span><span class=\"cell\" data-label=\"4\">1</span></div></div></div><div class=\"worked-step\"><h4>After i = 0 · cells 0..0 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 0: [1, 4, 3, 2, 5]\"><div class=\"array\"><span class=\"cell sorted key\" data-label=\"0\">1</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"1\">4</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">2</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After i = 1 · cells 0..1 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 1: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted key\" data-label=\"1\">2</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After i = 2 · cells 0..2 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 2: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted key\" data-label=\"2\">3</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>After i = 3 · cells 0..3 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 3: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted key\" data-label=\"3\">4</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"4\">5</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>i</th><th>Choice</th><th>Action</th><th>Array after the iteration</th><th>Comparisons</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td>—</td><td><code>[5, 4, 3, 2, 1]</code></td><td>—</td></tr><tr><td>0</td><td>smallest of the unsorted part is <code>1</code> at index 4</td><td>swap index 0 with index 4</td><td><code>[1, 4, 3, 2, 5]</code></td><td>4</td></tr><tr><td>1</td><td>smallest of the unsorted part is <code>2</code> at index 3</td><td>swap index 1 with index 3</td><td><code>[1, 2, 3, 4, 5]</code></td><td>3</td></tr><tr><td>2</td><td>smallest of the unsorted part is <code>3</code> at index 2</td><td>already in place: no swap</td><td><code>[1, 2, 3, 4, 5]</code></td><td>2</td></tr><tr><td>3</td><td>smallest of the unsorted part is <code>4</code> at index 3</td><td>already in place: no swap</td><td><code>[1, 2, 3, 4, 5]</code></td><td>1</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>2 swaps</strong></td><td><strong>sorted</strong></td><td><strong>10</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>10</code> comparisons but only <code>2</code> swaps. Each swap sends one value to each end at the same time, and the middle value needs nothing, so a reversed array needs about <code>n / 2</code> swaps.</div></article><article class=\"example-card\"><h3>The most swaps · <code>[2, 3, 4, 5, 1]</code></h3><p>The minimum is at the far end, then the next minimum is at the far end of what remains, and so on.</p><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Start [2, 3, 4, 5, 1]\"><div class=\"bar\" style=\"--p:0.400\"><i></i><b>2</b><small>2</small></div><div class=\"bar\" style=\"--p:0.600\"><i></i><b>3</b><small>3</small></div><div class=\"bar\" style=\"--p:0.800\"><i></i><b>4</b><small>4</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>5</b><small>5</small></div><div class=\"bar\" style=\"--p:0.200\"><i></i><b>1</b><small>1</small></div></div></figure><div class=\"worked-visual\" aria-label=\"Selection sort snapshots for [2, 3, 4, 5, 1]\"><div class=\"worked-step\"><h4>Start: nothing is sorted</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [2, 3, 4, 5, 1]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2</span><span class=\"cell\" data-label=\"1\">3</span><span class=\"cell\" data-label=\"2\">4</span><span class=\"cell\" data-label=\"3\">5</span><span class=\"cell\" data-label=\"4\">1</span></div></div></div><div class=\"worked-step\"><h4>After i = 0 · cells 0..0 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 0: [1, 3, 4, 5, 2]\"><div class=\"array\"><span class=\"cell sorted key\" data-label=\"0\">1</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"1\">3</span><span class=\"cell\" data-label=\"2\">4</span><span class=\"cell\" data-label=\"3\">5</span><span class=\"cell\" data-label=\"4\">2</span></div></div></div><div class=\"worked-step\"><h4>After i = 1 · cells 0..1 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 1: [1, 2, 4, 5, 3]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted key\" data-label=\"1\">2</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"2\">4</span><span class=\"cell\" data-label=\"3\">5</span><span class=\"cell\" data-label=\"4\">3</span></div></div></div><div class=\"worked-step\"><h4>After i = 2 · cells 0..2 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 2: [1, 2, 3, 5, 4]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted key\" data-label=\"2\">3</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"3\">5</span><span class=\"cell\" data-label=\"4\">4</span></div></div></div><div class=\"worked-step\"><h4>After i = 3 · cells 0..3 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 3: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted key\" data-label=\"3\">4</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"4\">5</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>i</th><th>Choice</th><th>Action</th><th>Array after the iteration</th><th>Comparisons</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td>—</td><td><code>[2, 3, 4, 5, 1]</code></td><td>—</td></tr><tr><td>0</td><td>smallest of the unsorted part is <code>1</code> at index 4</td><td>swap index 0 with index 4</td><td><code>[1, 3, 4, 5, 2]</code></td><td>4</td></tr><tr><td>1</td><td>smallest of the unsorted part is <code>2</code> at index 4</td><td>swap index 1 with index 4</td><td><code>[1, 2, 4, 5, 3]</code></td><td>3</td></tr><tr><td>2</td><td>smallest of the unsorted part is <code>3</code> at index 4</td><td>swap index 2 with index 4</td><td><code>[1, 2, 3, 5, 4]</code></td><td>2</td></tr><tr><td>3</td><td>smallest of the unsorted part is <code>4</code> at index 4</td><td>swap index 3 with index 4</td><td><code>[1, 2, 3, 4, 5]</code></td><td>1</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>4 swaps</strong></td><td><strong>sorted</strong></td><td><strong>10</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>10</code> comparisons and <code>4</code> swaps, which is the maximum <code>n − 1</code>. Even this worst case for swaps is tiny next to the 10 comparisons.</div></article><article class=\"example-card\"><h3>Duplicates · <code>[2ᵃ, 2ᵇ, 1]</code></h3><p>Two equal values, labelled so we can follow them.</p><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Start [2ᵃ, 2ᵇ, 1]\"><div class=\"bar\" style=\"--p:1.000\"><i></i><b>2</b><small>2ᵃ</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>2</b><small>2ᵇ</small></div><div class=\"bar\" style=\"--p:0.500\"><i></i><b>1</b><small>1</small></div></div></figure><div class=\"worked-visual\" aria-label=\"Selection sort snapshots for [2ᵃ, 2ᵇ, 1]\"><div class=\"worked-step\"><h4>Start: nothing is sorted</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [2ᵃ, 2ᵇ, 1]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">2ᵃ</span><span class=\"cell\" data-label=\"1\">2ᵇ</span><span class=\"cell\" data-label=\"2\">1</span></div></div></div><div class=\"worked-step\"><h4>After i = 0 · cells 0..0 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 0: [1, 2ᵇ, 2ᵃ]\"><div class=\"array\"><span class=\"cell sorted key\" data-label=\"0\">1</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"1\">2ᵇ</span><span class=\"cell\" data-label=\"2\">2ᵃ</span></div></div></div><div class=\"worked-step\"><h4>After i = 1 · cells 0..1 are final</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After i = 1: [1, 2ᵇ, 2ᵃ]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted key\" data-label=\"1\">2ᵇ</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"2\">2ᵃ</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>i</th><th>Choice</th><th>Action</th><th>Array after the iteration</th><th>Comparisons</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td>—</td><td><code>[2ᵃ, 2ᵇ, 1]</code></td><td>—</td></tr><tr><td>0</td><td>smallest of the unsorted part is <code>1</code> at index 2</td><td>swap index 0 with index 2</td><td><code>[1, 2ᵇ, 2ᵃ]</code></td><td>2</td></tr><tr><td>1</td><td>smallest of the unsorted part is <code>2ᵇ</code> at index 1</td><td>already in place: no swap</td><td><code>[1, 2ᵇ, 2ᵃ]</code></td><td>1</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>1 swaps</strong></td><td><strong>sorted</strong></td><td><strong>3</strong></td></tr></tbody></table></div><div class=\"result-line\">The result is <code>[1, 2ᵇ, 2ᵃ]</code>: the two 2s came out in the <em>opposite</em> order. The first swap threw <code>2ᵃ</code> to the far end, past <code>2ᵇ</code>. So selection sort is <strong>not stable</strong>.</div></article><article class=\"example-card\"><h3>A longer array · <code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code> (nine values)</h3><p>The array from Test 1, question 3. The table shows every iteration; try to predict the minimum before reading each row.</p><figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Start [50, 83, 76, 6, 32, 90, 12, 2, 59]\"><div class=\"bar\" style=\"--p:0.556\"><i></i><b>50</b><small>50</small></div><div class=\"bar\" style=\"--p:0.922\"><i></i><b>83</b><small>83</small></div><div class=\"bar\" style=\"--p:0.844\"><i></i><b>76</b><small>76</small></div><div class=\"bar\" style=\"--p:0.067\"><i></i><b>6</b><small>6</small></div><div class=\"bar\" style=\"--p:0.356\"><i></i><b>32</b><small>32</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>90</b><small>90</small></div><div class=\"bar\" style=\"--p:0.133\"><i></i><b>12</b><small>12</small></div><div class=\"bar\" style=\"--p:0.022\"><i></i><b>2</b><small>2</small></div><div class=\"bar\" style=\"--p:0.656\"><i></i><b>59</b><small>59</small></div></div></figure><div class=\"table-scroll\"><table><thead><tr><th>i</th><th>Choice</th><th>Action</th><th>Array after the iteration</th><th>Comparisons</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td>—</td><td><code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code></td><td>—</td></tr><tr><td>0</td><td>smallest of the unsorted part is <code>2</code> at index 7</td><td>swap index 0 with index 7</td><td><code>[2, 83, 76, 6, 32, 90, 12, 50, 59]</code></td><td>8</td></tr><tr><td>1</td><td>smallest of the unsorted part is <code>6</code> at index 3</td><td>swap index 1 with index 3</td><td><code>[2, 6, 76, 83, 32, 90, 12, 50, 59]</code></td><td>7</td></tr><tr><td>2</td><td>smallest of the unsorted part is <code>12</code> at index 6</td><td>swap index 2 with index 6</td><td><code>[2, 6, 12, 83, 32, 90, 76, 50, 59]</code></td><td>6</td></tr><tr><td>3</td><td>smallest of the unsorted part is <code>32</code> at index 4</td><td>swap index 3 with index 4</td><td><code>[2, 6, 12, 32, 83, 90, 76, 50, 59]</code></td><td>5</td></tr><tr><td>4</td><td>smallest of the unsorted part is <code>50</code> at index 7</td><td>swap index 4 with index 7</td><td><code>[2, 6, 12, 32, 50, 90, 76, 83, 59]</code></td><td>4</td></tr><tr><td>5</td><td>smallest of the unsorted part is <code>59</code> at index 8</td><td>swap index 5 with index 8</td><td><code>[2, 6, 12, 32, 50, 59, 76, 83, 90]</code></td><td>3</td></tr><tr><td>6</td><td>smallest of the unsorted part is <code>76</code> at index 6</td><td>already in place: no swap</td><td><code>[2, 6, 12, 32, 50, 59, 76, 83, 90]</code></td><td>2</td></tr><tr><td>7</td><td>smallest of the unsorted part is <code>83</code> at index 7</td><td>already in place: no swap</td><td><code>[2, 6, 12, 32, 50, 59, 76, 83, 90]</code></td><td>1</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>6 swaps</strong></td><td><strong>sorted</strong></td><td><strong>36</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>36</code> comparisons (always <code>n(n − 1) / 2</code>) and <code>6</code> swaps (at most <code>n − 1 = 8</code>).</div></article>\r\n      "
  },
  "selection-properties": {
    "id": "selection-properties",
    "title": "Properties",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · Properties</span>\r\n        <h2>Properties</h2>\r\n        \r\n        <div class=\"properties\"><div class=\"property\"><small>Best time</small><b>O(n²)</b></div><div class=\"property\"><small>Average time</small><b>O(n²)</b></div><div class=\"property\"><small>Worst time</small><b>O(n²)</b></div><div class=\"property\"><small>Extra space</small><b>O(1)</b></div><div class=\"property\"><small>Stable</small><b>No</b></div><div class=\"property\"><small>In-place</small><b>Yes</b></div><div class=\"property\"><small>Adaptive</small><b>No</b></div><div class=\"property\"><small>Swaps</small><b>≤ n − 1</b></div></div>\r\n        <h3>Not stable</h3>\r\n        <p>The long-distance swap can jump a value over an equal one. In <code>[2ᵃ, 2ᵇ, 1]</code> the first swap moves <code>2ᵃ</code> behind <code>2ᵇ</code>, and nothing later repairs it. A stable version exists (shift instead of swap), but that is a different algorithm.</p>\r\n        <h3>In-place</h3>\r\n        <p>Only the array and a few variables are used: <code>O(1)</code> extra space.</p>\r\n        <h3>Not adaptive</h3>\r\n        <p>The scan always examines the whole suffix, so sorted input costs exactly the same <code>n(n − 1) / 2</code> comparisons as random input.</p>\r\n        <h3>Fewest swaps</h3>\r\n        <p>At most one swap per iteration, so at most <code>n − 1</code> swaps in total, the smallest of the simple sorts. Bubble sort can need up to <code>n(n − 1) / 2</code>.</p>\r\n        <h3>Comparison-based</h3>\r\n        <p>Every decision comes from comparing two values.</p>\r\n    \r\n      "
  },
  "selection-complexity": {
    "id": "selection-complexity",
    "title": "Why those complexities occur",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · Why those complexities occur</span>\r\n        <h2>Why those complexities occur</h2>\r\n        \r\n        <div class=\"complexity-grid\"><div class=\"complexity-item\"><strong>Every case · O(n²) comparisons</strong>The scan for iteration <code>i</code> always looks at <code>n − 1 − i</code> cells, whatever the values are.</div><div class=\"complexity-item\"><strong>Swaps · at most n − 1</strong>One per iteration, so the writing is only <code>O(n)</code>: that is selection sort's one real advantage.</div></div>\r\n        <h3>The comparison staircase never changes</h3>\r\n        <div class=\"stairs\" role=\"img\" aria-label=\"4 + 3 + 2 + 1 = 10 comparisons\"><div class=\"stair-row\"><span>i = 1</span><div class=\"stair-sq\"><i></i><i></i><i></i><i></i></div><span class=\"stair-n\">4</span></div><div class=\"stair-row\"><span>i = 2</span><div class=\"stair-sq\"><i></i><i></i><i></i></div><span class=\"stair-n\">3</span></div><div class=\"stair-row\"><span>i = 3</span><div class=\"stair-sq\"><i></i><i></i></div><span class=\"stair-n\">2</span></div><div class=\"stair-row\"><span>i = 4</span><div class=\"stair-sq\"><i></i></div><span class=\"stair-n\">1</span></div><div class=\"stair-total\">total = 4 + 3 + 2 + 1 = <b>10</b></div></div>\r\n        <p>The staircase is exactly the same one bubble sort walks in its worst case, and for the same reason it totals <code>n(n − 1) / 2</code>. The difference is that for selection sort this is the cost <em>every time</em>: there is no best case that avoids it.</p>\r\n        <div class=\"formula\">(n − 1) + (n − 2) + … + 1 = n(n − 1) / 2 → O(n²) comparisons, always</div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>n (values)</th><th>Comparisons</th><th>Maximum swaps</th></tr></thead><tbody><tr><td>5</td><td>10</td><td>4</td></tr><tr><td>10</td><td>45</td><td>9</td></tr><tr><td>100</td><td>4,950</td><td>99</td></tr><tr><td>1,000</td><td>499,500</td><td>999</td></tr></tbody></table></div>\r\n        <p>Read across the row for 1,000 values: nearly half a million comparisons but never more than 999 swaps. If a swap were expensive (large records, slow storage) that gap would matter; if comparisons are the cost, selection sort has no way to save any.</p>\r\n        <h3>Space</h3>\r\n        <p>Only <code>i</code>, <code>j</code>, <code>minIndex</code> and <code>temp</code>: <code>O(1)</code>.</p>\r\n    \r\n      "
  },
  "selection-when": {
    "id": "selection-when",
    "title": "When to use it",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · When to use it</span>\r\n        <h2>When to use it</h2>\r\n        \r\n        <div class=\"use-grid\"><div class=\"use good\"><strong>A good choice</strong>Small arrays; situations where <strong>writing</strong> is much more expensive than reading (flash memory, very large records, writing to a file); when you need a predictable, data-independent running time; and when simplicity matters more than speed.</div><div class=\"use poor\"><strong>A poor choice</strong>Large arrays (<code>O(n²)</code> comparisons); data that is already or nearly sorted (it cannot take advantage); anywhere stability is needed, for example sorting records by one field while keeping an earlier order for ties.</div></div>\r\n        <p>Compared with its relatives: <strong>insertion sort</strong> beats it on nearly sorted data and is stable; <strong>bubble sort</strong> makes many more swaps; <strong>merge sort</strong> is far faster on large arrays. Selection sort is a good answer to “which simple sort minimises swaps?”, and almost nothing else.</p>\r\n    \r\n      "
  },
  "selection-mistakes": {
    "id": "selection-mistakes",
    "title": "Common mistakes",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · Common mistakes</span>\r\n        <h2>Common mistakes</h2>\r\n        <div class=\"mistake\"><span class=\"mistake-no\">1</span><div><strong>Storing the minimum value instead of its index.</strong><br>To swap you need the position. Keep <code>minIndex</code>.</div></div><div class=\"mistake\"><span class=\"mistake-no\">2</span><div><strong>Starting the scan at <code>i</code> instead of <code>i + 1</code>.</strong><br>It still works, because a value compared with itself is never smaller, but it wastes one comparison per iteration and changes your counts.</div></div><div class=\"mistake\"><span class=\"mistake-no\">3</span><div><strong>Swapping inside the scan.</strong><br>Swap <em>after</em> the scan finishes, once you know the true minimum. Swapping every time you find a smaller value turns it into a different (and slower) algorithm.</div></div><div class=\"mistake\"><span class=\"mistake-no\">4</span><div><strong>Forgetting that the minimum may already be at <code>i</code>.</strong><br>Then <code>minIndex == i</code> and no swap is needed. Counting a swap here gives a wrong total.</div></div><div class=\"mistake\"><span class=\"mistake-no\">5</span><div><strong>Running the outer loop to <code>n</code> instead of <code>n − 1</code>.</strong><br>When only one cell is left it is automatically correct, so the last iteration is wasted.</div></div><div class=\"mistake\"><span class=\"mistake-no\">6</span><div><strong>Expecting it to stop early on sorted data.</strong><br>It cannot. All <code>n(n − 1) / 2</code> comparisons are made whatever the input looks like.</div></div><div class=\"mistake\"><span class=\"mistake-no\">7</span><div><strong>Calling it stable.</strong><br>It is not: the long-distance swap can reorder equal values.</div></div><div class=\"mistake\"><span class=\"mistake-no\">8</span><div><strong>Using the wrong comparison for descending order.</strong><br>Select the <em>maximum</em> (<code>&gt;</code>); do not run the ascending sort and reverse the answer unless the question asks for it.</div></div>\r\n      "
  },
  "selection-summary": {
    "id": "selection-summary",
    "title": "A test-ready summary",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · A test-ready summary</span>\r\n        <h2>A test-ready summary</h2>\r\n        \r\n        <div class=\"test-summary\">\r\n          <p>Selection sort is an in-place, comparison-based sorting algorithm that is not stable and not adaptive. It splits the array into a sorted prefix and an unsorted suffix. In each iteration it scans the whole suffix to find the smallest value, remembers its index, and swaps it into the first position of the suffix, so the prefix grows by one final cell. It makes exactly n(n − 1) / 2 comparisons whatever the input, but at most n − 1 swaps. Its best, average and worst cases are all O(n²) with O(1) extra space. It is useful for small arrays and when swaps are expensive, but not for large data.</p>\r\n        </div>\r\n    \r\n      "
  },
  "selection-practice": {
    "id": "selection-practice",
    "title": "Practice",
    "body": "\r\n        <span class=\"section-no\">Sorting / Selection sort · Practice</span>\r\n        <h2>Practice</h2>\r\n        \r\n        <h3>Guided question</h3>\r\n        <p>Use selection sort (ascending) on <code>[6, 3, 8, 4]</code>. For each iteration say which value is selected, where it was, and whether a swap happened.</p>\r\n        <details><summary>Reveal the guided answer</summary><div class=\"answer\"><p><strong>i = 0:</strong> scan indexes 1..3; smallest is <code>3</code> at index 1 → swap → <code>[3, 6, 8, 4]</code></p><p><strong>i = 1:</strong> scan indexes 2..3; smallest is <code>4</code> at index 3 → swap → <code>[3, 4, 8, 6]</code></p><p><strong>i = 2:</strong> scan indexes 3..3; smallest is <code>6</code> at index 3 → swap → <code>[3, 4, 6, 8]</code></p><p><strong>Totals:</strong> 6 comparisons and 3 swaps.</p></div></details>\r\n        <h3>Independent question</h3>\r\n        <p>Trace selection sort on <code>[9, 4, 7, 3, 5]</code>, writing the array after every iteration and the totals.</p>\r\n        <ul class=\"checklist\">\r\n          <li>For each <code>i</code>, find the smallest value in the unsorted part and its index.</li>\r\n          <li>Say whether a swap is needed.</li>\r\n          <li>Write the array after the iteration.</li>\r\n          <li>Total the comparisons (it should be 10 without tracing them) and the swaps.</li>\r\n        </ul>\r\n        <details><summary>Reveal the independent answer</summary><div class=\"answer\"><div class=\"table-scroll\"><table><thead><tr><th>i</th><th>Choice</th><th>Action</th><th>Array after the iteration</th><th>Comparisons</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td>—</td><td><code>[9, 4, 7, 3, 5]</code></td><td>—</td></tr><tr><td>0</td><td>smallest of the unsorted part is <code>3</code> at index 3</td><td>swap index 0 with index 3</td><td><code>[3, 4, 7, 9, 5]</code></td><td>4</td></tr><tr><td>1</td><td>smallest of the unsorted part is <code>4</code> at index 1</td><td>already in place: no swap</td><td><code>[3, 4, 7, 9, 5]</code></td><td>3</td></tr><tr><td>2</td><td>smallest of the unsorted part is <code>5</code> at index 4</td><td>swap index 2 with index 4</td><td><code>[3, 4, 5, 9, 7]</code></td><td>2</td></tr><tr><td>3</td><td>smallest of the unsorted part is <code>7</code> at index 4</td><td>swap index 3 with index 4</td><td><code>[3, 4, 5, 7, 9]</code></td><td>1</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>3 swaps</strong></td><td><strong>sorted</strong></td><td><strong>10</strong></td></tr></tbody></table></div></div></details>\r\n        <h3>Test-style question</h3>\r\n        <p>Show the contents of <code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code> after each iteration when sorting <strong>descending</strong> with selection sort.</p>\r\n        <details><summary>Reveal the test-style answer</summary><div class=\"answer\"><div class=\"table-scroll\"><table><thead><tr><th>i</th><th>Choice</th><th>Action</th><th>Array after the iteration</th><th>Comparisons</th></tr></thead><tbody><tr><td>Start</td><td>—</td><td>—</td><td><code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code></td><td>—</td></tr><tr><td>0</td><td>largest of the unsorted part is <code>90</code> at index 5</td><td>swap index 0 with index 5</td><td><code>[90, 83, 76, 6, 32, 50, 12, 2, 59]</code></td><td>8</td></tr><tr><td>1</td><td>largest of the unsorted part is <code>83</code> at index 1</td><td>already in place: no swap</td><td><code>[90, 83, 76, 6, 32, 50, 12, 2, 59]</code></td><td>7</td></tr><tr><td>2</td><td>largest of the unsorted part is <code>76</code> at index 2</td><td>already in place: no swap</td><td><code>[90, 83, 76, 6, 32, 50, 12, 2, 59]</code></td><td>6</td></tr><tr><td>3</td><td>largest of the unsorted part is <code>59</code> at index 8</td><td>swap index 3 with index 8</td><td><code>[90, 83, 76, 59, 32, 50, 12, 2, 6]</code></td><td>5</td></tr><tr><td>4</td><td>largest of the unsorted part is <code>50</code> at index 5</td><td>swap index 4 with index 5</td><td><code>[90, 83, 76, 59, 50, 32, 12, 2, 6]</code></td><td>4</td></tr><tr><td>5</td><td>largest of the unsorted part is <code>32</code> at index 5</td><td>already in place: no swap</td><td><code>[90, 83, 76, 59, 50, 32, 12, 2, 6]</code></td><td>3</td></tr><tr><td>6</td><td>largest of the unsorted part is <code>12</code> at index 6</td><td>already in place: no swap</td><td><code>[90, 83, 76, 59, 50, 32, 12, 2, 6]</code></td><td>2</td></tr><tr><td>7</td><td>largest of the unsorted part is <code>6</code> at index 8</td><td>swap index 7 with index 8</td><td><code>[90, 83, 76, 59, 50, 32, 12, 6, 2]</code></td><td>1</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>4 swaps</strong></td><td><strong>sorted</strong></td><td><strong>36</strong></td></tr></tbody></table></div></div></details>\r\n    \r\n      "
  },
  "array": {
    "id": "array",
    "title": "The array we will sort",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · The array we will sort</span>\r\n        <h2>The array we will sort</h2>\r\n        <p class=\"lede\">We will use one array from beginning to end, arranging its values in ascending order—from smallest to largest.</p>\r\n        <div class=\"paper-card\">\r\n          <div class=\"kicker\">Starting array</div>\r\n          <div class=\"array-wrap\" aria-label=\"Starting array: 4, 2, 5, 1, 3\">\r\n            <div class=\"array\">\r\n              <span class=\"cell\">4</span><span class=\"cell\">2</span><span class=\"cell\">5</span><span class=\"cell\">1</span><span class=\"cell\">3</span>\r\n            </div>\r\n          </div>\r\n          <div class=\"kicker\">The result we want</div>\r\n          <div class=\"array-wrap\" aria-label=\"Sorted array: 1, 2, 3, 4, 5\">\r\n            <div class=\"array\">\r\n              <span class=\"cell sorted\">1</span><span class=\"cell sorted\">2</span><span class=\"cell sorted\">3</span><span class=\"cell sorted\">4</span><span class=\"cell sorted\">5</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <p>This example is deliberately uneven. It gives us an iteration with one shift, one with no shifts, one with three shifts, and one with two shifts.</p>\r\n      "
  },
  "definition": {
    "id": "definition",
    "title": "The textbook definition",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Definition</span>\r\n        <h2>The textbook definition</h2>\r\n        <div class=\"paper-card definition\">\r\n          <p><strong>Insertion sort</strong> is a comparison-based sorting algorithm that builds a sorted section of an array one element at a time. During each iteration, it takes the next element from the unsorted section, shifts all larger elements in the sorted section one position to the right, and inserts the element into its correct position.</p>\r\n        </div>\r\n        <div class=\"term-grid\">\r\n          <div class=\"term\"><strong>Comparison-based</strong>The order is decided by comparing one value with another.</div>\r\n          <div class=\"term\"><strong>Sorted section</strong>The part already placed in the correct order.</div>\r\n          <div class=\"term\"><strong>Unsorted section</strong>The part that has not yet been processed.</div>\r\n          <div class=\"term\"><strong>Shift</strong>Copying a value one position to the right.</div>\r\n          <div class=\"term\"><strong>Insert</strong>Placing the saved value in the gap made by the shifts.</div>\r\n          <div class=\"term\"><strong>Iteration</strong>One complete turn of the outer loop.</div>\r\n        </div>\r\n      "
  },
  "simple": {
    "id": "simple",
    "title": "In plain language",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · In plain language</span>\r\n        <h2>In plain language</h2>\r\n        <p class=\"lede\">Think about arranging playing cards in your hand. You pick up one new card, compare it with the cards already arranged, and slide larger cards aside until the new card fits.</p>\r\n        <div class=\"paper-card\">\r\n          <p>Suppose the arranged cards are <code>[2, 4, 5]</code> and the new card is <code>3</code>.</p>\r\n          <div class=\"compare-list\">\r\n            <div class=\"compare\"><span class=\"compare-num\">1</span><code>3 &lt; 5</code><span class=\"verdict move\">move 5 right</span></div>\r\n            <div class=\"compare\"><span class=\"compare-num\">2</span><code>3 &lt; 4</code><span class=\"verdict move\">move 4 right</span></div>\r\n            <div class=\"compare\"><span class=\"compare-num\">3</span><code>3 &lt; 2</code><span class=\"verdict\">false · stop</span></div>\r\n          </div>\r\n          <p>Place <code>3</code> after <code>2</code>. The result is <code>[2, 3, 4, 5]</code>.</p>\r\n        </div>\r\n      "
  },
  "idea": {
    "id": "idea",
    "title": "The main idea",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · The main idea</span>\r\n        <h2>The main idea</h2>\r\n        <p>The first element is treated as sorted. That is valid because one item on its own cannot be out of order.</p>\r\n        <div class=\"array-wrap\" aria-label=\"The first item is sorted and the rest are unsorted\">\r\n          <div class=\"array\">\r\n            <span class=\"cell sorted\" data-label=\"sorted\">4</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"next\">2</span><span class=\"cell\">5</span><span class=\"cell\">1</span><span class=\"cell\">3</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"legend\"><span><i class=\"swatch sorted\"></i>sorted section</span><span><i class=\"swatch key\"></i>current key</span></div>\r\n        <p>The algorithm processes <code>2</code>, then <code>5</code>, then <code>1</code>, then <code>3</code>. After each iteration, the sorted section grows by one value.</p>\r\n        <div class=\"callout\"><strong>The repeating recipe:</strong> save the key → inspect values to its left → shift larger values right → insert the key.</div>\r\n      "
  },
  "movements": {
    "id": "movements",
    "title": "Comparison, shift, insertion",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Comparison, shift, insertion</span>\r\n        <h2>Comparison, shift, insertion</h2>\r\n        <p class=\"lede\">These words describe different actions. Keeping them separate makes traces much easier to understand—and keeps test answers accurate.</p>\r\n        <div class=\"term-grid\">\r\n          <div class=\"term\"><strong>Comparison</strong>Ask a question such as <code>1 &lt; 5</code>.</div>\r\n          <div class=\"term\"><strong>Shift</strong>Copy a larger value one position right.</div>\r\n          <div class=\"term\"><strong>Insertion</strong>Put the saved key into the gap.</div>\r\n          <div class=\"term\"><strong>Swap</strong>Exchange two values. Standard insertion sort does not normally do this.</div>\r\n        </div>\r\n        <p>If <code>1</code> is the key in <code>[2, 4, 5, 1, 3]</code>, then <code>5</code>, <code>4</code>, and <code>2</code> each shift right. Those are <strong>three shifts</strong>, not three swaps. The key is then inserted once.</p>\r\n      "
  },
  "trace": {
    "id": "trace",
    "title": "The complete visual trace",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Visual trace</span>\r\n        <h2>The complete visual trace</h2>\r\n\r\n        <article class=\"iteration\">\r\n          <div class=\"iteration-head\"><h3>Iteration 1 · insert 2</h3><span class=\"count\">1 comparison · 1 shift</span></div>\r\n          <div class=\"array-wrap indexed\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">4</span><span class=\"divider\"></span><span class=\"cell key\" data-label=\"1 key\">2</span><span class=\"cell\" data-label=\"2\">5</span><span class=\"cell\" data-label=\"3\">1</span><span class=\"cell\" data-label=\"4\">3</span></div></div>\r\n          <div class=\"compare-list\"><div class=\"compare\"><span class=\"compare-num\">1</span><code>2 &lt; 4</code><span class=\"verdict move\">true · shift 4</span></div></div>\r\n          <p>Save <code>2</code>. Move <code>4</code> right, then insert <code>2</code> into the gap.</p>\r\n          <div class=\"array-wrap indexed\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">2</span><span class=\"cell sorted\" data-label=\"1\">4</span><span class=\"divider\"></span><span class=\"cell\" data-label=\"2\">5</span><span class=\"cell\" data-label=\"3\">1</span><span class=\"cell\" data-label=\"4\">3</span></div></div>\r\n        </article>\r\n\r\n        <article class=\"iteration\">\r\n          <div class=\"iteration-head\"><h3>Iteration 2 · insert 5</h3><span class=\"count\">1 comparison · 0 shifts</span></div>\r\n          <div class=\"array-wrap indexed\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">2</span><span class=\"cell sorted\" data-label=\"1\">4</span><span class=\"divider\"></span><span class=\"cell key\" data-label=\"2 key\">5</span><span class=\"cell\" data-label=\"3\">1</span><span class=\"cell\" data-label=\"4\">3</span></div></div>\r\n          <div class=\"compare-list\"><div class=\"compare\"><span class=\"compare-num\">1</span><code>5 &lt; 4</code><span class=\"verdict\">false · stop</span></div></div>\r\n          <p><code>5</code> is already larger than the value before it. Nothing moves. This is the <strong>no-shift case</strong>.</p>\r\n          <div class=\"array-wrap indexed\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">2</span><span class=\"cell sorted\" data-label=\"1\">4</span><span class=\"cell sorted\" data-label=\"2\">5</span><span class=\"divider\"></span><span class=\"cell\" data-label=\"3\">1</span><span class=\"cell\" data-label=\"4\">3</span></div></div>\r\n        </article>\r\n\r\n        <article class=\"iteration\">\r\n          <div class=\"iteration-head\"><h3>Iteration 3 · insert 1</h3><span class=\"count\">3 comparisons · 3 shifts</span></div>\r\n          <div class=\"array-wrap indexed\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">2</span><span class=\"cell sorted\" data-label=\"1\">4</span><span class=\"cell sorted\" data-label=\"2\">5</span><span class=\"divider\"></span><span class=\"cell key\" data-label=\"3 key\">1</span><span class=\"cell\" data-label=\"4\">3</span></div></div>\r\n          <div class=\"compare-list\">\r\n            <div class=\"compare\"><span class=\"compare-num\">1</span><code>1 &lt; 5</code><span class=\"verdict move\">true · shift 5</span></div>\r\n            <div class=\"compare\"><span class=\"compare-num\">2</span><code>1 &lt; 4</code><span class=\"verdict move\">true · shift 4</span></div>\r\n            <div class=\"compare\"><span class=\"compare-num\">3</span><code>1 &lt; 2</code><span class=\"verdict move\">true · shift 2</span></div>\r\n          </div>\r\n          <p>There is nothing else on the left. Insert <code>1</code> at index <code>0</code>. This is the <strong>multiple-shift case</strong>.</p>\r\n          <div class=\"array-wrap indexed\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">4</span><span class=\"cell sorted\" data-label=\"3\">5</span><span class=\"divider\"></span><span class=\"cell\" data-label=\"4\">3</span></div></div>\r\n        </article>\r\n\r\n        <article class=\"iteration\">\r\n          <div class=\"iteration-head\"><h3>Iteration 4 · insert 3</h3><span class=\"count\">3 comparisons · 2 shifts</span></div>\r\n          <div class=\"array-wrap indexed\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">4</span><span class=\"cell sorted\" data-label=\"3\">5</span><span class=\"divider\"></span><span class=\"cell key\" data-label=\"4 key\">3</span></div></div>\r\n          <div class=\"compare-list\">\r\n            <div class=\"compare\"><span class=\"compare-num\">1</span><code>3 &lt; 5</code><span class=\"verdict move\">true · shift 5</span></div>\r\n            <div class=\"compare\"><span class=\"compare-num\">2</span><code>3 &lt; 4</code><span class=\"verdict move\">true · shift 4</span></div>\r\n            <div class=\"compare\"><span class=\"compare-num\">3</span><code>3 &lt; 2</code><span class=\"verdict\">false · stop</span></div>\r\n          </div>\r\n          <p>Insert <code>3</code> after <code>2</code>. The failed comparison is useful: it tells the algorithm where to stop.</p>\r\n          <div class=\"array-wrap indexed\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div>\r\n        </article>\r\n      "
  },
  "table": {
    "id": "table",
    "title": "The trace at a glance",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Trace table</span>\r\n        <h2>The trace at a glance</h2>\r\n        <div class=\"table-scroll\">\r\n          <table>\r\n            <thead><tr><th>Iteration</th><th>Key</th><th>Comparisons</th><th>Shifts</th><th>Array after insertion</th></tr></thead>\r\n            <tbody>\r\n              <tr><td>1</td><td>2</td><td>1</td><td>1</td><td><code>[2, 4, 5, 1, 3]</code></td></tr>\r\n              <tr><td>2</td><td>5</td><td>1</td><td>0</td><td><code>[2, 4, 5, 1, 3]</code></td></tr>\r\n              <tr><td>3</td><td>1</td><td>3</td><td>3</td><td><code>[1, 2, 4, 5, 3]</code></td></tr>\r\n              <tr><td>4</td><td>3</td><td>3</td><td>2</td><td><code>[1, 2, 3, 4, 5]</code></td></tr>\r\n              <tr><td><strong>Total</strong></td><td>—</td><td><strong>8</strong></td><td><strong>6</strong></td><td>Sorted</td></tr>\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n        <div class=\"callout\">Comparisons and shifts are not always equal. In the last iteration, the third comparison is false: it causes no shift, but tells the algorithm to stop.</div>\r\n      "
  },
  "java": {
    "id": "java",
    "title": "The Java implementation",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Java implementation</span>\r\n        <h2>The Java implementation</h2>\r\n        <div class=\"code-panel\">\r\n          <div class=\"code-head\"><span>InsertionSort.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy Java code\">Copy code</button></div>\r\n          <pre id=\"java-code\"><code><span class=\"kw\">public static void</span> insertionSort(<span class=\"ty\">int</span>[] array) {\r\n    <span class=\"cm\">// Index 0 is already a sorted prefix of length one.</span>\r\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 1; i &lt; array.length; i++) {\r\n        <span class=\"cm\">// Save the next unsorted value before shifts overwrite its cell.</span>\r\n        <span class=\"ty\">int</span> key = array[i];\r\n        <span class=\"ty\">int</span> j = i - 1;\r\n\r\n        <span class=\"cm\">// Shift every larger prefix value one position right.</span>\r\n        <span class=\"kw\">while</span> (j &gt;= 0 &amp;&amp; key &lt; array[j]) {\r\n            array[j + 1] = array[j];\r\n            j--;\r\n        }\r\n\r\n        <span class=\"cm\">// j stopped before the key's correct insertion position.</span>\r\n        array[j + 1] = key;\r\n    }\r\n}</code></pre>\r\n        </div>\r\n\r\n        <h3>What each variable means</h3>\r\n        <div class=\"term-grid\">\r\n          <div class=\"term\"><strong><code>array</code></strong>The array being sorted.</div>\r\n          <div class=\"term\"><strong><code>i</code></strong>The index of the next unsorted value.</div>\r\n          <div class=\"term\"><strong><code>key</code></strong>A safe copy of the value being inserted.</div>\r\n          <div class=\"term\"><strong><code>j</code></strong>Moves backwards through the sorted section.</div>\r\n        </div>\r\n\r\n        <h3>Why does <code>i</code> start at 1?</h3>\r\n        <p>Index <code>0</code> already forms a one-value sorted section. The first value that needs inserting is therefore at index <code>1</code>.</p>\r\n\r\n        <h3>Why save the key?</h3>\r\n        <p>Shifts can overwrite <code>array[i]</code>. Saving it in <code>key</code> prevents the original value from being lost.</p>\r\n\r\n        <h3>Understanding the while condition</h3>\r\n        <div class=\"paper-card\"><code>j &gt;= 0 &amp;&amp; key &lt; array[j]</code></div>\r\n        <p>The algorithm may shift only when a valid position remains on the left <em>and</em> that value is larger than the key. The boundary check comes first so Java never attempts to access <code>array[-1]</code>.</p>\r\n\r\n        <h3>How the shift and insertion happen</h3>\r\n        <p><code>array[j + 1] = array[j]</code> copies a larger value one place right. When the loop ends, <code>array[j + 1] = key</code> fills the gap with the saved key.</p>\r\n        <div class=\"audit-grid\">\r\n          <div class=\"from-scratch\"><strong>Write it from scratch</strong><ol><li>Start <code>i</code> at 1.</li><li>Save <code>key</code> and set <code>j = i - 1</code>.</li><li>Shift larger prefix values right.</li><li>Insert at <code>j + 1</code>.</li></ol></div>\r\n          <div class=\"direction-card\"><strong>Ascending ↔ descending</strong><p>Ascending shifts while <code>key &lt; array[j]</code>. Descending shifts while <code>key &gt; array[j]</code>.</p></div>\r\n          <div class=\"debug-list\"><strong>Debug checklist</strong><ul><li>Save the key before shifting.</li><li>Check <code>j &gt;= 0</code> first.</li><li>Insert at <code>j + 1</code>, not <code>j</code>.</li></ul></div>\r\n        </div>\r\n      "
  },
  "recursive": {
    "id": "recursive",
    "title": "The same algorithm, expressed recursively",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Recursive implementation</span>\r\n        <h2>The same algorithm, expressed recursively</h2>\r\n        <p class=\"lede\">The recursive idea is: first sort the first <code>n - 1</code> values, then insert the final value into that sorted portion.</p>\r\n        <div class=\"term-grid\">\r\n          <div class=\"term\"><strong>Base case</strong><code>n &lt;= 1</code>. Zero or one item is already sorted.</div>\r\n          <div class=\"term\"><strong>Smaller problem</strong>Sort only the first <code>n - 1</code> values.</div>\r\n          <div class=\"term\"><strong>Work after return</strong>Insert <code>array[n - 1]</code> into the sorted prefix.</div>\r\n          <div class=\"term\"><strong>First call</strong><code>insertionSortRec(array, array.length)</code>.</div>\r\n        </div>\r\n\r\n        <h3>Approach 1 · recursive outer process</h3>\r\n        <p>The recursion chooses how much of the array to sort. A loop still performs the insertion step.</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Recursive sort + iterative insertion</span></div><pre><code><span class=\"kw\">public static void</span> insertionSortRec(<span class=\"ty\">int</span>[] array, <span class=\"ty\">int</span> n) {\r\n    <span class=\"cm\">// Base case: a prefix of length zero or one is sorted.</span>\r\n    <span class=\"kw\">if</span> (n &lt;= 1) <span class=\"kw\">return</span>;\r\n\r\n    <span class=\"cm\">// First sort the smaller prefix.</span>\r\n    insertionSortRec(array, n - 1);\r\n\r\n    <span class=\"cm\">// Then insert the final value into that sorted prefix.</span>\r\n    <span class=\"ty\">int</span> key = array[n - 1];\r\n    <span class=\"ty\">int</span> j = n - 2;\r\n    <span class=\"kw\">while</span> (j &gt;= 0 &amp;&amp; key &lt; array[j]) {\r\n        array[j + 1] = array[j];\r\n        j--;\r\n    }\r\n    array[j + 1] = key;\r\n}</code></pre></div>\r\n\r\n        <h3>Call-and-return trace on <code>[4, 2, 5, 1, 3]</code></h3>\r\n        <div class=\"kicker\">Calls become smaller</div>\r\n        <div class=\"stack-flow\" aria-label=\"Recursive calls descend from n equals five to n equals one\">\r\n          <span class=\"stack-frame\">n=5</span><span class=\"stack-arrow\">→</span><span class=\"stack-frame\">n=4</span><span class=\"stack-arrow\">→</span><span class=\"stack-frame\">n=3</span><span class=\"stack-arrow\">→</span><span class=\"stack-frame\">n=2</span><span class=\"stack-arrow\">→</span><span class=\"stack-frame\">n=1 · stop</span>\r\n        </div>\r\n        <div class=\"kicker\">Returns perform the insertions</div>\r\n        <div class=\"flow-steps\">\r\n          <div class=\"flow-step\"><b>1</b><div>Return to <code>n=1</code>. Base case: one value is already sorted, so nothing is inserted.</div></div>\r\n          <div class=\"flow-step\"><b>2</b><div>Return to <code>n=2</code>. Insert 2 into <code>[4]</code> → 1 shift; the array is now <code>[2, 4, 5, 1, 3]</code>.</div></div>\r\n          <div class=\"flow-step\"><b>3</b><div>Return to <code>n=3</code>. Insert 5 into <code>[2, 4]</code> → no shift; the array is now <code>[2, 4, 5, 1, 3]</code>.</div></div>\r\n          <div class=\"flow-step\"><b>4</b><div>Return to <code>n=4</code>. Insert 1 into <code>[2, 4, 5]</code> → 3 shifts; the array is now <code>[1, 2, 4, 5, 3]</code>.</div></div>\r\n          <div class=\"flow-step\"><b>5</b><div>Return to <code>n=5</code>. Insert 3 into <code>[1, 2, 4, 5]</code> → 2 shifts; the array is now <code>[1, 2, 3, 4, 5]</code>.</div></div>\r\n        </div>\r\n\r\n        <h3>Approach 2 · fully recursive shifting</h3>\r\n        <p>This version also replaces the insertion loop with a recursive helper. It is useful for understanding recursion, although the first version is usually simpler to read.</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Recursive sort + recursive insertion</span></div><pre><code><span class=\"kw\">public static void</span> insertionSortFullyRec(<span class=\"ty\">int</span>[] a, <span class=\"ty\">int</span> n) {\r\n    <span class=\"cm\">// Stop shrinking at a one-value prefix.</span>\r\n    <span class=\"kw\">if</span> (n &lt;= 1) <span class=\"kw\">return</span>;\r\n    insertionSortFullyRec(a, n - 1);\r\n    <span class=\"cm\">// Recursively place the last value into the sorted prefix.</span>\r\n    insertRec(a, a[n - 1], n - 2);\r\n}\r\n\r\n<span class=\"kw\">private static void</span> insertRec(<span class=\"ty\">int</span>[] a, <span class=\"ty\">int</span> key, <span class=\"ty\">int</span> j) {\r\n    <span class=\"cm\">// Stop at the left edge or after a value no larger than key.</span>\r\n    <span class=\"kw\">if</span> (j &lt; 0 || a[j] &lt;= key) {\r\n        a[j + 1] = key;\r\n        <span class=\"kw\">return</span>;\r\n    }\r\n    a[j + 1] = a[j];\r\n    insertRec(a, key, j - 1);\r\n}</code></pre></div>\r\n        <h4>Trace · insertRec for the last step of <code>[4, 2, 5, 1, 3]</code></h4><p>The final return inserts <code>3</code> into the sorted prefix <code>[1, 2, 4, 5]</code>. The helper is called with <code>j = n - 2 = 3</code>.</p><div class=\"table-scroll\"><table><thead><tr><th>Call</th><th>What happens</th><th>Array after</th></tr></thead><tbody><tr><td><code>insertRec(a, 3, 3)</code></td><td><code>a[3] = 5 &gt; 3</code>: shift, <code>a[4] = 5</code></td><td><code>[1, 2, 4, 5, 5]</code></td></tr><tr><td><code>insertRec(a, 3, 2)</code></td><td><code>a[2] = 4 &gt; 3</code>: shift, <code>a[3] = 4</code></td><td><code>[1, 2, 4, 4, 5]</code></td></tr><tr><td><code>insertRec(a, 3, 1)</code></td><td><code>a[1] = 2 &lt;= 3</code>: stop, so <code>a[2] = 3</code></td><td><code>[1, 2, 3, 4, 5]</code></td></tr></tbody></table></div>\r\n        <div class=\"callout\"><strong>Complexity:</strong> the comparisons and shifts remain <code>O(n²)</code> in the worst case. Unlike the iterative version’s <code>O(1)</code> extra space, recursive calls require <code>O(n)</code> extra call space.</div>\r\n      "
  },
  "insertion-descending": {
    "id": "insertion-descending",
    "title": "Reverse the order by reversing one comparison",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Descending order</span>\r\n        <h2>Reverse the order by reversing one comparison</h2>\r\n        <p class=\"lede\">Only the shift condition changes. Everything else, including saving the key, starting at index 1, and inserting at <code>j + 1</code>, stays identical.</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Two versions of the while line</span></div><pre><code><span class=\"cm\">// Ascending: shift while the key is SMALLER than the value on its left.</span>\r\n<span class=\"kw\">while</span> (j &gt;= 0 &amp;&amp; key &lt; array[j]) {\r\n    array[j + 1] = array[j];\r\n    j--;\r\n}\r\n\r\n<span class=\"cm\">// Descending: shift while the key is LARGER than the value on its left.</span>\r\n<span class=\"kw\">while</span> (j &gt;= 0 &amp;&amp; key &gt; array[j]) {\r\n    array[j + 1] = array[j];\r\n    j--;\r\n}</code></pre></div>\r\n        <h3>The same input in both directions</h3>\r\n        <p>Each cell reads comparisons / shifts for <code>[4, 2, 5, 1, 3]</code>.</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Key</th><th>Ascending c / s</th><th>Array after (ascending)</th><th>Descending c / s</th><th>Array after (descending)</th></tr></thead><tbody><tr><td>2</td><td>1 / 1</td><td><code>[2, 4, 5, 1, 3]</code></td><td>1 / 0</td><td><code>[4, 2, 5, 1, 3]</code></td></tr><tr><td>5</td><td>1 / 0</td><td><code>[2, 4, 5, 1, 3]</code></td><td>2 / 2</td><td><code>[5, 4, 2, 1, 3]</code></td></tr><tr><td>1</td><td>3 / 3</td><td><code>[1, 2, 4, 5, 3]</code></td><td>1 / 0</td><td><code>[5, 4, 2, 1, 3]</code></td></tr><tr><td>3</td><td>3 / 2</td><td><code>[1, 2, 3, 4, 5]</code></td><td>3 / 2</td><td><code>[5, 4, 3, 2, 1]</code></td></tr><tr><td><strong>Total</strong></td><td><strong>8 / 6</strong></td><td><code>[1, 2, 3, 4, 5]</code></td><td><strong>7 / 4</strong></td><td><code>[5, 4, 3, 2, 1]</code></td></tr></tbody></table></div>\r\n        <div class=\"result-line\">Ascending: <code>8</code> comparisons, <code>6</code> shifts. Descending: <code>7</code> comparisons, <code>4</code> shifts.</div>\r\n        <p>The costs differ because “out of order” depends on the direction. This array has 10 pairs of positions. Six have a larger value on the left, and those cost a shift when sorting ascending. The other four have a smaller value on the left, and those cost a shift when sorting descending: 6 + 4 = 10.</p>\r\n        <div class=\"callout\"><strong>Stability is unchanged.</strong> Descending still uses a strict <code>&gt;</code>, so equal values do not shift past each other.</div>\r\n        <details><summary>Quick check: for an already <em>descending</em> array, which direction is the best case?</summary><div class=\"answer\">Sorting descending. Every key is already not larger than the value on its left, so each iteration makes one failed comparison and no shifts: <code>O(n)</code>.</div></details>\r\n      "
  },
  "insertion-test": {
    "id": "insertion-test",
    "title": "Test 1 question 3(b): descending trace",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Test 1 question 3(b): descending trace</span>\r\n        <h2>Test 1 question 3(b): descending trace</h2>\r\n        <p class=\"lede\">The insertion-sort question from Test 1, solved step by step.</p>\r\n        \r\n        <p>This is Test 1, question 3(b): <em>“Show the contents of the array below at the end of each pass when sorting the array using the insertion sort algorithm, assuming <strong>descending</strong> order.”</em> The array is <code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code>.</p>\r\n        <h3>Before you start: what changes for descending?</h3>\r\n        <p>In ascending insertion sort the key moves left while it is <em>smaller</em> than the value before it. In descending order the key moves left while it is <em>larger</em>. In code, the only change is the comparison in the <code>while</code> loop:</p>\r\n        <div class=\"two-col\">\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>Ascending</span></div><pre><code><span class=\"kw\">while</span> (j &gt;= 0 &amp;&amp; key &lt; arr[j]) {\r\n    arr[j + 1] = arr[j];\r\n    j--;\r\n}</code></pre></div>\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>Descending (this question)</span></div><pre><code><span class=\"kw\">while</span> (j &gt;= 0 &amp;&amp; key &gt; arr[j]) {\r\n    arr[j + 1] = arr[j];\r\n    j--;\r\n}</code></pre></div>\r\n        </div>\r\n        <p>Use the descending rule on every row below: <strong>the largest values end up on the left</strong>, so the finished array is <code>[90, 83, 76, 59, 50, 32, 12, 6, 2]</code>. A pass is one value of <code>i</code> (the outer loop); there are 8 passes for nine values.</p>\r\n        <figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Unsorted nine values as bars\"><div class=\"bar\" style=\"--p:0.556\"><i></i><b>50</b><small>0</small></div><div class=\"bar\" style=\"--p:0.922\"><i></i><b>83</b><small>1</small></div><div class=\"bar\" style=\"--p:0.844\"><i></i><b>76</b><small>2</small></div><div class=\"bar\" style=\"--p:0.067\"><i></i><b>6</b><small>3</small></div><div class=\"bar\" style=\"--p:0.356\"><i></i><b>32</b><small>4</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>90</b><small>5</small></div><div class=\"bar\" style=\"--p:0.133\"><i></i><b>12</b><small>6</small></div><div class=\"bar\" style=\"--p:0.022\"><i></i><b>2</b><small>7</small></div><div class=\"bar\" style=\"--p:0.656\"><i></i><b>59</b><small>8</small></div></div></figure>\r\n        <h3>The answer, pass by pass</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Pass</th><th>Array at the end of the pass</th><th>Operation</th></tr></thead><tbody><tr><td>Start</td><td><code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code></td><td>(unsorted: only the first value is a sorted section of length 1)</td></tr><tr><td>1</td><td><code>[83, 50, 76, 6, 32, 90, 12, 2, 59]</code></td><td>key = 83: <code>83 &gt; 50</code> true → shift 50 right; front of the array reached → stop; insert <strong>83</strong> at index 0</td></tr><tr><td>2</td><td><code>[83, 76, 50, 6, 32, 90, 12, 2, 59]</code></td><td>key = 76: <code>76 &gt; 50</code> true → shift 50 right; <code>76 &gt; 83</code> false → stop; insert <strong>76</strong> at index 1</td></tr><tr><td>3</td><td><code>[83, 76, 50, 6, 32, 90, 12, 2, 59]</code></td><td>key = 6: <code>6 &gt; 50</code> false → stop; insert <strong>6</strong> at index 3 (no shift needed)</td></tr><tr><td>4</td><td><code>[83, 76, 50, 32, 6, 90, 12, 2, 59]</code></td><td>key = 32: <code>32 &gt; 6</code> true → shift 6 right; <code>32 &gt; 50</code> false → stop; insert <strong>32</strong> at index 3</td></tr><tr><td>5</td><td><code>[90, 83, 76, 50, 32, 6, 12, 2, 59]</code></td><td>key = 90: <code>90 &gt; 6</code> true → shift 6 right; <code>90 &gt; 32</code> true → shift 32 right; <code>90 &gt; 50</code> true → shift 50 right; <code>90 &gt; 76</code> true → shift 76 right; <code>90 &gt; 83</code> true → shift 83 right; front of the array reached → stop; insert <strong>90</strong> at index 0</td></tr><tr><td>6</td><td><code>[90, 83, 76, 50, 32, 12, 6, 2, 59]</code></td><td>key = 12: <code>12 &gt; 6</code> true → shift 6 right; <code>12 &gt; 32</code> false → stop; insert <strong>12</strong> at index 5</td></tr><tr><td>7</td><td><code>[90, 83, 76, 50, 32, 12, 6, 2, 59]</code></td><td>key = 2: <code>2 &gt; 6</code> false → stop; insert <strong>2</strong> at index 7 (no shift needed)</td></tr><tr><td>8</td><td><code>[90, 83, 76, 59, 50, 32, 12, 6, 2]</code></td><td>key = 59: <code>59 &gt; 2</code> true → shift 2 right; <code>59 &gt; 6</code> true → shift 6 right; <code>59 &gt; 12</code> true → shift 12 right; <code>59 &gt; 32</code> true → shift 32 right; <code>59 &gt; 50</code> true → shift 50 right; <code>59 &gt; 76</code> false → stop; insert <strong>59</strong> at index 3</td></tr></tbody></table></div>\r\n        <p><strong>Totals:</strong> 20 comparisons and 14 shifts. In a test you only need the middle column, but writing the operation (as above) shows the examiner you followed the algorithm and earns method marks even if one row slips.</p>\r\n        <h3>The same trace as pictures</h3>\r\n        <p>The divider separates the sorted section (left) from the unsorted rest. The darker cell is the key that was just inserted.</p>\r\n        <div class=\"worked-visual\" aria-label=\"Descending insertion sort on the Test 1 array\"><div class=\"worked-step\"><h4>Start</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [50, 83, 76, 6, 32, 90, 12, 2, 59]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">50</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"1\">83</span><span class=\"cell\" data-label=\"2\">76</span><span class=\"cell\" data-label=\"3\">6</span><span class=\"cell\" data-label=\"4\">32</span><span class=\"cell\" data-label=\"5\">90</span><span class=\"cell\" data-label=\"6\">12</span><span class=\"cell\" data-label=\"7\">2</span><span class=\"cell\" data-label=\"8\">59</span></div></div></div><div class=\"worked-step\"><h4>Pass 1 · key = 83 · 1 shift</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 1: [83, 50, 76, 6, 32, 90, 12, 2, 59]\"><div class=\"array\"><span class=\"cell sorted key\" data-label=\"0\">83</span><span class=\"cell sorted\" data-label=\"1\">50</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"2\">76</span><span class=\"cell\" data-label=\"3\">6</span><span class=\"cell\" data-label=\"4\">32</span><span class=\"cell\" data-label=\"5\">90</span><span class=\"cell\" data-label=\"6\">12</span><span class=\"cell\" data-label=\"7\">2</span><span class=\"cell\" data-label=\"8\">59</span></div></div></div><div class=\"worked-step\"><h4>Pass 2 · key = 76 · 1 shift</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 2: [83, 76, 50, 6, 32, 90, 12, 2, 59]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">83</span><span class=\"cell sorted key\" data-label=\"1\">76</span><span class=\"cell sorted\" data-label=\"2\">50</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"3\">6</span><span class=\"cell\" data-label=\"4\">32</span><span class=\"cell\" data-label=\"5\">90</span><span class=\"cell\" data-label=\"6\">12</span><span class=\"cell\" data-label=\"7\">2</span><span class=\"cell\" data-label=\"8\">59</span></div></div></div><div class=\"worked-step\"><h4>Pass 3 · key = 6 · 0 shifts</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 3: [83, 76, 50, 6, 32, 90, 12, 2, 59]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">83</span><span class=\"cell sorted\" data-label=\"1\">76</span><span class=\"cell sorted\" data-label=\"2\">50</span><span class=\"cell sorted key\" data-label=\"3\">6</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"4\">32</span><span class=\"cell\" data-label=\"5\">90</span><span class=\"cell\" data-label=\"6\">12</span><span class=\"cell\" data-label=\"7\">2</span><span class=\"cell\" data-label=\"8\">59</span></div></div></div><div class=\"worked-step\"><h4>Pass 4 · key = 32 · 1 shift</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 4: [83, 76, 50, 32, 6, 90, 12, 2, 59]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">83</span><span class=\"cell sorted\" data-label=\"1\">76</span><span class=\"cell sorted\" data-label=\"2\">50</span><span class=\"cell sorted key\" data-label=\"3\">32</span><span class=\"cell sorted\" data-label=\"4\">6</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"5\">90</span><span class=\"cell\" data-label=\"6\">12</span><span class=\"cell\" data-label=\"7\">2</span><span class=\"cell\" data-label=\"8\">59</span></div></div></div><div class=\"worked-step\"><h4>Pass 5 · key = 90 · 5 shifts</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 5: [90, 83, 76, 50, 32, 6, 12, 2, 59]\"><div class=\"array\"><span class=\"cell sorted key\" data-label=\"0\">90</span><span class=\"cell sorted\" data-label=\"1\">83</span><span class=\"cell sorted\" data-label=\"2\">76</span><span class=\"cell sorted\" data-label=\"3\">50</span><span class=\"cell sorted\" data-label=\"4\">32</span><span class=\"cell sorted\" data-label=\"5\">6</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"6\">12</span><span class=\"cell\" data-label=\"7\">2</span><span class=\"cell\" data-label=\"8\">59</span></div></div></div><div class=\"worked-step\"><h4>Pass 6 · key = 12 · 1 shift</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 6: [90, 83, 76, 50, 32, 12, 6, 2, 59]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">90</span><span class=\"cell sorted\" data-label=\"1\">83</span><span class=\"cell sorted\" data-label=\"2\">76</span><span class=\"cell sorted\" data-label=\"3\">50</span><span class=\"cell sorted\" data-label=\"4\">32</span><span class=\"cell sorted key\" data-label=\"5\">12</span><span class=\"cell sorted\" data-label=\"6\">6</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"7\">2</span><span class=\"cell\" data-label=\"8\">59</span></div></div></div><div class=\"worked-step\"><h4>Pass 7 · key = 2 · 0 shifts</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 7: [90, 83, 76, 50, 32, 12, 6, 2, 59]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">90</span><span class=\"cell sorted\" data-label=\"1\">83</span><span class=\"cell sorted\" data-label=\"2\">76</span><span class=\"cell sorted\" data-label=\"3\">50</span><span class=\"cell sorted\" data-label=\"4\">32</span><span class=\"cell sorted\" data-label=\"5\">12</span><span class=\"cell sorted\" data-label=\"6\">6</span><span class=\"cell sorted key\" data-label=\"7\">2</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"8\">59</span></div></div></div><div class=\"worked-step\"><h4>Pass 8 · key = 59 · 5 shifts</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After pass 8: [90, 83, 76, 59, 50, 32, 12, 6, 2]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">90</span><span class=\"cell sorted\" data-label=\"1\">83</span><span class=\"cell sorted\" data-label=\"2\">76</span><span class=\"cell sorted key\" data-label=\"3\">59</span><span class=\"cell sorted\" data-label=\"4\">50</span><span class=\"cell sorted\" data-label=\"5\">32</span><span class=\"cell sorted\" data-label=\"6\">12</span><span class=\"cell sorted\" data-label=\"7\">6</span><span class=\"cell sorted\" data-label=\"8\">2</span></div></div></div></div>\r\n        <figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"Result: a staircase going down\"><div class=\"bar done\" style=\"--p:1.000\"><i></i><b>90</b><small>0</small></div><div class=\"bar done\" style=\"--p:0.922\"><i></i><b>83</b><small>1</small></div><div class=\"bar done\" style=\"--p:0.844\"><i></i><b>76</b><small>2</small></div><div class=\"bar done\" style=\"--p:0.656\"><i></i><b>59</b><small>3</small></div><div class=\"bar done\" style=\"--p:0.556\"><i></i><b>50</b><small>4</small></div><div class=\"bar done\" style=\"--p:0.356\"><i></i><b>32</b><small>5</small></div><div class=\"bar done\" style=\"--p:0.133\"><i></i><b>12</b><small>6</small></div><div class=\"bar done\" style=\"--p:0.067\"><i></i><b>6</b><small>7</small></div><div class=\"bar done\" style=\"--p:0.022\"><i></i><b>2</b><small>8</small></div></div></figure>\r\n        <p class=\"fig-cap\">Descending order drawn as bars: a staircase going <em>down</em>.</p>\r\n        <div class=\"callout\"><strong>How to check your own answer:</strong> after every pass, the first <code>i + 1</code> values must be in descending order, and together they must be exactly the first <code>i + 1</code> original values. The cells to the right of the divider must be untouched.</div>\r\n    \r\n      "
  },
  "examples": {
    "id": "examples",
    "title": "Four patterns you must recognise",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Worked examples</span>\r\n        <h2>Four patterns you must recognise</h2>\r\n        <article class=\"example-card\"><h3>Already sorted · <code>[1, 2, 3, 4, 5]</code></h3><p>Every key is already larger than the value before it.</p><div class=\"worked-visual\" aria-label=\"Insertion sort trace for [1, 2, 3, 4, 5]\"><div class=\"worked-step\"><h4>Start · the first value is already a sorted section of length 1</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start array [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>Insert 2 · i = 1</h4><p><code>2 &lt; 1</code> false → stop. Insert <code>2</code> at index 1.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 2: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted key\" data-label=\"1\">2</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>Insert 3 · i = 2</h4><p><code>3 &lt; 2</code> false → stop. Insert <code>3</code> at index 2.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 3: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted key\" data-label=\"2\">3</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>Insert 4 · i = 3</h4><p><code>4 &lt; 3</code> false → stop. Insert <code>4</code> at index 3.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 4: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted key\" data-label=\"3\">4</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>Insert 5 · i = 4</h4><p><code>5 &lt; 4</code> false → stop. Insert <code>5</code> at index 4.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 5: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted key\" data-label=\"4\">5</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Key</th><th>Comparisons</th><th>Shifts</th><th>Array after insertion</th></tr></thead><tbody><tr><td>2</td><td>1</td><td>0</td><td><code>[1, 2, 3, 4, 5]</code></td></tr><tr><td>3</td><td>1</td><td>0</td><td><code>[1, 2, 3, 4, 5]</code></td></tr><tr><td>4</td><td>1</td><td>0</td><td><code>[1, 2, 3, 4, 5]</code></td></tr><tr><td>5</td><td>1</td><td>0</td><td><code>[1, 2, 3, 4, 5]</code></td></tr><tr><td><strong>Total</strong></td><td><strong>4</strong></td><td><strong>0</strong></td><td>Sorted</td></tr></tbody></table></div><div class=\"result-line\"><code>4</code> comparisons, <code>0</code> shifts: <code>n − 1</code> comparisons, the <code>O(n)</code> best case.</div></article><article class=\"example-card\"><h3>Reverse order · <code>[5, 4, 3, 2, 1]</code></h3><p>Every key is smaller than everything in the sorted section, so it crosses all of it.</p><div class=\"worked-visual\" aria-label=\"Insertion sort trace for [5, 4, 3, 2, 1]\"><div class=\"worked-step\"><h4>Start · the first value is already a sorted section of length 1</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start array [5, 4, 3, 2, 1]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">5</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"1\">4</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">2</span><span class=\"cell\" data-label=\"4\">1</span></div></div></div><div class=\"worked-step\"><h4>Insert 4 · i = 1</h4><p><code>4 &lt; 5</code> true → shift 5; no cell remains on the left → stop. Insert <code>4</code> at index 0.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 4: [4, 5, 3, 2, 1]\"><div class=\"array\"><span class=\"cell sorted key\" data-label=\"0\">4</span><span class=\"cell sorted\" data-label=\"1\">5</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">2</span><span class=\"cell\" data-label=\"4\">1</span></div></div></div><div class=\"worked-step\"><h4>Insert 3 · i = 2</h4><p><code>3 &lt; 5</code> true → shift 5; <code>3 &lt; 4</code> true → shift 4; no cell remains on the left → stop. Insert <code>3</code> at index 0.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 3: [3, 4, 5, 2, 1]\"><div class=\"array\"><span class=\"cell sorted key\" data-label=\"0\">3</span><span class=\"cell sorted\" data-label=\"1\">4</span><span class=\"cell sorted\" data-label=\"2\">5</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"3\">2</span><span class=\"cell\" data-label=\"4\">1</span></div></div></div><div class=\"worked-step\"><h4>Insert 2 · i = 3</h4><p><code>2 &lt; 5</code> true → shift 5; <code>2 &lt; 4</code> true → shift 4; <code>2 &lt; 3</code> true → shift 3; no cell remains on the left → stop. Insert <code>2</code> at index 0.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 2: [2, 3, 4, 5, 1]\"><div class=\"array\"><span class=\"cell sorted key\" data-label=\"0\">2</span><span class=\"cell sorted\" data-label=\"1\">3</span><span class=\"cell sorted\" data-label=\"2\">4</span><span class=\"cell sorted\" data-label=\"3\">5</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"4\">1</span></div></div></div><div class=\"worked-step\"><h4>Insert 1 · i = 4</h4><p><code>1 &lt; 5</code> true → shift 5; <code>1 &lt; 4</code> true → shift 4; <code>1 &lt; 3</code> true → shift 3; <code>1 &lt; 2</code> true → shift 2; no cell remains on the left → stop. Insert <code>1</code> at index 0.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 1: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted key\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted\" data-label=\"4\">5</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Key</th><th>Comparisons</th><th>Shifts</th><th>Array after insertion</th></tr></thead><tbody><tr><td>4</td><td>1</td><td>1</td><td><code>[4, 5, 3, 2, 1]</code></td></tr><tr><td>3</td><td>2</td><td>2</td><td><code>[3, 4, 5, 2, 1]</code></td></tr><tr><td>2</td><td>3</td><td>3</td><td><code>[2, 3, 4, 5, 1]</code></td></tr><tr><td>1</td><td>4</td><td>4</td><td><code>[1, 2, 3, 4, 5]</code></td></tr><tr><td><strong>Total</strong></td><td><strong>10</strong></td><td><strong>10</strong></td><td>Sorted</td></tr></tbody></table></div><div class=\"result-line\"><code>10</code> comparisons and <code>10</code> shifts: <code>1 + 2 + 3 + 4 = n(n − 1) / 2</code>, the <code>O(n²)</code> worst case.</div></article><article class=\"example-card\"><h3>Nearly sorted · <code>[1, 2, 4, 3, 5]</code></h3><p>Only one pair is out of order, so only one key moves.</p><div class=\"worked-visual\" aria-label=\"Insertion sort trace for [1, 2, 4, 3, 5]\"><div class=\"worked-step\"><h4>Start · the first value is already a sorted section of length 1</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start array [1, 2, 4, 3, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">4</span><span class=\"cell\" data-label=\"3\">3</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>Insert 2 · i = 1</h4><p><code>2 &lt; 1</code> false → stop. Insert <code>2</code> at index 1.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 2: [1, 2, 4, 3, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted key\" data-label=\"1\">2</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"2\">4</span><span class=\"cell\" data-label=\"3\">3</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>Insert 4 · i = 2</h4><p><code>4 &lt; 2</code> false → stop. Insert <code>4</code> at index 2.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 4: [1, 2, 4, 3, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted key\" data-label=\"2\">4</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"3\">3</span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>Insert 3 · i = 3</h4><p><code>3 &lt; 4</code> true → shift 4; <code>3 &lt; 2</code> false → stop. Insert <code>3</code> at index 2.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 3: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted key\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"4\">5</span></div></div></div><div class=\"worked-step\"><h4>Insert 5 · i = 4</h4><p><code>5 &lt; 4</code> false → stop. Insert <code>5</code> at index 4.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 5: [1, 2, 3, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3</span><span class=\"cell sorted\" data-label=\"3\">4</span><span class=\"cell sorted key\" data-label=\"4\">5</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Key</th><th>Comparisons</th><th>Shifts</th><th>Array after insertion</th></tr></thead><tbody><tr><td>2</td><td>1</td><td>0</td><td><code>[1, 2, 4, 3, 5]</code></td></tr><tr><td>4</td><td>1</td><td>0</td><td><code>[1, 2, 4, 3, 5]</code></td></tr><tr><td>3</td><td>2</td><td>1</td><td><code>[1, 2, 3, 4, 5]</code></td></tr><tr><td>5</td><td>1</td><td>0</td><td><code>[1, 2, 3, 4, 5]</code></td></tr><tr><td><strong>Total</strong></td><td><strong>5</strong></td><td><strong>1</strong></td><td>Sorted</td></tr></tbody></table></div><div class=\"result-line\"><code>5</code> comparisons and <code>1</code> shift. The cost tracks how disordered the input is, which is what <strong>adaptive</strong> means.</div></article><article class=\"example-card\"><h3>Duplicates · <code>[3ᵃ, 1, 3ᵇ, 2]</code></h3><p>Two equal 3s are labelled <code>ᵃ</code> and <code>ᵇ</code> so their order can be tracked.</p><div class=\"worked-visual\" aria-label=\"Insertion sort trace for [3ᵃ, 1, 3ᵇ, 2]\"><div class=\"worked-step\"><h4>Start · the first value is already a sorted section of length 1</h4><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start array [3ᵃ, 1, 3ᵇ, 2]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">3ᵃ</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"1\">1</span><span class=\"cell\" data-label=\"2\">3ᵇ</span><span class=\"cell\" data-label=\"3\">2</span></div></div></div><div class=\"worked-step\"><h4>Insert 1 · i = 1</h4><p><code>1 &lt; 3ᵃ</code> true → shift 3ᵃ; no cell remains on the left → stop. Insert <code>1</code> at index 0.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 1: [1, 3ᵃ, 3ᵇ, 2]\"><div class=\"array\"><span class=\"cell sorted key\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">3ᵃ</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"2\">3ᵇ</span><span class=\"cell\" data-label=\"3\">2</span></div></div></div><div class=\"worked-step\"><h4>Insert 3ᵇ · i = 2</h4><p><code>3ᵇ &lt; 3ᵃ</code> false → stop. Insert <code>3ᵇ</code> at index 2.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 3ᵇ: [1, 3ᵃ, 3ᵇ, 2]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted\" data-label=\"1\">3ᵃ</span><span class=\"cell sorted key\" data-label=\"2\">3ᵇ</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell\" data-label=\"3\">2</span></div></div></div><div class=\"worked-step\"><h4>Insert 2 · i = 3</h4><p><code>2 &lt; 3ᵇ</code> true → shift 3ᵇ; <code>2 &lt; 3ᵃ</code> true → shift 3ᵃ; <code>2 &lt; 1</code> false → stop. Insert <code>2</code> at index 1.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"After inserting 2: [1, 2, 3ᵃ, 3ᵇ]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">1</span><span class=\"cell sorted key\" data-label=\"1\">2</span><span class=\"cell sorted\" data-label=\"2\">3ᵃ</span><span class=\"cell sorted\" data-label=\"3\">3ᵇ</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Key</th><th>Comparisons</th><th>Shifts</th><th>Array after insertion</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>1</td><td><code>[1, 3ᵃ, 3ᵇ, 2]</code></td></tr><tr><td>3ᵇ</td><td>1</td><td>0</td><td><code>[1, 3ᵃ, 3ᵇ, 2]</code></td></tr><tr><td>2</td><td>3</td><td>2</td><td><code>[1, 2, 3ᵃ, 3ᵇ]</code></td></tr><tr><td><strong>Total</strong></td><td><strong>5</strong></td><td><strong>3</strong></td><td>Sorted</td></tr></tbody></table></div><div class=\"result-line\"><code>5</code> comparisons, <code>3</code> shifts. <code>3ᵇ &lt; 3ᵃ</code> is false, so <code>3ᵃ</code> stays ahead of <code>3ᵇ</code>. Equal values never cross, which is what <strong>stable</strong> means.</div></article>\r\n                <h3 id=\"insertion-questions\">Questions</h3>\r\n        <details><summary>Why is shifting preferred to swapping the key repeatedly?</summary><div class=\"answer\">Saving one key and shifting a block makes the algorithm’s purpose clearer and avoids unnecessary repeated exchanges.</div></details>\r\n        <details><summary>What happens if the while comparison uses <code>&lt;=</code>?</summary><div class=\"answer\">Equal values may move past one another, so the implementation can lose stability.</div></details>\r\n        <details><summary>Does descending order cost the same as ascending order?</summary><div class=\"answer\">Not necessarily. On <code>[4, 2, 5, 1, 3]</code> ascending makes 8 comparisons and 6 shifts, while descending makes 7 comparisons and 4 shifts. Each shift removes one out-of-order pair, and the number of such pairs depends on the direction. See <a href=\"#insertion-descending\">Descending order</a>.</div></details>\r\n        <div class=\"method-summary\"><strong>Insertion sort in one sentence</strong><p>Take the next key, shift larger values in the sorted prefix right, and place the key into the gap.</p></div>\r\n      "
  },
  "properties": {
    "id": "properties",
    "title": "Properties",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Properties</span>\r\n        <h2>Properties</h2>\r\n        <div class=\"properties\">\r\n          <div class=\"property\"><small>Best time</small><b>O(n)</b></div>\r\n          <div class=\"property\"><small>Average time</small><b>O(n²)</b></div>\r\n          <div class=\"property\"><small>Worst time</small><b>O(n²)</b></div>\r\n          <div class=\"property\"><small>Extra space</small><b>O(1)</b></div>\r\n          <div class=\"property\"><small>Stable</small><b>Yes</b></div>\r\n          <div class=\"property\"><small>In-place</small><b>Yes</b></div>\r\n          <div class=\"property\"><small>Adaptive</small><b>Yes</b></div>\r\n          <div class=\"property\"><small>Type</small><b>Comparison</b></div>\r\n        </div>\r\n\r\n        <h3>Stable</h3>\r\n        <p>Equal values keep their original relative order. The condition uses <code>&lt;</code>, so equal values are not moved past each other. Changing it to <code>&lt;=</code> would remove that guarantee.</p>\r\n        <h3>In-place</h3>\r\n        <p>The values are rearranged inside the original array. Only a few variables are added, so extra space remains constant: <code>O(1)</code>.</p>\r\n        <h3>Adaptive</h3>\r\n        <p>Already sorted or nearly sorted data needs very few shifts. The algorithm notices this naturally; it does not keep scanning left once a comparison fails.</p>\r\n        <h3>Comparison-based</h3>\r\n        <p>Every placement decision comes from questions such as <code>3 &lt; 5</code> and <code>3 &lt; 2</code>.</p>\r\n      "
  },
  "complexity": {
    "id": "complexity",
    "title": "Why those complexities occur",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Why those complexities occur</span>\r\n        <h2>Why those complexities occur</h2>\r\n        <div class=\"complexity-grid\">\r\n          <div class=\"complexity-item\"><strong>Best case · O(n)</strong>An already sorted array needs one failed comparison for each new key and no shifts.</div>\r\n          <div class=\"complexity-item\"><strong>Worst case · O(n²)</strong>A reverse-sorted array makes every new key cross the entire sorted section.</div>\r\n        </div>\r\n        <h3>Best case</h3>\r\n        <p>For <code>[1, 2, 3, 4, 5]</code>, the comparisons <code>2 &lt; 1</code>, <code>3 &lt; 2</code>, <code>4 &lt; 3</code>, and <code>5 &lt; 4</code> all fail immediately. That is <code>n − 1</code> comparisons and no shifts, so the work grows directly with <code>n</code>.</p>\r\n        <h3>Worst case</h3>\r\n        <p>For <code>[5, 4, 3, 2, 1]</code>, the new keys move past 1, then 2, then 3, then 4 earlier values.</p>\r\n        <div class=\"formula\">1 + 2 + 3 + … + (n − 1) = n(n − 1) / 2 → O(n²)</div>\r\n        <h3>Average case</h3>\r\n        <p>In random data, a key moves across roughly half of the sorted section on average. The constant is smaller than in the worst case, but the dominant growth is still proportional to <code>n²</code>.</p>\r\n      "
  },
  "when": {
    "id": "when",
    "title": "When should you use it?",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · When to use it</span>\r\n        <h2>When should you use it?</h2>\r\n        <div class=\"use-grid\">\r\n          <div class=\"use good\"><strong>A good choice</strong>Small arrays; nearly sorted values; data arriving one item at a time; very limited memory; cases that need stability.</div>\r\n          <div class=\"use poor\"><strong>A poor choice</strong>Very large arrays; reverse-ordered data; situations requiring predictable <code>O(n log n)</code> performance.</div>\r\n        </div>\r\n        <p>Insertion sort is excellent for a small hand of cards or adding a new score to an already sorted leaderboard. For a large, disorderly array, merge sort is usually more efficient.</p>\r\n      "
  },
  "mistakes": {
    "id": "mistakes",
    "title": "Common mistakes",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Common mistakes</span>\r\n        <h2>Common mistakes</h2>\r\n        <div class=\"mistake\"><span class=\"mistake-no\">1</span><div><strong>Calling shifts swaps.</strong><br>Insertion sort saves the key, shifts larger values, and inserts the key. It does not normally exchange pairs.</div></div>\r\n        <div class=\"mistake\"><span class=\"mistake-no\">2</span><div><strong>Starting at index 0.</strong><br>The first element already forms the initial sorted section, so the outer loop begins at index 1.</div></div>\r\n        <div class=\"mistake\"><span class=\"mistake-no\">3</span><div><strong>Forgetting to save the key.</strong><br>A shift may overwrite its array position. Save <code>array[i]</code> before moving anything.</div></div>\r\n        <div class=\"mistake\"><span class=\"mistake-no\">4</span><div><strong>Checking the value before the boundary.</strong><br>Use <code>j &gt;= 0 &amp;&amp; key &lt; array[j]</code>. The reverse order may attempt to read index −1.</div></div>\r\n        <div class=\"mistake\"><span class=\"mistake-no\">5</span><div><strong>Using <code>&lt;=</code> unnecessarily.</strong><br>Moving equal values can destroy the algorithm’s stability. Use <code>&lt;</code>.</div></div>\r\n        <div class=\"mistake\"><span class=\"mistake-no\">6</span><div><strong>Forgetting the final insertion.</strong><br>After shifting, place the key with <code>array[j + 1] = key</code>.</div></div>\r\n      "
  },
  "summary": {
    "id": "summary",
    "title": "A test-ready summary",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Test summary</span>\r\n        <h2>A test-ready summary</h2>\r\n        <div class=\"test-summary\">\r\n          <p>Insertion sort is a stable, in-place and adaptive comparison-based sorting algorithm. It builds a sorted section from left to right. During each iteration, the next value is saved as the key, larger values in the sorted section are shifted to the right, and the key is inserted into the resulting gap. Its best-case time complexity is O(n) for an already sorted array, while its average and worst-case complexities are O(n²). It is suitable for small or nearly sorted arrays but inefficient for large, randomly ordered arrays.</p>\r\n        </div>\r\n      "
  },
  "practice": {
    "id": "practice",
    "title": "Practice",
    "body": "\r\n        <span class=\"section-no\">Sorting / Insertion sort · Practice</span>\r\n        <h2>Practice</h2>\r\n        <h3>Guided question</h3>\r\n        <p>Use insertion sort to arrange <code>[6, 3, 8, 4]</code>. Record the key, comparisons, shifts, and array after each iteration.</p>\r\n        <details>\r\n          <summary>Reveal the guided answer</summary>\r\n          <div class=\"answer\">\r\n            <p><strong>Insert 3:</strong> <code>3 &lt; 6</code>, so shift 6 → <code>[3, 6, 8, 4]</code>.</p>\r\n            <p><strong>Insert 8:</strong> <code>8 &lt; 6</code> is false, so nothing moves.</p>\r\n            <p><strong>Insert 4:</strong> shift 8, shift 6, then stop at 3 → <code>[3, 4, 6, 8]</code>.</p>\r\n            <p><strong>Totals:</strong> 5 comparisons and 3 shifts.</p>\r\n          </div>\r\n        </details>\r\n        <h3>Independent question</h3>\r\n        <p>Trace insertion sort on <code>[7, 2, 5, 1, 6]</code>.</p>\r\n        <ul class=\"checklist\">\r\n          <li>Write the key for every iteration.</li>\r\n          <li>Record every comparison.</li>\r\n          <li>Record every shift.</li>\r\n          <li>Write the resulting array after each insertion.</li>\r\n          <li>Calculate the totals.</li>\r\n        </ul>\r\n        <details><summary>Reveal the independent answer</summary><div class=\"answer\"><div class=\"table-scroll\"><table><thead><tr><th>Key</th><th>Comparisons</th><th>Shifts</th><th>Array after insertion</th></tr></thead><tbody><tr><td>2</td><td>1</td><td>1</td><td><code>[2, 7, 5, 1, 6]</code></td></tr><tr><td>5</td><td>2</td><td>1</td><td><code>[2, 5, 7, 1, 6]</code></td></tr><tr><td>1</td><td>3</td><td>3</td><td><code>[1, 2, 5, 7, 6]</code></td></tr><tr><td>6</td><td>2</td><td>1</td><td><code>[1, 2, 5, 6, 7]</code></td></tr><tr><td><strong>Total</strong></td><td><strong>8</strong></td><td><strong>6</strong></td><td>Sorted</td></tr></tbody></table></div><p>Key 1 crosses the entire sorted section (3 shifts) and reaches the left edge, so it makes no fourth comparison.</p></div></details>\r\n      "
  },
  "merge-array": {
    "id": "merge-array",
    "title": "The array we will sort",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · The array we will sort</span>\r\n        <h2>The array we will sort</h2>\r\n        <p class=\"lede\">Eight values this time, so the array splits evenly all the way down: <code>[63, 29, 72, 85, 18, 49, 3, 54]</code>.</p>\r\n        \r\n        <div class=\"paper-card\">\r\n          <div class=\"kicker\">Starting array: eight values</div>\r\n          <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Starting array 63, 29, 72, 85, 18, 49, 3, 54\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">63</span><span class=\"cell\" data-label=\"1\">29</span><span class=\"cell\" data-label=\"2\">72</span><span class=\"cell\" data-label=\"3\">85</span><span class=\"cell\" data-label=\"4\">18</span><span class=\"cell\" data-label=\"5\">49</span><span class=\"cell\" data-label=\"6\">3</span><span class=\"cell\" data-label=\"7\">54</span></div></div>\r\n          <figure class=\"bars-fig\"><div class=\"bars\" role=\"img\" aria-label=\"The same eight values as bars\"><div class=\"bar\" style=\"--p:0.741\"><i></i><b>63</b><small>0</small></div><div class=\"bar\" style=\"--p:0.341\"><i></i><b>29</b><small>1</small></div><div class=\"bar\" style=\"--p:0.847\"><i></i><b>72</b><small>2</small></div><div class=\"bar\" style=\"--p:1.000\"><i></i><b>85</b><small>3</small></div><div class=\"bar\" style=\"--p:0.212\"><i></i><b>18</b><small>4</small></div><div class=\"bar\" style=\"--p:0.576\"><i></i><b>49</b><small>5</small></div><div class=\"bar\" style=\"--p:0.035\"><i></i><b>3</b><small>6</small></div><div class=\"bar\" style=\"--p:0.635\"><i></i><b>54</b><small>7</small></div></div></figure>\r\n          <div class=\"kicker\">The result we want</div>\r\n          <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Sorted array\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">3</span><span class=\"cell sorted\" data-label=\"1\">18</span><span class=\"cell sorted\" data-label=\"2\">29</span><span class=\"cell sorted\" data-label=\"3\">49</span><span class=\"cell sorted\" data-label=\"4\">54</span><span class=\"cell sorted\" data-label=\"5\">63</span><span class=\"cell sorted\" data-label=\"6\">72</span><span class=\"cell sorted\" data-label=\"7\">85</span></div></div>\r\n        </div>\r\n        <p>For merge sort we use eight values, not five, and that is deliberate. Eight is 2 × 2 × 2, so the array can be cut exactly in half three times (8 → 4 → 2 → 1) and the picture of the whole algorithm is a perfectly balanced tree. Later examples use five and nine values, where the halves are uneven, so you will see that case too.</p>\r\n        <p>These are the values the lab uses, so the traces here match the Lab05 trace later in the guide.</p>\r\n    \r\n      "
  },
  "merge-definition": {
    "id": "merge-definition",
    "title": "The textbook definition",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · The textbook definition</span>\r\n        <h2>The textbook definition</h2>\r\n        \r\n        <div class=\"paper-card definition\">\r\n          <p><strong>Merge sort</strong> is a comparison-based, divide-and-conquer sorting algorithm. It splits the array into two halves, sorts each half by calling itself recursively, and then <em>merges</em> the two sorted halves into one sorted array. A sub-array of one value is already sorted, so it is the base case of the recursion. The work of actually putting values in order is done by the merge step on the way back up.</p>\r\n        </div>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Divide and conquer</strong>Solve a big problem by solving smaller copies of the same problem, then combining the answers.</div><div class=\"term\"><strong>Run</strong>A sorted stretch of the array. Single values are runs of length 1; the merge step builds longer runs.</div><div class=\"term\"><strong>Split point <code>mid</code></strong>The index where the range is cut: <code>mid = start + (end − start) / 2</code>. The left half is <code>start..mid</code> and the right half <code>mid + 1..end</code>.</div><div class=\"term\"><strong>Base case</strong>A range with one value (<code>start ≥ end</code>). It returns immediately, because one value is already sorted.</div><div class=\"term\"><strong>Merge</strong>Combine two sorted runs into one by repeatedly taking the smaller of the two front values.</div><div class=\"term\"><strong>Temporary arrays</strong>Copies of the two halves made during a merge, so values can be written back without overwriting unread ones.</div><div class=\"term\"><strong>Level</strong>One row of the recursion tree. Halving 8 values down to single values takes 3 splitting levels.</div></div>\r\n        <p>Everything interesting about merge sort comes from one fact: <strong>merging two sorted runs is cheap</strong>, because only the two front values ever need to be compared. The recursion exists only to create sorted runs for the merge to work on.</p>\r\n    \r\n      "
  },
  "merge-simple": {
    "id": "merge-simple",
    "title": "In plain language",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · In plain language</span>\r\n        <h2>In plain language</h2>\r\n        <p class=\"lede\">Merge sort turns “sort this pile” into “zip together two sorted piles” over and over.</p>\r\n        \r\n        <div class=\"paper-card\">\r\n          <p>Imagine two stacks of exam papers, each already sorted by mark from lowest to highest. You want one sorted stack. You do not need to look through the stacks: only the two papers on <em>top</em> matter. Whichever top paper has the lower mark goes onto the new stack, and then you look at the two tops again.</p>\r\n          <p>That is a <strong>merge</strong>. It is like a zip: two sorted lines go in, one sorted line comes out, and every paper is touched once.</p>\r\n          <p>Merge sort uses this trick on an unsorted pile: split the pile in half and keep splitting until each piece is a single paper. A single paper is a perfectly sorted stack of one. Now merge pairs of stacks, then pairs of those, until one stack is left.</p>\r\n        </div>\r\n        <p>Here is one merge in full: the sorted piles <code>[2, 9]</code> and <code>[4, 5, 8]</code>. Crossed-out cells have already been used; the labelled cell is the front of its pile.</p>\r\n        <div class=\"worked-visual\" aria-label=\"Merging [2, 9] and [4, 5, 8]\"><div class=\"worked-step\"><h4>Start: point at the front of each pile</h4><div class=\"kicker\">Left run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"i run, 0 values consumed\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 i\">2</span><span class=\"cell\" data-label=\"1\">9</span></div></div><div class=\"kicker\">Right run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"j run, 0 values consumed\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 j\">4</span><span class=\"cell\" data-label=\"1\">5</span><span class=\"cell\" data-label=\"2\">8</span></div></div><div class=\"kicker\">Output</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Output so far: []\"><div class=\"array\"><span class=\"cell empty\" data-label=\"0\">·</span><span class=\"cell empty\" data-label=\"1\">·</span><span class=\"cell empty\" data-label=\"2\">·</span><span class=\"cell empty\" data-label=\"3\">·</span><span class=\"cell empty\" data-label=\"4\">·</span></div></div></div><div class=\"worked-step\"><h4>After choice 1: took 2 from the left pile (2 <= 4 was true)</h4><div class=\"kicker\">Left run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"i run, 1 value consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">2</span><span class=\"cell bound\" data-label=\"1 i\">9</span></div></div><div class=\"kicker\">Right run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"j run, 0 values consumed\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 j\">4</span><span class=\"cell\" data-label=\"1\">5</span><span class=\"cell\" data-label=\"2\">8</span></div></div><div class=\"kicker\">Output</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Output so far: [2]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">2</span><span class=\"cell empty\" data-label=\"1\">·</span><span class=\"cell empty\" data-label=\"2\">·</span><span class=\"cell empty\" data-label=\"3\">·</span><span class=\"cell empty\" data-label=\"4\">·</span></div></div></div><div class=\"worked-step\"><h4>After choice 2: took 4 from the right pile (9 <= 4 was false)</h4><div class=\"kicker\">Left run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"i run, 1 value consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">2</span><span class=\"cell bound\" data-label=\"1 i\">9</span></div></div><div class=\"kicker\">Right run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"j run, 1 value consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">4</span><span class=\"cell bound\" data-label=\"1 j\">5</span><span class=\"cell\" data-label=\"2\">8</span></div></div><div class=\"kicker\">Output</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Output so far: [2, 4]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">2</span><span class=\"cell sorted\" data-label=\"1\">4</span><span class=\"cell empty\" data-label=\"2\">·</span><span class=\"cell empty\" data-label=\"3\">·</span><span class=\"cell empty\" data-label=\"4\">·</span></div></div></div><div class=\"worked-step\"><h4>After choice 3: took 5 from the right pile (9 <= 5 was false)</h4><div class=\"kicker\">Left run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"i run, 1 value consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">2</span><span class=\"cell bound\" data-label=\"1 i\">9</span></div></div><div class=\"kicker\">Right run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"j run, 2 values consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">4</span><span class=\"cell discarded\" data-label=\"1\">5</span><span class=\"cell bound\" data-label=\"2 j\">8</span></div></div><div class=\"kicker\">Output</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Output so far: [2, 4, 5]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">2</span><span class=\"cell sorted\" data-label=\"1\">4</span><span class=\"cell sorted\" data-label=\"2\">5</span><span class=\"cell empty\" data-label=\"3\">·</span><span class=\"cell empty\" data-label=\"4\">·</span></div></div></div><div class=\"worked-step\"><h4>After choice 4: took 8 from the right pile (9 <= 8 was false)</h4><div class=\"kicker\">Left run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"i run, 1 value consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">2</span><span class=\"cell bound\" data-label=\"1 i\">9</span></div></div><div class=\"kicker\">Right run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"j run, 3 values consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">4</span><span class=\"cell discarded\" data-label=\"1\">5</span><span class=\"cell discarded\" data-label=\"2\">8</span></div></div><div class=\"kicker\">Output</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Output so far: [2, 4, 5, 8]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">2</span><span class=\"cell sorted\" data-label=\"1\">4</span><span class=\"cell sorted\" data-label=\"2\">5</span><span class=\"cell sorted\" data-label=\"3\">8</span><span class=\"cell empty\" data-label=\"4\">·</span></div></div></div><div class=\"worked-step\"><h4>The right pile is empty, so the leftover 9 is copied across</h4><div class=\"kicker\">Left run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"i run, 1 value consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">2</span><span class=\"cell bound\" data-label=\"1 i\">9</span></div></div><div class=\"kicker\">Right run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"j run, 3 values consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">4</span><span class=\"cell discarded\" data-label=\"1\">5</span><span class=\"cell discarded\" data-label=\"2\">8</span></div></div><div class=\"kicker\">Output</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Output so far: [2, 4, 5, 8, 9]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">2</span><span class=\"cell sorted\" data-label=\"1\">4</span><span class=\"cell sorted\" data-label=\"2\">5</span><span class=\"cell sorted\" data-label=\"3\">8</span><span class=\"cell sorted\" data-label=\"4\">9</span></div></div></div></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Choice</th><th>Left front</th><th>Right front</th><th>Compare</th><th>Taken</th><th>Output so far</th></tr></thead><tbody><tr><td>1</td><td>2</td><td>4</td><td><code>2 <= 4</code> is true</td><td><strong>2</strong> (from left)</td><td><code>[2]</code></td></tr><tr><td>2</td><td>9</td><td>4</td><td><code>9 <= 4</code> is false</td><td><strong>4</strong> (from right)</td><td><code>[2, 4]</code></td></tr><tr><td>3</td><td>9</td><td>5</td><td><code>9 <= 5</code> is false</td><td><strong>5</strong> (from right)</td><td><code>[2, 4, 5]</code></td></tr><tr><td>4</td><td>9</td><td>8</td><td><code>9 <= 8</code> is false</td><td><strong>8</strong> (from right)</td><td><code>[2, 4, 5, 8]</code></td></tr></tbody></table></div>\r\n        <p>Only <strong>4 comparisons</strong> were needed for 5 values (never more than <code>n − 1</code>), and the last value, <code>9</code>, was copied without any comparison because the right pile had run out. Merging never looks at a value more than a couple of times: that is why it is cheap.</p>\r\n    \r\n      "
  },
  "merge-idea": {
    "id": "merge-idea",
    "title": "The main idea: divide, conquer, combine",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · The main idea: divide, conquer, combine</span>\r\n        <h2>The main idea: divide, conquer, combine</h2>\r\n        \r\n        <div class=\"flow-steps\"><div class=\"flow-step\"><b>1</b><div><strong>Divide:</strong> cut the range in half at <code>mid</code>.</div></div><div class=\"flow-step\"><b>2</b><div><strong>Conquer:</strong> sort the left half, then the right half, by calling merge sort on each. These calls do the same thing again on smaller ranges.</div></div><div class=\"flow-step\"><b>3</b><div><strong>Combine:</strong> merge the two sorted halves into one sorted range. This is the only step that moves values.</div></div></div>\r\n        <h3>Splitting goes down, merging comes back up</h3>\r\n        <p>Calling merge sort on the whole array makes two calls on halves, which make two calls each, until every call has a single value. Nothing is sorted on the way <em>down</em>; the array is only being cut up. Here is the cut-up for the eight values, with each box drawn as wide as the number of values it holds.</p>\r\n        <div class=\"rtree\" role=\"img\" aria-label=\"split tree\"><div class=\"rt-level\"><span class=\"rt-tag\">level 0</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:8\">63 29 72 85 18 49 3 54</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 1</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:4\">63 29 72 85</div><div class=\"rt-node split\" style=\"--n:4\">18 49 3 54</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 2</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:2\">63 29</div><div class=\"rt-node split\" style=\"--n:2\">72 85</div><div class=\"rt-node split\" style=\"--n:2\">18 49</div><div class=\"rt-node split\" style=\"--n:2\">3 54</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 3</span><div class=\"rt-row\"><div class=\"rt-node split leaf\" style=\"--n:1\">63</div><div class=\"rt-node split leaf\" style=\"--n:1\">29</div><div class=\"rt-node split leaf\" style=\"--n:1\">72</div><div class=\"rt-node split leaf\" style=\"--n:1\">85</div><div class=\"rt-node split leaf\" style=\"--n:1\">18</div><div class=\"rt-node split leaf\" style=\"--n:1\">49</div><div class=\"rt-node split leaf\" style=\"--n:1\">3</div><div class=\"rt-node split leaf\" style=\"--n:1\">54</div></div></div></div>\r\n        <p>Now the calls return. Each call, once both of its halves are sorted, merges them. Read the next picture from the <strong>bottom row upward</strong>: the bottom row (single values) is already sorted; each row above is made by merging pairs of boxes from the row below, until the top box is the whole sorted array.</p>\r\n        <div class=\"rtree\" role=\"img\" aria-label=\"merge tree\"><div class=\"rt-level\"><span class=\"rt-tag\">level 0</span><div class=\"rt-row\"><div class=\"rt-node merge\" style=\"--n:8\">3 18 29 49 54 63 72 85</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 1</span><div class=\"rt-row\"><div class=\"rt-node merge\" style=\"--n:4\">29 63 72 85</div><div class=\"rt-node merge\" style=\"--n:4\">3 18 49 54</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 2</span><div class=\"rt-row\"><div class=\"rt-node merge\" style=\"--n:2\">29 63</div><div class=\"rt-node merge\" style=\"--n:2\">72 85</div><div class=\"rt-node merge\" style=\"--n:2\">18 49</div><div class=\"rt-node merge\" style=\"--n:2\">3 54</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 3</span><div class=\"rt-row\"><div class=\"rt-node merge leaf\" style=\"--n:1\">63</div><div class=\"rt-node merge leaf\" style=\"--n:1\">29</div><div class=\"rt-node merge leaf\" style=\"--n:1\">72</div><div class=\"rt-node merge leaf\" style=\"--n:1\">85</div><div class=\"rt-node merge leaf\" style=\"--n:1\">18</div><div class=\"rt-node merge leaf\" style=\"--n:1\">49</div><div class=\"rt-node merge leaf\" style=\"--n:1\">3</div><div class=\"rt-node merge leaf\" style=\"--n:1\">54</div></div></div></div>\r\n        <h3>Why this is fast</h3>\r\n        <p>Look at any one row of the tree: all its boxes together hold the 8 values once, so merging a whole row costs about 8 steps. There are only 3 rows of merges, because halving 8 down to 1 takes 3 cuts. Total work ≈ 8 × 3 = 24 value-writes. For a million values there are only about 20 rows, so the work is about one million × 20, not one million × one million. That halving is the same trick binary search uses.</p>\r\n        <div class=\"callout\"><strong>The mental picture:</strong> the recursion is just a way of <em>organising</em> merges. The real sorting happens in the merge step, always on two runs that are already sorted.</div>\r\n    \r\n      "
  },
  "merge-movements": {
    "id": "merge-movements",
    "title": "Split, call, merge",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · Split, call, merge</span>\r\n        <h2>Split, call, merge</h2>\r\n        \r\n        <p class=\"lede\">Three different things happen in merge sort, and a trace mixes them up unless you keep them apart.</p>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Split</strong>Calculating <code>mid</code>. No values move; only a number is computed.</div><div class=\"term\"><strong>Call</strong>Recursing on a half. A call that waits for its two halves to finish is parked on the <em>call stack</em>.</div><div class=\"term\"><strong>Merge</strong>The only phase that moves values: they are copied from two temporary arrays back into <code>arr</code> in sorted order.</div><div class=\"term\"><strong>Comparison</strong>One question per output value while both runs still have values: <code>left[i] &lt;= right[j]</code>.</div></div>\r\n        <h3>Where exactly is the split?</h3>\r\n        <p>The left half is <code>start..mid</code> and the right half <code>mid + 1..end</code>, with <code>mid = start + (end − start) / 2</code> (integer division). When the number of values is odd, the left half gets the extra value:</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Range</th><th>Values</th><th>mid</th><th>Left half</th><th>Right half</th></tr></thead><tbody><tr><td><code>(0, 7)</code></td><td>8</td><td><code>0 + (7 − 0) / 2 = 3</code></td><td><code>0..3</code> (4 values)</td><td><code>4..7</code> (4 values)</td></tr><tr><td><code>(0, 3)</code></td><td>4</td><td><code>0 + (3 − 0) / 2 = 1</code></td><td><code>0..1</code> (2 values)</td><td><code>2..3</code> (2 values)</td></tr><tr><td><code>(4, 7)</code></td><td>4</td><td><code>4 + (7 − 4) / 2 = 5</code></td><td><code>4..5</code> (2 values)</td><td><code>6..7</code> (2 values)</td></tr><tr><td><code>(0, 4)</code></td><td>5</td><td><code>0 + (4 − 0) / 2 = 2</code></td><td><code>0..2</code> (3 values)</td><td><code>3..4</code> (2 values)</td></tr><tr><td><code>(5, 8)</code></td><td>4</td><td><code>5 + (8 − 5) / 2 = 6</code></td><td><code>5..6</code> (2 values)</td><td><code>7..8</code> (2 values)</td></tr></tbody></table></div>\r\n        <h3>What is waiting on the call stack?</h3>\r\n        <p>Merge sort calls itself, so Java keeps a stack of calls that have started but not finished. At the moment of the <em>first</em> merge on our eight values, three calls are alive:</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Position</th><th>Call</th><th>What it is doing</th></tr></thead><tbody><tr><td>top (running)</td><td><code>mergeSort(arr, 0, 1)</code></td><td>Both of its halves, <code>(0, 0)</code> and <code>(1, 1)</code>, have returned: it merges them now.</td></tr><tr><td>below</td><td><code>mergeSort(arr, 0, 3)</code></td><td>Waiting. Its left half <code>(0, 1)</code> is still running; the right half <code>(2, 3)</code> has not started.</td></tr><tr><td>bottom</td><td><code>mergeSort(arr, 0, 7)</code></td><td>Waiting. Its left half <code>(0, 3)</code> is still running; the right half <code>(4, 7)</code> has not started.</td></tr></tbody></table></div>\r\n        <p>The stack is never deeper than the number of levels (here 4), which is why merge sort's recursion cannot overflow the stack for any realistic array: <code>log₂ n</code> is small even for a billion values (about 30).</p>\r\n        <h3>The left half is always finished first</h3>\r\n        <p>Because the left call is written before the right call, the whole left side is sorted and merged before the right side is even cut up. This is why the merges happen in <em>depth-first</em> order (see the trace table earlier), and why a bottom-up version that goes level by level makes the same merges in a different order.</p>\r\n    \r\n      "
  },
  "merge-sort": {
    "id": "merge-sort",
    "title": "Divide first. Merge on the way back.",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort</span>\r\n        <h2 id=\"merge-concept\">Divide first. Merge on the way back.</h2>\r\n        <p class=\"lede\">Merge sort repeatedly divides an array into halves until every piece has one value. It then combines sorted pieces into larger sorted pieces.</p>\r\n        <div class=\"flow-steps\">\r\n          <div class=\"flow-step\"><b>1</b><div><strong>Base case:</strong> <code>start &gt;= end</code>. A section with one value is already sorted.</div></div>\r\n          <div class=\"flow-step\"><b>2</b><div><strong>Divide:</strong> calculate <code>mid</code>.</div></div>\r\n          <div class=\"flow-step\"><b>3</b><div><strong>Recur left:</strong> sort <code>start..mid</code>.</div></div>\r\n          <div class=\"flow-step\"><b>4</b><div><strong>Recur right:</strong> sort <code>mid+1..end</code>.</div></div>\r\n          <div class=\"flow-step\"><b>5</b><div><strong>Merge:</strong> combine both sorted halves.</div></div>\r\n        </div>\r\n        <h3 id=\"merge-illustration\">Illustration · split the example array</h3>\r\n        <div class=\"stack-flow\">\r\n          <span class=\"stack-frame\">63 29 72 85 18 49 3 54</span><span class=\"stack-arrow\">→</span>\r\n          <span class=\"stack-frame\">63 29 72 85</span><span class=\"stack-frame\">18 49 3 54</span>\r\n        </div>\r\n        <div class=\"stack-flow\">\r\n          <span class=\"stack-frame\">63 29</span><span class=\"stack-frame\">72 85</span><span class=\"stack-frame\">18 49</span><span class=\"stack-frame\">3 54</span>\r\n        </div>\r\n        <div class=\"stack-flow\">\r\n          <span class=\"stack-frame\">63</span><span class=\"stack-frame\">29</span><span class=\"stack-frame\">72</span><span class=\"stack-frame\">85</span><span class=\"stack-frame\">18</span><span class=\"stack-frame\">49</span><span class=\"stack-frame\">3</span><span class=\"stack-frame\">54</span>\r\n        </div>\r\n        <h4>Merge phase · the same tree level by level (the recursion itself merges depth-first: see the trace table below)</h4><div class=\"stack-flow\"><span class=\"stack-frame\">29 63</span><span class=\"stack-frame\">72 85</span><span class=\"stack-frame\">18 49</span><span class=\"stack-frame\">3 54</span><span class=\"stack-arrow\">← four merges of single values</span></div><div class=\"stack-flow\"><span class=\"stack-frame\">29 63 72 85</span><span class=\"stack-frame\">3 18 49 54</span><span class=\"stack-arrow\">← two merges of pairs</span></div><div class=\"stack-flow\"><span class=\"stack-frame\">3 18 29 49 54 63 72 85</span><span class=\"stack-arrow\">← one final merge</span></div>\r\n        <h3 id=\"merge-calltree\">Call tree · <code>mergeSort(arr, 0, 7)</code></h3><p>The calls run top to bottom in this order. Each call goes left all the way down before it goes right, and its <code>merge</code> happens only after both of its recursive calls have returned. Indentation shows the depth.</p><div class=\"table-scroll\"><table><thead><tr><th>Call</th><th>Call made</th><th>mid</th><th>What happens</th></tr></thead><tbody><tr><td>1</td><td><code>mergeSort(arr, 0, 7)</code></td><td>3</td><td>Call left <code>(0, 3)</code>, then right <code>(4, 7)</code>, then merge</td></tr><tr><td>2</td><td>&nbsp;&nbsp;<code>mergeSort(arr, 0, 3)</code></td><td>1</td><td>Call left <code>(0, 1)</code>, then right <code>(2, 3)</code>, then merge</td></tr><tr><td>3</td><td>&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 0, 1)</code></td><td>0</td><td>Call left <code>(0, 0)</code>, then right <code>(1, 1)</code>, then merge</td></tr><tr><td>4</td><td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 0, 0)</code></td><td>—</td><td><code>0 &gt;= 0</code>: one value, return</td></tr><tr><td>5</td><td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 1, 1)</code></td><td>—</td><td><code>1 &gt;= 1</code>: one value, return</td></tr><tr><td>6</td><td>&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 2, 3)</code></td><td>2</td><td>Call left <code>(2, 2)</code>, then right <code>(3, 3)</code>, then merge</td></tr><tr><td>7</td><td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 2, 2)</code></td><td>—</td><td><code>2 &gt;= 2</code>: one value, return</td></tr><tr><td>8</td><td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 3, 3)</code></td><td>—</td><td><code>3 &gt;= 3</code>: one value, return</td></tr><tr><td>9</td><td>&nbsp;&nbsp;<code>mergeSort(arr, 4, 7)</code></td><td>5</td><td>Call left <code>(4, 5)</code>, then right <code>(6, 7)</code>, then merge</td></tr><tr><td>10</td><td>&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 4, 5)</code></td><td>4</td><td>Call left <code>(4, 4)</code>, then right <code>(5, 5)</code>, then merge</td></tr><tr><td>11</td><td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 4, 4)</code></td><td>—</td><td><code>4 &gt;= 4</code>: one value, return</td></tr><tr><td>12</td><td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 5, 5)</code></td><td>—</td><td><code>5 &gt;= 5</code>: one value, return</td></tr><tr><td>13</td><td>&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 6, 7)</code></td><td>6</td><td>Call left <code>(6, 6)</code>, then right <code>(7, 7)</code>, then merge</td></tr><tr><td>14</td><td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 6, 6)</code></td><td>—</td><td><code>6 &gt;= 6</code>: one value, return</td></tr><tr><td>15</td><td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 7, 7)</code></td><td>—</td><td><code>7 &gt;= 7</code>: one value, return</td></tr></tbody></table></div><h3 id=\"merge-trace\">Trace table · merge on return</h3><p>Each merge fires as the calls above return, so the order is depth-first, <em>not</em> level by level: the left half is fully sorted before the right half is even split.</p><div class=\"table-scroll\"><table><thead><tr><th>Return step</th><th>Merge call</th><th>Returns from call #</th><th>Left sorted half</th><th>Right sorted half</th><th>Merged result</th></tr></thead><tbody><tr><td>1</td><td><code>merge(arr, 0, 0, 1)</code></td><td>call 3</td><td><code>[63]</code></td><td><code>[29]</code></td><td><code>[29, 63]</code></td></tr><tr><td>2</td><td><code>merge(arr, 2, 2, 3)</code></td><td>call 6</td><td><code>[72]</code></td><td><code>[85]</code></td><td><code>[72, 85]</code></td></tr><tr><td>3</td><td><code>merge(arr, 0, 1, 3)</code></td><td>call 2</td><td><code>[29, 63]</code></td><td><code>[72, 85]</code></td><td><code>[29, 63, 72, 85]</code></td></tr><tr><td>4</td><td><code>merge(arr, 4, 4, 5)</code></td><td>call 10</td><td><code>[18]</code></td><td><code>[49]</code></td><td><code>[18, 49]</code></td></tr><tr><td>5</td><td><code>merge(arr, 6, 6, 7)</code></td><td>call 13</td><td><code>[3]</code></td><td><code>[54]</code></td><td><code>[3, 54]</code></td></tr><tr><td>6</td><td><code>merge(arr, 4, 5, 7)</code></td><td>call 9</td><td><code>[18, 49]</code></td><td><code>[3, 54]</code></td><td><code>[3, 18, 49, 54]</code></td></tr><tr><td>7</td><td><code>merge(arr, 0, 3, 7)</code></td><td>call 1</td><td><code>[29, 63, 72, 85]</code></td><td><code>[3, 18, 49, 54]</code></td><td><code>[3, 18, 29, 49, 54, 63, 72, 85]</code></td></tr></tbody></table></div>\r\n\r\n        <h3 id=\"merge-implementation\">Implementation</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Recursive merge sort</span></div><pre><code><span class=\"kw\">public static void</span> mergeSort(<span class=\"ty\">int</span>[] arr, <span class=\"ty\">int</span> start, <span class=\"ty\">int</span> end) {\r\n    <span class=\"cm\">// A zero- or one-value range is already sorted.</span>\r\n    <span class=\"kw\">if</span> (start &lt; end) {\r\n        <span class=\"cm\">// Split without risking integer overflow.</span>\r\n        <span class=\"ty\">int</span> mid = start + (end - start) / 2;\r\n        <span class=\"cm\">// Sort both halves before combining them.</span>\r\n        mergeSort(arr, start, mid);\r\n        mergeSort(arr, mid + 1, end);\r\n        merge(arr, start, mid, end);\r\n    }\r\n}</code></pre></div>\r\n        <details open><summary>The merge method used by Lab05</summary><div class=\"answer\"><pre><code><span class=\"kw\">public static void</span> merge(<span class=\"ty\">int</span>[] arr, <span class=\"ty\">int</span> s, <span class=\"ty\">int</span> m, <span class=\"ty\">int</span> e) {\r\n    <span class=\"cm\">// Requires: import java.util.Arrays;</span>\r\n    <span class=\"cm\">// Copy both already-sorted halves into temporary arrays.</span>\r\n    <span class=\"ty\">int</span>[] left = Arrays.copyOfRange(arr, s, m + 1);\r\n    <span class=\"ty\">int</span>[] right = Arrays.copyOfRange(arr, m + 1, e + 1);\r\n    <span class=\"ty\">int</span> i = 0, j = 0, cur = s;\r\n\r\n    <span class=\"cm\">// Copy the smaller front value back into the original array.</span>\r\n    <span class=\"kw\">while</span> (i &lt; left.length &amp;&amp; j &lt; right.length)\r\n        arr[cur++] = left[i] &lt;= right[j] ? left[i++] : right[j++];\r\n    <span class=\"cm\">// Exactly one of these leftover loops will copy values.</span>\r\n    <span class=\"kw\">while</span> (i &lt; left.length) arr[cur++] = left[i++];\r\n    <span class=\"kw\">while</span> (j &lt; right.length) arr[cur++] = right[j++];\r\n}</code></pre></div></details>\r\n        <details><summary>Iterative bottom-up merge sort</summary><div class=\"answer\"><pre><code><span class=\"kw\">public static void</span> mergeSortIterative(<span class=\"ty\">int</span>[] arr) {\r\n    <span class=\"cm\">// width is the current size of each sorted run.</span>\r\n    <span class=\"kw\">for</span> (<span class=\"ty\">int</span> width = 1; width &lt; arr.length; width *= 2) {\r\n        <span class=\"cm\">// Merge neighbouring runs of size width.</span>\r\n        <span class=\"kw\">for</span> (<span class=\"ty\">int</span> start = 0; start &lt; arr.length - 1; start += 2 * width) {\r\n            <span class=\"ty\">int</span> mid = Math.min(start + width - 1, arr.length - 1);\r\n            <span class=\"ty\">int</span> end = Math.min(start + 2 * width - 1, arr.length - 1);\r\n            <span class=\"kw\">if</span> (mid &lt; end) merge(arr, start, mid, end);\r\n        }\r\n    }\r\n}</code></pre><p><strong>Bottom-up trace</strong> on <code>[63, 29, 72, 85, 18, 49, 3, 54]</code>. The outer loop doubles <code>width</code>; the inner loop merges neighbouring runs of that width.</p><div class=\"table-scroll\"><table><thead><tr><th>width</th><th>Runs merged</th><th>Array after this pass</th></tr></thead><tbody><tr><td>1</td><td><code>[63]+[29]</code>, <code>[72]+[85]</code>, <code>[18]+[49]</code>, <code>[3]+[54]</code></td><td><code>[29, 63, 72, 85, 18, 49, 3, 54]</code></td></tr><tr><td>2</td><td><code>[29,63]+[72,85]</code>, <code>[18,49]+[3,54]</code></td><td><code>[29, 63, 72, 85, 3, 18, 49, 54]</code></td></tr><tr><td>4</td><td><code>[29,63,72,85]+[3,18,49,54]</code></td><td><code>[3, 18, 29, 49, 54, 63, 72, 85]</code></td></tr></tbody></table></div><p>These are the same seven merges as the recursive trace table, performed in a different order: bottom-up goes level by level, while the recursive version finishes the whole left half before touching the right. When <code>n</code> is not a power of two, <code>Math.min</code> clamps the last run, and the <code>mid &lt; end</code> test skips a run that has no partner until a wider pass reaches it.</p></div></details>\r\n\r\n        <div class=\"audit-grid\">\r\n          <div class=\"from-scratch\"><strong>Write it from scratch</strong><ol><li>Stop on a one-value range.</li><li>Calculate the midpoint.</li><li>Sort the left half.</li><li>Sort the right half.</li><li>Merge both sorted halves.</li></ol></div>\r\n          <div class=\"direction-card\"><strong>Ascending ↔ descending</strong><p>Ascending merge chooses the left value when <code>left[i] &lt;= right[j]</code>. Descending chooses it when <code>left[i] &gt;= right[j]</code>.</p><p><strong>Same fronts, opposite choice:</strong> with left front <code>29</code> and right front <code>3</code>, ascending takes <code>3</code>; descending takes <code>29</code> because <code>29 &gt;= 3</code>.</p></div>\r\n          <div class=\"debug-list\"><strong>Debug checklist</strong><ul><li>Include <code>m + 1</code> in the left copy’s exclusive end.</li><li>Recur on <code>mid + 1</code> for the right half.</li><li>Copy leftovers after the paired comparison loop.</li></ul></div>\r\n        </div>\r\n\r\n        <h3 id=\"merge-example\">Worked example · final merge</h3><p>Merge <code>[29, 63, 72, 85]</code> and <code>[3, 18, 49, 54]</code> into one sorted run. <code>i</code> and <code>j</code> point at the front of each run; the lower-front value moves to the output, and its pointer advances. Cells crossed out have already been copied.</p><div class=\"worked-visual\" aria-label=\"Final merge of two sorted runs, shown at four moments\"><div class=\"worked-step\"><h4>Start · both runs are sorted; i and j mark the front of each run</h4><div class=\"kicker\">Left run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"i run, 0 values consumed\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 i\">29</span><span class=\"cell\" data-label=\"1\">63</span><span class=\"cell\" data-label=\"2\">72</span><span class=\"cell\" data-label=\"3\">85</span></div></div><div class=\"kicker\">Right run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"j run, 0 values consumed\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 j\">3</span><span class=\"cell\" data-label=\"1\">18</span><span class=\"cell\" data-label=\"2\">49</span><span class=\"cell\" data-label=\"3\">54</span></div></div><div class=\"kicker\">Output</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Output so far: []\"><div class=\"array\"><span class=\"cell empty\" data-label=\"0\">·</span><span class=\"cell empty\" data-label=\"1\">·</span><span class=\"cell empty\" data-label=\"2\">·</span><span class=\"cell empty\" data-label=\"3\">·</span><span class=\"cell empty\" data-label=\"4\">·</span><span class=\"cell empty\" data-label=\"5\">·</span><span class=\"cell empty\" data-label=\"6\">·</span><span class=\"cell empty\" data-label=\"7\">·</span></div></div></div><div class=\"worked-step\"><h4>After 2 choices · i = 0, j = 2 (3 and 18 came from the right run)</h4><div class=\"kicker\">Left run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"i run, 0 values consumed\"><div class=\"array\"><span class=\"cell bound\" data-label=\"0 i\">29</span><span class=\"cell\" data-label=\"1\">63</span><span class=\"cell\" data-label=\"2\">72</span><span class=\"cell\" data-label=\"3\">85</span></div></div><div class=\"kicker\">Right run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"j run, 2 values consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">3</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell bound\" data-label=\"2 j\">49</span><span class=\"cell\" data-label=\"3\">54</span></div></div><div class=\"kicker\">Output</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Output so far: [3, 18]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">3</span><span class=\"cell sorted\" data-label=\"1\">18</span><span class=\"cell empty\" data-label=\"2\">·</span><span class=\"cell empty\" data-label=\"3\">·</span><span class=\"cell empty\" data-label=\"4\">·</span><span class=\"cell empty\" data-label=\"5\">·</span><span class=\"cell empty\" data-label=\"6\">·</span><span class=\"cell empty\" data-label=\"7\">·</span></div></div></div><div class=\"worked-step\"><h4>After 5 choices · the right run is exhausted (j = 4)</h4><div class=\"kicker\">Left run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"i run, 1 value consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">29</span><span class=\"cell bound\" data-label=\"1 i\">63</span><span class=\"cell\" data-label=\"2\">72</span><span class=\"cell\" data-label=\"3\">85</span></div></div><div class=\"kicker\">Right run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"j run, 4 values consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">3</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell discarded\" data-label=\"2\">49</span><span class=\"cell discarded\" data-label=\"3\">54</span></div></div><div class=\"kicker\">Output</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Output so far: [3, 18, 29, 49, 54]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">3</span><span class=\"cell sorted\" data-label=\"1\">18</span><span class=\"cell sorted\" data-label=\"2\">29</span><span class=\"cell sorted\" data-label=\"3\">49</span><span class=\"cell sorted\" data-label=\"4\">54</span><span class=\"cell empty\" data-label=\"5\">·</span><span class=\"cell empty\" data-label=\"6\">·</span><span class=\"cell empty\" data-label=\"7\">·</span></div></div></div><div class=\"worked-step\"><h4>Leftovers copied · 63, 72, 85 move across unchanged</h4><div class=\"kicker\">Left run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"i run, 4 values consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">29</span><span class=\"cell discarded\" data-label=\"1\">63</span><span class=\"cell discarded\" data-label=\"2\">72</span><span class=\"cell discarded\" data-label=\"3\">85</span></div></div><div class=\"kicker\">Right run</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"j run, 4 values consumed\"><div class=\"array\"><span class=\"cell discarded\" data-label=\"0\">3</span><span class=\"cell discarded\" data-label=\"1\">18</span><span class=\"cell discarded\" data-label=\"2\">49</span><span class=\"cell discarded\" data-label=\"3\">54</span></div></div><div class=\"kicker\">Output</div><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Output so far: [3, 18, 29, 49, 54, 63, 72, 85]\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">3</span><span class=\"cell sorted\" data-label=\"1\">18</span><span class=\"cell sorted\" data-label=\"2\">29</span><span class=\"cell sorted\" data-label=\"3\">49</span><span class=\"cell sorted\" data-label=\"4\">54</span><span class=\"cell sorted\" data-label=\"5\">63</span><span class=\"cell sorted\" data-label=\"6\">72</span><span class=\"cell sorted\" data-label=\"7\">85</span></div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>Output index</th><th>i</th><th>j</th><th>left[i]</th><th>right[j]</th><th>Chosen</th><th>Reason</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>0</td><td>29</td><td>3</td><td><strong>3</strong></td><td><code>3 &lt; 29</code></td></tr><tr><td>1</td><td>0</td><td>1</td><td>29</td><td>18</td><td><strong>18</strong></td><td><code>18 &lt; 29</code></td></tr><tr><td>2</td><td>0</td><td>2</td><td>29</td><td>49</td><td><strong>29</strong></td><td><code>29 &lt;= 49</code></td></tr><tr><td>3</td><td>1</td><td>2</td><td>63</td><td>49</td><td><strong>49</strong></td><td><code>49 &lt; 63</code></td></tr><tr><td>4</td><td>1</td><td>3</td><td>63</td><td>54</td><td><strong>54</strong></td><td><code>54 &lt; 63</code></td></tr><tr><td>5..7</td><td>1..3</td><td>4</td><td>63, 72, 85</td><td>empty</td><td>63, 72, 85</td><td>Right run is empty; copy the leftovers</td></tr></tbody></table></div><div class=\"result-line\">Result: <code>[3, 18, 29, 49, 54, 63, 72, 85]</code> after <code>5</code> comparisons and <code>3</code> leftover copies. Eight values were written to the output.</div>\r\n        <div class=\"callout\"><strong>Why <code>O(n log n)</code>?</strong> There are about <code>log₂n</code> levels of halving, and merging touches all <code>n</code> values at every level.</div>\r\n        <p><strong>Counting it for the 8-value array.</strong> Every level re-merges all 8 values, and halving 8 values down to single values takes 3 levels.</p><div class=\"table-scroll\"><table><thead><tr><th>Level (bottom to top)</th><th>Merges at this level</th><th>Run sizes merged</th><th>Values written</th></tr></thead><tbody><tr><td>1</td><td>4</td><td>1 + 1</td><td>8</td></tr><tr><td>2</td><td>2</td><td>2 + 2</td><td>8</td></tr><tr><td>3</td><td>1</td><td>4 + 4</td><td>8</td></tr><tr><td><strong>Total</strong></td><td>—</td><td>—</td><td><strong>24 = 8 × log₂ 8</strong></td></tr></tbody></table></div><p class=\"fine-print\">This particular run made only 14 comparisons because leftovers are copied without comparing. The growth rate is still n log₂ n.</p>\r\n        <div class=\"properties\"><div class=\"property\"><small>Best</small><b>O(n log n)</b></div><div class=\"property\"><small>Average</small><b>O(n log n)</b></div><div class=\"property\"><small>Worst</small><b>O(n log n)</b></div><div class=\"property\"><small>Stable</small><b>Yes</b></div><div class=\"property\"><small>In-place</small><b>No*</b></div><div class=\"property\"><small>Adaptive</small><b>No</b></div><div class=\"property\"><small>Auxiliary space</small><b>O(n)</b></div><div class=\"property\"><small>Call depth</small><b>O(log n)</b></div></div>\r\n\r\n        <p class=\"fine-print\">* Merge sort needs temporary copies of the halves, so it uses <code>O(n)</code> auxiliary space and is not in-place. In-place merge variants exist but are far more complicated and are outside this guide.</p>\r\n\r\n        <h3 id=\"merge-questions\">Questions</h3>\r\n        <details><summary>What is the base case?</summary><div class=\"answer\"><code>start &gt;= end</code>. A range containing zero or one item is already sorted.</div></details>\r\n        <details><summary>Why does merge sort need extra memory?</summary><div class=\"answer\">The merge step temporarily copies the left and right halves so their smallest remaining values can be compared safely.</div></details>\r\n        <div class=\"method-summary\"><strong>Merge sort in one sentence</strong><p>Divide the range into one-value pieces, then merge sorted halves while choosing the smaller front value.</p></div>\r\n      "
  },
  "merge-descending": {
    "id": "merge-descending",
    "title": "Descending order",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · Descending order</span>\r\n        <h2>Descending order</h2>\r\n        \r\n        <p>To sort largest to smallest, change the comparison that decides which front value is taken: take the <strong>left</strong> value when it is <em>greater than or equal to</em> the right one.</p>\r\n        <div class=\"two-col\">\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>Ascending</span></div><pre><code>arr[cur++] = left[i] &lt;= right[j]\r\n        ? left[i++]\r\n        : right[j++];</code></pre></div>\r\n          <div class=\"code-panel\"><div class=\"code-head\"><span>Descending</span></div><pre><code>arr[cur++] = left[i] &gt;= right[j]\r\n        ? left[i++]\r\n        : right[j++];</code></pre></div>\r\n        </div>\r\n        <p>The splitting, the recursion, the base case and the leftovers loops do not change. Only the merge direction does, and note that it is still <code>=</code> that makes ties take the left value, which keeps the sort stable in both directions.</p>\r\n        <h3>The final merge, both ways</h3>\r\n        <p>Ascending merges <code>[29, 63, 72, 85]</code> and <code>[3, 18, 49, 54]</code> into <code>[3, 18, 29, 49, 54, 63, 72, 85]</code>. Descending first sorts each half the other way, then merges <code>[85, 72, 63, 29]</code> and <code>[54, 49, 18, 3]</code> into <code>[85, 72, 63, 54, 49, 29, 18, 3]</code>.</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th></th><th>Ascending</th><th>Descending</th></tr></thead><tbody><tr><td>Result</td><td><code>[3, 18, 29, 49, 54, 63, 72, 85]</code></td><td><code>[85, 72, 63, 54, 49, 29, 18, 3]</code></td></tr><tr><td>Calls / merges</td><td>15 / 7</td><td>15 / 7</td></tr><tr><td>Comparisons</td><td>14</td><td>15</td></tr><tr><td>Values written</td><td>24</td><td>24</td></tr></tbody></table></div>\r\n        <p>The structure of the work is identical; the comparison count can differ slightly because it depends on how the runs interleave.</p>\r\n    \r\n      "
  },
  "merge-examples": {
    "id": "merge-examples",
    "title": "Worked examples",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · Worked examples</span>\r\n        <h2>Worked examples</h2>\r\n        <p class=\"lede\">Six arrays: the smallest case, an odd length, sorted input, reversed input, duplicates and the nine values from Test 1.</p>\r\n        <article class=\"example-card\"><h3>Two values · <code>[5, 2]</code></h3><p>The smallest interesting case: one split, two base cases, one merge.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [5, 2]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">5</span><span class=\"cell\" data-label=\"1\">2</span></div></div><p><strong>How the array is split</strong> (box width is proportional to size):</p><div class=\"rtree\" role=\"img\" aria-label=\"split tree\"><div class=\"rt-level\"><span class=\"rt-tag\">level 0</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:2\">5 2</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 1</span><div class=\"rt-row\"><div class=\"rt-node split leaf\" style=\"--n:1\">5</div><div class=\"rt-node split leaf\" style=\"--n:1\">2</div></div></div></div><p><strong>Merges, in the order they happen</strong> (3 calls, 1 merges):</p><div class=\"table-scroll\"><table><thead><tr><th>#</th><th>Merge call</th><th>Left run</th><th>Right run</th><th>Merged result</th><th>Comparisons</th></tr></thead><tbody><tr><td>1</td><td><code>merge(arr, 0, 0, 1)</code></td><td><code>[5]</code></td><td><code>[2]</code></td><td><code>[2, 5]</code></td><td>1</td></tr><tr><td><strong>Total</strong></td><td><strong>1 merges</strong></td><td></td><td></td><td><strong>[2, 5]</strong></td><td><strong>1</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>3</code> calls and <code>1</code> merge. The two singles are compared once: <code>5 &lt;= 2</code> is false, so the <code>2</code> goes first.</div></article><article class=\"example-card\"><h3>An odd number of values · <code>[5, 2, 9, 1, 7]</code></h3><p>Five values cannot be halved evenly: the left half gets three and the right half two, and the left three split again as 2 + 1.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [5, 2, 9, 1, 7]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">5</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">9</span><span class=\"cell\" data-label=\"3\">1</span><span class=\"cell\" data-label=\"4\">7</span></div></div><p><strong>How the array is split</strong> (box width is proportional to size):</p><div class=\"rtree\" role=\"img\" aria-label=\"split tree\"><div class=\"rt-level\"><span class=\"rt-tag\">level 0</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:5\">5 2 9 1 7</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 1</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:3\">5 2 9</div><div class=\"rt-node split\" style=\"--n:2\">1 7</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 2</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:2\">5 2</div><div class=\"rt-node split leaf\" style=\"--n:1\">9</div><div class=\"rt-node split leaf\" style=\"--n:1\">1</div><div class=\"rt-node split leaf\" style=\"--n:1\">7</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 3</span><div class=\"rt-row\"><div class=\"rt-node split leaf\" style=\"--n:1\">5</div><div class=\"rt-node split leaf\" style=\"--n:1\">2</div><div class=\"rt-node split leaf\" style=\"--n:1\">9</div><div class=\"rt-node split leaf\" style=\"--n:1\">1</div><div class=\"rt-node split leaf\" style=\"--n:1\">7</div></div></div></div><p><strong>Merges, in the order they happen</strong> (9 calls, 4 merges):</p><div class=\"table-scroll\"><table><thead><tr><th>#</th><th>Merge call</th><th>Left run</th><th>Right run</th><th>Merged result</th><th>Comparisons</th></tr></thead><tbody><tr><td>1</td><td><code>merge(arr, 0, 0, 1)</code></td><td><code>[5]</code></td><td><code>[2]</code></td><td><code>[2, 5]</code></td><td>1</td></tr><tr><td>2</td><td><code>merge(arr, 0, 1, 2)</code></td><td><code>[2, 5]</code></td><td><code>[9]</code></td><td><code>[2, 5, 9]</code></td><td>2</td></tr><tr><td>3</td><td><code>merge(arr, 3, 3, 4)</code></td><td><code>[1]</code></td><td><code>[7]</code></td><td><code>[1, 7]</code></td><td>1</td></tr><tr><td>4</td><td><code>merge(arr, 0, 2, 4)</code></td><td><code>[2, 5, 9]</code></td><td><code>[1, 7]</code></td><td><code>[1, 2, 5, 7, 9]</code></td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>4 merges</strong></td><td></td><td></td><td><strong>[1, 2, 5, 7, 9]</strong></td><td><strong>8</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>9</code> calls, <code>4</code> merges, <code>8</code> comparisons. Uneven halves are normal and the algorithm needs no special case for them.</div></article><article class=\"example-card\"><h3>Already sorted · <code>[1, 2, 3, 4, 5, 6, 7, 8]</code></h3><p>No disorder at all: does merge sort notice?</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [1, 2, 3, 4, 5, 6, 7, 8]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">1</span><span class=\"cell\" data-label=\"1\">2</span><span class=\"cell\" data-label=\"2\">3</span><span class=\"cell\" data-label=\"3\">4</span><span class=\"cell\" data-label=\"4\">5</span><span class=\"cell\" data-label=\"5\">6</span><span class=\"cell\" data-label=\"6\">7</span><span class=\"cell\" data-label=\"7\">8</span></div></div><p><strong>How the array is split</strong> (box width is proportional to size):</p><div class=\"rtree\" role=\"img\" aria-label=\"split tree\"><div class=\"rt-level\"><span class=\"rt-tag\">level 0</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:8\">1 2 3 4 5 6 7 8</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 1</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:4\">1 2 3 4</div><div class=\"rt-node split\" style=\"--n:4\">5 6 7 8</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 2</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:2\">1 2</div><div class=\"rt-node split\" style=\"--n:2\">3 4</div><div class=\"rt-node split\" style=\"--n:2\">5 6</div><div class=\"rt-node split\" style=\"--n:2\">7 8</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 3</span><div class=\"rt-row\"><div class=\"rt-node split leaf\" style=\"--n:1\">1</div><div class=\"rt-node split leaf\" style=\"--n:1\">2</div><div class=\"rt-node split leaf\" style=\"--n:1\">3</div><div class=\"rt-node split leaf\" style=\"--n:1\">4</div><div class=\"rt-node split leaf\" style=\"--n:1\">5</div><div class=\"rt-node split leaf\" style=\"--n:1\">6</div><div class=\"rt-node split leaf\" style=\"--n:1\">7</div><div class=\"rt-node split leaf\" style=\"--n:1\">8</div></div></div></div><p><strong>Merges, in the order they happen</strong> (15 calls, 7 merges):</p><div class=\"table-scroll\"><table><thead><tr><th>#</th><th>Merge call</th><th>Left run</th><th>Right run</th><th>Merged result</th><th>Comparisons</th></tr></thead><tbody><tr><td>1</td><td><code>merge(arr, 0, 0, 1)</code></td><td><code>[1]</code></td><td><code>[2]</code></td><td><code>[1, 2]</code></td><td>1</td></tr><tr><td>2</td><td><code>merge(arr, 2, 2, 3)</code></td><td><code>[3]</code></td><td><code>[4]</code></td><td><code>[3, 4]</code></td><td>1</td></tr><tr><td>3</td><td><code>merge(arr, 0, 1, 3)</code></td><td><code>[1, 2]</code></td><td><code>[3, 4]</code></td><td><code>[1, 2, 3, 4]</code></td><td>2</td></tr><tr><td>4</td><td><code>merge(arr, 4, 4, 5)</code></td><td><code>[5]</code></td><td><code>[6]</code></td><td><code>[5, 6]</code></td><td>1</td></tr><tr><td>5</td><td><code>merge(arr, 6, 6, 7)</code></td><td><code>[7]</code></td><td><code>[8]</code></td><td><code>[7, 8]</code></td><td>1</td></tr><tr><td>6</td><td><code>merge(arr, 4, 5, 7)</code></td><td><code>[5, 6]</code></td><td><code>[7, 8]</code></td><td><code>[5, 6, 7, 8]</code></td><td>2</td></tr><tr><td>7</td><td><code>merge(arr, 0, 3, 7)</code></td><td><code>[1, 2, 3, 4]</code></td><td><code>[5, 6, 7, 8]</code></td><td><code>[1, 2, 3, 4, 5, 6, 7, 8]</code></td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>7 merges</strong></td><td></td><td></td><td><strong>[1, 2, 3, 4, 5, 6, 7, 8]</strong></td><td><strong>12</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>12</code> comparisons, compared with <code>14</code> for the unsorted example. A little cheaper (a run empties early), but the algorithm still makes every call and every merge. It is not adaptive.</div></article><article class=\"example-card\"><h3>Reverse order · <code>[8, 7, 6, 5, 4, 3, 2, 1]</code></h3><p>The input that ruins bubble and insertion sort.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [8, 7, 6, 5, 4, 3, 2, 1]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">8</span><span class=\"cell\" data-label=\"1\">7</span><span class=\"cell\" data-label=\"2\">6</span><span class=\"cell\" data-label=\"3\">5</span><span class=\"cell\" data-label=\"4\">4</span><span class=\"cell\" data-label=\"5\">3</span><span class=\"cell\" data-label=\"6\">2</span><span class=\"cell\" data-label=\"7\">1</span></div></div><p><strong>How the array is split</strong> (box width is proportional to size):</p><div class=\"rtree\" role=\"img\" aria-label=\"split tree\"><div class=\"rt-level\"><span class=\"rt-tag\">level 0</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:8\">8 7 6 5 4 3 2 1</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 1</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:4\">8 7 6 5</div><div class=\"rt-node split\" style=\"--n:4\">4 3 2 1</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 2</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:2\">8 7</div><div class=\"rt-node split\" style=\"--n:2\">6 5</div><div class=\"rt-node split\" style=\"--n:2\">4 3</div><div class=\"rt-node split\" style=\"--n:2\">2 1</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 3</span><div class=\"rt-row\"><div class=\"rt-node split leaf\" style=\"--n:1\">8</div><div class=\"rt-node split leaf\" style=\"--n:1\">7</div><div class=\"rt-node split leaf\" style=\"--n:1\">6</div><div class=\"rt-node split leaf\" style=\"--n:1\">5</div><div class=\"rt-node split leaf\" style=\"--n:1\">4</div><div class=\"rt-node split leaf\" style=\"--n:1\">3</div><div class=\"rt-node split leaf\" style=\"--n:1\">2</div><div class=\"rt-node split leaf\" style=\"--n:1\">1</div></div></div></div><p><strong>Merges, in the order they happen</strong> (15 calls, 7 merges):</p><div class=\"table-scroll\"><table><thead><tr><th>#</th><th>Merge call</th><th>Left run</th><th>Right run</th><th>Merged result</th><th>Comparisons</th></tr></thead><tbody><tr><td>1</td><td><code>merge(arr, 0, 0, 1)</code></td><td><code>[8]</code></td><td><code>[7]</code></td><td><code>[7, 8]</code></td><td>1</td></tr><tr><td>2</td><td><code>merge(arr, 2, 2, 3)</code></td><td><code>[6]</code></td><td><code>[5]</code></td><td><code>[5, 6]</code></td><td>1</td></tr><tr><td>3</td><td><code>merge(arr, 0, 1, 3)</code></td><td><code>[7, 8]</code></td><td><code>[5, 6]</code></td><td><code>[5, 6, 7, 8]</code></td><td>2</td></tr><tr><td>4</td><td><code>merge(arr, 4, 4, 5)</code></td><td><code>[4]</code></td><td><code>[3]</code></td><td><code>[3, 4]</code></td><td>1</td></tr><tr><td>5</td><td><code>merge(arr, 6, 6, 7)</code></td><td><code>[2]</code></td><td><code>[1]</code></td><td><code>[1, 2]</code></td><td>1</td></tr><tr><td>6</td><td><code>merge(arr, 4, 5, 7)</code></td><td><code>[3, 4]</code></td><td><code>[1, 2]</code></td><td><code>[1, 2, 3, 4]</code></td><td>2</td></tr><tr><td>7</td><td><code>merge(arr, 0, 3, 7)</code></td><td><code>[5, 6, 7, 8]</code></td><td><code>[1, 2, 3, 4]</code></td><td><code>[1, 2, 3, 4, 5, 6, 7, 8]</code></td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>7 merges</strong></td><td></td><td></td><td><strong>[1, 2, 3, 4, 5, 6, 7, 8]</strong></td><td><strong>12</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>12</code> comparisons: the same order of magnitude as every other input. Merge sort has no bad input: <code>O(n log n)</code> in all cases.</div></article><article class=\"example-card\"><h3>Duplicates · <code>[3ᵃ, 1, 3ᵇ, 2]</code></h3><p>Equal values must keep their original order for the sort to be stable. Watch the merge of <code>[1, 3ᵃ]</code> with <code>[2, 3ᵇ]</code>.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [3ᵃ, 1, 3ᵇ, 2]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">3ᵃ</span><span class=\"cell\" data-label=\"1\">1</span><span class=\"cell\" data-label=\"2\">3ᵇ</span><span class=\"cell\" data-label=\"3\">2</span></div></div><p><strong>How the array is split</strong> (box width is proportional to size):</p><div class=\"rtree\" role=\"img\" aria-label=\"split tree\"><div class=\"rt-level\"><span class=\"rt-tag\">level 0</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:4\">3ᵃ 1 3ᵇ 2</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 1</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:2\">3ᵃ 1</div><div class=\"rt-node split\" style=\"--n:2\">3ᵇ 2</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 2</span><div class=\"rt-row\"><div class=\"rt-node split leaf\" style=\"--n:1\">3ᵃ</div><div class=\"rt-node split leaf\" style=\"--n:1\">1</div><div class=\"rt-node split leaf\" style=\"--n:1\">3ᵇ</div><div class=\"rt-node split leaf\" style=\"--n:1\">2</div></div></div></div><p><strong>Merges, in the order they happen</strong> (7 calls, 3 merges):</p><div class=\"table-scroll\"><table><thead><tr><th>#</th><th>Merge call</th><th>Left run</th><th>Right run</th><th>Merged result</th><th>Comparisons</th></tr></thead><tbody><tr><td>1</td><td><code>merge(arr, 0, 0, 1)</code></td><td><code>[3ᵃ]</code></td><td><code>[1]</code></td><td><code>[1, 3ᵃ]</code></td><td>1</td></tr><tr><td>2</td><td><code>merge(arr, 2, 2, 3)</code></td><td><code>[3ᵇ]</code></td><td><code>[2]</code></td><td><code>[2, 3ᵇ]</code></td><td>1</td></tr><tr><td>3</td><td><code>merge(arr, 0, 1, 3)</code></td><td><code>[1, 3ᵃ]</code></td><td><code>[2, 3ᵇ]</code></td><td><code>[1, 2, 3ᵃ, 3ᵇ]</code></td><td>3</td></tr><tr><td><strong>Total</strong></td><td><strong>3 merges</strong></td><td></td><td></td><td><strong>[1, 2, 3ᵃ, 3ᵇ]</strong></td><td><strong>5</strong></td></tr></tbody></table></div><div class=\"result-line\">The result is <code>[1, 2, 3ᵃ, 3ᵇ]</code>: <code>3ᵃ</code> still comes before <code>3ᵇ</code>. When the two front values are equal (<code>3ᵃ</code> vs <code>3ᵇ</code>) the <code>&lt;=</code> takes the <strong>left</strong> one first. With <code>&lt;</code> it would take the right one and break stability.</div></article><article class=\"example-card\"><h3>The nine values from Test 1 · <code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code></h3><p>Nine values: the first cut is 5 | 4, the left five cut as 3 | 2, and so on. Check each merge by merging by hand.</p><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Start [50, 83, 76, 6, 32, 90, 12, 2, 59]\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">50</span><span class=\"cell\" data-label=\"1\">83</span><span class=\"cell\" data-label=\"2\">76</span><span class=\"cell\" data-label=\"3\">6</span><span class=\"cell\" data-label=\"4\">32</span><span class=\"cell\" data-label=\"5\">90</span><span class=\"cell\" data-label=\"6\">12</span><span class=\"cell\" data-label=\"7\">2</span><span class=\"cell\" data-label=\"8\">59</span></div></div><p><strong>How the array is split</strong> (box width is proportional to size):</p><div class=\"rtree\" role=\"img\" aria-label=\"split tree\"><div class=\"rt-level\"><span class=\"rt-tag\">level 0</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:9\">50 83 76 6 32 90 12 2 59</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 1</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:5\">50 83 76 6 32</div><div class=\"rt-node split\" style=\"--n:4\">90 12 2 59</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 2</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:3\">50 83 76</div><div class=\"rt-node split\" style=\"--n:2\">6 32</div><div class=\"rt-node split\" style=\"--n:2\">90 12</div><div class=\"rt-node split\" style=\"--n:2\">2 59</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 3</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:2\">50 83</div><div class=\"rt-node split leaf\" style=\"--n:1\">76</div><div class=\"rt-node split leaf\" style=\"--n:1\">6</div><div class=\"rt-node split leaf\" style=\"--n:1\">32</div><div class=\"rt-node split leaf\" style=\"--n:1\">90</div><div class=\"rt-node split leaf\" style=\"--n:1\">12</div><div class=\"rt-node split leaf\" style=\"--n:1\">2</div><div class=\"rt-node split leaf\" style=\"--n:1\">59</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 4</span><div class=\"rt-row\"><div class=\"rt-node split leaf\" style=\"--n:1\">50</div><div class=\"rt-node split leaf\" style=\"--n:1\">83</div><div class=\"rt-node split leaf\" style=\"--n:1\">76</div><div class=\"rt-node split leaf\" style=\"--n:1\">6</div><div class=\"rt-node split leaf\" style=\"--n:1\">32</div><div class=\"rt-node split leaf\" style=\"--n:1\">90</div><div class=\"rt-node split leaf\" style=\"--n:1\">12</div><div class=\"rt-node split leaf\" style=\"--n:1\">2</div><div class=\"rt-node split leaf\" style=\"--n:1\">59</div></div></div></div><p><strong>Merges, in the order they happen</strong> (17 calls, 8 merges):</p><div class=\"table-scroll\"><table><thead><tr><th>#</th><th>Merge call</th><th>Left run</th><th>Right run</th><th>Merged result</th><th>Comparisons</th></tr></thead><tbody><tr><td>1</td><td><code>merge(arr, 0, 0, 1)</code></td><td><code>[50]</code></td><td><code>[83]</code></td><td><code>[50, 83]</code></td><td>1</td></tr><tr><td>2</td><td><code>merge(arr, 0, 1, 2)</code></td><td><code>[50, 83]</code></td><td><code>[76]</code></td><td><code>[50, 76, 83]</code></td><td>2</td></tr><tr><td>3</td><td><code>merge(arr, 3, 3, 4)</code></td><td><code>[6]</code></td><td><code>[32]</code></td><td><code>[6, 32]</code></td><td>1</td></tr><tr><td>4</td><td><code>merge(arr, 0, 2, 4)</code></td><td><code>[50, 76, 83]</code></td><td><code>[6, 32]</code></td><td><code>[6, 32, 50, 76, 83]</code></td><td>2</td></tr><tr><td>5</td><td><code>merge(arr, 5, 5, 6)</code></td><td><code>[90]</code></td><td><code>[12]</code></td><td><code>[12, 90]</code></td><td>1</td></tr><tr><td>6</td><td><code>merge(arr, 7, 7, 8)</code></td><td><code>[2]</code></td><td><code>[59]</code></td><td><code>[2, 59]</code></td><td>1</td></tr><tr><td>7</td><td><code>merge(arr, 5, 6, 8)</code></td><td><code>[12, 90]</code></td><td><code>[2, 59]</code></td><td><code>[2, 12, 59, 90]</code></td><td>3</td></tr><tr><td>8</td><td><code>merge(arr, 0, 4, 8)</code></td><td><code>[6, 32, 50, 76, 83]</code></td><td><code>[2, 12, 59, 90]</code></td><td><code>[2, 6, 12, 32, 50, 59, 76, 83, 90]</code></td><td>8</td></tr><tr><td><strong>Total</strong></td><td><strong>8 merges</strong></td><td></td><td></td><td><strong>[2, 6, 12, 32, 50, 59, 76, 83, 90]</strong></td><td><strong>19</strong></td></tr></tbody></table></div><div class=\"result-line\"><code>17</code> calls, <code>8</code> merges, <code>19</code> comparisons. Always <code>n − 1 = 8</code> merges for <code>n = 9</code>: each merge reduces the number of runs by one.</div></article>\r\n      "
  },
  "merge-properties": {
    "id": "merge-properties",
    "title": "Properties",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · Properties</span>\r\n        <h2>Properties</h2>\r\n        \r\n        <div class=\"properties\"><div class=\"property\"><small>Best time</small><b>O(n log n)</b></div><div class=\"property\"><small>Average time</small><b>O(n log n)</b></div><div class=\"property\"><small>Worst time</small><b>O(n log n)</b></div><div class=\"property\"><small>Extra space</small><b>O(n)</b></div><div class=\"property\"><small>Stable</small><b>Yes*</b></div><div class=\"property\"><small>In-place</small><b>No</b></div><div class=\"property\"><small>Adaptive</small><b>No</b></div><div class=\"property\"><small>Type</small><b>Divide and conquer</b></div></div>\r\n        <p class=\"fine-print\">* stable because the merge takes the <em>left</em> value when the two fronts are equal (<code>&lt;=</code>).</p>\r\n        <h3>Same time for every input</h3>\r\n        <p>The array is cut in the same places whatever the values are, and every level merges every value. A sorted, reversed or random array all cost <code>O(n log n)</code>. That predictability is merge sort's main selling point.</p>\r\n        <h3>Stable</h3>\r\n        <p>Equal values keep their original order, <em>provided</em> the merge uses <code>&lt;=</code> so ties are taken from the left run (which contains the earlier values). Changing it to <code>&lt;</code> silently loses stability.</p>\r\n        <h3>Not in-place</h3>\r\n        <p>The merge copies both halves into temporary arrays before writing back, so extra memory proportional to <code>n</code> is needed: <code>O(n)</code>. This is the price paid for the guaranteed speed.</p>\r\n        <h3>Not adaptive</h3>\r\n        <p>The standard version cannot take advantage of existing order, as the sorted example showed.</p>\r\n        <h3>Comparison-based</h3>\r\n        <p>For comparison-based sorting, <code>O(n log n)</code> is the best possible worst case, and merge sort reaches it.</p>\r\n    \r\n      "
  },
  "merge-complexity": {
    "id": "merge-complexity",
    "title": "Why those complexities occur",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · Why those complexities occur</span>\r\n        <h2>Why those complexities occur</h2>\r\n        \r\n        <div class=\"complexity-grid\"><div class=\"complexity-item\"><strong>Time · O(n log n), always</strong><code>log₂ n</code> levels, and each level merges all <code>n</code> values once.</div><div class=\"complexity-item\"><strong>Space · O(n)</strong>The merge needs temporary copies of the halves, up to <code>n</code> values at a time.</div></div>\r\n        <h3>Count the levels, then count the work per level</h3>\r\n        <p>How many times can you halve 8 before you reach 1? Three: 8 → 4 → 2 → 1. In general <code>log₂ n</code> times. That is the number of rows of merging.</p>\r\n        <div class=\"halving\" role=\"img\" aria-label=\"Size after each halving: 8, 4, 2, 1\"><div class=\"halve-row\"><span>0 cuts</span><div class=\"halve-bar\"><i style=\"width:100.00%\"></i></div><span class=\"halve-n\">8 per piece</span></div><div class=\"halve-row\"><span>1 cut</span><div class=\"halve-bar\"><i style=\"width:50.00%\"></i></div><span class=\"halve-n\">4 per piece</span></div><div class=\"halve-row\"><span>2 cuts</span><div class=\"halve-bar\"><i style=\"width:25.00%\"></i></div><span class=\"halve-n\">2 per piece</span></div><div class=\"halve-row\"><span>3 cuts</span><div class=\"halve-bar\"><i style=\"width:12.50%\"></i></div><span class=\"halve-n\">1 per piece</span></div></div>\r\n        <p>Each row merges <em>every</em> value exactly once (the boxes in a row together hold all <code>n</code> values), so one row costs about <code>n</code> steps. Rows × work per row:</p>\r\n        <div class=\"formula\">n values × log₂ n levels = n log₂ n steps</div>\r\n        <p>You can also write this as a recurrence: sorting <code>n</code> values costs two sorts of <code>n / 2</code> plus one merge of <code>n</code>, that is <code>T(n) = 2·T(n / 2) + n</code>, and unrolling it gives the same <code>n log₂ n</code>.</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>n (values)</th><th>Levels ⌈log₂ n⌉</th><th>Merge sort ≈ n·levels</th><th>A quadratic sort ≈ n²</th><th>Quadratic is how many times more</th></tr></thead><tbody><tr><td>8</td><td>3</td><td>24</td><td>64</td><td>≈ 2×</td></tr><tr><td>1,000</td><td>10</td><td>10,000</td><td>1,000,000</td><td>≈ 100×</td></tr><tr><td>1,000,000</td><td>20</td><td>20,000,000</td><td>1,000,000,000,000</td><td>≈ 50,000×</td></tr></tbody></table></div>\r\n        <p>For a million values, merge sort takes about <strong>20 million</strong> steps and a quadratic sort about <strong>a trillion</strong>. Even if each step of merge sort cost ten times as much (because of copying), merge sort would still be thousands of times faster. This is why the sorting library of nearly every language uses a merge-sort relative.</p>\r\n        <h3>Space</h3>\r\n        <p>During one merge, two temporary arrays hold copies of the two halves: together at most <code>n</code> values. Merges happen one at a time, so the copies are discarded between them and the peak extra memory is <code>O(n)</code>, plus <code>O(log n)</code> for the call stack.</p>\r\n    \r\n      "
  },
  "merge-when": {
    "id": "merge-when",
    "title": "When to use it",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · When to use it</span>\r\n        <h2>When to use it</h2>\r\n        \r\n        <div class=\"use-grid\"><div class=\"use good\"><strong>A good choice</strong>Large arrays; when you need guaranteed <code>O(n log n)</code> whatever the data; when you need a <strong>stable</strong> sort (sorting records by one field while keeping the order of ties); when data is too big for memory and is sorted in chunks that are merged (external sorting); sorting linked lists.</div><div class=\"use poor\"><strong>A poor choice</strong>Very small arrays, where the overhead of recursion and copying costs more than a simple insertion sort; situations with very little spare memory (<code>O(n)</code> extra space); data that is already nearly sorted, where insertion sort is almost free.</div></div>\r\n        <p>Real libraries combine the ideas: they use merge sort (or a close relative) for the big picture, and switch to <strong>insertion sort</strong> for pieces smaller than about 10 to 20 values, because on tiny arrays the simple sort wins. Knowing both lets you see why.</p>\r\n    \r\n      "
  },
  "merge-mistakes": {
    "id": "merge-mistakes",
    "title": "Common mistakes",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · Common mistakes</span>\r\n        <h2>Common mistakes</h2>\r\n        <div class=\"mistake\"><span class=\"mistake-no\">1</span><div><strong>Recursing on <code>mid</code> instead of <code>mid + 1</code> for the right half.</strong><br>The ranges must not overlap: left is <code>start..mid</code>, right is <code>mid + 1..end</code>. Overlap causes endless recursion or wrong results.</div></div><div class=\"mistake\"><span class=\"mistake-no\">2</span><div><strong>Merging before the halves are sorted.</strong><br><code>merge</code> must come <em>after</em> both recursive calls. Merge only works on two sorted runs.</div></div><div class=\"mistake\"><span class=\"mistake-no\">3</span><div><strong>Using <code>&lt;</code> instead of <code>&lt;=</code> in the merge.</strong><br>The sort still sorts but is no longer stable: equal values from the right run jump ahead of equal values from the left.</div></div><div class=\"mistake\"><span class=\"mistake-no\">4</span><div><strong>Forgetting the leftovers.</strong><br>When one run is exhausted, the remaining values of the other must still be copied. Without the two leftover loops the end of the array keeps stale values.</div></div><div class=\"mistake\"><span class=\"mistake-no\">5</span><div><strong>Copying the left half with <code>copyOfRange(arr, s, m)</code>.</strong><br>The end index is exclusive, so the left half needs <code>m + 1</code>: <code>copyOfRange(arr, s, m + 1)</code>.</div></div><div class=\"mistake\"><span class=\"mistake-no\">6</span><div><strong>Wrong base case.</strong><br>Stop when <code>start &gt;= end</code> (zero or one value). Testing <code>start == end</code> only can loop forever on an empty range.</div></div><div class=\"mistake\"><span class=\"mistake-no\">7</span><div><strong>Writing the answer into the temporary arrays.</strong><br>The result must land back in <code>arr</code>, starting at index <code>start</code>, not index 0.</div></div><div class=\"mistake\"><span class=\"mistake-no\">8</span><div><strong>Expecting the merges to happen level by level.</strong><br>The recursive version merges depth-first: the whole left half is sorted before the right half is touched.</div></div>\r\n      "
  },
  "merge-summary": {
    "id": "merge-summary",
    "title": "A test-ready summary",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · A test-ready summary</span>\r\n        <h2>A test-ready summary</h2>\r\n        \r\n        <div class=\"test-summary\">\r\n          <p>Merge sort is a stable, comparison-based, divide-and-conquer sorting algorithm. It splits the array at the midpoint, recursively sorts the left and right halves, and then merges the two sorted halves into one sorted array by repeatedly taking the smaller front value (taking the left value on ties). A single value is the base case. Its time complexity is O(n log n) in the best, average and worst cases, because there are log₂ n levels and each level merges n values, but it needs O(n) extra space and is not in-place. It is the right choice for large arrays and when a guaranteed running time or stability matters, and a poor choice when memory is very limited.</p>\r\n        </div>\r\n    \r\n      "
  },
  "merge-practice": {
    "id": "merge-practice",
    "title": "Practice",
    "body": "\r\n        <span class=\"section-no\">Sorting / Merge sort · Practice</span>\r\n        <h2>Practice</h2>\r\n        \r\n        <h3>Guided question</h3>\r\n        <p>Use merge sort on <code>[6, 3, 8, 4]</code>. List every call in order, then every merge in the order it happens.</p>\r\n        <details><summary>Reveal the guided answer</summary><div class=\"answer\"><p><strong>Calls (indentation = depth):</strong></p><p><code>mergeSort(arr, 0, 3)</code> → mid = 1</p><p>&nbsp;&nbsp;<code>mergeSort(arr, 0, 1)</code> → mid = 0</p><p>&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 0, 0)</code> → one value: return</p><p>&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 1, 1)</code> → one value: return</p><p>&nbsp;&nbsp;<code>mergeSort(arr, 2, 3)</code> → mid = 2</p><p>&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 2, 2)</code> → one value: return</p><p>&nbsp;&nbsp;&nbsp;&nbsp;<code>mergeSort(arr, 3, 3)</code> → one value: return</p><p><strong>Merges:</strong></p><div class=\"table-scroll\"><table><thead><tr><th>#</th><th>Merge call</th><th>Left run</th><th>Right run</th><th>Merged result</th><th>Comparisons</th></tr></thead><tbody><tr><td>1</td><td><code>merge(arr, 0, 0, 1)</code></td><td><code>[6]</code></td><td><code>[3]</code></td><td><code>[3, 6]</code></td><td>1</td></tr><tr><td>2</td><td><code>merge(arr, 2, 2, 3)</code></td><td><code>[8]</code></td><td><code>[4]</code></td><td><code>[4, 8]</code></td><td>1</td></tr><tr><td>3</td><td><code>merge(arr, 0, 1, 3)</code></td><td><code>[3, 6]</code></td><td><code>[4, 8]</code></td><td><code>[3, 4, 6, 8]</code></td><td>3</td></tr><tr><td><strong>Total</strong></td><td><strong>3 merges</strong></td><td></td><td></td><td><strong>[3, 4, 6, 8]</strong></td><td><strong>5</strong></td></tr></tbody></table></div></div></details>\r\n        <h3>Independent question</h3>\r\n        <p>Show how <code>[9, 4, 7, 3, 5]</code> is split (remember the left half gets the extra value), then list the merges.</p>\r\n        <ul class=\"checklist\">\r\n          <li>Draw the split tree down to single values.</li>\r\n          <li>Work out the merges in depth-first order: whole left side first.</li>\r\n          <li>Write each merged result.</li>\r\n          <li>It must take exactly <code>n − 1 = 4</code> merges.</li>\r\n        </ul>\r\n        <details><summary>Reveal the independent answer</summary><div class=\"answer\"><div class=\"rtree\" role=\"img\" aria-label=\"split tree\"><div class=\"rt-level\"><span class=\"rt-tag\">level 0</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:5\">9 4 7 3 5</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 1</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:3\">9 4 7</div><div class=\"rt-node split\" style=\"--n:2\">3 5</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 2</span><div class=\"rt-row\"><div class=\"rt-node split\" style=\"--n:2\">9 4</div><div class=\"rt-node split leaf\" style=\"--n:1\">7</div><div class=\"rt-node split leaf\" style=\"--n:1\">3</div><div class=\"rt-node split leaf\" style=\"--n:1\">5</div></div></div><div class=\"rt-level\"><span class=\"rt-tag\">level 3</span><div class=\"rt-row\"><div class=\"rt-node split leaf\" style=\"--n:1\">9</div><div class=\"rt-node split leaf\" style=\"--n:1\">4</div><div class=\"rt-node split leaf\" style=\"--n:1\">7</div><div class=\"rt-node split leaf\" style=\"--n:1\">3</div><div class=\"rt-node split leaf\" style=\"--n:1\">5</div></div></div></div><div class=\"table-scroll\"><table><thead><tr><th>#</th><th>Merge call</th><th>Left run</th><th>Right run</th><th>Merged result</th><th>Comparisons</th></tr></thead><tbody><tr><td>1</td><td><code>merge(arr, 0, 0, 1)</code></td><td><code>[9]</code></td><td><code>[4]</code></td><td><code>[4, 9]</code></td><td>1</td></tr><tr><td>2</td><td><code>merge(arr, 0, 1, 2)</code></td><td><code>[4, 9]</code></td><td><code>[7]</code></td><td><code>[4, 7, 9]</code></td><td>2</td></tr><tr><td>3</td><td><code>merge(arr, 3, 3, 4)</code></td><td><code>[3]</code></td><td><code>[5]</code></td><td><code>[3, 5]</code></td><td>1</td></tr><tr><td>4</td><td><code>merge(arr, 0, 2, 4)</code></td><td><code>[4, 7, 9]</code></td><td><code>[3, 5]</code></td><td><code>[3, 4, 5, 7, 9]</code></td><td>3</td></tr><tr><td><strong>Total</strong></td><td><strong>4 merges</strong></td><td></td><td></td><td><strong>[3, 4, 5, 7, 9]</strong></td><td><strong>7</strong></td></tr></tbody></table></div></div></details>\r\n        <h3>Test-style question</h3>\r\n        <p>List every merge made when merge sort sorts <code>[50, 83, 76, 6, 32, 90, 12, 2, 59]</code> ascending, and give the total number of comparisons.</p>\r\n        <details><summary>Reveal the test-style answer</summary><div class=\"answer\"><div class=\"table-scroll\"><table><thead><tr><th>#</th><th>Merge call</th><th>Left run</th><th>Right run</th><th>Merged result</th><th>Comparisons</th></tr></thead><tbody><tr><td>1</td><td><code>merge(arr, 0, 0, 1)</code></td><td><code>[50]</code></td><td><code>[83]</code></td><td><code>[50, 83]</code></td><td>1</td></tr><tr><td>2</td><td><code>merge(arr, 0, 1, 2)</code></td><td><code>[50, 83]</code></td><td><code>[76]</code></td><td><code>[50, 76, 83]</code></td><td>2</td></tr><tr><td>3</td><td><code>merge(arr, 3, 3, 4)</code></td><td><code>[6]</code></td><td><code>[32]</code></td><td><code>[6, 32]</code></td><td>1</td></tr><tr><td>4</td><td><code>merge(arr, 0, 2, 4)</code></td><td><code>[50, 76, 83]</code></td><td><code>[6, 32]</code></td><td><code>[6, 32, 50, 76, 83]</code></td><td>2</td></tr><tr><td>5</td><td><code>merge(arr, 5, 5, 6)</code></td><td><code>[90]</code></td><td><code>[12]</code></td><td><code>[12, 90]</code></td><td>1</td></tr><tr><td>6</td><td><code>merge(arr, 7, 7, 8)</code></td><td><code>[2]</code></td><td><code>[59]</code></td><td><code>[2, 59]</code></td><td>1</td></tr><tr><td>7</td><td><code>merge(arr, 5, 6, 8)</code></td><td><code>[12, 90]</code></td><td><code>[2, 59]</code></td><td><code>[2, 12, 59, 90]</code></td><td>3</td></tr><tr><td>8</td><td><code>merge(arr, 0, 4, 8)</code></td><td><code>[6, 32, 50, 76, 83]</code></td><td><code>[2, 12, 59, 90]</code></td><td><code>[2, 6, 12, 32, 50, 59, 76, 83, 90]</code></td><td>8</td></tr><tr><td><strong>Total</strong></td><td><strong>8 merges</strong></td><td></td><td></td><td><strong>[2, 6, 12, 32, 50, 59, 76, 83, 90]</strong></td><td><strong>19</strong></td></tr></tbody></table></div></div></details>\r\n    \r\n      "
  },
  "sort-compare": {
    "id": "sort-compare",
    "title": "The same array, four algorithms",
    "body": "<span class=\"section-no\">Sorting / Comparison</span><h2>The same array, four algorithms</h2><p class=\"lede\">Work done sorting <code>[4, 2, 5, 1, 3]</code> ascending. Only five values, but the pattern already shows each algorithm’s character.</p><div class=\"table-scroll\"><table><thead><tr><th>Algorithm</th><th>Comparisons</th><th>Data movement</th><th>Array writes (same unit)</th><th>What the numbers show</th></tr></thead><tbody><tr><td>Bubble</td><td>10</td><td>6 swaps</td><td><strong>12</strong></td><td>One swap per inversion; each swap writes two cells.</td></tr><tr><td>Selection</td><td>10</td><td>2 swaps</td><td><strong>4</strong></td><td>Comparisons never shrink, but swaps are minimal.</td></tr><tr><td>Insertion</td><td>8</td><td>6 shifts</td><td><strong>10</strong></td><td>Comparisons stop early at the first failed test.</td></tr><tr><td>Merge</td><td>7</td><td>12 writes</td><td><strong>12</strong></td><td>Fewest comparisons on <em>this</em> input (on an already sorted array of 5, insertion needs 4 and merge 7); pays with temporary copies.</td></tr></tbody></table></div><p class=\"fine-print\">Counts come from the exact code in this guide: insertion stops at the left edge without an extra comparison, and merge counts only pairwise comparisons. “Data movement” mixes units on purpose, because that is how each algorithm is described; the last column converts them to one unit, writes into the array (a swap writes 2 cells, a shift 1, each insertion 1 more, and merge writes each value once per level it takes part in). Merge also copies halves into temporary arrays, which is not counted here.</p><h3>Properties at a glance</h3><div class=\"table-scroll\"><table><thead><tr><th>Algorithm</th><th>Best</th><th>Average</th><th>Worst</th><th>Stable</th><th>In-place</th><th>Extra space</th><th>Adaptive</th></tr></thead><tbody><tr><td>Bubble (with swapped flag)</td><td>O(n)</td><td>O(n²)</td><td>O(n²)</td><td>Yes</td><td>Yes</td><td>O(1)</td><td>Yes</td></tr><tr><td>Selection</td><td>O(n²)</td><td>O(n²)</td><td>O(n²)</td><td>No</td><td>Yes</td><td>O(1)</td><td>No</td></tr><tr><td>Insertion</td><td>O(n)</td><td>O(n²)</td><td>O(n²)</td><td>Yes</td><td>Yes</td><td>O(1)</td><td>Yes</td></tr><tr><td>Merge</td><td>O(n log n)</td><td>O(n log n)</td><td>O(n log n)</td><td>Yes</td><td>No</td><td>O(n)</td><td>No</td></tr></tbody></table></div><p class=\"fine-print\">Stable: equal values keep their original order. Adaptive: faster when the input is already nearly sorted. Selection sort is stable only if implemented with shifting instead of a long-distance swap, which is not the version taught here.</p>"
  },
  "sorting-summary": {
    "id": "sorting-summary",
    "title": "Recognise each algorithm by its repeated action",
    "body": "\r\n        <span class=\"section-no\">Sorting / Chapter summary</span>\r\n        <h2>Recognise each algorithm by its repeated action</h2>\r\n        <div class=\"term-grid\"><div class=\"term\"><strong>Bubble</strong>Swap inverted neighbours; the largest active value ends at the right.</div><div class=\"term\"><strong>Selection</strong>Find the suffix minimum; swap it into the next position.</div><div class=\"term\"><strong>Insertion</strong>Save a key; shift larger prefix values; insert into the gap.</div><div class=\"term\"><strong>Merge</strong>Divide into halves; merge sorted runs using two pointers.</div></div>\r\n        <details><summary>Quick check: which sorts improve on nearly sorted input?</summary><div class=\"answer\">Optimised bubble sort and insertion sort are adaptive. Selection and the standard merge sort still perform their usual major work.</div></details>\r\n      "
  },
  "growth": {
    "id": "growth",
    "title": "Big-O growth side by side",
    "body": "\r\n        <span class=\"section-no\">Sorting & searching · Big-O growth side by side</span>\r\n        <h2>Big-O growth side by side</h2>\r\n        <p class=\"lede\">The same four growth rates compared as a chart and as numbers, and the ranking behind Test 1 question 3(d)–(e).</p>\r\n        \r\n        <p>Big-O answers one question: <em>when the input gets bigger, how fast does the number of steps grow?</em> It ignores small details (a multiplier of 2, a few extra steps) and keeps only the term that dominates when <code>n</code> is large. This chart plots the four growth rates that appear in this guide, for <code>n</code> from 0 to 16.</p>\r\n        <svg class=\"growth\" viewBox=\"0 0 640 340\" role=\"img\" aria-label=\"Steps needed as n grows from 0 to 16: n squared climbs fastest, then n log n, then n, then log n stays almost flat\"><line class=\"g-grid\" x1=\"54\" x2=\"624\" y1=\"300.0\" y2=\"300.0\"/><text class=\"g-tick\" x=\"46\" y=\"304.0\" text-anchor=\"end\">0</text><line class=\"g-grid\" x1=\"54\" x2=\"624\" y1=\"229.0\" y2=\"229.0\"/><text class=\"g-tick\" x=\"46\" y=\"233.0\" text-anchor=\"end\">64</text><line class=\"g-grid\" x1=\"54\" x2=\"624\" y1=\"158.0\" y2=\"158.0\"/><text class=\"g-tick\" x=\"46\" y=\"162.0\" text-anchor=\"end\">128</text><line class=\"g-grid\" x1=\"54\" x2=\"624\" y1=\"87.0\" y2=\"87.0\"/><text class=\"g-tick\" x=\"46\" y=\"91.0\" text-anchor=\"end\">192</text><line class=\"g-grid\" x1=\"54\" x2=\"624\" y1=\"16.0\" y2=\"16.0\"/><text class=\"g-tick\" x=\"46\" y=\"20.0\" text-anchor=\"end\">256</text><text class=\"g-tick\" x=\"54.0\" y=\"318\" text-anchor=\"middle\">0</text><text class=\"g-tick\" x=\"196.5\" y=\"318\" text-anchor=\"middle\">4</text><text class=\"g-tick\" x=\"339.0\" y=\"318\" text-anchor=\"middle\">8</text><text class=\"g-tick\" x=\"481.5\" y=\"318\" text-anchor=\"middle\">12</text><text class=\"g-tick\" x=\"624.0\" y=\"318\" text-anchor=\"middle\">16</text><line class=\"g-axis\" x1=\"54\" x2=\"624\" y1=\"300\" y2=\"300\"/><line class=\"g-axis\" x1=\"54\" x2=\"54\" y1=\"16\" y2=\"300\"/><polyline class=\"g-line g-n2\" points=\"89.6,298.9 107.4,297.5 125.2,295.6 143.1,293.1 160.9,290.0 178.7,286.4 196.5,282.2 214.3,277.5 232.1,272.3 249.9,266.4 267.8,260.1 285.6,253.1 303.4,245.6 321.2,237.6 339.0,229.0 356.8,219.8 374.6,210.1 392.4,199.9 410.2,189.1 428.1,177.7 445.9,165.8 463.7,153.3 481.5,140.2 499.3,126.7 517.1,112.5 534.9,97.8 552.8,82.6 570.6,66.8 588.4,50.4 606.2,33.5 624.0,16.0\"/><text class=\"g-label g-n2\" x=\"618\" y=\"10\" text-anchor=\"end\">n²</text><polyline class=\"g-line g-nlogn\" points=\"89.6,300.0 107.4,299.0 125.2,297.8 143.1,296.3 160.9,294.7 178.7,293.0 196.5,291.1 214.3,289.2 232.1,287.1 249.9,285.0 267.8,282.8 285.6,280.5 303.4,278.2 321.2,275.8 339.0,273.4 356.8,270.9 374.6,268.4 392.4,265.8 410.2,263.1 428.1,260.5 445.9,257.8 463.7,255.0 481.5,252.3 499.3,249.5 517.1,246.6 534.9,243.8 552.8,240.9 570.6,237.9 588.4,235.0 606.2,232.0 624.0,229.0\"/><text class=\"g-label g-nlogn\" x=\"618\" y=\"223\" text-anchor=\"end\">n log₂ n</text><polyline class=\"g-line g-n\" points=\"89.6,298.9 107.4,298.3 125.2,297.8 143.1,297.2 160.9,296.7 178.7,296.1 196.5,295.6 214.3,295.0 232.1,294.5 249.9,293.9 267.8,293.3 285.6,292.8 303.4,292.2 321.2,291.7 339.0,291.1 356.8,290.6 374.6,290.0 392.4,289.5 410.2,288.9 428.1,288.4 445.9,287.8 463.7,287.2 481.5,286.7 499.3,286.1 517.1,285.6 534.9,285.0 552.8,284.5 570.6,283.9 588.4,283.4 606.2,282.8 624.0,282.2\"/><text class=\"g-label g-n\" x=\"618\" y=\"276\" text-anchor=\"end\">n</text><polyline class=\"g-line g-log\" points=\"89.6,300.0 107.4,299.4 125.2,298.9 143.1,298.5 160.9,298.2 178.7,298.0 196.5,297.8 214.3,297.6 232.1,297.4 249.9,297.3 267.8,297.1 285.6,297.0 303.4,296.9 321.2,296.8 339.0,296.7 356.8,296.6 374.6,296.5 392.4,296.4 410.2,296.3 428.1,296.2 445.9,296.2 463.7,296.1 481.5,296.0 499.3,296.0 517.1,295.9 534.9,295.8 552.8,295.8 570.6,295.7 588.4,295.7 606.2,295.6 624.0,295.6\"/><text class=\"g-label g-log\" x=\"618\" y=\"290\" text-anchor=\"end\">log₂ n</text><text class=\"g-tick\" x=\"339\" y=\"334\" text-anchor=\"middle\">n (number of values)</text><text class=\"g-tick\" x=\"12\" y=\"158\" transform=\"rotate(-90 12 158)\" text-anchor=\"middle\">steps</text></svg>\r\n        <p>Read it from the bottom: <span class=\"g-key\" style=\"color:var(--moss)\"><strong>log₂ n</strong></span> barely rises at all; <strong>n</strong> is a straight diagonal; <strong>n log₂ n</strong> bends upward a little; <span style=\"color:var(--danger)\"><strong>n²</strong></span> shoots away. At n = 16 the steps are about 4, 16, 64 and 256.</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>n (values)</th><th>log₂ n</th><th>n</th><th>n log₂ n</th><th>n²</th></tr></thead><tbody><tr><td>10</td><td>3.3</td><td>10</td><td>33</td><td>100</td></tr><tr><td>100</td><td>6.6</td><td>100</td><td>664</td><td>10,000</td></tr><tr><td>1,000</td><td>10.0</td><td>1,000</td><td>9,965</td><td>1,000,000</td></tr><tr><td>1,000,000</td><td>19.9</td><td>1,000,000</td><td>19,931,568</td><td>1,000,000,000,000</td></tr></tbody></table></div>\r\n        <p>A million values: <code>log₂ n</code> is 20; <code>n log₂ n</code> is 20 million; <code>n²</code> is a <em>trillion</em>. That last gap is why the choice of algorithm matters far more than how fast your computer is.</p>\r\n        <h3>Ranking the algorithms in this guide (worst case)</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Algorithm</th><th>Job</th><th>Worst-case time</th><th>Where it comes from</th><th>Efficiency rank</th></tr></thead><tbody><tr><td>Linear search</td><td>find a value</td><td><code>O(n)</code></td><td>may check every cell</td><td>3rd</td></tr><tr><td>Binary search</td><td>find a value (sorted data)</td><td><code>O(log n)</code></td><td>halves the candidates each probe</td><td><strong>1st: most efficient</strong></td></tr><tr><td>Selection sort</td><td>sort</td><td><code>O(n²)</code></td><td>n(n − 1) / 2 comparisons always</td><td>5th</td></tr><tr><td>Bubble sort</td><td>sort</td><td><code>O(n²)</code></td><td>n(n − 1) / 2 comparisons in the worst case</td><td>5th</td></tr><tr><td>Insertion sort</td><td>sort</td><td><code>O(n²)</code></td><td>n(n − 1) / 2 shifts in the worst case</td><td>5th</td></tr><tr><td>Merge sort</td><td>sort</td><td><code>O(n log n)</code></td><td>log₂ n levels × n values per level</td><td>4th</td></tr></tbody></table></div>\r\n        <p>Test 1 question 3(d)–(e) asks for the worst-case complexity of linear search, binary search, selection sort and bubble sort, and which of them is the most efficient. The answers: <code>O(n)</code>, <code>O(log n)</code>, <code>O(n²)</code>, <code>O(n²)</code>, and <strong>binary search</strong> is the most efficient, because <code>log n</code> grows slowest.</p>\r\n        <div class=\"callout\"><strong>Two traps on that question:</strong> (1) Binary search is <code>O(log n)</code>, not <code>O(n²)</code>: it does <em>not</em> have a loop inside a loop; each pass halves the work. (2) Comparing a searching algorithm with sorting algorithms is not quite fair, since binary search needs data that is already sorted. Say so if the question lets you; the expected answer is still binary search.</div>\r\n        <h3>How to read a Big-O answer quickly</h3>\r\n        <ul>\r\n          <li><strong>One loop over all the data → <code>O(n)</code>.</strong> Linear search.</li>\r\n          <li><strong>A loop inside a loop over the data → <code>O(n²)</code>.</strong> Bubble, selection and insertion sort.</li>\r\n          <li><strong>Halve the problem each step → <code>O(log n)</code>.</strong> Binary search.</li>\r\n          <li><strong>Halve the problem <em>and</em> do <code>n</code> work at each level → <code>O(n log n)</code>.</strong> Merge sort.</li>\r\n        </ul>\r\n        <details><summary>Quick check: put these in order from fastest to slowest growth: O(n²), O(log n), O(n log n), O(n)</summary><div class=\"answer\"><code>O(log n)</code> &lt; <code>O(n)</code> &lt; <code>O(n log n)</code> &lt; <code>O(n²)</code>. Check with n = 1,000: about 10, 1,000, 10,000, 1,000,000.</div></details>\r\n    \r\n      "
  },
  "file-array-app": {
    "id": "file-array-app",
    "title": "Read a file, fill an array, then sort only the values read",
    "body": "\r\n        <span class=\"section-no\">Applications / File → array → sort</span>\r\n        <h2>Read a file, fill an array, then sort only the values read</h2>\r\n        <p class=\"lede\">A file supplies text tokens, a Scanner parses integers, an array stores them, and the insertion sort from the sorting chapter orders the used portion. The program must track how many cells are really in use.</p>\r\n        <div class=\"flow-steps\"><div class=\"flow-step\"><b>1</b><div><strong>File text</strong><br><code>63 29 bad 72 85 18</code></div></div><div class=\"flow-step\"><b>2</b><div><strong>Parse</strong><br>Accept integers; report and skip <code>bad</code>.</div></div><div class=\"flow-step\"><b>3</b><div><strong>Store</strong><br><code>[63,29,72,85,18]</code> with <code>count = 5</code>.</div></div><div class=\"flow-step\"><b>4</b><div><strong>Sort</strong><br><code>[18,29,63,72,85]</code>.</div></div></div>\r\n        <h3>Capacity versus logical size</h3>\r\n        <p><code>buffer.length</code> is the <strong>capacity</strong>: 100 cells always exist. <code>count</code> is the <strong>logical size</strong>: only cells <code>0 .. count − 1</code> hold file values. The first eight of the 100 cells are drawn here; the rest also hold <code>0</code>.</p>\r\n        <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"First eight cells of buffer: five stored values then unused zeros. count is 5\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">63</span><span class=\"cell sorted\" data-label=\"1\">29</span><span class=\"cell sorted\" data-label=\"2\">72</span><span class=\"cell sorted\" data-label=\"3\">85</span><span class=\"cell sorted\" data-label=\"4\">18</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell empty\" data-label=\"5 count\">0</span><span class=\"cell empty\" data-label=\"6\">0</span><span class=\"cell empty\" data-label=\"7\">0</span></div></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>FileArraySort.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy FileArraySort.java\">Copy code</button></div><pre><code><span class=\"kw\">import</span> java.io.<span class=\"ty\">File</span>;\r\n<span class=\"kw\">import</span> java.io.<span class=\"ty\">FileNotFoundException</span>;\r\n<span class=\"kw\">import</span> java.util.<span class=\"ty\">Arrays</span>;\r\n<span class=\"kw\">import</span> java.util.<span class=\"ty\">Scanner</span>;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">FileArraySort</span> {\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> main(<span class=\"ty\">String</span>[] args) <span class=\"kw\">throws</span> <span class=\"ty\">FileNotFoundException</span> {\r\n        <span class=\"ty\">int</span>[] marks = readIntegers(<span class=\"st\">\"marks.txt\"</span>);\r\n        <span class=\"ty\">System</span>.out.println(<span class=\"st\">\"Read:   \"</span> + <span class=\"ty\">Arrays</span>.toString(marks));\r\n        insertionSort(marks); <span class=\"cm\">// apply the course algorithm</span>\r\n        <span class=\"ty\">System</span>.out.println(<span class=\"st\">\"Sorted: \"</span> + <span class=\"ty\">Arrays</span>.toString(marks));\r\n    }\r\n\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"ty\">int</span>[] readIntegers(<span class=\"ty\">String</span> filename)\r\n            <span class=\"kw\">throws</span> <span class=\"ty\">FileNotFoundException</span> {\r\n        <span class=\"ty\">int</span>[] buffer = <span class=\"kw\">new</span> <span class=\"ty\">int</span>[100]; <span class=\"cm\">// maximum capacity</span>\r\n        <span class=\"ty\">int</span> count = 0;               <span class=\"cm\">// values actually stored</span>\r\n\r\n        <span class=\"cm\">// try-with-resources closes the Scanner automatically.</span>\r\n        <span class=\"kw\">try</span> (<span class=\"ty\">Scanner</span> input = <span class=\"kw\">new</span> <span class=\"ty\">Scanner</span>(<span class=\"kw\">new</span> <span class=\"ty\">File</span>(filename))) {\r\n            <span class=\"kw\">while</span> (input.hasNext() &amp;&amp; count &lt; buffer.length) {\r\n                <span class=\"kw\">if</span> (input.hasNextInt()) {\r\n                    buffer[count] = input.nextInt();\r\n                    count++; <span class=\"cm\">// advance only after storing a valid int</span>\r\n                } <span class=\"kw\">else</span> {\r\n                    <span class=\"ty\">System</span>.out.println(<span class=\"st\">\"Skipped token: \"</span> + input.next());\r\n                }\r\n            }\r\n        }\r\n        <span class=\"cm\">// Remove unused zero-filled cells before sorting.</span>\r\n        <span class=\"kw\">return</span> <span class=\"ty\">Arrays</span>.copyOf(buffer, count);\r\n    }\r\n\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> insertionSort(<span class=\"ty\">int</span>[] a) {\r\n        <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 1; i &lt; a.length; i++) {\r\n            <span class=\"ty\">int</span> key = a[i];\r\n            <span class=\"ty\">int</span> j = i - 1;\r\n            <span class=\"kw\">while</span> (j &gt;= 0 &amp;&amp; key &lt; a[j]) {\r\n                a[j + 1] = a[j];\r\n                j--;\r\n            }\r\n            a[j + 1] = key;\r\n        }\r\n    }\r\n}\r\n</code></pre></div>\r\n        <p>With <code>marks.txt</code> containing <code>63 29 bad 72 85 18</code>, the program prints:</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Console output</span></div><pre><code>Skipped token: bad\r\nRead:   [63, 29, 72, 85, 18]\r\nSorted: [18, 29, 63, 72, 85]</code></pre></div>\r\n        <h3>Basic trace · parsing <code>marks.txt</code></h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Token</th><th>Integer?</th><th>count before</th><th>Action</th><th>Used values after</th></tr></thead><tbody><tr><td>63</td><td>Yes</td><td>0</td><td>Store at index 0; count++</td><td><code>[63]</code></td></tr><tr><td>29</td><td>Yes</td><td>1</td><td>Store at index 1; count++</td><td><code>[63,29]</code></td></tr><tr><td>bad</td><td>No</td><td>2</td><td>Consume and skip; count unchanged</td><td><code>[63,29]</code></td></tr><tr><td>72</td><td>Yes</td><td>2</td><td>Store at index 2; count++</td><td><code>[63,29,72]</code></td></tr><tr><td>85</td><td>Yes</td><td>3</td><td>Store at index 3; count++</td><td><code>[63,29,72,85]</code></td></tr><tr><td>18</td><td>Yes</td><td>4</td><td>Store at index 4; count++</td><td><code>[63,29,72,85,18]</code></td></tr></tbody></table></div>\r\n        <div class=\"direction-grid\"><div><strong>Before sorting</strong><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Used values before sorting\"><div class=\"array\"><span class=\"cell\" data-label=\"0\">63</span><span class=\"cell\" data-label=\"1\">29</span><span class=\"cell\" data-label=\"2\">72</span><span class=\"cell\" data-label=\"3\">85</span><span class=\"cell\" data-label=\"4\">18</span></div></div></div><div><strong>After insertion sort</strong><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Values after insertion sort\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">18</span><span class=\"cell sorted\" data-label=\"1\">29</span><span class=\"cell sorted\" data-label=\"2\">63</span><span class=\"cell sorted\" data-label=\"3\">72</span><span class=\"cell sorted\" data-label=\"4\">85</span></div></div></div></div>\r\n        <div class=\"callout\"><strong>If the file is missing.</strong> <code>new File(&quot;marks.txt&quot;)</code> is searched for in the program’s working directory: the folder you ran <code>java</code> from, or the project folder in many IDEs. If it is not there, <code>new Scanner(...)</code> throws <code>FileNotFoundException</code> (<code>marks.txt (No such file or directory)</code> on Linux and macOS; Windows words it <code>(The system cannot find the file specified)</code>) before the loop starts. That checked exception is why <code>main</code> and <code>readIntegers</code> say <code>throws FileNotFoundException</code>. An <em>empty</em> file is not an error: <code>count</code> stays 0 and the result is <code>[]</code>.</div>\r\n        <h3>Application questions</h3>\r\n        <details><summary>Why keep <code>count</code> separately from <code>buffer.length</code>?</summary><div class=\"answer\"><code>buffer.length</code> is capacity: 100 cells exist. <code>count</code> is logical size: only the first <code>count</code> cells contain values read from the file. Sorting all 100 would drag unused zeros into the result.</div></details>\r\n        <details><summary>Why must the invalid token be consumed with <code>input.next()</code>?</summary><div class=\"answer\"><code>hasNextInt()</code> only looks at the next token; it does not consume it. Without <code>input.next()</code> the Scanner stays on the same invalid token and the loop never progresses.</div></details>\r\n        <details><summary>What should happen if the file contains more than 100 integers?</summary><div class=\"answer\">This version stops when the buffer is full and ignores the rest, because the loop condition includes <code>count &lt; buffer.length</code>. To keep every value, remove that part of the condition and grow the array inside the <code>if (input.hasNextInt())</code> branch (below), or use an <code>ArrayList&lt;Integer&gt;</code>.<div class=\"code-panel\"><div class=\"code-head\"><span>Doubling the capacity</span></div><pre><code><span class=\"cm\">// Change the loop condition: drop \"&amp;&amp; count &lt; buffer.length\" so the loop keeps reading.</span>\r\n<span class=\"kw\">while</span> (input.hasNext()) {\r\n    <span class=\"kw\">if</span> (input.hasNextInt()) {\r\n        <span class=\"cm\">// Grow instead of stopping: double the capacity when the buffer is full.</span>\r\n        <span class=\"kw\">if</span> (count == buffer.length) {\r\n            buffer = <span class=\"ty\">Arrays</span>.copyOf(buffer, buffer.length * 2);\r\n        }\r\n        buffer[count] = input.nextInt();\r\n        count++;\r\n    } <span class=\"kw\">else</span> {\r\n        <span class=\"ty\">System</span>.out.println(<span class=\"st\">\"Skipped token: \"</span> + input.next());\r\n    }\r\n}</code></pre></div></div></details>\r\n        <details><summary>Why does <code>return Arrays.copyOf(buffer, count)</code> help the sort?</summary><div class=\"answer\">It returns an array whose <code>length</code> equals the number of real values. <code>insertionSort</code> loops to <code>a.length</code>, so it never touches the unused zero cells.</div></details>\r\n        <details><summary>Practice: trace the file <code>40 x 15 15 9</code>. What is printed?</summary><div class=\"answer\"><div class=\"table-scroll\"><table><thead><tr><th>Token</th><th>Integer?</th><th>count before</th><th>Action</th><th>Used values after</th></tr></thead><tbody><tr><td>40</td><td>Yes</td><td>0</td><td>Store at index 0; count++</td><td><code>[40]</code></td></tr><tr><td>x</td><td>No</td><td>1</td><td>Consume and skip</td><td><code>[40]</code></td></tr><tr><td>15</td><td>Yes</td><td>1</td><td>Store at index 1; count++</td><td><code>[40,15]</code></td></tr><tr><td>15</td><td>Yes</td><td>2</td><td>Store at index 2; count++ (duplicates are kept)</td><td><code>[40,15,15]</code></td></tr><tr><td>9</td><td>Yes</td><td>3</td><td>Store at index 3; count++</td><td><code>[40,15,15,9]</code></td></tr></tbody></table></div><p>The program prints <code>Skipped token: x</code>, then <code>Read:   [40, 15, 15, 9]</code>, then <code>Sorted: [9, 15, 15, 40]</code>. <code>count</code> ends at 4.</p></div></details>\r\n        <div class=\"method-summary\"><strong>Arrays and file input in one sentence</strong><p>Indexes connect loops to array cells; primitive cells store values, reference cells store nullable object references, and file input needs both capacity control and a logical count before sorting.</p></div>\r\n      "
  },
  "object-sorting": {
    "id": "object-sorting",
    "title": "Sort and search an array of objects by one field",
    "body": "\r\n        <span class=\"section-no\">Applications / Objects by key field</span>\r\n        <h2>Sort and search an array of objects by one field</h2>\r\n        <p class=\"lede\">Binary search needs the array sorted “by the same key” it searches. For objects the key is a field you choose. The algorithms are unchanged: the comparison reads the field through a getter instead of comparing the cell directly.</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Staff.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy Staff.java\">Copy code</button></div><pre><code><span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">Staff</span> {\r\n    <span class=\"kw\">private</span> <span class=\"ty\">String</span> name;\r\n    <span class=\"kw\">private</span> <span class=\"ty\">int</span> staffId;\r\n    <span class=\"kw\">private</span> <span class=\"ty\">String</span> department;\r\n\r\n    <span class=\"kw\">public</span> <span class=\"ty\">Staff</span>(<span class=\"ty\">String</span> name, <span class=\"ty\">int</span> staffId, <span class=\"ty\">String</span> department) {\r\n        <span class=\"kw\">this</span>.name = name;\r\n        <span class=\"kw\">this</span>.staffId = staffId;\r\n        <span class=\"kw\">this</span>.department = department;\r\n    }\r\n\r\n    <span class=\"kw\">public</span> <span class=\"ty\">String</span> getName() { <span class=\"kw\">return</span> name; }\r\n    <span class=\"kw\">public</span> <span class=\"ty\">int</span> getId() { <span class=\"kw\">return</span> staffId; }\r\n    <span class=\"kw\">public</span> <span class=\"kw\">void</span> setId(<span class=\"ty\">int</span> staffId) { <span class=\"kw\">this</span>.staffId = staffId; }\r\n    <span class=\"kw\">public</span> <span class=\"kw\">void</span> setDepartment(<span class=\"ty\">String</span> department) { <span class=\"kw\">this</span>.department = department; }\r\n}\r\n</code></pre></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>StaffTools.java · sort and search by id</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy StaffTools.java · sort and search by id\">Copy code</button></div><pre><code><span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">StaffTools</span> {\r\n    <span class=\"cm\">// Insertion sort by id over the USED part only: staff[0 .. count - 1].</span>\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> sortById(<span class=\"ty\">Staff</span>[] staff, <span class=\"ty\">int</span> count) {\r\n        <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 1; i &lt; count; i++) {\r\n            <span class=\"ty\">Staff</span> key = staff[i];               <span class=\"cm\">// save the object reference</span>\r\n            <span class=\"ty\">int</span> j = i - 1;\r\n            <span class=\"kw\">while</span> (j &gt;= 0 &amp;&amp; key.getId() &lt; staff[j].getId()) {\r\n                staff[j + 1] = staff[j];        <span class=\"cm\">// shift the reference right</span>\r\n                j--;\r\n            }\r\n            staff[j + 1] = key;\r\n        }\r\n    }\r\n\r\n    <span class=\"cm\">// Binary search by id. The array must already be sorted by id.</span>\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"ty\">int</span> findById(<span class=\"ty\">Staff</span>[] staff, <span class=\"ty\">int</span> count, <span class=\"ty\">int</span> id) {\r\n        <span class=\"ty\">int</span> low = 0, high = count - 1;\r\n        <span class=\"kw\">while</span> (low &lt;= high) {\r\n            <span class=\"ty\">int</span> mid = low + (high - low) / 2;\r\n            <span class=\"ty\">int</span> midId = staff[mid].getId();\r\n            <span class=\"kw\">if</span> (midId == id) <span class=\"kw\">return</span> mid;\r\n            <span class=\"kw\">if</span> (midId &lt; id) low = mid + 1;\r\n            <span class=\"kw\">else</span> high = mid - 1;\r\n        }\r\n        <span class=\"kw\">return</span> -1;\r\n    }\r\n\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> main(<span class=\"ty\">String</span>[] args) {\r\n        <span class=\"ty\">Staff</span>[] staff = <span class=\"kw\">new</span> <span class=\"ty\">Staff</span>[6];           <span class=\"cm\">// capacity 6</span>\r\n        staff[0] = <span class=\"kw\">new</span> <span class=\"ty\">Staff</span>(<span class=\"st\">\"Mike\"</span>, 17, <span class=\"st\">\"Bio\"</span>);\r\n        staff[1] = <span class=\"kw\">new</span> <span class=\"ty\">Staff</span>(<span class=\"st\">\"Ana\"</span>, 3, <span class=\"st\">\"Mat\"</span>);\r\n        staff[2] = <span class=\"kw\">new</span> <span class=\"ty\">Staff</span>(<span class=\"st\">\"Raj\"</span>, 11, <span class=\"st\">\"Phy\"</span>);\r\n        staff[3] = <span class=\"kw\">new</span> <span class=\"ty\">Staff</span>(<span class=\"st\">\"Lee\"</span>, 9, <span class=\"st\">\"Bio\"</span>);\r\n        <span class=\"ty\">int</span> count = 4;                          <span class=\"cm\">// only four cells are used</span>\r\n\r\n        sortById(staff, count);\r\n        <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; count; i++) {\r\n            <span class=\"ty\">System</span>.out.println(staff[i].getId() + <span class=\"st\">\" \"</span> + staff[i].getName());\r\n        }\r\n        <span class=\"ty\">System</span>.out.println(<span class=\"st\">\"id 11 is at index \"</span> + findById(staff, count, 11));\r\n        <span class=\"ty\">System</span>.out.println(<span class=\"st\">\"id 99 is at index \"</span> + findById(staff, count, 99));\r\n    }\r\n}\r\n</code></pre></div>\r\n        <p>Each cell holds a <em>reference</em>. Shifting <code>staff[j + 1] = staff[j]</code> moves references, never copies Staff objects. The ids and names are used here, with names shown beneath each cell:</p>\r\n        <div class=\"direction-grid\"><div><strong>Before</strong><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Staff ids before sorting with names beneath\"><div class=\"array\"><span class=\"cell\" data-label=\"Mike\">17</span><span class=\"cell\" data-label=\"Ana\">3</span><span class=\"cell\" data-label=\"Raj\">11</span><span class=\"cell\" data-label=\"Lee\">9</span></div></div></div><div><strong>After sorting by id</strong><div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Staff ids after sorting with names beneath\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"Ana\">3</span><span class=\"cell sorted\" data-label=\"Lee\">9</span><span class=\"cell sorted\" data-label=\"Raj\">11</span><span class=\"cell sorted\" data-label=\"Mike\">17</span></div></div></div></div>\r\n        <h3>Insertion-sort trace by id</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Key (id)</th><th>Comparisons</th><th>Shifts</th><th>Array of ids after insertion</th></tr></thead><tbody><tr><td>3</td><td>1</td><td>1</td><td><code>[3, 17, 11, 9]</code></td></tr><tr><td>11</td><td>2</td><td>1</td><td><code>[3, 11, 17, 9]</code></td></tr><tr><td>9</td><td>3</td><td>2</td><td><code>[3, 9, 11, 17]</code></td></tr><tr><td><strong>Total</strong></td><td><strong>6</strong></td><td><strong>4</strong></td><td>Sorted by id</td></tr></tbody></table></div>\r\n        <h3>Binary search for id 11</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Step</th><th>low</th><th>high</th><th>mid</th><th>id at mid</th><th>Decision</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>3</td><td>1</td><td>9</td><td><code>9 &lt; 11</code> → <code>low = 2</code></td></tr><tr><td>2</td><td>2</td><td>3</td><td>2</td><td>11</td><td>Match → return <code>2</code></td></tr></tbody></table></div>\r\n        <div class=\"result-line\"><code>findById(staff, 4, 11)</code> returns <code>2</code> after 2 comparisons. For id 99 the range empties and it returns <code>-1</code>.</div>\r\n        <h3>The used part versus the whole array</h3>\r\n        <p>The staff array has capacity 6 but only 4 cells are filled. Cells 4 and 5 are <code>null</code>.</p>\r\n        <div class=\"array-wrap indexed\" role=\"img\" aria-label=\"Six-cell staff array: four used cells then two null cells\"><div class=\"array\"><span class=\"cell sorted\" data-label=\"0\">3</span><span class=\"cell sorted\" data-label=\"1\">9</span><span class=\"cell sorted\" data-label=\"2\">11</span><span class=\"cell sorted\" data-label=\"3\">17</span><span class=\"divider\" aria-hidden=\"true\"></span><span class=\"cell empty\" data-label=\"4 count\">null</span><span class=\"cell empty\" data-label=\"5\">null</span></div></div>\r\n        <p>That is why both methods take <code>count</code>. If <code>sortById</code> were called with <code>staff.length</code>, the loop would reach <code>staff[4]</code>, and <code>key.getId()</code> would throw <code>NullPointerException</code> because the cell holds no Staff object.</p>\r\n        <h3>Sorting by text instead of a number</h3>\r\n        <p>Use <code>compareTo</code>, never <code>&lt;</code>, for Strings. It returns a negative number if the left String sorts first, zero if equal, and a positive number otherwise. Only the while line changes:</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Sort by name</span></div><pre><code><span class=\"cm\">// Text key: compareTo returns a negative number when the left String sorts first.</span>\r\n<span class=\"kw\">while</span> (j &gt;= 0 &amp;&amp; key.getName().compareTo(staff[j].getName()) &lt; 0) {</code></pre></div>\r\n        <p>The same <code>main</code> then prints <code>3 Ana</code>, <code>9 Lee</code>, <code>17 Mike</code>, <code>11 Raj</code>: alphabetical by name, so the ids are now out of order. Its two lookups therefore print <code>id 11 is at index -1</code> and <code>id 99 is at index -1</code>. Binary search by id fails on this array, even though id 11 is present. Binary search by name would need the matching <code>compareTo</code> test as well, on an array sorted by name.</p>\r\n        <details><summary>Quick check: why would binary search by id fail on an array sorted by name?</summary><div class=\"answer\">The array is ordered by name, so ids appear in any order. Comparing the id at the midpoint says nothing about which half holds the target, and the search can discard the half that contains it.</div></details>\r\n        <details><summary>Quick check: after <code>staff[0] = staff[1];</code>, how many Staff objects exist?</summary><div class=\"answer\">The number of objects is unchanged. The statement copies a reference, so <code>staff[0]</code> and <code>staff[1]</code> now reach the same object, and the object previously at index 0 may become unreachable.</div></details>\r\n      "
  },
  "packages": {
    "id": "packages",
    "title": "Group related classes together",
    "body": "\r\n        <span class=\"section-no\">Java packages</span>\r\n        <h2>Group related classes together</h2>\r\n        <p class=\"lede\">A package is a named group of related classes organised in a matching folder structure. Packages improve maintainability and prevent class-name conflicts.</p>\r\n        <div class=\"use-grid\">\r\n          <div class=\"use\"><strong>Built-in packages</strong>Provided by Java, such as <code>java.lang</code>, <code>java.util</code>, and <code>java.io</code>.</div>\r\n          <div class=\"use\"><strong>User-defined packages</strong>Created by programmers to organise their own related classes.</div>\r\n        </div>\r\n        <h3>Common built-in examples</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Package</th><th>Purpose</th><th>Example</th></tr></thead><tbody>\r\n          <tr><td><code>java.lang</code></td><td>Fundamental Java classes; imported automatically</td><td><code>String</code>, <code>Math</code></td></tr>\r\n          <tr><td><code>java.util</code></td><td>Utilities and collections</td><td><code>Scanner</code>, <code>Random</code>, <code>Arrays</code></td></tr>\r\n          <tr><td><code>java.io</code></td><td>File input and output</td><td><code>PrintWriter</code>, <code>File</code></td></tr>\r\n        </tbody></table></div>\r\n        <p>A source file with no <code>package</code> statement belongs to the unnamed <em>default package</em>. Classes in a named package cannot import classes from the default package, so every file in this chapter declares a package. (The earlier array and file examples are single files in the default package, which is fine for a one-file program.)</p>\r\n\r\n        <h3 id=\"package-tree\">The required folder hierarchy</h3>\r\n        <div class=\"paper-card\"><pre><code>project/\r\n├── src/\r\n│   ├── pkg/\r\n│   │   ├── A.java\r\n│   │   ├── B.java\r\n│   │   └── Tester.java\r\n│   └── app/\r\n│       └── Main.java\r\n└── classes/            ← created by javac -d\r\n    ├── pkg/\r\n    │   ├── A.class\r\n    │   ├── B.class\r\n    │   └── Tester.class\r\n    └── app/\r\n        └── Main.class</code></pre></div>\r\n        <p>The <code>pkg</code> folders under <code>src</code> and <code>classes</code> mirror each other. The package name is the folder path with dots instead of slashes.</p>\r\n\r\n        <h3>Inside every packaged source file</h3>\r\n        <p><code>A</code> offers a method, <code>B</code> a second helper, and <code>Tester</code> is the class you run because it alone contains <code>main</code>.</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>src/pkg/A.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy src/pkg/A.java\">Copy code</button></div><pre><code><span class=\"kw\">package</span> pkg; <span class=\"cm\">// first non-comment statement</span>\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">A</span> {\r\n    <span class=\"cm\">// public: other packages may call this method after importing pkg.A</span>\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> greet() {\r\n        <span class=\"ty\">System</span>.out.println(<span class=\"st\">\"Hello from pkg.A\"</span>);\r\n    }\r\n}\r\n</code></pre></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>src/pkg/B.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy src/pkg/B.java\">Copy code</button></div><pre><code><span class=\"kw\">package</span> pkg;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">B</span> {\r\n    <span class=\"cm\">// public: visible everywhere</span>\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"ty\">int</span> twice(<span class=\"ty\">int</span> x) {\r\n        <span class=\"kw\">return</span> 2 * x;\r\n    }\r\n\r\n    <span class=\"cm\">// no modifier = package-private: visible only inside pkg</span>\r\n    <span class=\"kw\">static</span> <span class=\"ty\">String</span> secret() {\r\n        <span class=\"kw\">return</span> <span class=\"st\">\"pkg only\"</span>;\r\n    }\r\n}\r\n</code></pre></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>src/pkg/Tester.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy src/pkg/Tester.java\">Copy code</button></div><pre><code><span class=\"kw\">package</span> pkg;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">Tester</span> {\r\n    <span class=\"cm\">// The class you run must contain a main method like this one.</span>\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> main(<span class=\"ty\">String</span>[] args) {\r\n        <span class=\"ty\">A</span>.greet();                        <span class=\"cm\">// same package: no import needed</span>\r\n        <span class=\"ty\">System</span>.out.println(<span class=\"ty\">B</span>.twice(21));  <span class=\"cm\">// prints 42</span>\r\n        <span class=\"ty\">System</span>.out.println(<span class=\"ty\">B</span>.secret());   <span class=\"cm\">// legal here: same package</span>\r\n    }\r\n}\r\n</code></pre></div>\r\n\r\n        <h3 id=\"package-access\">Imports and visibility</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Choose specific, wildcard, or fully qualified</span></div><pre><code><span class=\"kw\">import</span> java.util.<span class=\"ty\">Scanner</span>;  <span class=\"cm\">// one class</span>\r\n<span class=\"kw\">import</span> java.io.*;           <span class=\"cm\">// every public class directly in java.io</span>\r\n<span class=\"kw\">import</span> pkg.<span class=\"ty\">A</span>;               <span class=\"cm\">// a user-defined class</span>\r\n\r\n<span class=\"cm\">// Without an import you may write the fully qualified name instead:</span>\r\npkg.<span class=\"ty\">A</span>.greet();</code></pre></div>\r\n        <ul class=\"checklist\">\r\n          <li><code>java.lang</code> is imported automatically. Classes in the <em>same</em> package never need an import.</li>\r\n          <li>A wildcard such as <code>java.io.*</code> imports the classes directly in that package, not classes in its sub-packages.</li>\r\n          <li>An import only shortens names. It does not grant access to members that are not visible.</li>\r\n        </ul>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Modifier</th><th>Same class</th><th>Same package</th><th>Subclass in another package</th><th>Any other class</th></tr></thead><tbody><tr><td><code>public</code></td><td>Yes</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td><code>protected</code></td><td>Yes</td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td><em>(none)</em> · package-private</td><td>Yes</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td><code>private</code></td><td>Yes</td><td>No</td><td>No</td><td>No</td></tr></tbody></table></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>src/app/Main.java · uses another package</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy src/app/Main.java · uses another package\">Copy code</button></div><pre><code><span class=\"kw\">package</span> app;\r\n\r\n<span class=\"kw\">import</span> pkg.<span class=\"ty\">A</span>;   <span class=\"cm\">// one class from another package</span>\r\n<span class=\"kw\">import</span> pkg.<span class=\"ty\">B</span>;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">Main</span> {\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> main(<span class=\"ty\">String</span>[] args) {\r\n        <span class=\"ty\">A</span>.greet();\r\n        <span class=\"ty\">System</span>.out.println(<span class=\"ty\">B</span>.twice(5));   <span class=\"cm\">// prints 10</span>\r\n        <span class=\"cm\">// B.secret();  // compile error: secret() is not public</span>\r\n    }\r\n}\r\n</code></pre></div>\r\n\r\n        <h3 id=\"package-implementation\">Compile and run from the project folder</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Commands</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy Commands\">Copy code</button></div><pre><code>javac -d classes -sourcepath src src/pkg/*.java\r\njava -classpath classes pkg.Tester\r\n\r\njavac -d classes -sourcepath src src/app/Main.java\r\njava -classpath classes app.Main</code></pre></div>\r\n        <div class=\"flow-steps\"><div class=\"flow-step\"><b>1</b><div><code>-sourcepath src</code> tells the compiler where source files live.</div></div><div class=\"flow-step\"><b>2</b><div><code>-d classes</code> tells it where to create the package folders and <code>.class</code> files.</div></div><div class=\"flow-step\"><b>3</b><div><code>-classpath classes</code> tells Java where compiled packages begin.</div></div><div class=\"flow-step\"><b>4</b><div><code>pkg.Tester</code> uses the fully qualified class name: package plus class. It must contain <code>main</code>.</div></div><div class=\"flow-step\"><b>5</b><div>Forward slashes in the paths also work on Windows command prompts.</div></div></div>\r\n        <div class=\"audit-grid\">\r\n          <div class=\"from-scratch\"><strong>Build a package from scratch</strong><ol><li>Create <code>src/pkg</code> and <code>classes</code>.</li><li>Place <code>package pkg;</code> first in each source file.</li><li>Save source files inside <code>src/pkg</code>.</li><li>Give one class a <code>main</code> method.</li><li>Compile with <code>-d classes</code>.</li><li>Run the fully qualified class name.</li></ol></div>\r\n          <div class=\"debug-list\"><strong>Debug checklist</strong><ul><li>Package name and folder path must match.</li><li>Java is case-sensitive.</li><li>Run from the folder above <code>classes</code>.</li><li>Do not include <code>.class</code> in the run command.</li><li>The class you run needs <code>main</code>.</li></ul></div>\r\n        </div>\r\n\r\n        <h3 id=\"package-errors\">Reading the error messages</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Message</th><th>Usual cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Error: Could not find or load main class pkg.Tester</code></td><td>Running from the wrong folder, a wrong classpath, a misspelled name, or adding <code>.class</code>.</td><td>Run from the folder that contains <code>classes</code>; use <code>-classpath classes pkg.Tester</code> with no extension.</td></tr><tr><td><code>Error: Main method not found in class pkg.A</code></td><td>The class has no <code>public static void main(String[] args)</code>.</td><td>Run a class that has <code>main</code>, such as <code>pkg.Tester</code>.</td></tr><tr><td><code>error: package pkg does not exist</code></td><td>Compiling <code>app.Main</code> without telling javac where <code>pkg</code> lives.</td><td>Add <code>-sourcepath src</code> (or <code>-classpath classes</code> if pkg is already compiled).</td></tr><tr><td><code>error: class Wrong is public, should be declared in a file named Wrong.java</code></td><td>A public class name must match its file name.</td><td>Rename the file or the class.</td></tr><tr><td><code>error: secret() is not public in B; cannot be accessed from outside package</code></td><td>Calling a package-private member from another package.</td><td>Make it <code>public</code>, or call it only from inside <code>pkg</code>.</td></tr><tr><td>Compiles, but <code>java pkg.A</code> says it cannot find the class</td><td>The <code>package</code> statement does not match the folder, so the <code>.class</code> landed in a different folder.</td><td>Make the <code>package</code> statement, the source folder, and the run command agree.</td></tr></tbody></table></div>\r\n\r\n        <h3>Worked example · source to running class</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Stage</th><th>Input</th><th>What Java resolves</th><th>Result</th></tr></thead><tbody><tr><td>Declare</td><td><code>package pkg;</code> in <code>src/pkg/Tester.java</code></td><td>The source folder path must equal the package name</td><td><code>src/pkg/Tester.java</code></td></tr><tr><td>Compile</td><td><code>javac -d classes -sourcepath src src/pkg/*.java</code></td><td><code>-d classes</code> creates <code>classes/pkg/</code>; one <code>.class</code> per class</td><td><code>classes/pkg/A.class</code>, <code>B.class</code>, <code>Tester.class</code></td></tr><tr><td>Run</td><td><code>java -classpath classes pkg.Tester</code></td><td>Classpath root <code>classes</code> + <code>pkg.Tester</code> → <code>classes/pkg/Tester.class</code>; then <code>main</code> runs</td><td><code>Hello from pkg.A</code> · <code>42</code> · <code>pkg only</code></td></tr><tr><td>Cross-package</td><td><code>import pkg.A;</code> in <code>src/app/Main.java</code></td><td><code>-sourcepath src</code> lets javac find <code>src/pkg/A.java</code> when compiling <code>app.Main</code></td><td><code>classes/app/Main.class</code>; prints <code>Hello from pkg.A</code> · <code>10</code></td></tr></tbody></table></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Console output of java -classpath classes pkg.Tester</span></div><pre><code>Hello from pkg.A\r\n42\r\npkg only</code></pre></div>\r\n      "
  },
  "lab-work": {
    "id": "lab-work",
    "title": "Recommended implementation sequence",
    "body": "\r\n        <span class=\"section-no\">Lab05</span>\r\n        <h2>Recommended implementation sequence</h2>\r\n        <p class=\"lede\">Complete the lab in dependency order so each piece is testable before the next one uses it. Step 1 is only folder set-up; steps 2–4 are written out in <a href=\"#lab-marks\">the marks application</a>; steps 5–8 in <a href=\"#lab-staff\">the staff and files section</a>.</p>\r\n        <div class=\"flow-steps\"><div class=\"flow-step\"><b>1</b><div><strong>Create folders and package.</strong> Make <code>src/lab05</code> and <code>classes</code>; put <code>package lab05;</code> at the top of each source file.</div></div><div class=\"flow-step\"><b>2</b><div><strong>Implement <code>merge</code>.</strong> Test it on two already sorted halves before adding recursion.</div></div><div class=\"flow-step\"><b>3</b><div><strong>Implement <code>mergeSort</code>.</strong> Use the base case, midpoint, left call, right call, then merge.</div></div><div class=\"flow-step\"><b>4</b><div><strong>Build the marks application.</strong> Generate 30 marks from 0 to 100 with a <code>while</code> loop, print before and after, and repeat until the user stops.</div></div><div class=\"flow-step\"><b>5</b><div><strong>Draw the UML first.</strong> Put shared fields and methods in <code>Doctor</code>; connect <code>GP</code> and <code>Surgeon</code> with inheritance arrows.</div></div><div class=\"flow-step\"><b>6</b><div><strong>Implement and test each class.</strong> Test constructors, <code>tagName()</code>, and <code>calculatePay()</code> before file reading.</div></div><div class=\"flow-step\"><b>7</b><div><strong>Read <code>data.txt</code>.</strong> Use field count to decide whether each record represents a Doctor, GP, or Surgeon.</div></div><div class=\"flow-step\"><b>8</b><div><strong>Write the three output files.</strong> Route subclasses first, close resources, then inspect every output file.</div></div></div>\r\n        <div class=\"callout\"><strong>Final check:</strong> compile from the folder above <code>src</code> and <code>classes</code>, then run with <code>java -classpath classes lab05.ClassName</code>.</div>\r\n      "
  },
  "lab-marks": {
    "id": "lab-marks",
    "title": "The marks application: merge sort, random data, and a repeat loop",
    "body": "\r\n        <span class=\"section-no\">Lab05 / Steps 2–4</span>\r\n        <h2>The marks application: merge sort, random data, and a repeat loop</h2>\r\n        <p class=\"lede\">Both files live in <code>src/lab05/</code> and start with <code>package lab05;</code>. <code>MergeSort</code> holds the two methods; <code>MarksApp</code> is the class you run.</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>src/lab05/MergeSort.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy src/lab05/MergeSort.java\">Copy code</button></div><pre><code><span class=\"kw\">package</span> lab05;\r\n\r\n<span class=\"kw\">import</span> java.util.<span class=\"ty\">Arrays</span>;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">MergeSort</span> {\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> mergeSort(<span class=\"ty\">int</span>[] arr, <span class=\"ty\">int</span> start, <span class=\"ty\">int</span> end) {\r\n        <span class=\"cm\">// A zero- or one-value range is already sorted.</span>\r\n        <span class=\"kw\">if</span> (start &lt; end) {\r\n            <span class=\"ty\">int</span> mid = start + (end - start) / 2;\r\n            mergeSort(arr, start, mid);      <span class=\"cm\">// sort the left half</span>\r\n            mergeSort(arr, mid + 1, end);    <span class=\"cm\">// sort the right half</span>\r\n            merge(arr, start, mid, end);     <span class=\"cm\">// combine the two sorted halves</span>\r\n        }\r\n    }\r\n\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> merge(<span class=\"ty\">int</span>[] arr, <span class=\"ty\">int</span> s, <span class=\"ty\">int</span> m, <span class=\"ty\">int</span> e) {\r\n        <span class=\"cm\">// Copy both halves; the right half starts at m + 1.</span>\r\n        <span class=\"ty\">int</span>[] left = <span class=\"ty\">Arrays</span>.copyOfRange(arr, s, m + 1);\r\n        <span class=\"ty\">int</span>[] right = <span class=\"ty\">Arrays</span>.copyOfRange(arr, m + 1, e + 1);\r\n        <span class=\"ty\">int</span> i = 0, j = 0, cur = s;\r\n\r\n        <span class=\"cm\">// Take the smaller front value each time (&lt;= keeps the merge stable).</span>\r\n        <span class=\"kw\">while</span> (i &lt; left.length &amp;&amp; j &lt; right.length)\r\n            arr[cur++] = left[i] &lt;= right[j] ? left[i++] : right[j++];\r\n\r\n        <span class=\"cm\">// Exactly one of these loops copies the leftovers.</span>\r\n        <span class=\"kw\">while</span> (i &lt; left.length) arr[cur++] = left[i++];\r\n        <span class=\"kw\">while</span> (j &lt; right.length) arr[cur++] = right[j++];\r\n    }\r\n}\r\n</code></pre></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>src/lab05/MarksApp.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy src/lab05/MarksApp.java\">Copy code</button></div><pre><code><span class=\"kw\">package</span> lab05;\r\n\r\n<span class=\"kw\">import</span> java.util.<span class=\"ty\">Arrays</span>;\r\n<span class=\"kw\">import</span> java.util.<span class=\"ty\">Random</span>;\r\n<span class=\"kw\">import</span> java.util.<span class=\"ty\">Scanner</span>;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">MarksApp</span> {\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> main(<span class=\"ty\">String</span>[] args) {\r\n        <span class=\"ty\">Random</span> random = <span class=\"kw\">new</span> <span class=\"ty\">Random</span>();\r\n        <span class=\"ty\">Scanner</span> keyboard = <span class=\"kw\">new</span> <span class=\"ty\">Scanner</span>(<span class=\"ty\">System</span>.in); <span class=\"cm\">// create ONCE, outside the loop</span>\r\n        <span class=\"ty\">String</span> again = <span class=\"st\">\"y\"</span>;                        <span class=\"cm\">// lets the first pass run</span>\r\n\r\n        <span class=\"kw\">while</span> (again.equalsIgnoreCase(<span class=\"st\">\"y\"</span>)) {\r\n            <span class=\"ty\">int</span>[] marks = <span class=\"kw\">new</span> <span class=\"ty\">int</span>[30];\r\n\r\n            <span class=\"cm\">// Fill every cell with a random mark from 0 to 100 inclusive.</span>\r\n            <span class=\"ty\">int</span> i = 0;\r\n            <span class=\"kw\">while</span> (i &lt; marks.length) {\r\n                marks[i] = random.nextInt(101); <span class=\"cm\">// upper bound is exclusive</span>\r\n                i++;\r\n            }\r\n\r\n            <span class=\"ty\">System</span>.out.println(<span class=\"st\">\"Before: \"</span> + <span class=\"ty\">Arrays</span>.toString(marks));\r\n            <span class=\"ty\">MergeSort</span>.mergeSort(marks, 0, marks.length - 1);\r\n            <span class=\"ty\">System</span>.out.println(<span class=\"st\">\"After:  \"</span> + <span class=\"ty\">Arrays</span>.toString(marks));\r\n\r\n            <span class=\"ty\">System</span>.out.print(<span class=\"st\">\"Run again? (y/n) \"</span>);\r\n            again = keyboard.nextLine().trim();\r\n        }\r\n        keyboard.close();\r\n    }\r\n}\r\n</code></pre></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Compile and run</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy Compile and run\">Copy code</button></div><pre><code>javac -d classes -sourcepath src src/lab05/*.java\r\njava -classpath classes lab05.MarksApp</code></pre></div>\r\n        <p>Each run prints a <code>Before:</code> line of 30 random marks, an <code>After:</code> line with the same 30 values in ascending order, and the prompt <code>Run again? (y/n)</code>. Answering <code>y</code> repeats with fresh random marks; anything else ends the loop.</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Detail</th><th>Why it is written that way</th></tr></thead><tbody><tr><td><code>random.nextInt(101)</code></td><td>The bound is <em>exclusive</em>, so <code>nextInt(101)</code> gives 0 to 100 inclusive. <code>nextInt(100)</code> could never produce 100.</td></tr><tr><td><code>int i = 0; while (i &lt; marks.length) { … i++; }</code></td><td>The lab asks for a <code>while</code> loop. The three parts of a <code>for</code> loop are still there: start, condition, update.</td></tr><tr><td><code>String again = &quot;y&quot;</code></td><td>Starting at <code>y</code> lets the loop body run once before the user is asked anything.</td></tr><tr><td><code>Scanner keyboard</code> created once</td><td>Closing a Scanner on <code>System.in</code> closes the keyboard stream. Create it before the loop and close it after.</td></tr><tr><td><code>MergeSort.mergeSort(marks, 0, marks.length - 1)</code></td><td>Both bounds are <em>inclusive</em> indexes, so the last index is <code>length - 1</code>.</td></tr></tbody></table></div>\r\n        <details><summary>Quick check: what would go wrong if <code>int[] marks = new int[30];</code> were placed before the <code>while (again…)</code> loop?</summary><div class=\"answer\">Nothing would visibly break. The fill loop sits inside the <code>while</code>, so every run still overwrites all 30 cells with new random marks, prints a fresh <code>Before:</code> line, and sorts it. Declaring the array inside the loop is still better: each run starts from a brand-new array, no values can leak from the previous run, and <code>marks</code> exists only where it is used.</div></details>\r\n      "
  },
  "lab-staff": {
    "id": "lab-staff",
    "title": "Inheritance, record routing, and three output files",
    "body": "\r\n        <span class=\"section-no\">Lab05 / Steps 5–8</span>\r\n        <h2>Inheritance, record routing, and three output files</h2>\r\n        <div class=\"callout\"><strong>Read this first.</strong> The class names and the sequence come from the lab outline, but this guide does not contain the lab handout. The field names, pay formulas, and field counts below are <strong>placeholders that demonstrate the pattern</strong>. Replace them with the exact specification you were given.</div>\r\n        <p class=\"lede\">The pattern has four ideas: a shared superclass, subclasses that extend it, an array typed as the superclass that holds all three kinds, and routing each record to the right file.</p>\r\n        <div class=\"uml\" role=\"img\" aria-label=\"UML class diagram: GP and Surgeon both extend Doctor\">\r\n          <div class=\"uml-box\"><b>Doctor</b><span># name : String</span><span># basePay : double</span><span>+ tagName() : String</span><span>+ calculatePay() : double</span></div>\r\n          <div class=\"uml-arrow\" aria-hidden=\"true\">△<br>│</div>\r\n          <div class=\"uml-row\">\r\n            <div class=\"uml-box\"><b>GP</b><span>- patients : int</span><span>+ tagName() : String</span><span>+ calculatePay() : double</span></div>\r\n            <div class=\"uml-box\"><b>Surgeon</b><span>- operations : int</span><span>- specialty : String</span><span>+ tagName() : String</span><span>+ calculatePay() : double</span></div>\r\n          </div>\r\n        </div>\r\n        <p class=\"fine-print\">The hollow triangle points to the superclass. <code>#</code> protected, <code>-</code> private, <code>+</code> public.</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>src/lab05/Doctor.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy src/lab05/Doctor.java\">Copy code</button></div><pre><code><span class=\"kw\">package</span> lab05;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">Doctor</span> {\r\n    <span class=\"kw\">protected</span> <span class=\"ty\">String</span> name;      <span class=\"cm\">// protected: visible to subclasses</span>\r\n    <span class=\"kw\">protected</span> <span class=\"ty\">double</span> basePay;\r\n\r\n    <span class=\"kw\">public</span> <span class=\"ty\">Doctor</span>(<span class=\"ty\">String</span> name, <span class=\"ty\">double</span> basePay) {\r\n        <span class=\"kw\">this</span>.name = name;\r\n        <span class=\"kw\">this</span>.basePay = basePay;\r\n    }\r\n\r\n    <span class=\"kw\">public</span> <span class=\"ty\">String</span> tagName() { <span class=\"kw\">return</span> <span class=\"st\">\"Dr \"</span> + name; }\r\n    <span class=\"kw\">public</span> <span class=\"ty\">double</span> calculatePay() { <span class=\"kw\">return</span> basePay; }\r\n}\r\n</code></pre></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>src/lab05/GP.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy src/lab05/GP.java\">Copy code</button></div><pre><code><span class=\"kw\">package</span> lab05;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> GP <span class=\"kw\">extends</span> <span class=\"ty\">Doctor</span> {          <span class=\"cm\">// a GP IS-A Doctor</span>\r\n    <span class=\"kw\">private</span> <span class=\"ty\">int</span> patients;\r\n\r\n    <span class=\"kw\">public</span> GP(<span class=\"ty\">String</span> name, <span class=\"ty\">double</span> basePay, <span class=\"ty\">int</span> patients) {\r\n        <span class=\"kw\">super</span>(name, basePay);             <span class=\"cm\">// must be the first statement</span>\r\n        <span class=\"kw\">this</span>.patients = patients;\r\n    }\r\n\r\n    <span class=\"kw\">@Override</span> <span class=\"kw\">public</span> <span class=\"ty\">String</span> tagName() { <span class=\"kw\">return</span> <span class=\"st\">\"GP \"</span> + name; }\r\n    <span class=\"kw\">@Override</span> <span class=\"kw\">public</span> <span class=\"ty\">double</span> calculatePay() {\r\n        <span class=\"kw\">return</span> <span class=\"kw\">super</span>.calculatePay() + patients * 2.0; <span class=\"cm\">// placeholder formula</span>\r\n    }\r\n}\r\n</code></pre></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>src/lab05/Surgeon.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy src/lab05/Surgeon.java\">Copy code</button></div><pre><code><span class=\"kw\">package</span> lab05;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">Surgeon</span> <span class=\"kw\">extends</span> <span class=\"ty\">Doctor</span> {\r\n    <span class=\"kw\">private</span> <span class=\"ty\">int</span> operations;\r\n    <span class=\"kw\">private</span> <span class=\"ty\">String</span> specialty;\r\n\r\n    <span class=\"kw\">public</span> <span class=\"ty\">Surgeon</span>(<span class=\"ty\">String</span> name, <span class=\"ty\">double</span> basePay, <span class=\"ty\">int</span> operations, <span class=\"ty\">String</span> specialty) {\r\n        <span class=\"kw\">super</span>(name, basePay);\r\n        <span class=\"kw\">this</span>.operations = operations;\r\n        <span class=\"kw\">this</span>.specialty = specialty;\r\n    }\r\n\r\n    <span class=\"kw\">@Override</span> <span class=\"kw\">public</span> <span class=\"ty\">String</span> tagName() { <span class=\"kw\">return</span> <span class=\"st\">\"Surgeon \"</span> + name; }\r\n    <span class=\"kw\">@Override</span> <span class=\"kw\">public</span> <span class=\"ty\">double</span> calculatePay() {\r\n        <span class=\"kw\">return</span> <span class=\"kw\">super</span>.calculatePay() + operations * 50.0; <span class=\"cm\">// placeholder formula</span>\r\n    }\r\n}\r\n</code></pre></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Idea</th><th>In the code</th><th>Why it matters</th></tr></thead><tbody><tr><td><code>extends</code></td><td><code>GP extends Doctor</code></td><td>A GP is a Doctor, so it inherits <code>name</code>, <code>basePay</code>, and every public method.</td></tr><tr><td><code>super(…)</code></td><td>First line of each subclass constructor</td><td>Runs <code>Doctor</code>’s constructor to set the shared fields.</td></tr><tr><td><code>@Override</code></td><td><code>tagName()</code>, <code>calculatePay()</code></td><td>A subclass supplies its own version. <code>super.calculatePay()</code> reuses the parent’s.</td></tr><tr><td>Superclass array</td><td><code>Doctor[] staff</code></td><td>A <code>Doctor</code> cell may hold a Doctor, GP, or Surgeon object. The call <code>staff[i].calculatePay()</code> runs the version belonging to the real object.</td></tr></tbody></table></div>\r\n        <h3>Read the records, then route them</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>src/lab05/StaffReport.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy src/lab05/StaffReport.java\">Copy code</button></div><pre><code><span class=\"kw\">package</span> lab05;\r\n\r\n<span class=\"kw\">import</span> java.io.<span class=\"ty\">File</span>;\r\n<span class=\"kw\">import</span> java.io.<span class=\"ty\">FileNotFoundException</span>;\r\n<span class=\"kw\">import</span> java.io.<span class=\"ty\">PrintWriter</span>;\r\n<span class=\"kw\">import</span> java.util.<span class=\"ty\">Scanner</span>;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">StaffReport</span> {\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> main(<span class=\"ty\">String</span>[] args) <span class=\"kw\">throws</span> <span class=\"ty\">FileNotFoundException</span> {\r\n        <span class=\"ty\">Doctor</span>[] staff = <span class=\"kw\">new</span> <span class=\"ty\">Doctor</span>[20];   <span class=\"cm\">// capacity; holds Doctor, GP and Surgeon</span>\r\n        <span class=\"ty\">int</span> count = 0;                     <span class=\"cm\">// logical size</span>\r\n\r\n        <span class=\"kw\">try</span> (<span class=\"ty\">Scanner</span> in = <span class=\"kw\">new</span> <span class=\"ty\">Scanner</span>(<span class=\"kw\">new</span> <span class=\"ty\">File</span>(<span class=\"st\">\"data.txt\"</span>))) {\r\n            <span class=\"kw\">while</span> (in.hasNextLine() &amp;&amp; count &lt; staff.length) {\r\n                <span class=\"ty\">Doctor</span> d = parse(in.nextLine());\r\n                <span class=\"kw\">if</span> (d != <span class=\"kw\">null</span>) staff[count++] = d;   <span class=\"cm\">// skip records with an unrecognised field count</span>\r\n            }\r\n        }\r\n\r\n        <span class=\"cm\">// All three writers are closed automatically, which flushes their output.</span>\r\n        <span class=\"kw\">try</span> (<span class=\"ty\">PrintWriter</span> doctors = <span class=\"kw\">new</span> <span class=\"ty\">PrintWriter</span>(<span class=\"st\">\"doctors.txt\"</span>);\r\n             <span class=\"ty\">PrintWriter</span> gps = <span class=\"kw\">new</span> <span class=\"ty\">PrintWriter</span>(<span class=\"st\">\"gps.txt\"</span>);\r\n             <span class=\"ty\">PrintWriter</span> surgeons = <span class=\"kw\">new</span> <span class=\"ty\">PrintWriter</span>(<span class=\"st\">\"surgeons.txt\"</span>)) {\r\n            <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; count; i++) {\r\n                <span class=\"ty\">Doctor</span> d = staff[i];\r\n                <span class=\"cm\">// Test subclasses first: every GP and Surgeon is also a Doctor.</span>\r\n                <span class=\"ty\">PrintWriter</span> target = (d <span class=\"kw\">instanceof</span> <span class=\"ty\">Surgeon</span>) ? surgeons\r\n                                   : (d <span class=\"kw\">instanceof</span> GP) ? gps\r\n                                   : doctors;\r\n                target.println(d.tagName() + <span class=\"st\">\" \"</span> + d.calculatePay());\r\n            }\r\n        }\r\n    }\r\n\r\n    <span class=\"cm\">// The number of fields on the line decides which class to build.</span>\r\n    <span class=\"kw\">static</span> <span class=\"ty\">Doctor</span> parse(<span class=\"ty\">String</span> line) {\r\n        <span class=\"ty\">String</span>[] f = line.trim().split(<span class=\"st\">\"\\\\s+\"</span>);\r\n        <span class=\"kw\">switch</span> (f.length) {\r\n            <span class=\"kw\">case</span> 2:  <span class=\"kw\">return</span> <span class=\"kw\">new</span> <span class=\"ty\">Doctor</span>(f[0], <span class=\"ty\">Double</span>.parseDouble(f[1]));\r\n            <span class=\"kw\">case</span> 3:  <span class=\"kw\">return</span> <span class=\"kw\">new</span> GP(f[0], <span class=\"ty\">Double</span>.parseDouble(f[1]), <span class=\"ty\">Integer</span>.parseInt(f[2]));\r\n            <span class=\"kw\">case</span> 4:  <span class=\"kw\">return</span> <span class=\"kw\">new</span> <span class=\"ty\">Surgeon</span>(f[0], <span class=\"ty\">Double</span>.parseDouble(f[1]),\r\n                                        <span class=\"ty\">Integer</span>.parseInt(f[2]), f[3]);\r\n            <span class=\"kw\">default</span>: <span class=\"kw\">return</span> <span class=\"kw\">null</span>;          <span class=\"cm\">// wrong field count</span>\r\n        }\r\n    }\r\n}\r\n</code></pre></div>\r\n        <p>With this <code>data.txt</code>:</p>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>data.txt</span></div><pre><code>Ann 5000\r\nBo 5000 40\r\nCy 5000 3 cardiac\r\nbroken\r\nDee 4000</code></pre></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Line</th><th>Fields</th><th>Object built</th><th>Written to</th></tr></thead><tbody><tr><td><code>Ann 5000</code></td><td>2</td><td>Doctor</td><td><code>doctors.txt</code>: <code>Dr Ann 5000.0</code></td></tr><tr><td><code>Bo 5000 40</code></td><td>3</td><td>GP</td><td><code>gps.txt</code>: <code>GP Bo 5080.0</code></td></tr><tr><td><code>Cy 5000 3 cardiac</code></td><td>4</td><td>Surgeon</td><td><code>surgeons.txt</code>: <code>Surgeon Cy 5150.0</code></td></tr><tr><td><code>broken</code></td><td>1</td><td>none (<code>null</code>)</td><td>skipped</td></tr><tr><td><code>Dee 4000</code></td><td>2</td><td>Doctor</td><td><code>doctors.txt</code>: <code>Dr Dee 4000.0</code></td></tr></tbody></table></div>\r\n        <div class=\"audit-grid\">\r\n          <div class=\"from-scratch\"><strong>Build it in this order</strong><ol><li>Draw the UML and decide what is shared.</li><li>Write and test <code>Doctor</code>.</li><li>Write <code>GP</code> and <code>Surgeon</code>; test each constructor and method.</li><li>Parse one line into one object.</li><li>Loop over the file, storing into the array with a <code>count</code>.</li><li>Open three writers and route each object.</li><li>Open every output file and check it.</li></ol></div>\r\n          <div class=\"debug-list\"><strong>Debug checklist</strong><ul><li>Test <code>Surgeon</code> and <code>GP</code> before <code>Doctor</code> in the routing chain. A Doctor test first would match all three kinds.</li><li><code>super(…)</code> must be the first statement of a subclass constructor.</li><li>Close the writers (try-with-resources does it) or buffered output may never reach the file.</li><li>Skip a record whose field count is not recognised rather than crashing.</li></ul></div>\r\n        </div>\r\n        <h3 id=\"package-questions\">Package and lab questions</h3>\r\n        <details><summary>Why is <code>classes</code> the classpath rather than <code>classes/lab05</code>?</summary><div class=\"answer\">The classpath names the root above the package hierarchy. Java then uses <code>lab05.ClassName</code> to find <code>lab05/ClassName.class</code> below that root.</div></details>\r\n        <details><summary>Where must <code>package lab05;</code> appear?</summary><div class=\"answer\">It must be the first non-comment statement in the source file.</div></details>\r\n        <details><summary>Why does <code>java -classpath classes pkg.A</code> fail even though <code>A.class</code> exists?</summary><div class=\"answer\">Class <code>A</code> only defines <code>greet()</code>. To start a program Java needs <code>public static void main(String[] args)</code> in the named class. Run <code>pkg.Tester</code>, which contains it.</div></details>\r\n        <details><summary>What is the difference between an <code>import</code> and a fully qualified name?</summary><div class=\"answer\">Both reach the same class. An import lets you write the short name <code>A</code> for the rest of the file; the fully qualified name <code>pkg.A</code> spells out the package each time. Neither bypasses visibility rules.</div></details>\r\n        <details><summary>Can a <code>Doctor[]</code> array hold a <code>GP</code>?</summary><div class=\"answer\">Yes. A GP is a Doctor, so a Doctor reference may refer to it. The array stores references, so the cell holds a reference to the GP object and <code>calculatePay()</code> runs the GP version.</div></details>\r\n        <div id=\"package-summary\" class=\"method-summary\"><strong>Packages in one sentence</strong><p>The declared package, source folders, compiled folders, imports, classpath root, and fully qualified class name must all describe the same hierarchy, and the class you run must contain <code>main</code>.</p></div>\r\n      "
  },
  "test1-overview": {
    "id": "test1-overview",
    "title": "How to approach this 50-mark past paper",
    "body": "\r\n        <span class=\"section-no\">Exam-style walkthroughs · How to approach this 50-mark past paper</span>\r\n        <h2>How to approach this 50-mark past paper</h2>\r\n        <p class=\"lede\">These are guided exam-style questions adapted from the supplied 2025/26 past paper and answer sheet, not a replacement for attempting the paper under timed conditions.</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Question</th><th>Marks</th><th>Main skill</th><th>Suggested time</th></tr></thead><tbody><tr><td>Q1</td><td>20</td><td>Classify methods, constructors, references, memory diagram</td><td>28 min</td></tr><tr><td>Q2</td><td>15</td><td>Imports, file reading, parsing, object array</td><td>21 min</td></tr><tr><td>Q3</td><td>15</td><td>Descending trace, binary probes, Big-O</td><td>21 min</td></tr></tbody></table></div><div class=\"callout\"><strong>Timing is a starting point.</strong> The paper allows 70 minutes for 50 marks, about 1.4 minutes per mark. Leave a short final scan for missing labels, indexes, and return values.</div><p>For every code answer, state the precondition, trace the variables the marker can award, and give the final output or array. If a term is ambiguous, explain the behaviour before choosing the label.</p>\r\n      "
  },
  "test1-q1": {
    "id": "test1-q1",
    "title": "Classes, constructors, and one shared object",
    "body": "\r\n        <span class=\"section-no\">Past paper / Q1 · 20 marks · Classes, constructors, and one shared object</span>\r\n        <h2>Classes, constructors, and one shared object</h2>\r\n        <p class=\"lede\">The marks come from explaining what code creates and changes, not from counting variable names.</p>\r\n        <div class=\"callout\"><strong>Reading assumption.</strong> The scan has a handwritten correction on the assignment line. This walkthrough reads it as <code>m = n;</code>, which matches the reference-sharing question and answer <code>90.0</code> twice.</div>\r\n        <h3>Question 1(a): C, M, A — classify from behaviour</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Mist.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy Mist.java\">Copy code</button></div><pre><code><span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">Mist</span> {\r\n    <span class=\"kw\">private</span> <span class=\"ty\">int</span> num;\r\n    <span class=\"kw\">public</span> <span class=\"ty\">Mist</span>(<span class=\"ty\">int</span> n) { num = n; }\r\n    <span class=\"kw\">public</span> <span class=\"ty\">double</span> aa() { <span class=\"kw\">return</span> num; }\r\n    <span class=\"kw\">public</span> <span class=\"ty\">boolean</span> isSmall(<span class=\"ty\">int</span> n) { <span class=\"kw\">return</span> (num &gt; n); }\r\n    <span class=\"kw\">public</span> <span class=\"kw\">void</span> bb(<span class=\"ty\">int</span> n) { num += n; }\r\n}\r\n</code></pre></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Member</th><th>Best label</th><th>Reason</th></tr></thead><tbody><tr><td><code>Mist(int n)</code></td><td>C — constructor</td><td>Same name as the class, no return type, and runs when <code>new Mist(...)</code> creates an object.</td></tr><tr><td><code>aa()</code></td><td>A — accessor</td><td>Reads <code>num</code>, returns it as a <code>double</code>, and changes no field.</td></tr><tr><td><code>bb(int n)</code></td><td>M — mutator</td><td>Changes the stored field with <code>num += n</code>.</td></tr><tr><td><code>isSmall(int n)</code></td><td>Accessor/query, or neither under a narrow definition</td><td>It reads state and returns a Boolean answer without changing state. Some lecturers call every read-only query an accessor; a narrow definition reserves accessor for a direct field getter. State the definition and reason.</td></tr></tbody></table></div>\r\n        <div class=\"callout\"><strong>How to earn the mark when terminology is ambiguous.</strong> Do not guess from the method name. Write what the method reads, returns, and changes. For <code>isSmall</code>, explicitly say that it is a read-only query and then use your lecturer's accessor definition.</div>\r\n        <h3>Questions 1(b)–(e): constructors</h3>\r\n        <div class=\"flow-steps\"><div class=\"flow-step\"><b>b</b><div>A constructor gives a newly created object its valid initial field values.</div></div><div class=\"flow-step\"><b>c</b><div><code>Mist(int n)</code> is a parameterised (non-default) constructor.</div></div><div class=\"flow-step\"><b>d</b><div>The other expected type is a default/no-argument constructor such as <code>Mist()</code>.</div></div><div class=\"flow-step\"><b>e</b><div>Java supplies an implicit no-argument constructor only when the class declares no constructor at all. Declaring <code>Mist(int)</code> means <code>new Mist()</code> does not compile unless you write <code>Mist()</code> yourself.</div></div></div>\r\n        <h3>Questions 1(f)–(g): count objects, then draw references</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Misty.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy Misty.java\">Copy code</button></div><pre><code><span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">Misty</span> {\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> main(<span class=\"ty\">String</span>[] args) {\r\n        <span class=\"ty\">Mist</span> n, m;\r\n        n = <span class=\"kw\">new</span> <span class=\"ty\">Mist</span>(50);\r\n        n.bb(20);\r\n        m = n;\r\n        m.bb(20);\r\n        <span class=\"ty\">System</span>.out.println(n.aa());\r\n        <span class=\"ty\">System</span>.out.println(m.aa());\r\n    }\r\n}\r\n</code></pre></div>\r\n        <p>There is <strong>one object</strong> because the code contains one <code>new Mist(...)</code>. A declaration makes reference variables, and an assignment such as <code>m = n</code> copies a reference; neither makes another object.</p>\r\n        <div class=\"paper-card\"><h3>1 · Mist n, m;</h3><div class=\"memory-board\"><div class=\"memory-sketch\"><div class=\"sketch-object-row\"><div><div class=\"sketch-ref\"><strong>n</strong><small>unassigned</small></div><div class=\"sketch-ref\"><strong>m</strong><small>unassigned</small></div></div><div class=\"staff-sketch\"><div class=\"staff-sketch-title\">No Mist object yet</div><div class=\"sketch-field\"><span class=\"sketch-field-name\">heap</span><span>empty for this code</span></div></div></div><p class=\"sketch-note\">Two reference variables exist. No constructor has run and no object exists.</p></div></div></div><div class=\"paper-card\"><h3>2 · n = new Mist(50);</h3><div class=\"memory-board\"><div class=\"memory-sketch\"><div class=\"sketch-object-row\"><div><div class=\"sketch-ref\"><strong>n</strong><small>M1</small></div><div class=\"sketch-ref\"><strong>m</strong><small>unassigned</small></div></div><span class=\"sketch-arrow\">→</span><div class=\"staff-sketch\"><div class=\"staff-sketch-title\">Mist object · M1</div><div class=\"sketch-field\"><span class=\"sketch-field-name\">num</span><span>50</span></div></div></div><p class=\"sketch-note\">Exactly one new expression creates exactly one Mist object. n points to it.</p></div></div></div><div class=\"paper-card\"><h3>3 · n.bb(20);</h3><div class=\"memory-board\"><div class=\"memory-sketch\"><div class=\"sketch-object-row\"><div><div class=\"sketch-ref\"><strong>n</strong><small>M1</small></div><div class=\"sketch-ref\"><strong>m</strong><small>unassigned</small></div></div><span class=\"sketch-arrow\">→</span><div class=\"staff-sketch\"><div class=\"staff-sketch-title\">Mist object · M1</div><div class=\"sketch-field\"><span class=\"sketch-field-name\">num</span><span><span class=\"rewrite\"><span class=\"old-value\">50</span><span class=\"red-arrow\">→</span><span class=\"new-value\">70</span></span></span></div></div></div><p class=\"sketch-note\">bb mutates M1. The reference n does not change.</p></div></div></div><div class=\"paper-card\"><h3>4 · m = n;</h3><div class=\"memory-board\"><div class=\"memory-sketch\"><div class=\"sketch-object-row\"><div><div class=\"sketch-ref\"><strong>n</strong><small>M1</small></div><div class=\"sketch-ref\"><strong>m</strong><small>M1</small></div></div><span class=\"sketch-arrow\">→</span><div class=\"staff-sketch\"><div class=\"staff-sketch-title\">Mist object · M1</div><div class=\"sketch-field\"><span class=\"sketch-field-name\">num</span><span>70</span></div></div></div><p class=\"sketch-note\">The reference is copied. Both variables point to the same object; no second Mist is created.</p></div></div></div><div class=\"paper-card\"><h3>5 · m.bb(20);</h3><div class=\"memory-board\"><div class=\"memory-sketch\"><div class=\"sketch-object-row\"><div><div class=\"sketch-ref\"><strong>n</strong><small>M1</small></div><div class=\"sketch-ref\"><strong>m</strong><small>M1</small></div></div><span class=\"sketch-arrow\">→</span><div class=\"staff-sketch\"><div class=\"staff-sketch-title\">Mist object · M1</div><div class=\"sketch-field\"><span class=\"sketch-field-name\">num</span><span><span class=\"rewrite\"><span class=\"old-value\">70</span><span class=\"red-arrow\">→</span><span class=\"new-value\">90</span></span></span></div></div></div><p class=\"sketch-note\">Calling through m mutates M1, so n observes the same updated num.</p></div></div></div>\r\n        <h3>Question 1(h): output</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Console output</span></div><pre><code>90.0\r\n90.0</code></pre></div>\r\n        <p>Both calls reach M1, whose final <code>num</code> is 90. The <code>.0</code> appears because <code>aa()</code> declares a <code>double</code> return type, so Java widens the stored <code>int</code> before printing.</p>\r\n        <details><summary>Self-check: what would change if the line were m = new Mist(70)?</summary><div class=\"answer\">There would be two objects. n would still point to the first object with num 70; m would point to a second object that becomes 90. The output would be 70.0 then 90.0.</div></details>\r\n      "
  },
  "test1-q2": {
    "id": "test1-q2",
    "title": "Read a file into Book objects",
    "body": "\r\n        <span class=\"section-no\">Past paper / Q2 · 15 marks · Read a file into Book objects</span>\r\n        <h2>Read a file into Book objects</h2>\r\n        <p class=\"lede\">Follow one record all the way from text, through parsing, to a non-null array cell.</p>\r\n        <h3>Questions 2(a)–(c): imports, reader, and array</h3>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Approach</th><th>Required imports</th><th>Open the current-directory file</th></tr></thead><tbody><tr><td>The question's FileReader route</td><td><code>java.io.FileReader</code>, <code>BufferedReader</code>, <code>IOException</code></td><td><code>FileReader fr = new FileReader(\"books.txt\");</code></td></tr><tr><td>Scanner alternative</td><td><code>java.io.File</code>, <code>FileNotFoundException</code>, <code>java.util.Scanner</code></td><td><code>new Scanner(new File(\"books.txt\"))</code></td></tr></tbody></table></div>\r\n        <p><code>new Book[50]</code> creates one array with capacity 50. Every cell starts as <code>null</code>; it does not call the Book constructor 50 times.</p>\r\n        <div class=\"memory-board\" role=\"img\" aria-label=\"Book array with the first three cells referring to Book objects and remaining cells null\"><div class=\"memory-sketch\"><div class=\"sketch-heading\">A 50-cell reference array after reading three records</div><div class=\"sketch-array-wrap\"><div class=\"sketch-array\"><div class=\"sketch-slot changed\" data-index=\"0\">B1</div><div class=\"sketch-slot changed\" data-index=\"1\">B2</div><div class=\"sketch-slot changed\" data-index=\"2\">B3</div><div class=\"sketch-slot\" data-index=\"3\">null</div><div class=\"sketch-slot\" data-index=\"4\">null</div><div class=\"sketch-slot\" data-index=\"5\">null</div></div><div class=\"sketch-note\">Shown: cells 0–5. Cells 6–49 are also null. count = 3.</div></div></div></div>\r\n        <h3>Question 2(d): turn each file line into one object</h3>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>books.txt used for the trace</span></div><pre><code>Hobbit,20.99\r\nDune, 15.50\r\nEmma,9.75</code></pre></div>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Line</th><th>After split and trim</th><th>Book stored</th><th>count after</th></tr></thead><tbody><tr><td><code>Hobbit,20.99</code></td><td>title = Hobbit; price = 20.99</td><td><code>books[0]</code></td><td>1</td></tr><tr><td><code>Dune, 15.50</code></td><td>title = Dune; price = 15.50</td><td><code>books[1]</code></td><td>2</td></tr><tr><td><code>Emma,9.75</code></td><td>title = Emma; price = 9.75</td><td><code>books[2]</code></td><td>3</td></tr></tbody></table></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Book.java</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy Book.java\">Copy code</button></div><pre><code><span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">Book</span> {\r\n    <span class=\"kw\">private</span> <span class=\"ty\">String</span> title;\r\n    <span class=\"kw\">private</span> <span class=\"ty\">double</span> price;\r\n\r\n    <span class=\"kw\">public</span> <span class=\"ty\">Book</span>(<span class=\"ty\">String</span> ttl, <span class=\"ty\">double</span> pr) {\r\n        title = ttl;\r\n        price = pr;\r\n    }\r\n    <span class=\"kw\">public</span> <span class=\"ty\">String</span> getTitle() { <span class=\"kw\">return</span> title; }\r\n    <span class=\"kw\">public</span> <span class=\"ty\">double</span> getPrice() { <span class=\"kw\">return</span> price; }\r\n    <span class=\"kw\">public</span> <span class=\"kw\">void</span> setTitle(<span class=\"ty\">String</span> ttl) { title = ttl; }\r\n    <span class=\"kw\">public</span> <span class=\"kw\">void</span> setPrice(<span class=\"ty\">double</span> pr) { price = pr; }\r\n    <span class=\"kw\">public</span> <span class=\"ty\">String</span> toString() { <span class=\"kw\">return</span> title + <span class=\"st\">\" (\"</span> + price + <span class=\"st\">\")\"</span>; }\r\n    <span class=\"kw\">public</span> <span class=\"ty\">boolean</span> equals(<span class=\"ty\">Book</span> bk) { <span class=\"kw\">return</span> title.equals(bk.title) &amp;&amp; price == bk.price; }\r\n}\r\n</code></pre></div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>BooksApp.java · BufferedReader answer</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy BooksApp.java · BufferedReader answer\">Copy code</button></div><pre><code><span class=\"kw\">import</span> java.io.<span class=\"ty\">BufferedReader</span>;\r\n<span class=\"kw\">import</span> java.io.<span class=\"ty\">FileReader</span>;\r\n<span class=\"kw\">import</span> java.io.<span class=\"ty\">IOException</span>;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">BooksApp</span> {\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> main(<span class=\"ty\">String</span>[] args) {\r\n        <span class=\"ty\">Book</span>[] books = <span class=\"kw\">new</span> <span class=\"ty\">Book</span>[50];              <span class=\"cm\">// 50 empty (null) cells</span>\r\n        <span class=\"ty\">int</span> count = 0;                             <span class=\"cm\">// how many cells really hold a Book</span>\r\n\r\n        <span class=\"kw\">try</span> (<span class=\"ty\">BufferedReader</span> br = <span class=\"kw\">new</span> <span class=\"ty\">BufferedReader</span>(<span class=\"kw\">new</span> <span class=\"ty\">FileReader</span>(<span class=\"st\">\"books.txt\"</span>))) {\r\n            <span class=\"ty\">String</span> line;\r\n            <span class=\"kw\">while</span> ((line = br.readLine()) != <span class=\"kw\">null</span> &amp;&amp; count &lt; books.length) {\r\n                <span class=\"ty\">String</span>[] details = line.split(<span class=\"st\">\",\"</span>);              <span class=\"cm\">// \"Hobbit,20.99\" -&gt; [\"Hobbit\", \"20.99\"]</span>\r\n                <span class=\"ty\">String</span> title = details[0].trim();\r\n                <span class=\"ty\">double</span> price = <span class=\"ty\">Double</span>.parseDouble(details[1].trim());\r\n                books[count] = <span class=\"kw\">new</span> <span class=\"ty\">Book</span>(title, price);\r\n                count++;\r\n            }\r\n        } <span class=\"kw\">catch</span> (<span class=\"ty\">IOException</span> e) {\r\n            <span class=\"ty\">System</span>.out.println(<span class=\"st\">\"Error reading file: \"</span> + e.getMessage());\r\n        }\r\n\r\n        <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; count; i++) {          <span class=\"cm\">// only the filled cells</span>\r\n            <span class=\"ty\">System</span>.out.println(books[i].getTitle());\r\n        }\r\n    }\r\n}\r\n</code></pre></div>\r\n        <p>The checked exception is handled by <code>catch (IOException e)</code>; try-with-resources closes the reader even if parsing fails. <code>trim()</code> removes spaces around comma-separated fields, and <code>Double.parseDouble</code> converts the price text.</p>\r\n        <h3>Question 2(e): print only cells that contain objects</h3>\r\n        <div class=\"callout\"><strong>The 50-cell trap.</strong> If only three records were read, an enhanced-for loop over all 50 cells eventually calls <code>getTitle()</code> on <code>null</code> and throws <code>NullPointerException</code>. Loop from 0 to <code>count - 1</code>. Use <code>println</code> because the question requires one title per line.</div>\r\n        <div class=\"code-panel\"><div class=\"code-head\"><span>Scanner route · also compiled and run</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy Scanner route · also compiled and run\">Copy code</button></div><pre><code><span class=\"kw\">import</span> java.io.<span class=\"ty\">File</span>;\r\n<span class=\"kw\">import</span> java.io.<span class=\"ty\">FileNotFoundException</span>;\r\n<span class=\"kw\">import</span> java.util.<span class=\"ty\">Scanner</span>;\r\n\r\n<span class=\"kw\">public</span> <span class=\"kw\">class</span> <span class=\"ty\">BooksScanner</span> {\r\n    <span class=\"kw\">public</span> <span class=\"kw\">static</span> <span class=\"kw\">void</span> main(<span class=\"ty\">String</span>[] args) {\r\n        <span class=\"ty\">Book</span>[] books = <span class=\"kw\">new</span> <span class=\"ty\">Book</span>[50];\r\n        <span class=\"ty\">int</span> count = 0;\r\n\r\n        <span class=\"kw\">try</span> (<span class=\"ty\">Scanner</span> in = <span class=\"kw\">new</span> <span class=\"ty\">Scanner</span>(<span class=\"kw\">new</span> <span class=\"ty\">File</span>(<span class=\"st\">\"books.txt\"</span>))) {\r\n            <span class=\"kw\">while</span> (in.hasNextLine() &amp;&amp; count &lt; books.length) {\r\n                <span class=\"ty\">String</span>[] details = in.nextLine().split(<span class=\"st\">\",\"</span>);\r\n                books[count] = <span class=\"kw\">new</span> <span class=\"ty\">Book</span>(details[0].trim(), <span class=\"ty\">Double</span>.parseDouble(details[1].trim()));\r\n                count++;\r\n            }\r\n        } <span class=\"kw\">catch</span> (<span class=\"ty\">FileNotFoundException</span> e) {\r\n            <span class=\"ty\">System</span>.out.println(<span class=\"st\">\"File not found!\"</span>);\r\n        }\r\n\r\n        <span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = 0; i &lt; count; i++) {\r\n            <span class=\"ty\">System</span>.out.println(books[i].getTitle());\r\n        }\r\n    }\r\n}\r\n</code></pre></div>\r\n        <details><summary>Why keep count separate from books.length?</summary><div class=\"answer\">books.length is capacity: always 50. count is logical size: how many Book objects were actually stored. Algorithms that read the data must stop at count.</div></details>\r\n      "
  },
  "test1-q3": {
    "id": "test1-q3",
    "title": "Sorting, searching, and Big-O",
    "body": "\r\n        <span class=\"section-no\">Past paper / Q3 · 15 marks · Sorting, searching, and Big-O</span>\r\n        <h2>Sorting, searching, and Big-O</h2>\r\n        <p class=\"lede\">Use the detailed simulated chapters for the full traces; this page keeps the marking targets together.</p>\r\n        <div class=\"table-scroll\"><table><thead><tr><th>Part</th><th>Model answer</th><th>Full teaching section</th></tr></thead><tbody><tr><td>(a) Purpose of sorting</td><td>Arrange data so later operations such as searching, grouping, and reporting are easier.</td><td><a href=\"#why-sort\">Why sort data?</a></td></tr><tr><td>(b) Descending insertion sort</td><td>Eight passes; final array <code>[90, 83, 76, 59, 50, 32, 12, 6, 2]</code>.</td><td><a href=\"#insertion-test\">Test 1 question 3(b)</a></td></tr><tr><td>(c) Binary search for 88</td><td>Four probes, then the active range is empty.</td><td><a href=\"#binary-examples\">Binary worked examples</a></td></tr><tr><td>(d) Worst-case Big-O</td><td>Linear <code>O(n)</code>; binary <code>O(log n)</code>; selection and bubble <code>O(n²)</code>.</td><td><a href=\"#growth\">Big-O side by side</a></td></tr><tr><td>(e) Most efficient</td><td>Binary search among the four listed algorithms, provided the array is sorted.</td><td><a href=\"#binary-summary\">Binary test summary</a></td></tr></tbody></table></div>\r\n        <div class=\"callout\"><strong>Midpoint formula.</strong> Use <code>low + (high - low) / 2</code>. It gives the same midpoint without adding two potentially huge positive indexes first, so it avoids integer overflow.</div>\r\n        <h3>Typical mark-losing slips</h3>\r\n        <ul class=\"checklist\"><li>Sorting ascending when the question says descending.</li><li>Showing comparisons instead of the array at the end of each insertion pass.</li><li>Writing <code>O(n²)</code> for binary search.</li><li>Choosing linear search as most efficient while a sorted array and binary search are available.</li><li>Counting the final empty range as another array comparison.</li></ul>\r\n      "
  },
  "mixed-practice": {
    "id": "mixed-practice",
    "title": "Mixed practice: try each one before opening the answer",
    "body": "\r\n        <span class=\"section-no\">Review / Mixed practice</span>\r\n        <h2>Mixed practice: try each one before opening the answer</h2>\r\n        <p class=\"lede\">Problems from the array, searching, sorting and Lab05 chapters. Work them on paper first: write the indexes, boundaries, and values at every step.</p>\r\n        <h3>Trace and predict</h3>\r\n        <p><strong>1 ·</strong> What does this print?</p><div class=\"code-panel\"><div class=\"code-head\"><span>Code</span></div><pre><code><span class=\"ty\">int</span>[] a = {3, 8, 1};\r\n<span class=\"kw\">for</span> (<span class=\"ty\">int</span> i = a.length - 1; i &gt;= 0; i--) {\r\n    <span class=\"ty\">System</span>.out.print(a[i] + <span class=\"st\">\" \"</span>);\r\n}</code></pre></div><details><summary>Reveal the answer</summary><div class=\"answer\"><code>1 8 3</code>. The loop starts at the last valid index, 2, and counts down to 0, so it prints the array in reverse.</div></details>\r\n        <p><strong>2 ·</strong> Binary search for <code>63</code> in <code>[8, 18, 23, 29, 34, 42, 54, 63, 72, 85]</code>. How many comparisons, and what is returned?</p><details><summary>Reveal the answer</summary><div class=\"answer\"><div class=\"table-scroll\"><table><thead><tr><th>Step</th><th>low</th><th>high</th><th>mid</th><th>arr[mid]</th><th>Decision</th></tr></thead><tbody><tr><td>1</td><td>0</td><td>9</td><td>4</td><td>34</td><td><code>63 &gt; 34</code> → <code>low = 5</code></td></tr><tr><td>2</td><td>5</td><td>9</td><td>7</td><td>63</td><td>Match → return <code>7</code></td></tr></tbody></table></div><p>2 comparisons; returns <code>7</code>.</p></div></details>\r\n        <p><strong>3 ·</strong> One ascending bubble-sort pass on <code>[5, 1, 4, 2, 8]</code>. What is the array and how many swaps?</p><details><summary>Reveal the answer</summary><div class=\"answer\">Compare <code>5&gt;1</code> swap → <code>[1,5,4,2,8]</code>; <code>5&gt;4</code> swap → <code>[1,4,5,2,8]</code>; <code>5&gt;2</code> swap → <code>[1,4,2,5,8]</code>; <code>5&gt;8</code> no swap. Result <code>[1, 4, 2, 5, 8]</code> with 4 comparisons and 3 swaps. The 5 was carried right until it met the larger 8.</div></details>\r\n        <p><strong>4 ·</strong> Selection sort on <code>[29, 10, 14, 37, 13]</code>. Show the array after the first two outer iterations.</p><details><summary>Reveal the answer</summary><div class=\"answer\"><code>i = 0</code>: minimum <code>10</code> at index 1; swap → <code>[10, 29, 14, 37, 13]</code>. <code>i = 1</code>: minimum of <code>[29, 14, 37, 13]</code> is <code>13</code> at index 4; swap → <code>[10, 13, 14, 37, 29]</code>.</div></details>\r\n        <p><strong>5 ·</strong> Merge the sorted runs <code>[2, 9]</code> and <code>[4, 5, 8]</code>. List each choice.</p><details><summary>Reveal the answer</summary><div class=\"answer\"><div class=\"table-scroll\"><table><thead><tr><th>Output index</th><th>left front</th><th>right front</th><th>Chosen</th></tr></thead><tbody><tr><td>0</td><td>2</td><td>4</td><td>2</td></tr><tr><td>1</td><td>9</td><td>4</td><td>4</td></tr><tr><td>2</td><td>9</td><td>5</td><td>5</td></tr><tr><td>3</td><td>9</td><td>8</td><td>8</td></tr><tr><td>4</td><td>9</td><td>empty</td><td>9 (leftover)</td></tr></tbody></table></div><p>Result <code>[2, 4, 5, 8, 9]</code> after 4 comparisons.</p></div></details>\r\n        <h3>Find the bug</h3>\r\n        <p><strong>6 ·</strong> This binary search returns <code>-1</code> for <code>search([5], 5)</code>. Why?</p><div class=\"code-panel\"><div class=\"code-head\"><span>Code</span></div><pre><code><span class=\"kw\">while</span> (low &lt; high) {\r\n    <span class=\"ty\">int</span> mid = low + (high - low) / 2;\r\n    <span class=\"cm\">// compare arr[mid] with key and move low or high</span>\r\n}</code></pre></div><details><summary>Reveal the answer</summary><div class=\"answer\">With one value, <code>low = 0</code> and <code>high = 0</code>. The condition <code>0 &lt; 0</code> is false, so the loop never examines the only candidate. The condition must be <code>low &lt;= high</code> so a one-cell range is checked.</div></details>\r\n        <p><strong>7 ·</strong> The inner loop of a bubble sort reads <code>for (int j = 0; j &lt; arr.length; j++)</code> and compares <code>arr[j]</code> with <code>arr[j + 1]</code>. What fails?</p><details><summary>Reveal the answer</summary><div class=\"answer\">On the last iteration <code>j</code> is <code>length − 1</code>, so <code>arr[j + 1]</code> is index <code>length</code>: <code>ArrayIndexOutOfBoundsException</code>. The bound must be <code>arr.length - 1 - pass</code>.</div></details>\r\n        <p><strong>8 ·</strong> In merge, the left half is copied with <code>Arrays.copyOfRange(arr, s, m)</code>. What happens to <code>[4, 2]</code>?</p><details><summary>Reveal the answer</summary><div class=\"answer\"><code>copyOfRange</code> excludes its end index, so the left copy is empty and the 4 at index <code>m</code> is lost. The right copy is <code>[2]</code>, and the array becomes <code>[2, 2]</code>. The call needs <code>m + 1</code>.</div></details>\r\n        <p><strong>9 ·</strong> This loop reads the file <code>63 bad 72</code>. What do <code>count</code> and <code>buffer</code> hold afterwards, and what is wrong?</p><div class=\"code-panel\"><div class=\"code-head\"><span>Code</span></div><pre><code><span class=\"kw\">while</span> (input.hasNext()) {\r\n    count++;                        <span class=\"cm\">// too early</span>\r\n    <span class=\"kw\">if</span> (input.hasNextInt()) {\r\n        buffer[count - 1] = input.nextInt();\r\n    } <span class=\"kw\">else</span> {\r\n        input.next();               <span class=\"cm\">// skip the bad token</span>\r\n    }\r\n}</code></pre></div><details><summary>Reveal the answer</summary><div class=\"answer\"><code>count</code> is <code>3</code> and the used part of <code>buffer</code> is <code>[63, 0, 72]</code>: the invalid token still consumed a slot, leaving an unset <code>0</code> inside the used part. <code>count</code> must increase only after a valid integer is stored.</div></details>\r\n        <h3>Insertion sort and merge sort</h3>\r\n        <p><strong>10 ·</strong> Trace insertion sort on <code>[3, 1, 2]</code>. How many comparisons and shifts does it make?</p><details><summary>Reveal the answer</summary><div class=\"answer\"><code>3</code> comparisons and <code>2</code> shifts. Key <code>1</code>: compare with <code>3</code>, shift once, reach the left edge: <code>[1, 3, 2]</code> (1 comparison, 1 shift). Key <code>2</code>: compare with <code>3</code>, shift, then compare with <code>1</code> and stop: <code>[1, 2, 3]</code> (2 comparisons, 1 shift).</div></details>\r\n        <p><strong>11 ·</strong> List every call and every merge for <code>mergeSort(arr, 0, 3)</code> on <code>[5, 2, 4, 1]</code>, in the order they happen. How many comparisons?</p><details><summary>Reveal the answer</summary><div class=\"answer\">Calls: <code>(0,3)</code> mid 1, <code>(0,1)</code> mid 0, <code>(0,0)</code>, <code>(1,1)</code>, <code>(2,3)</code> mid 2, <code>(2,2)</code>, <code>(3,3)</code>. Merges, depth-first: <code>merge(0,0,1)</code> → <code>[2, 5]</code>; <code>merge(2,2,3)</code> → <code>[1, 4]</code>; <code>merge(0,1,3)</code> → <code>[1, 2, 4, 5]</code>. Comparisons: 1 + 1 + 3 = <code>5</code>.</div></details>\r\n        <h3>Packages</h3>\r\n        <p><strong>12 ·</strong> <code>app.Main</code> imports <code>pkg.A</code>. Which two commands compile and run it from the project folder?</p><details><summary>Reveal the answer</summary><div class=\"answer\"><code>javac -d classes -sourcepath src src/app/Main.java</code> then <code>java -classpath classes app.Main</code>. The sourcepath lets javac find <code>src/pkg/A.java</code>; the classpath root lets Java find <code>classes/app/Main.class</code>.</div></details>\r\n      "
  },
  "quiz": {
    "id": "quiz",
    "title": "Cumulative quiz",
    "body": "\r\n        <span class=\"section-no\">Self-check</span>\r\n        <h2>Cumulative quiz</h2>\r\n        <p class=\"lede\">Choose an answer to see at once whether it is right and why. You can change an answer; the explanation updates. Use the score button when you have finished.</p>\r\n        <form class=\"quiz-form\" id=\"quiz-form\">\r\n          <p class=\"quiz-status\" id=\"quiz-status\">Answered 0 of 34 · 0 correct</p>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>1. What does an unsuccessful search return in these lecture methods?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q1\" value=\"a\"> <span class=\"opt-text\">0</span></label><label class=\"option\"><input type=\"radio\" name=\"q1\" value=\"b\"> <span class=\"opt-text\">-1</span></label><label class=\"option\"><input type=\"radio\" name=\"q1\" value=\"c\"> <span class=\"opt-text\">The array length</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Index 0 is a real position, the first cell. Returning 0 would claim the key was found at the start.</div><div class=\"why\" data-for=\"b\" hidden>-1 can never be a valid index, so it safely signals “not found”.</div><div class=\"why\" data-for=\"c\" hidden>The length is one past the last valid index. It is not a position, and these methods do not return it.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"c\"><legend>2. Which condition must be true before using binary search?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q2\" value=\"a\"> <span class=\"opt-text\">The array must contain no duplicates</span></label><label class=\"option\"><input type=\"radio\" name=\"q2\" value=\"b\"> <span class=\"opt-text\">The array must contain integers</span></label><label class=\"option\"><input type=\"radio\" name=\"q2\" value=\"c\"> <span class=\"opt-text\">The array must be sorted</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Duplicates are allowed. Binary search simply returns one matching index.</div><div class=\"why\" data-for=\"b\" hidden>Any values that can be ordered work, such as Strings compared with <code>compareTo</code>.</div><div class=\"why\" data-for=\"c\" hidden>Each comparison discards half the range, which is only valid when order tells you which half can hold the key.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"a\"><legend>3. For a five-position array, what is the final valid index?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q3\" value=\"a\"> <span class=\"opt-text\">4</span></label><label class=\"option\"><input type=\"radio\" name=\"q3\" value=\"b\"> <span class=\"opt-text\">5</span></label><label class=\"option\"><input type=\"radio\" name=\"q3\" value=\"c\"> <span class=\"opt-text\">6</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Indexes run 0 to <code>length − 1</code>, so the five cells are 0, 1, 2, 3, 4.</div><div class=\"why\" data-for=\"b\" hidden>Index 5 would be the sixth cell. Using it throws <code>ArrayIndexOutOfBoundsException</code>.</div><div class=\"why\" data-for=\"c\" hidden>Index 6 is even further past the end.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"c\"><legend>4. In insertion sort, what happens when the key is smaller than the value to its left?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q4\" value=\"a\"> <span class=\"opt-text\">The key is deleted</span></label><label class=\"option\"><input type=\"radio\" name=\"q4\" value=\"b\"> <span class=\"opt-text\">The whole array is reversed</span></label><label class=\"option\"><input type=\"radio\" name=\"q4\" value=\"c\"> <span class=\"opt-text\">The larger value shifts right</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>The key was saved in <code>key</code> precisely so it is not lost.</div><div class=\"why\" data-for=\"b\" hidden>Only larger prefix values move, one position each. Nothing is reversed.</div><div class=\"why\" data-for=\"c\" hidden>Shifting makes room, and the key is inserted into the gap afterwards.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>5. What is the base case for recursive binary search?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q5\" value=\"a\"> <span class=\"opt-text\"><code>mid == 0</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q5\" value=\"b\"> <span class=\"opt-text\"><code>low &gt; high</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q5\" value=\"c\"> <span class=\"opt-text\"><code>array.length == 0</code> only</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>The midpoint being 0 has nothing to do with running out of candidates.</div><div class=\"why\" data-for=\"b\" hidden>When <code>low</code> passes <code>high</code> no indexes remain, so the key is absent.</div><div class=\"why\" data-for=\"c\" hidden>Every sub-range can become empty, not just the whole array. <code>low &gt; high</code> covers all of them.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"a\"><legend>6. Why do <code>one</code> and <code>emps[4]</code> show the same updated Staff fields?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q6\" value=\"a\"> <span class=\"opt-text\">They refer to the same object</span></label><label class=\"option\"><input type=\"radio\" name=\"q6\" value=\"b\"> <span class=\"opt-text\">Java automatically copied the fields twice</span></label><label class=\"option\"><input type=\"radio\" name=\"q6\" value=\"c\"> <span class=\"opt-text\">Arrays cannot store null</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Assignment copied the reference, not the object. One Staff object exists, reached by two names.</div><div class=\"why\" data-for=\"b\" hidden>Java copies nothing here. Only the reference was copied.</div><div class=\"why\" data-for=\"c\" hidden>Arrays can store null. It is the default for reference cells, and it is unrelated to this result.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>7. What does <code>javac -d classes</code> control?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q7\" value=\"a\"> <span class=\"opt-text\">The name of the source package</span></label><label class=\"option\"><input type=\"radio\" name=\"q7\" value=\"b\"> <span class=\"opt-text\">Where compiled package folders and class files are created</span></label><label class=\"option\"><input type=\"radio\" name=\"q7\" value=\"c\"> <span class=\"opt-text\">Which class contains <code>main</code></span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>The name comes from the <code>package</code> statement inside the file.</div><div class=\"why\" data-for=\"b\" hidden><code>-d</code> sets the destination root, and javac builds the package folders beneath it.</div><div class=\"why\" data-for=\"c\" hidden>That is decided when you run a class, not when you compile.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"c\"><legend>8. Which package is imported automatically?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q8\" value=\"a\"> <span class=\"opt-text\"><code>java.io</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q8\" value=\"b\"> <span class=\"opt-text\"><code>java.util</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q8\" value=\"c\"> <span class=\"opt-text\"><code>java.lang</code></span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Classes such as <code>File</code> and <code>PrintWriter</code> need an import.</div><div class=\"why\" data-for=\"b\" hidden><code>Scanner</code>, <code>Random</code>, and <code>Arrays</code> need an import.</div><div class=\"why\" data-for=\"c\" hidden><code>String</code>, <code>Math</code>, and <code>System</code> live here, and it is always imported.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"a\"><legend>9. What is merge sort’s worst-case time complexity?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q9\" value=\"a\"> <span class=\"opt-text\"><code>O(n log n)</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q9\" value=\"b\"> <span class=\"opt-text\"><code>O(n²)</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q9\" value=\"c\"> <span class=\"opt-text\"><code>O(1)</code></span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>It halves the range about log₂ n times and merges all n values at each level, in every case.</div><div class=\"why\" data-for=\"b\" hidden>That is the cost of bubble, selection, and insertion sort in their worst case.</div><div class=\"why\" data-for=\"c\" hidden>Constant time would mean the work does not depend on n, which is impossible for sorting.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>10. Which line makes insertion sort stable when equal values are present?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q10\" value=\"a\"> <span class=\"opt-text\">Using <code>&lt;=</code> in the shift condition</span></label><label class=\"option\"><input type=\"radio\" name=\"q10\" value=\"b\"> <span class=\"opt-text\">Using <code>&lt;</code> in the shift condition</span></label><label class=\"option\"><input type=\"radio\" name=\"q10\" value=\"c\"> <span class=\"opt-text\">Starting <code>i</code> at 0</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden><code>&lt;=</code> shifts equal values, letting the key cross an equal one, which breaks stability.</div><div class=\"why\" data-for=\"b\" hidden>A strict test stops at an equal value, so equal values never cross.</div><div class=\"why\" data-for=\"c\" hidden>That does not affect equal values. Index 0 is already a sorted section, so starting at 1 is simply correct.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"c\"><legend>11. What does one complete ascending bubble-sort pass guarantee?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q11\" value=\"a\"> <span class=\"opt-text\">The smallest value is always at index 0</span></label><label class=\"option\"><input type=\"radio\" name=\"q11\" value=\"b\"> <span class=\"opt-text\">Every value is fully sorted</span></label><label class=\"option\"><input type=\"radio\" name=\"q11\" value=\"c\"> <span class=\"opt-text\">The largest active value reaches the right edge</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>The pass carries a large value to the right, not a small one to the left.</div><div class=\"why\" data-for=\"b\" hidden>Usually several passes are needed. One pass fixes one value.</div><div class=\"why\" data-for=\"c\" hidden>Each swap carries the current largest value onward until the end of the active range.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"a\"><legend>12. Why is selection sort not adaptive?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q12\" value=\"a\"> <span class=\"opt-text\">It scans the remaining suffix even when the array is sorted</span></label><label class=\"option\"><input type=\"radio\" name=\"q12\" value=\"b\"> <span class=\"opt-text\">It always uses recursion</span></label><label class=\"option\"><input type=\"radio\" name=\"q12\" value=\"c\"> <span class=\"opt-text\">It requires a second array</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Finding the minimum always requires scanning the whole suffix, so sorted input saves nothing.</div><div class=\"why\" data-for=\"b\" hidden>The standard version is iterative, and recursion has no bearing on adaptivity.</div><div class=\"why\" data-for=\"c\" hidden>It sorts in place, so no second array is needed.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>13. Which insertion-sort condition produces descending order?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q13\" value=\"a\"> <span class=\"opt-text\"><code>key &lt; array[j]</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q13\" value=\"b\"> <span class=\"opt-text\"><code>key &gt; array[j]</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q13\" value=\"c\"> <span class=\"opt-text\"><code>key == array[j]</code></span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>That is the ascending condition.</div><div class=\"why\" data-for=\"b\" hidden>Shifting while the key is larger leaves larger values toward the left, which is descending.</div><div class=\"why\" data-for=\"c\" hidden>Shifting only equal values would not order anything.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"c\"><legend>14. Which statement correctly compares merge-sort implementations?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q14\" value=\"a\"> <span class=\"opt-text\">Only the recursive version can merge</span></label><label class=\"option\"><input type=\"radio\" name=\"q14\" value=\"b\"> <span class=\"opt-text\">The iterative version has quadratic time</span></label><label class=\"option\"><input type=\"radio\" name=\"q14\" value=\"c\"> <span class=\"opt-text\">Both can run in <code>O(n log n)</code>; one uses calls and one grows run width</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Both versions call the same <code>merge</code> method.</div><div class=\"why\" data-for=\"b\" hidden>Bottom-up merge sort is also <code>O(n log n)</code>.</div><div class=\"why\" data-for=\"c\" hidden>The recursive form splits with calls; the bottom-up form merges runs of width 1, 2, 4, and so on.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>15. What is the default value of every cell in <code>new int[3]</code>?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q15\" value=\"a\"> <span class=\"opt-text\"><code>null</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q15\" value=\"b\"> <span class=\"opt-text\"><code>0</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q15\" value=\"c\"> <span class=\"opt-text\">Whatever was left in memory</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden><code>null</code> is the default for reference cells. An <code>int</code> cell holds a number.</div><div class=\"why\" data-for=\"b\" hidden>Java always initialises numeric cells to 0, <code>boolean</code> cells to false, and reference cells to null.</div><div class=\"why\" data-for=\"c\" hidden>Java never exposes leftover memory. New arrays are always initialised.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>16. Which loop header visits every cell of <code>marks</code> exactly once?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q16\" value=\"a\"> <span class=\"opt-text\"><code>for (int i = 0; i &lt;= marks.length; i++)</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q16\" value=\"b\"> <span class=\"opt-text\"><code>for (int i = 0; i &lt; marks.length; i++)</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q16\" value=\"c\"> <span class=\"opt-text\"><code>for (int i = 1; i &lt; marks.length; i++)</code></span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>The final iteration uses index <code>marks.length</code>, one past the end, and throws an exception.</div><div class=\"why\" data-for=\"b\" hidden><code>i</code> runs from 0 to <code>length − 1</code>, which are exactly the valid indexes.</div><div class=\"why\" data-for=\"c\" hidden>That skips index 0.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>17. Inside <code>for (int mark : marks)</code>, what does the statement <code>mark = 0;</code> do?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q17\" value=\"a\"> <span class=\"opt-text\">Sets every array cell to 0</span></label><label class=\"option\"><input type=\"radio\" name=\"q17\" value=\"b\"> <span class=\"opt-text\">Changes only the loop variable, not the array</span></label><label class=\"option\"><input type=\"radio\" name=\"q17\" value=\"c\"> <span class=\"opt-text\">Throws an exception</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>The variable <code>mark</code> is a copy of one value, not a link to the array.</div><div class=\"why\" data-for=\"b\" hidden>An enhanced for loop gives you a copy of each primitive value, so the array is untouched.</div><div class=\"why\" data-for=\"c\" hidden>It is legal Java. It simply has no effect on the array.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"a\"><legend>18. After <code>Dog[] dogs = new Dog[4];</code>, how many Dog objects exist?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q18\" value=\"a\"> <span class=\"opt-text\">None</span></label><label class=\"option\"><input type=\"radio\" name=\"q18\" value=\"b\"> <span class=\"opt-text\">Four</span></label><label class=\"option\"><input type=\"radio\" name=\"q18\" value=\"c\"> <span class=\"opt-text\">One</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>The statement creates one array of four <code>null</code> references. No Dog constructor has run.</div><div class=\"why\" data-for=\"b\" hidden>Four cells exist, but each is <code>null</code>. A Dog only exists after <code>new Dog(...)</code>.</div><div class=\"why\" data-for=\"c\" hidden>The array is one object, but it is not a Dog.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"c\"><legend>19. What happens when <code>dogs[0].setName(&quot;Coco&quot;)</code> runs while <code>dogs[0]</code> is <code>null</code>?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q19\" value=\"a\"> <span class=\"opt-text\"><code>ArrayIndexOutOfBoundsException</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q19\" value=\"b\"> <span class=\"opt-text\">A new Dog is created automatically</span></label><label class=\"option\"><input type=\"radio\" name=\"q19\" value=\"c\"> <span class=\"opt-text\"><code>NullPointerException</code></span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Index 0 is valid. The problem is what the cell holds, not where it is.</div><div class=\"why\" data-for=\"b\" hidden>Java never creates objects on its own.</div><div class=\"why\" data-for=\"c\" hidden>Calling a method through a <code>null</code> reference throws it, which is why the guide checks for null first.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>20. What does each cell of <code>new Scanner[2]</code> hold before any assignment?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q20\" value=\"a\"> <span class=\"opt-text\">A closed Scanner</span></label><label class=\"option\"><input type=\"radio\" name=\"q20\" value=\"b\"> <span class=\"opt-text\"><code>null</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q20\" value=\"c\"> <span class=\"opt-text\">A Scanner reading <code>System.in</code></span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>No Scanner objects exist yet.</div><div class=\"why\" data-for=\"b\" hidden>Reference cells default to <code>null</code>. The array creates cells, not Scanners.</div><div class=\"why\" data-for=\"c\" hidden>A Scanner is only created by an explicit <code>new Scanner(...)</code>.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"c\"><legend>21. In the file example, why is <code>count</code> kept separately from <code>buffer.length</code>?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q21\" value=\"a\"> <span class=\"opt-text\"><code>length</code> changes as values are added</span></label><label class=\"option\"><input type=\"radio\" name=\"q21\" value=\"b\"> <span class=\"opt-text\"><code>count</code> is faster to read</span></label><label class=\"option\"><input type=\"radio\" name=\"q21\" value=\"c\"> <span class=\"opt-text\"><code>length</code> is the capacity; <code>count</code> is how many values were really stored</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>The length of an array never changes.</div><div class=\"why\" data-for=\"b\" hidden>Speed is not the reason.</div><div class=\"why\" data-for=\"c\" hidden>The buffer always has 100 cells, but only the first <code>count</code> hold file values. Sorting the rest would include unused zeros.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"a\"><legend>22. What must the read loop do with an invalid token such as <code>bad</code>?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q22\" value=\"a\"> <span class=\"opt-text\">Consume it with <code>next()</code> and skip it without increasing <code>count</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q22\" value=\"b\"> <span class=\"opt-text\">Leave it and loop again</span></label><label class=\"option\"><input type=\"radio\" name=\"q22\" value=\"c\"> <span class=\"opt-text\">Store 0 and increase <code>count</code></span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>The token must be consumed so the Scanner advances, and no value is stored, so <code>count</code> stays the same.</div><div class=\"why\" data-for=\"b\" hidden><code>hasNextInt()</code> does not consume the token, so the loop would repeat forever.</div><div class=\"why\" data-for=\"c\" hidden>That would invent a value that is not in the file.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>23. After <code>int[] b = a; b[0] = 99;</code>, what is <code>a[0]</code>?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q23\" value=\"a\"> <span class=\"opt-text\">The original value</span></label><label class=\"option\"><input type=\"radio\" name=\"q23\" value=\"b\"> <span class=\"opt-text\"><code>99</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q23\" value=\"c\"> <span class=\"opt-text\">The code does not compile</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>There is only one array, so the original value was overwritten.</div><div class=\"why\" data-for=\"b\" hidden><code>b</code> and <code>a</code> are two names for one array, so the write is visible through both.</div><div class=\"why\" data-for=\"c\" hidden>It compiles. Assigning an array reference is legal.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"c\"><legend>24. Which statement creates an independent copy of the <code>int[]</code> named <code>a</code>?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q24\" value=\"a\"> <span class=\"opt-text\"><code>int[] b = a;</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q24\" value=\"b\"> <span class=\"opt-text\"><code>a = new int[a.length];</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q24\" value=\"c\"> <span class=\"opt-text\"><code>int[] b = Arrays.copyOf(a, a.length);</code></span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>That copies only the reference, so both names reach the same array.</div><div class=\"why\" data-for=\"b\" hidden>That replaces <code>a</code> with a new empty array and loses the data.</div><div class=\"why\" data-for=\"c\" hidden><code>copyOf</code> allocates a second array and copies the values into it.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>25. Class <code>pkg.A</code> only defines <code>greet()</code>. What does <code>java -classpath classes pkg.A</code> do?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q25\" value=\"a\"> <span class=\"opt-text\">Prints the greeting</span></label><label class=\"option\"><input type=\"radio\" name=\"q25\" value=\"b\"> <span class=\"opt-text\">Reports that no main method was found</span></label><label class=\"option\"><input type=\"radio\" name=\"q25\" value=\"c\"> <span class=\"opt-text\">Recompiles the class</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden><code>greet()</code> is never called because nothing starts the program.</div><div class=\"why\" data-for=\"b\" hidden>Java needs <code>public static void main(String[] args)</code> in the class you run, so the guide runs <code>pkg.Tester</code>.</div><div class=\"why\" data-for=\"c\" hidden>The <code>java</code> command runs classes. It does not compile.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"c\"><legend>26. Why is selection sort not stable?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q26\" value=\"a\"> <span class=\"opt-text\">It compares with <code>&lt;=</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q26\" value=\"b\"> <span class=\"opt-text\">It uses recursion</span></label><label class=\"option\"><input type=\"radio\" name=\"q26\" value=\"c\"> <span class=\"opt-text\">Its swap can jump a value over an equal value</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Its minimum search uses a strict <code>&lt;</code>. The cause is the swap.</div><div class=\"why\" data-for=\"b\" hidden>The standard version is iterative.</div><div class=\"why\" data-for=\"c\" hidden>In <code>[2ᵃ, 2ᵇ, 1]</code> swapping 1 with <code>2ᵃ</code> puts <code>2ᵇ</code> ahead of <code>2ᵃ</code>.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"a\"><legend>27. A <code>Doctor[]</code> holds Doctor, GP, and Surgeon objects. Why test <code>instanceof Surgeon</code> and <code>instanceof GP</code> before the plain Doctor case?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q27\" value=\"a\"> <span class=\"opt-text\">Every GP and Surgeon is also a Doctor, so a Doctor test would match them first</span></label><label class=\"option\"><input type=\"radio\" name=\"q27\" value=\"b\"> <span class=\"opt-text\"><code>instanceof</code> only works on the first test written</span></label><label class=\"option\"><input type=\"radio\" name=\"q27\" value=\"c\"> <span class=\"opt-text\">Surgeon objects are null until tested</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden><code>instanceof Doctor</code> is true for all three kinds, so the more specific tests must come first.</div><div class=\"why\" data-for=\"b\" hidden>Every test is evaluated normally. Order matters only because the tests overlap.</div><div class=\"why\" data-for=\"c\" hidden>Objects are not null. They are built when the record is parsed.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"b\"><legend>28. Binary search for <code>20</code> in <code>[10, 20, 20, 20, 30]</code> returns which index?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q28\" value=\"a\"> <span class=\"opt-text\">1</span></label><label class=\"option\"><input type=\"radio\" name=\"q28\" value=\"b\"> <span class=\"opt-text\">2</span></label><label class=\"option\"><input type=\"radio\" name=\"q28\" value=\"c\"> <span class=\"opt-text\">3</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Index 1 is the first 20, but the search never lands there.</div><div class=\"why\" data-for=\"b\" hidden>The first midpoint is <code>0 + (4 − 0) / 2 = 2</code> and <code>arr[2]</code> is 20, so it returns immediately.</div><div class=\"why\" data-for=\"c\" hidden>Index 3 is a 20 as well, but the search stops at the first match it meets.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"a\"><legend>29. Binary search for <code>57</code> in <code>[8, 18, 23, 29, 34, 42, 57, 63]</code>. Where is it found, and after how many probes of <code>arr[mid]</code>?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q29\" value=\"a\"> <span class=\"opt-text\">Index 6, after 3 probes</span></label><label class=\"option\"><input type=\"radio\" name=\"q29\" value=\"b\"> <span class=\"opt-text\">Index 6, after 7 probes</span></label><label class=\"option\"><input type=\"radio\" name=\"q29\" value=\"c\"> <span class=\"opt-text\">Index 7, after 2 probes</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>The probes are at indexes 3 (29), 5 (42) and 6 (57). Each probe that misses discards its half.</div><div class=\"why\" data-for=\"b\" hidden>Seven probes is what linear search needs to reach index 6. Binary search halves the range every time.</div><div class=\"why\" data-for=\"c\" hidden>63 is at index 7, but 57 is at index 6, and the second probe lands on index 5.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"a\"><legend>30. After the <em>second</em> pass of bubble sort on <code>[5, 1, 4, 2, 8]</code>, what does the array hold?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q30\" value=\"a\"> <span class=\"opt-text\"><code>[1, 2, 4, 5, 8]</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q30\" value=\"b\"> <span class=\"opt-text\"><code>[1, 4, 2, 5, 8]</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q30\" value=\"c\"> <span class=\"opt-text\"><code>[1, 2, 4, 8, 5]</code></span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Pass 1 gives <code>[1, 4, 2, 5, 8]</code>. Pass 2 swaps 4 and 2, and the 5 and the 8 are already locked on the right.</div><div class=\"why\" data-for=\"b\" hidden>That is the array after pass 1, not after pass 2.</div><div class=\"why\" data-for=\"c\" hidden>A pass never moves a larger value to the left of a smaller one on the right; the largest active value ends at the right.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"a\"><legend>31. How many shifts does insertion sort make on the reversed array <code>[4, 3, 2, 1]</code>?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q31\" value=\"a\"> <span class=\"opt-text\">6</span></label><label class=\"option\"><input type=\"radio\" name=\"q31\" value=\"b\"> <span class=\"opt-text\">3</span></label><label class=\"option\"><input type=\"radio\" name=\"q31\" value=\"c\"> <span class=\"opt-text\">10</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Keys 3, 2 and 1 shift 1 + 2 + 3 times. Every pair is out of order, and 4 × 3 / 2 = 6.</div><div class=\"why\" data-for=\"b\" hidden>That would be one shift per key, but each key has to pass every larger value to its left.</div><div class=\"why\" data-for=\"c\" hidden>Ten is more than the number of out-of-order pairs, which is 6. Each shift fixes exactly one pair.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"a\"><legend>32. <code>mergeSort(arr, 0, 7)</code> sorts 8 values. How many times is <code>merge</code> called?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q32\" value=\"a\"> <span class=\"opt-text\">7</span></label><label class=\"option\"><input type=\"radio\" name=\"q32\" value=\"b\"> <span class=\"opt-text\">8</span></label><label class=\"option\"><input type=\"radio\" name=\"q32\" value=\"c\"> <span class=\"opt-text\">3</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Each merge turns two runs into one, so 8 single-value runs need 8 − 1 = 7 merges (4 + 2 + 1).</div><div class=\"why\" data-for=\"b\" hidden>There are 8 values but only 7 merges: 8 runs become 1 run, and each merge removes one run.</div><div class=\"why\" data-for=\"c\" hidden>Three is the number of levels, log₂ 8. Each level makes several merges: 4 + 2 + 1.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"c\"><legend>33. After the first pass (<code>i = 0</code>) of selection sort on <code>[64, 25, 12, 22, 11]</code>, what does the array hold?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q33\" value=\"a\"> <span class=\"opt-text\"><code>[11, 64, 25, 12, 22]</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q33\" value=\"b\"> <span class=\"opt-text\"><code>[12, 25, 64, 22, 11]</code></span></label><label class=\"option\"><input type=\"radio\" name=\"q33\" value=\"c\"> <span class=\"opt-text\"><code>[11, 25, 12, 22, 64]</code></span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>That is what shifting would give. Selection sort swaps the minimum with position 0, so only two cells change.</div><div class=\"why\" data-for=\"b\" hidden>12 is not the minimum; 11 is, at index 4.</div><div class=\"why\" data-for=\"c\" hidden>The minimum, 11 at index 4, trades places with 64 at index 0. Nothing else moves.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <fieldset class=\"question\" data-answer=\"c\"><legend>34. In binary search <code>low = 3</code> and <code>high = 10</code>. What is <code>int mid = low + (high - low) / 2;</code>?</legend>\r\n            <label class=\"option\"><input type=\"radio\" name=\"q34\" value=\"a\"> <span class=\"opt-text\">7</span></label><label class=\"option\"><input type=\"radio\" name=\"q34\" value=\"b\"> <span class=\"opt-text\">6.5</span></label><label class=\"option\"><input type=\"radio\" name=\"q34\" value=\"c\"> <span class=\"opt-text\">6</span></label>\r\n            <div class=\"why\" data-for=\"a\" hidden>Integer division truncates: <code>(10 − 3) / 2</code> is 3, not 3.5, so there is no rounding up.</div><div class=\"why\" data-for=\"b\" hidden><code>mid</code> is an <code>int</code>, and integer division discards the fraction, so it can never be 6.5.</div><div class=\"why\" data-for=\"c\" hidden><code>(10 − 3) / 2 = 3</code> in integer division, so <code>mid = 3 + 3 = 6</code>.</div>\r\n            <div class=\"feedback\" role=\"status\" aria-live=\"polite\"></div>\r\n          </fieldset>\r\n          <div class=\"quiz-actions\">\r\n            <button class=\"paper-button\" type=\"submit\">Show my score</button>\r\n            <button class=\"paper-button secondary\" type=\"reset\">Try again</button>\r\n          </div>\r\n          <div class=\"quiz-result\" id=\"quiz-result\" aria-live=\"polite\"></div>\r\n        </form>\r\n      "
  },
  "flashcards": {
    "id": "flashcards",
    "title": "Flashcards",
    "body": "\r\n        <span class=\"section-no\">Rapid review</span>\r\n        <h2>Flashcards</h2>\r\n        <p class=\"lede\">Say the answer aloud, then tap the card to reveal it. Use the buttons to move through the deck.</p>\r\n        <div class=\"flash-deck\">\r\n          <button class=\"flashcard\" type=\"button\" aria-label=\"Flip flashcard\">\r\n            <span class=\"flashcard-inner\">\r\n              <span class=\"flash-face flash-front\"><span class=\"flash-label\">Question</span><span class=\"flash-text\" id=\"flash-question\"></span><span class=\"flash-hint\">Tap to reveal</span></span>\r\n              <span class=\"flash-face flash-back\"><span class=\"flash-label\">Answer</span><span class=\"flash-text\" id=\"flash-answer\"></span><span class=\"flash-hint\">Tap to hide</span></span>\r\n            </span>\r\n          </button>\r\n          <div class=\"deck-controls\">\r\n            <button class=\"paper-button secondary\" id=\"prev-card\" type=\"button\">Previous</button>\r\n            <span class=\"card-count\" id=\"card-count\"></span>\r\n            <button class=\"paper-button\" id=\"next-card\" type=\"button\">Next</button>\r\n          </div>\r\n        </div>\r\n      "
  }
};
